local _, ns = ...
local E = ns.DB.entries
E["npc:auntie-bernice-stonefield"] = {t="npc",n="\"Auntie\" Bernice Stonefield",z="elwynn",s="“Auntie” Bernice Stonefield is an elder of the Stonefield family, residing at their homestead in south-central Elwynn Forest. Widowed after her husband fell in battle during the kingdom's military campaigns, she is renowned throughout the valley for her famous pork belly pies. She can be found outside the farmhouse alongside Ma Stonefield, keeping a sharp eye on the neighborhood and harboring a deep suspicion of the rival Maclure family.",h="“Auntie” Bernice Stonefield is an elder of the Stonefield family, residing at their homestead in...",sec={{t="A Life of Hardship",b="Like many common folk across the Kingdom of Stormwind, Bernice has borne the steep price of ongoing war. Having lost her husband to military campaigns, she now lives out her days on the family homestead with her kin, helping manage daily farm affairs alongside matriarch Ma Stonefield. Despite personal loss, she keeps the household fed and running, earning local fame for her celebrated pork belly pies.",sp=0},{t="The Feud and the Missing Necklace",b="The long-standing bitterness between the Stonefields and the Maclures is a defining part of Bernice's world. When her prized family necklace went missing, she immediately suspected young Billy Maclure of swiping it. However, recovering her keepsake proves more complicated than dealing with a petty neighbor's prank: Billy insists he dropped it while running away from the fearsome kobold Goldtooth over at the Fargodeep Mine.",sp=1}},faq={{q="Who is Auntie Bernice Stonefield?",a="She is an elder of the Stonefield clan living at the Stonefield Farm in southern Elwynn Forest. She is a war widow who spends her days tending the farm alongside Ma Stonefield and baking her famous pork belly pies.",al={"who is auntie bernice","bernice stonefield lore","stonefield auntie"}},{q="What happened to Auntie Bernice's husband?",a="Bernice became a widow when her husband was killed during a military campaign fought for the Kingdom of Stormwind.",al={"auntie bernice husband","who was bernice married to","stonefield widow"}},{q="What is Auntie Bernice famous for?",a="She is well known throughout the local countryside for her savory pork belly pies, a treat delicious enough that even mischievous neighbors cannot resist bargaining for a slice.",al={"bernice stonefield pie","pork belly pie elwynn"}},{q="Why is Auntie Bernice angry with Billy Maclure?",a="Bernice suspected Billy Maclure stole her cherished family necklace, stoking the fires of the long-standing family feud between the Stonefields and the Maclures.",al={"billy maclure feud","bernice necklace thief","why does bernice hate billy"}},{q="Did Billy Maclure actually steal the necklace?",a="Billy found the necklace, but while carrying it, he was chased by the notorious kobold Goldtooth near the Fargodeep Mine and dropped it during his escape. Goldtooth subsequently took possession of it.",al={"did billy steal the necklace","who has the stonefield necklace","goldtooth necklace"},sp=1},{q="Where is Auntie Bernice located?",a="She can be found standing right outside the main farmhouse on the Stonefield Farm, located south of the road between Goldshire and Westfall, standing beside Ma Stonefield.",al={"auntie bernice location","where is bernice stonefield"}}},ang={["profession:Cooking"]="Bernice's pork belly pie is famous across Elwynn Forest as a quintessential staple of hearty human frontier cooking.",["race:Human"]="Bernice embodies the gritty resilience of Stormwind's rural folk, carrying on daily life and family pride after losing a husband to the kingdom's wars."},kw={"auntie","bernice","elwynn","goldtooth","maclure","necklace","pork belly pie","stonefield"},rel={"subzone:stonefield-farm","npc:ma-stonefield","npc:billy-maclure","quest:85","quest:86","quest:84","quest:87","zone:elwynn"},src={"\"Auntie\" Bernice Stonefield"}}
E["npc:billy-maclure"] = {t="npc",n="Billy Maclure",z="elwynn",s="Billy Maclure is a mischievous young human boy living at the Maclure Vineyards in Elwynn Forest. Caught in the midst of a bitter feud between his family and the neighboring Stonefields, Billy's petty antics often cause trouble for both farms. His weakness for fresh pastries makes him easy to bribe when his shenanigans get out of hand.",h="Billy Maclure is a mischievous young human boy living at the Maclure Vineyards in Elwynn Forest.",sec={{t="A Boy at the Vineyards",b="Billy Maclure can usually be found loitering outside the barn at the Maclure Vineyards, not far from the farmer Gerard Tiller. Growing up amidst the endless rows of grapevines, Billy spends much of his time dodging chores and running wild across the rural meadows of central Elwynn Forest. Like the rest of his kin, he is keenly aware of the long-standing hostility between the Maclures and the Stonefields, though Billy treats the feud more like a game of pranks and petty theft than a serious conflict.",sp=0},{t="The Stolen Necklace",b="Billy's mischief crossed the line when he swiped a treasured heirloom necklace belonging to Auntie Bernice Stonefield. While dashing about near the perilous Fargodeep Mine, the frightened youngster lost his grip on the trinket. Before he could retrieve it, the necklace was snatched up by a particularly massive and vicious kobold named Goldtooth, who vanished back into the subterranean tunnels. Terrified of both the subterranean vermin and the wrath of the neighboring elders, Billy remains reluctant to confess until coaxed with a savory bribe—specifically, a hot pork belly pie baked by Auntie Bernice herself.",sp=1}},faq={{q="Who is Billy Maclure?",a="Billy Maclure is a young human child living at the Maclure Vineyards in Elwynn Forest. He spends his days dodging work around the farm, playing pranks, and aggravating the neighboring Stonefield family.",al={"who is billy","billy maclure lore","maclure kid"}},{q="Where can Billy Maclure be found?",a="Billy is stationed just outside the main barn on the grounds of the Maclure Vineyards, located in central Elwynn Forest to the southwest of the Stonefield Farm.",al={"billy maclure location","where is billy","find billy maclure"}},{q="What did Billy do to Auntie Bernice?",a="Billy snuck over to the Stonefield Farm and stole Auntie Bernice Stonefield's heirloom necklace as part of the ongoing feud between their families.",al={"bernice necklace","what did billy steal","stolen necklace elwynn"}},{q="What happened to the necklace Billy stole?",a="While playing carelessly near the entrance of Fargodeep Mine, Billy dropped the necklace. It was swiftly picked up by Goldtooth, a notorious and formidable kobold who carried it deep into the mine.",al={"where is the necklace","lost necklace elwynn","who has bernice necklace"},sp=1},{q="How do you get Billy to confess what happened to the necklace?",a="Billy refuses to tell the truth out of stubbornness and fear of punishment, but he cannot resist his appetite. Offering him one of Auntie Bernice's freshly baked pork belly pies is enough to loosen his tongue.",al={"pie for billy","how to bribe billy","bribing billy maclure"},sp=1},{q="Who is Goldtooth?",a="Goldtooth is an exceptionally large and vicious kobold leader who nests inside Fargodeep Mine. He snatched Auntie Bernice's dropped necklace from near the mine's entrance and hoards it within the dark tunnels.",al={"who is goldtooth","goldtooth lore","fargodeep kobold"},sp=1}},ang={["race:Human"]="Billy represents the grounded, everyday squabbles of the Elwynn countryside, showing that even with Stormwind's political turmoil, local farm feuds and childhood misbehavior carry on as usual.",["faction:Alliance"]="For Alliance adventurers newly arrived from Northshire, assisting with Billy's foolish pranks provides an introduction to the dangers lurking in Fargodeep Mine.",["profession:Cooking"]="Auntie Bernice's renowned pork belly pie demonstrates how simple frontier cooking can resolve tense local disputes and pry confessions from tight-lipped farm boys."},kw={"bernice stonefield","billy maclure","fargodeep mine","goldtooth","lost necklace","maclure vineyards","pork belly pie","stonefield"},rel={"subzone:maclure-vineyards","quest:85","quest:86","quest:87","quest:84","subzone:fargodeep-mine","topic:kobold","npc:gerard-tiller"},src={"Billy Maclure"}}
E["npc:brother-neals"] = {t="npc",n="Brother Neals",z="elwynn",s="Brother Neals is a monk residing in Northshire Abbey within Elwynn Forest. Responsible for managing the abbey's stores of food and drink, he spends much of his time overseeing shipments and sampling the vintage produced by the local vineyard.",h="Brother Neals is a monk residing in Northshire Abbey within Elwynn Forest.",sec={{t="Keeper of the Cellar",b="Tucked away in the upper belfry rooms of Northshire Abbey, Brother Neals looks after the monastery's culinary provisions and beverage stores. He takes a particular, enthusiastic interest in the Northshire vineyards, carefully tracking grape manifests and ensuring the quality of the abbey's renowned wine by tasting it with dedicated frequency. Despite the peaceful duties of inventory and cellar management, he keeps close tabs on the shipments arriving from the valley's surrounding fields.",sp=0}},faq={{q="Who is Brother Neals?",a="Brother Neals is a member of the brotherhood at Northshire Abbey who manages food, drink, and wine inventories for the clergy and recruits stationed in the valley.",al={"brother neals","neals","who is neals"}},{q="Where can Brother Neals be found?",a="He stays in the uppermost room of Northshire Abbey. To reach him, head up the stone staircases inside the main hall until you reach the quiet chamber near the top of the tower.",al={"where is brother neals","brother neals location","find neals"}},{q="What is his role regarding the vineyard?",a="He tracks the grape harvests and wine shipments coming in from the nearby Northshire Vineyard, though he is known to spend just as much time sampling the vintage as he does balancing the ledgers.",al={"grape manifest quest","neals wine","what does neals do"}}},ang={["profession:Cooking"]="Brother Neals manages the monastery's provisions and spirits, making him a kindred spirit to anyone interested in the culinary arts and brewing traditions of the kingdom."},kw={"brother neals","elwynn forest","grape manifest","northshire abbey","northshire valley","vineyard","wine"},rel={"subzone:northshire-abbey","subzone:northshire-valley","quest:3905","zone:elwynn"},src={"Brother Neals"}}
E["npc:deputy-rainer"] = {t="npc",n="Deputy Rainer",z="elwynn",s="Deputy Rainer is a Stormwind Army officer stationed outside Westbrook Garrison along Elwynn Forest's western boundary. Tasked with holding the line against encroaching gnoll packs and bandits bleeding over from Westfall, he coordinates local defense efforts when official military reinforcements fail to arrive.",h="Deputy Rainer is a Stormwind Army officer stationed outside Westbrook Garrison along Elwynn Forest's western...",sec={{t="Holding the Western Border",b="Westbrook Garrison serves as Elwynn Forest's westernmost bulwark, positioned just along the boundary road leading into Westfall. As political paralysis in Stormwind City keeps the bulk of the army stationed abroad or tied up in bureaucracy, border posts like Westbrook are left severely understaffed. Deputy Rainer stands outside the tower to organize what little defense the garrison can muster. With local roads constantly threatened by aggressive Riverpaw gnolls and wandering thieves, Rainer is forced to rely on passing travelers and mercenary adventurers rather than official crown regiments to keep the forest trails secure.",sp=0},{t="The Road to Westfall",b="Beyond managing the immediate threat of the Riverpaw pack and cautioning travelers against the infamous gnoll chieftain Hogger, Rainer serves as a vital communications link to the troubled lands beyond the river. Knowing that the chaos plaguing Elwynn's borders originates in the lawless farmlands to the west, he directs capable volunteers across the threshold into Westfall, pointing them toward Gryan Stoutmantle and the struggling People's Militia.",sp=0}},faq={{q="Who is Deputy Rainer?",a="Deputy Rainer is an officer of the Stormwind Army stationed at Westbrook Garrison on the western edge of Elwynn Forest. He oversees local road security and contracts adventurers to fight surrounding threats.",al={"rainer elwynn","who is rainer","westbrook garrison officer"}},{q="Why is Westbrook Garrison undermanned?",a="The Stormwind Army has the bulk of its forces deployed elsewhere, and political disarray in the capital prevents regular reinforcements from reaching outlying regions. As a result, Marshal Dughan in Goldshire must rely on independent adventurers to assist Rainer.",al={"why no guards at westbrook","why is the garrison struggling","westbrook needs help"}},{q="What threats is Rainer trying to counter?",a="Rainer focuses primarily on containment of the Riverpaw gnoll pack infesting the woods south of the garrison, roving thieves, and the notorious gnoll chieftain Hogger, who preys on travelers along the border.",al={"what enemies are near westbrook","riverpaw gnolls westbrook","westbrook gnolls"}},{q="Where does Rainer send adventurers after clearing the gnolls?",a="Once the gnoll menace near the garrison is suppressed, Rainer directs seasoned adventurers across the western border into Westfall to assist Gryan Stoutmantle and the People's Militia at Sentinel Hill.",al={"where to go after rainer","rainer quest westfall","after westbrook garrison"}}},ang={["faction:Alliance"]="Deputy Rainer represents the fraying edges of Stormwind's military reach, offering Alliance heroes a direct look at how local garrisons must adapt to survive without regular royal support."},kw={"deputy rainer","elwynn forest","gryan stoutmantle","hogger","marshal dughan","riverpaw","westbrook garrison","westfall"},rel={"subzone:westbrook-garrison","quest:11","quest:109","quest:239","quest:176","npc:marshal-dughan","npc:gryan-stoutmantle","zone:westfall"},src={"Deputy Rainer"}}
E["npc:drusilla-la-salle"] = {t="npc",n="Drusilla La Salle",z="elwynn",s="Drusilla La Salle is a human warlock trainer situated in the shadowed graveyard outside Northshire Abbey. Operating on the fringes of the Holy Order of Northshire, she mentors fledgling spellcasters in the dark arts of summoning and shadow. When forbidden knowledge slips beyond the abbey walls, she does not hesitate to use opportunism and dark magic to claim it.",h="Drusilla La Salle is a human warlock trainer situated in the shadowed graveyard outside Northshire Abbey.",sec={{t="Shadows in Holy Ground",b="While paladins and priests practice beneath the stained glass of Northshire Abbey, Drusilla La Salle remains outdoors among the headstones of the graveyard. Practicing demonology and fel magic is deeply taboo within the kingdom of Stormwind, forcing warlocks to dwell on the periphery of polite society. Drusilla provides early instruction to novice warlocks who have received tainted correspondence, teaching them how to harness shadow power without drawing the immediate wrath of abbey authorities.",sp=0},{t="Powers of the Void",b="Northshire Abbey’s library wing secretly preserves several hazardous and forbidden tomes, including 'Powers of the Void'. Drusilla long covets the manuscript, but a warlock loitering in the secure archives would provoke immediate suspicion. Her chance arrives when an apostate novice flees the abbey to join the Defias Brotherhood, taking the text with him. Taking advantage of the theft, Drusilla dispatches her apprentices to hunt the turncoat down and deliver the grimoire into her hands under the pretense of recovering abbey property.",sp=1}},faq={{q="Why is a warlock allowed near Northshire Abbey?",a="Warlocks are viewed with deep distrust by the Church of the Holy Light and Stormwind's leadership. Drusilla La Salle stays outside the abbey proper, secluded in the nearby graveyard where she conducts her instruction away from the devout priests and clerics studying inside.",al={"why is drusilla at abbey","warlock in holy abbey","why is she in the graveyard"}},{q="What book is Drusilla trying to obtain?",a="She seeks a grimoire titled 'Powers of the Void'. It was originally locked away in a protected section of Northshire Abbey's Library Wing, far out of reach of open warlock investigation until a Defias defector stole it.",al={"what book does she want","powers of the void book","the stolen tome quest book"}},{q="Who stole the book from the library?",a="A novice studying at Northshire Abbey broke his vows, allied with the Defias Brotherhood, and plundered the tome before fleeing to a nearby camp in Northshire Valley.",al={"who took the tome","defias book thief","who stole powers of the void"}},{q="What role does she play for new human warlocks?",a="Drusilla acts as the very first trainer for human warlocks, accepting tainted letters sent to recruits and instructing them in basic curses and summoned servitors.",al={"human warlock trainer northshire","who trains warlocks in northshire"}}},ang={["class:Warlock"]="Drusilla serves as your first mentor in the dark arts, guiding you toward practical mastery of curses and fel summoning while teaching you to keep your ambition hidden in plain sight.",["class:Priest"]="Standing outside the holy halls of Northshire, Drusilla represents the dark inversion of your calling, trafficking in shadow and demonic pacts right beside the consecrated graveyard."},kw={"abbey","drusilla la salle","graveyard","northshire","powers of the void","stolen tome","warlock trainer"},rel={"quest:1598","subzone:northshire-abbey","subzone:northshire-valley","subzone:library-wing-northshire","topic:defias-brotherhood","zone:elwynn"},src={"Drusilla La Salle"}}
E["npc:gerard-tiller"] = {t="npc",n="Gerard Tiller",z="elwynn",s="Gerard Tiller is a thirsty human farmhand working outside the barn at the Maclure Vineyards in Elwynn Forest. Tending the vineyards under the warm sun, he is always eager to trade a crisp, shiny red apple to any traveler willing to spare a skin of refreshing spring water.",h="Gerard Tiller is a thirsty human farmhand working outside the barn at the Maclure Vineyards in Elwynn Forest.",sec={{t="A Thirsty Farmhand",b="Gerard Tiller spends his days toiling in the fields and tending the grounds outside the barn at the Maclure Vineyards. Located just south of Goldshire, the vineyard produces some of Elwynn's best-known grapes, but keeping the harvest running is hard labor. Tiller is constantly parched from his chores, making him quick to barter with passing adventurers. If someone offers him a fresh skin of cool spring water, he happily repays the courtesy with fresh, shiny red apples gathered straight from the local orchards.",sp=0}},faq={{q="Who is Gerard Tiller?",a="Gerard Tiller is a human farmhand stationed outside the barn at the Maclure Vineyards in southern Elwynn Forest.",al={"gerard tiller identity","who is gerard","tiller elwynn"}},{q="Where can I find Gerard Tiller?",a="He stands right outside the large wooden barn at the Maclure Vineyards, located south of Goldshire and east of the Stonefield Farm.",al={"gerard tiller location","where is gerard","find gerard elwynn"}},{q="What does Gerard Tiller trade?",a="Gerard trades a Shiny Red Apple to any traveler who brings him a skin of Refreshing Spring Water to quench his thirst.",al={"gerard apple trade","gerard tiller water","what does gerard want"}},{q="Does Gerard get involved in the Maclure and Stonefield feud?",a="No. While he works at the Maclure Vineyards, Gerard focuses on his chores and staying hydrated rather than meddling in the family rivalry between the Maclures and Stonefields.",al={"gerard tiller feud","maclure feud gerard"}}},ang={["profession:Cooking"]="Gerard's willingness to trade fresh apples for plain spring water makes him a handy source of fruit for wandering cooks looking for simple ingredients."},kw={"elwynn forest","gerard tiller","give gerard a drink","maclure vineyards","refreshing spring water","shiny red apple"},rel={"quest:16","subzone:maclure-vineyards","zone:elwynn"},src={"Gerard Tiller"}}
E["npc:gramma-stonefield"] = {t="npc",n="Gramma Stonefield",z="elwynn",s="Gramma Stonefield, whose given name is Mildred, is the elderly matriarch of the Stonefield family residing at their farm in Elwynn Forest. Unlike her bickering kin, she has grown weary of the bitter, generations-long feud with the neighboring Maclures. Quietly working behind her family's back, she does everything she can to help her grandson Tommy Joe pursue his forbidden romance with Maybell Maclure.",h="Gramma Stonefield, whose given name is Mildred, is the elderly matriarch of the Stonefield family residing at...",sec={{t="A Secret Peacemaker",b="As the oldest living member of the Stonefield clan, Mildred Stonefield has witnessed decades of petty squabbling between her household and the Maclures across the road. Rather than stoking the bad blood, she views the enduring rivalry as senseless and destructive. When her grandson Tommy Joe Stonefield falls in love with Maybell Maclure, Gramma chooses compassion over clan loyalty. Relying on an old friendship with William Pestle in Goldshire, she quietly plots to help the star-crossed sweethearts meet in secret, subverting the stubborn hostility dividing the two farms.",sp=0}},faq={{q="Who is Gramma Stonefield?",a="Gramma Stonefield, named Mildred, is the elderly matriarch of the Stonefield family living on their farm in central Elwynn Forest. She is the grandmother of Tommy Joe Stonefield.",al={"who is gramma","mildred stonefield","stonefield grandma"}},{q="How does she feel about the feud with the Maclures?",a="Mildred has no interest in maintaining the feud. Unlike most members of both families, she views the grudge as foolish and harmful, preferring to see harmony between the households rather than endless bickering.",al={"stonefield maclure feud","does she hate maclures"}},{q="Why is she helping Tommy Joe and Maybell?",a="She loves her grandson Tommy Joe and wants him to be happy. Because she rejects the family feud, she actively aids his forbidden romance with Maybell Maclure by calling upon her old friend William Pestle to concoct a solution for the pair.",al={"why help tommy joe","gramma love potion","help lovers"}},{q="Who is William Pestle to her?",a="William Pestle, the alchemist residing at the Lion's Pride Inn in Goldshire, is an old and trusted friend of Gramma Stonefield. She reaches out to him through trusted couriers to concoct subtle remedies and aids for Tommy Joe.",al={"william pestle connection","william pestle gramma"}}},ang={["faction:Alliance"]="Gramma Stonefield is a gentle reminder that even within the heartland of the Alliance, local conflicts often require quiet diplomacy and simple empathy rather than steel."},kw={"elwynn","gramma stonefield","maclure","maybell","mildred","stonefield farm","tommy joe","william pestle"},rel={"npc:tommy-joe-stonefield","npc:maybell-maclure","npc:william-pestle","subzone:stonefield-farm","npc:ma-stonefield","quest:111","zone:elwynn"},src={"Gramma Stonefield"}}
E["npc:guard-thomas"] = {t="npc",n="Guard Thomas",z="elwynn",s="Guard Thomas is a dedicated soldier of the Stormwind Army stationed at the bridge west of the Eastvale Logging Camp. Isolated on the eastern frontier of Elwynn Forest, he oversees the defense of local settlers against predatory wildlife and encroaching murlocs.",h="Guard Thomas is a dedicated soldier of the Stormwind Army stationed at the bridge west of the Eastvale...",sec={{t="On the Eastern Border",b="While much of the realm's attention is focused inward toward the capital or west toward Westfall, Guard Thomas holds one of the quietest yet most precarious posts in Elwynn Forest. Positioned at the stone bridge crossing the river toward Eastvale Logging Camp, Thomas acts as the thin blue line between everyday forestry workers and the aggressive creatures roaming the woods. With the Stormwind military stretched thin, guards like Thomas must rely heavily on passing adventurers to maintain order and carry messages back to central command.",sp=0},{t="Frontier Troubles",b="The eastern edges of Elwynn face persistent pressures. Aggressive bears and prowlers stalk the treeline, threatening lumberjacks and travelers, while strange murloc tribes have established camps along the waterways. Thomas tracks the movements of these aquatic predators and issues bounties to cull their numbers. Worse still, scouting patrols along the river occasionally vanish without a trace, leaving Thomas to piece together the fate of his fellow guards amidst rising regional instability.",sp=1}},faq={{q="Where can I find Guard Thomas?",a="Guard Thomas is posted on the stone bridge spanning the river just west of the Eastvale Logging Camp, along the eastern road in Elwynn Forest.",al={"guard thomas location","where is thomas","guard thomas bridge"}},{q="What is Guard Thomas's duty in Elwynn Forest?",a="He is an officer of the Stormwind Army assigned to protect the eastern frontier of Elwynn. His responsibilities include securing the trade bridge, defending nearby workers from wild predators, and monitoring hostile murloc encroachments along the riverbanks.",al={"what does thomas do","guard thomas role","thomas eastvale"}},{q="Why is Guard Thomas asking for help with lost guards?",a="Routine patrols dispatched into the river basins have failed to report back. Without sufficient reinforcements to leave his post unmanned, Thomas enlists traveling adventurers to search the waterways and find out what happened to his missing comrades.",al={"lost guards elwynn","guard thomas missing scouts","what happened to the guards"}},{q="Why are murlocs a problem for Guard Thomas?",a="Murloc tribes have increasingly crept up the river systems of eastern Elwynn. Their growing presence threatens both local logging operations and overland supply routes, prompting Thomas to place open bounties on their fins to keep the waterways clear.",al={"murlocs eastvale","why kill murlocs","guard thomas murloc bounty"}},{q="Who does Guard Thomas report to?",a="Thomas serves within the Stormwind Army, reporting through the military hierarchy back to regional command in Goldshire and the capital. As matters deteriorate across the borders, his dispatches also coordinate with frontier leadership like Gryan Stoutmantle out in Westfall.",al={"thomas superior","stormwind army chain of command","who does thomas work for"}},{q="Where does Guard Thomas send adventurers once their work in Elwynn is done?",a="Once the immediate threats around Eastvale and the eastern river are handled, Thomas provides reports directing seasoned travelers toward Westfall to aid Captain Gryan Stoutmantle and the struggling People's Militia.",al={"after guard thomas","where to go after eastvale","westfall report"}}},ang={["faction:Alliance"]="Guard Thomas embodies the overstretched state of the Stormwind Army, holding a vital outpost on the frontier with minimal support from the crown.",["class:Warrior"]="For young warriors of the Alliance, Thomas represents frontline discipline and the unglamorous realities of regional border defense."},kw={"eastvale","eastvale logging camp","elwynn forest","guard thomas","lost guards","murloc","stormwind army","thomas"},rel={"subzone:eastvale-logging-camp","zone:elwynn","topic:stormwind-army","quest:37","quest:46","quest:52","quest:39","npc:gryan-stoutmantle"},src={"Guard Thomas"}}
E["npc:henze-faulk"] = {t="npc",n="Henze Faulk",z="elwynn",s="Henze Faulk is a dwarven adventurer found lying near death on the stone circle outside Heroes' Vigil in Elwynn Forest. Struck down by the Defias Brotherhood while shielding his companion, he serves as a pivotal test for aspiring paladins learning to wield the gift of resurrection.",h="Henze Faulk is a dwarven adventurer found lying near death on the stone circle outside Heroes' Vigil in...",sec={{t="A Sacrifice at Heroes' Vigil",b="Near the ancient stone ring east of Stormwind sits Heroes' Vigil, a place often haunted by Defias bandits prowling the Elwynn woods. Henze Faulk and his friend Gazin Tenorm were ambushed here by Defias marauders. Putting himself in harm's way to ensure Gazin's survival, Henze fell to the bandits' blades. While his companion survived to summon aid from the Cathedral of Light, Henze's body remains on the threshold of life and death, awaiting the divine intervention of a paladin carrying a Symbol of Life.",sp=0}},faq={{q="Who is Henze Faulk?",a="Henze Faulk is an Ironforge dwarf found lying fatally wounded at the stone circle near Heroes' Vigil in Elwynn Forest. He was ambushed and struck down by Defias bandits while saving his friend Gazin Tenorm.",al={"henze faulk","dwarf at heroes vigil","dying dwarf elwynn"}},{q="Why is Henze Faulk lying on the ground?",a="Henze was ambushed by the Defias Brotherhood while traveling with Gazin Tenorm. He took the brunt of the attack so Gazin could escape, leaving him mortally wounded and awaiting resurrection by an initiate of the Holy Light.",al={"why is henze dying","is henze dead","henze faulk dead"}},{q="What is Henze's connection to paladins?",a="Henze is the central figure in a rite of passage for young paladins undertaking the trials of the Tome of Divinity. Paladin initiates are entrusted with a Symbol of Life and sent to Elwynn to restore Henze from death, proving their mastery over the Light's most sacred blessing of redemption.",al={"henze paladin quest","tome of divinity dwarf"}},{q="Who is Gazin Tenorm?",a="Gazin Tenorm is Henze Faulk's companion. When the two were cornered by Defias outlaws, Henze protected Gazin, allowing Gazin to survive and seek help from the Church of the Holy Light.",al={"who is gazin","gazin tenorm friend"}}},ang={["class:Paladin"]="Henze Faulk represents your first true test of divine mercy. Bringing him back from the brink with a Symbol of Life teaches a paladin that the Light is not merely a weapon for battle, but a solemn power to defy death.",["race:Dwarf"]="Seeing a fellow dwarf laid low in human lands is a sobering reminder that Defias outlaws pose a deadly threat to travelers of every race, not just the locals of Stormwind."},kw={"defias","elwynn forest","gazin tenorm","henze faulk","heroes' vigil","resurrection","symbol of life","tome of divinity"},rel={"npc:gazin-tenorm","quest:1641","subzone:heroes-vigil","zone:elwynn","topic:defias-brotherhood","topic:dwarf"},src={"Henze Faulk"}}
E["npc:hogger"] = {t="npc",n="Hogger",z="elwynn",s="Hogger is the vicious chieftain of the Riverpaw gnolls prowling southwestern Elwynn Forest. Towering over his kin and remarkably aggressive, he has become notorious for raiding local farms and butchering unsuspecting travelers. His violent rampages have earned him an official bounty from the Stormwind Marshals.",h="Hogger is the vicious chieftain of the Riverpaw gnolls prowling southwestern Elwynn Forest.",sec={{t="Terror of the Riverpaw",b="Prowling atop Hogger Hill in southwestern Elwynn Forest, Hogger commands the local Riverpaw pack with unmatched savagery. In the years following the Third War, gnoll raids across local homesteads grew increasingly bold and coordinated. Behind this rise in violence lies an unsettling alliance: the Riverpaw have begun colluding with the Defias Brotherhood, trading raw ferocity for arms, tactical direction, and magical support. To safeguard Elwynn's borders and protect trade routes from further bloodshed, Marshal Dughan has posted a generous bounty on Hogger's head.",sp=0}},faq={{q="Who is Hogger?",a="Hogger is a massive, exceptionally dangerous gnoll who leads the Riverpaw pack in southwestern Elwynn Forest. Known for raiding nearby farmsteads, he is wanted dead by Stormwind authorities for his brutal attacks on human settlements.",al={"hogger lore","who is hogger","riverpaw leader"}},{q="Why is there a bounty on Hogger?",a="Marshal Dughan and the Stormwind guard issued an official bounty on Hogger due to his escalating raids on rural farms and travelers. Anyone daring enough to end his rampage must bring his huge claw back to Goldshire as proof of the deed.",al={"wanted hogger","why kill hogger","hogger bounty"}},{q="Are the Riverpaw gnolls working with the Defias Brotherhood?",a="Yes. The Defias Brotherhood has been conspiring with the Riverpaw pack, supplying the brutish gnolls with refined weaponry, tactical guidance, and mystical support to further destabilize Stormwind's grip on the region.",al={"hogger defias","gnoll defias connection","riverpaw defias"}},{q="Where does Hogger make his camp?",a="Hogger resides atop Hogger Hill in the southwestern reaches of Elwynn Forest, surrounded by his loyal Riverpaw packmates near the border of Westfall.",al={"hogger location","where is hogger","hogger hill"}}},ang={["race:Human"]="For young defenders of Stormwind, confronting Hogger is an early trial by fire and a direct response to the threats destabilizing Elwynn's heartland.",["faction:Alliance"]="Hogger's raids demonstrate how stretched thin the Stormwind army is, forcing the Marshals to rely on roaming adventurers to maintain order near the capital."},kw={"bounty","defias","dughan","elwynn","gnoll","goldshire","hogger","riverpaw"},rel={"quest:176","topic:riverpaw-pack","zone:elwynn","subzone:hogger-hill","npc:marshal-dughan","topic:defias-brotherhood","subzone:goldshire","topic:gnoll"},src={"Hogger"}}
E["npc:katie-hunter"] = {t="npc",n="Katie Hunter",z="elwynn",s="Katie Hunter is a horse breeder stationed at the stables in the Eastvale Logging Camp within eastern Elwynn Forest. She provides trained riding horses and steeds to citizens of Stormwind and trusted champions of the Alliance. Alongside her relative Randal Hunter, she ensures travelers and soldiers have reliable mounts to navigate the kingdom's roads.",h="Katie Hunter is a horse breeder stationed at the stables in the Eastvale Logging Camp within eastern Elwynn...",sec={{t="Stables of Eastvale",b="Tucked away in the quiet, wooded clearings of the Eastvale Logging Camp, Katie Hunter manages the kingdom's primary horse stock for aspiring riders in Elwynn Forest. While the lumberjacks harvest timber for Stormwind's reconstruction, Katie tends to the stables, raising a variety of dependable breeds including pintos, mares, and swift steeds. Her stock represents the classic equestrian tradition of the kingdom, offering faithful companions capable of braving dangerous roads across southern Azeroth.",sp=0}},faq={{q="Who is Katie Hunter?",a="Katie Hunter is the horse breeder and mount vendor for the Kingdom of Stormwind, located at the stables of the Eastvale Logging Camp in Elwynn Forest.",al={"katie hunter elwynn","who is katie hunter","katie hunter horse vendor"}},{q="Where can I find Katie Hunter?",a="She is located in the northern section of the Eastvale Logging Camp, tending the corral and stables near riding trainer Randal Hunter in eastern Elwynn Forest.",al={"katie hunter location","where is katie hunter","find katie hunter"}},{q="Can non-humans buy horses from her?",a="Yes, but only if they have earned an exalted reputation with the Kingdom of Stormwind. Human adventurers can purchase her horses without any special standing.",al={"dwarf buy horse","night elf horse mount","stormwind reputation mount"}},{q="What horses does she sell?",a="Katie provides standard riding horses—including pinto, brown, and chestnut varieties—as well as swift, armored steeds such as the Swift Palomino, Swift Brown Steed, and Swift White Steed.",al={"what mounts does katie sell","katie hunter horse types"}}},ang={["race:Human"]="For human travelers, Katie's stables represent a natural rite of passage, offering classic Stormwind horses as soon as you have mastered the basics of horsemanship.",["faction:Alliance"]="Allied races who earn high standing and respect with the court of Stormwind can earn the privilege of riding Katie's prized steeds into battle."},kw={"eastvale","elwynn forest","horse vendor","katie hunter","logging camp","mounts","stables","stormwind"},rel={"subzone:eastvale-logging-camp","zone:elwynn","topic:stormwind-kingdom","quest:7677","quest:7678"},src={"Katie Hunter"}}
E["npc:khelden-bremen"] = {t="npc",n="Khelden Bremen",z="elwynn",s="Khelden Bremen is a human mage and instructor stationed on the upper floor of Northshire Abbey in Elwynn Forest. He oversees the earliest instruction of novice spellcasters who take up the arcane arts in service to Stormwind.",h="Khelden Bremen is a human mage and instructor stationed on the upper floor of Northshire Abbey in Elwynn...",sec={{t="Tutor of the Arcane",b="Situated within the tranquil stone walls of Northshire Abbey, Khelden Bremen acts as the primary instructor for fledgling human mages. While the clergy and defenders handle martial and spiritual pursuits below, Bremen maintains a quiet study upstairs. Here, he introduces novices to the discipline, focus, and fundamental techniques required to weave raw magical energy safely before they venture out into Elwynn Forest and beyond to Stormwind's Mage Quarter.",sp=0}},faq={{q="Who is Khelden Bremen?",a="Khelden Bremen is the resident mage trainer at Northshire Abbey in Elwynn Forest. He guides newly awakened mages through their first spells and foundational arcane studies.",al={"who is khelden","bremen","mage trainer northshire"}},{q="Where can I find Khelden Bremen?",a="He is located on the second floor of Northshire Abbey. Enter the abbey and head up the staircase found in the second room on the left.",al={"where is khelden","khelden bremen location","northshire mage trainer location"}},{q="What role does he play for new adventurers?",a="Aspiring human mages are directed to Khelden upon arriving in Northshire, often bearing a Glyphic Letter of introduction. He teaches essential early spells and helps novices harness their magical aptitude.",al={"what does khelden do","bremen quests","glyphic letter recipient"}}},ang={["class:Mage"]="For human mages, Khelden Bremen represents the first formal step into arcane scholarship before continuing advanced training in the towers of Stormwind City."},kw={"arcane","elwynn forest","glyphic letter","khelden bremen","mage trainer","northshire abbey"},rel={"subzone:northshire-abbey","quest:3104","zone:elwynn"},src={"Khelden Bremen"}}
E["npc:ma-stonefield"] = {t="npc",n="Ma Stonefield",z="elwynn",s="Ma Stonefield is a human matriarch residing at the Stonefield Farm in western Elwynn Forest. Standing right outside the family homestead alongside Auntie Bernice, she deals with the daily hardships of rural farm life amidst neighboring rivalries and pest troubles.",h="Ma Stonefield is a human matriarch residing at the Stonefield Farm in western Elwynn Forest.",sec={{t="Homestead Troubles",b="Standing beside her family cottage in southwestern Elwynn Forest, Ma Stonefield watches over the farmstead alongside \"Auntie\" Bernice Stonefield. Life between the neighboring Maclure homestead and the nearby pumpkin patches is rarely peaceful. Local wild boars continuously threaten the family crops, and none poses a greater nuisance than Princess, an enormous prize sow notorious for trampling fields and devouring hard-earned harvests.",sp=0}},faq={{q="Who is Ma Stonefield?",a="Ma Stonefield is one of the resident elders of the Stonefield family, living at their farmstead in southwestern Elwynn Forest alongside relatives like Auntie Bernice.",al={"who is ma stonefield","ma stonefield","stonefield mother"}},{q="Where can I find Ma Stonefield?",a="She can be found standing outdoors directly in front of the main house at the Stonefield Farm, located west of Goldshire in Elwynn Forest.",al={"ma stonefield location","where is ma stonefield","stonefield farm loc"}},{q="What problem does Ma Stonefield need solved?",a="Ma Stonefield seeks adventurers to put an end to Princess, a massive prize pig that repeatedly rampages through the surrounding fields and devours the local crops.",al={"ma stonefield quest","princess sow quest","princess must die questgiver"}}},ang={["faction:Alliance"]="For Alliance adventurers exploring Elwynn Forest, aiding hardworking homesteaders like Ma Stonefield helps preserve Stormwind's agricultural backbone."},kw={"bernice stonefield","elwynn forest","ma stonefield","princess","princess must die","stonefield farm"},rel={"subzone:stonefield-farm","npc:auntie-bernice-stonefield","quest:330","zone:elwynn"},src={"Ma Stonefield"}}
E["npc:marshal-dughan"] = {t="npc",n="Marshal Dughan",z="elwynn",s="Marshal Dughan is the commanding officer of the Stormwind Army detachment stationed in Goldshire. Tasked with protecting the heart of Elwynn Forest, he finds his local garrison stretched thin against growing incursions of kobolds, gnolls, and bandits. To keep the crossroads town and surrounding farmsteads safe, he relies heavily on independent adventurers.",h="Marshal Dughan is the commanding officer of the Stormwind Army detachment stationed in Goldshire.",sec={{t="Commander of the Crossroads",b="Stationed prominently in Goldshire outside the Lion's Pride Inn, Marshal Dughan bears the heavy burden of keeping Elwynn Forest secure while Stormwind's military resources are tied up elsewhere. The surrounding woods are steadily deteriorating: vermin choke the mines, gnolls mass along the riverbanks, and highwaymen harass travelers along the King's Road. With too few footmen under his direct command, Dughan orchestrates local defense by directing fresh recruits to reinforce outposts and scout contested ground.",sp=0},{t="Threats on Every Border",b="Dughan's immediate concerns lie with the kobold infestations overrunning Fargodeep and Jasperlode Mines, threatening Goldshire's vital mineral output. To the west, Riverpaw gnolls led by the notorious Hogger press hard against Westbrook Garrison. To the east, Dughan is forced to confront reports from Guard Thomas concerning vicious murlocs slaughtering patrols along the river. Managing these overlapping crises with limited manpower keeps the marshal in constant need of capable mercenaries.",sp=0}},faq={{q="Who is Marshal Dughan?",a="Marshal Dughan is an officer of the Stormwind Army stationed in Goldshire. He oversees military security for central Elwynn Forest, coordinating defense efforts against local threats such as thieves, gnolls, and kobolds.",al={"dughan","marshal dughan lore","goldshire marshal"}},{q="Why doesn't Dughan send more guards to help Westbrook Garrison or the east?",a="The Stormwind Army is spread thin, leaving Dughan with barely enough guards to maintain order in Goldshire itself. Because he lacks the standing manpower to garrison every outlying farm and border post, he relies on visiting adventurers to scout hot spots, deliver dispatches, and eliminate regional dangers.",al={"why no guards","goldshire garrison strength","dughan troops"}},{q="What is Dughan's view on the murloc threat in Elwynn?",a="Initially, Dughan dismissed warnings from Remy 'Two Times' that murlocs were a serious threat to the region. He only recognized the true peril after Guard Thomas sent tragic reports confirming the deaths of guardsmen Rolf Hartford and Malakai Stone along the eastern waterways.",al={"dughan murlocs","remy two times murloc","dughan fish men"},sp=1},{q="How does Dughan handle local crime and rowdy civilians?",a="Dughan enforces the law strictly but gives fair warning before throwing citizens behind bars. When locals or travelers cause public disturbances in Goldshire, he warns them that continuing to pick fights will land them directly in Stormwind's Stockade, and he will actively hunt them down if they commit murder.",al={"dughan crime","goldshire law","stockade threat"}},{q="Why is Dughan concerned about the mines?",a="Fargodeep Mine and Jasperlode Mine are essential sources of gold and ore for Stormwind. Kobolds have overrun both subterranean complexes, driving out the miners and threatening to expand their tunnels directly under Elwynn's settlements.",al={"fargodeep mine dughan","jasperlode mine dughan","kobold infestation"}},{q="Does Marshal Dughan coordinate with Westfall?",a="Yes. Once an adventurer proves their capability in Elwynn Forest, Marshal Dughan directs them to Westfall to report to Gryan Stoutmantle at Sentinel Hill, where the People's Militia desperately needs veteran help against the Defias Brotherhood.",al={"dughan gryan","report to westfall","dughan sentinel hill"}}},ang={["faction:Alliance"]="Marshal Dughan represents the frontline administrative authority for the Alliance in Elwynn, providing newly arrived recruits with their earliest military assignments on behalf of Stormwind.",["class:Warrior"]="For martial fighters, Dughan embodies the standard discipline and logistical strain of Stormwind's military footmen holding the line against impossible odds."},kw={"elwynn forest","fargodeep","goldshire","hogger","jasperlode","marshal dughan","stormwind army","westbrook garrison"},rel={"subzone:goldshire","zone:elwynn","npc:guard-thomas","npc:remy-two-times","quest:176","subzone:westbrook-garrison","npc:gryan-stoutmantle","topic:stormwind-army"},src={"Marshal Dughan"}}
E["npc:marshal-mcbride"] = {t="npc",n="Marshal McBride",z="elwynn",s="Marshal Douglas McBride is the commander of the Stormwind garrison stationed at Northshire Abbey. Tasked with the defense of Northshire Valley, he directs freshly arrived recruits against the rising kobold infestation threatening local farms and mines. He serves as the primary military authority for newcomers beginning their service to the kingdom of Stormwind.",h="Marshal Douglas McBride is the commander of the Stormwind garrison stationed at Northshire Abbey.",sec={{t="Commander of Northshire",b="Stationed right outside Northshire Abbey, Marshal Douglas McBride represents the direct authority of the Stormwind Army in this quiet valley. While the abbey itself is an enclave of faith and learning, rising turmoil across the kingdom has stretched military garrisons thin. McBride must maintain peace and secure the valley's food and resource supplies with only a handful of sworn guards and an influx of green recruits seeking training under the abbey's masters.",sp=0},{t="The Kobold Incursion",b="McBride's primary headache is the sudden aggression of local vermin. Kobolds, once merely a nuisance, have overrun the surrounding woods and seized Echo Ridge Mine—a vital local asset. Lacking the regular soldiers needed to clear them out, McBride marshals paladins, warriors, and other novices to push back the tunneling pests and uncover the extent of the infestation before the valley is completely choked off.",sp=0}},faq={{q="Who is Marshal McBride?",a="Marshal Douglas McBride is an officer of the Stormwind Army stationed as the garrison commander at Northshire Abbey. He is in charge of defending Northshire Valley and directing new recruits into service.",al={"marshal mcbride","who is mcbride","northshire commander"}},{q="Why is McBride having recruits fight kobolds?",a="Kobolds have infested the forests around Northshire and seized control of Echo Ridge Mine. With Stormwind's military stretched thin, McBride relies on newly arrived adventurers to clear the vermin and secure the area.",al={"why kill kobolds","kobold problem","echo ridge problem"}},{q="Where does McBride send recruits next?",a="Once a recruit has demonstrated their capability by dealing with the threats in Northshire Valley, McBride directs them down the southern road to Goldshire to assist Marshal Dughan.",al={"where do i go after mcbride","after northshire","next town"}},{q="What is Echo Ridge Mine?",a="Echo Ridge Mine is a mineral-rich cavern located on the northern edge of Northshire Valley. It has recently been overrun by tunneling kobolds, prompting McBride to order several operations to reclaim it.",al={"echo ridge","the mine in northshire"}},{q="Does McBride command the abbey itself?",a="No. Northshire Abbey is maintained by the holy orders and priests of the Light. McBride oversees the military garrison tasked with defending the abbey and the surrounding valley.",al={"does mcbride lead northshire abbey","who is in charge of the abbey"}},{q="Is McBride concerned about threats beyond kobolds?",a="While kobolds are the most immediate nuisance, McBride watches for deeper instability. Bandits and outlaws hover at the fringes of the valley, signaling broader unrest brewing across Elwynn Forest.",al={"defias in northshire","is northshire safe"}}},ang={["race:Human"]="For humans beginning their adventures in Northshire, Marshal McBride is the first representative of Stormwind's royal authority they encounter.",["class:Warrior"]="McBride actively seeks out sturdy fighters to serve the kingdom, relying on frontline warriors to clear out the tunnels of Echo Ridge.",["faction:Alliance"]="McBride represents the starting frontier of the Grand Alliance in the heartland of humanity, inducting recruits into service of the Crown."},kw={"douglas mcbride","echo ridge","elwynn","kobold","marshal mcbride","northshire","northshire abbey"},rel={"subzone:northshire-abbey","subzone:northshire-valley","subzone:echo-ridge-mine","zone:elwynn","topic:stormwind-army","quest:15","quest:21","subzone:goldshire"},src={"Marshal McBride"}}
E["npc:maybell-maclure"] = {t="npc",n="Maybell Maclure",z="elwynn",s="Maybell Maclure is a young woman living at the Maclure Vineyards in Elwynn Forest. Despite a bitter, long-standing feud between her family and the neighboring Stonefields, she has secretly fallen in love with Tommy Joe Stonefield.",h="Maybell Maclure is a young woman living at the Maclure Vineyards in Elwynn Forest.",sec={{t="Star-Crossed in the Vineyards",b="Life on the Maclure Vineyards is defined by endless labor and an enduring grudge against the neighboring Stonefield family. Caught in the middle is Maybell Maclure, who has fallen deeply in love with Tommy Joe Stonefield, the young heir to the rival farmstead. Kept apart by vigilant relatives and ancient family resentment, Maybell is desperate for any chance to communicate with Tommy Joe beyond the prying eyes of her kin.",sp=0},{t="A Concoction for True Love",b="Unable to cross the boundary between the farms openly, Maybell relies on sympathetic travelers and the guidance of Gramma Stonefield. With the aid of Goldshire's local alchemist, William Pestle, an invisibility liquor is brewed. By drinking this illicit draught, Maybell can slip away from the Maclure homestead unseen and steal precious moments with Tommy Joe down by the riverbank.",sp=1}},faq={{q="Why can't Maybell and Tommy Joe see each other?",a="The Maclure and Stonefield families have harbored a bitter rivalry for years. Because both households forbid any contact between the clans, Maybell and Tommy Joe must keep their romance an absolute secret or face the wrath of their kin.",al={"why family feud","maclure stonefield feud","why cant they be together"}},{q="How does Maybell manage to escape the vineyard?",a="With the advice of Gramma Stonefield, adventurer allies consult the alchemist William Pestle in Goldshire. Pestle brews an invisibility draught that allows Maybell to slip past her watchful family and slip away to the river to meet Tommy Joe.",al={"how does maybell sneak out","invisibility potion elwynn","how does she meet tommy"},sp=1},{q="Where does Maybell meet Tommy Joe?",a="Tommy Joe waits along the riverbank on the border between the Maclure Vineyards and the Stonefield Farm, hidden from the direct view of both farmsteads.",al={"meeting spot","where are they meeting","where is tommy joe"}},{q="Who helps Maybell with her romance?",a="Gramma Stonefield proves sympathetic to the lovers' plight and directs willing adventurers to William Pestle, the alchemist in Goldshire, who provides the means for their clandestine tryst.",al={"who helps maybell","stonefield helpers"},sp=1}},ang={["faction:Alliance"]="For Alliance adventurers passing through Elwynn Forest, Maybell's romance is a reminder that personal troubles and ancient grudges persist even in the heartlands of the kingdom."},kw={"lovers","maclure","maybell","stonefield","tommy joe","vineyards"},rel={"npc:tommy-joe-stonefield","subzone:maclure-vineyards","subzone:stonefield-farm","npc:gramma-stonefield","npc:william-pestle","quest:114","quest:111","zone:elwynn"},src={"Maybell Maclure"}}
E["npc:merissa-stilwell"] = {t="npc",n="Merissa Stilwell",z="elwynn",s="Merissa Stilwell is a young human townsperson residing in Goldshire within Elwynn Forest. Standing right by the lamppost outside the Lion's Pride Inn, she offers a cheerful greeting and a helping hand to newcomers arriving from Northshire.",h="Merissa Stilwell is a young human townsperson residing in Goldshire within Elwynn Forest.",sec={{t="A Welcoming Face in Goldshire",b="Positioned just outside the bustling Lion's Pride Inn, Merissa Stilwell greets fresh travelers making their way into town from Northshire Valley. For wandering novices, she offers simple hospitality and practical advice on resting up and getting oriented. Sharing a surname with notable craftsmen and homesteaders across the kingdom—such as the blacksmith Jordan Stilwell and the Westfall defender Daphne Stilwell—she remains a peaceful local face amidst the kingdom's rising tensions.",sp=0}},faq={{q="Who is Merissa Stilwell?",a="Merissa is a friendly human resident of Goldshire. She stands near the streetlamp outside the Lion's Pride Inn, offering advice and a warm welcome to travelers entering the hamlet.",al={"merissa stilwell","who is merissa","stilwell girl goldshire"}},{q="Where can I find Merissa Stilwell?",a="She is located in central Goldshire in Elwynn Forest, standing next to a lamppost directly outside the front entrance of the Lion's Pride Inn.",al={"merissa stilwell location","where is merissa","find merissa"}},{q="Is Merissa related to the other Stilwells in the kingdom?",a="While she shares her surname with prominent figures like the smith Jordan Stilwell and Daphne Stilwell in Westfall, she lives quietly in Goldshire, welcoming travelers rather than fighting bandits or forging blades.",al={"stilwell family","daphne stilwell relative","jordan stilwell relative"}},{q="Does Merissa Stilwell offer any quests?",a="Yes, she assists new arrivals through the brief introductory task 'Welcome!', directing them to visit the local tavern and speak with the innkeeper.",al={"merissa quests","merissa stilwell quest"}}},ang={["faction:Alliance"]="For Alliance recruits leaving the sheltered cloister of Northshire, Merissa represents the warm hospitality of Elwynn before the harsh realities of the Defias threat set in."},kw={"elwynn","goldshire","inn","lion's pride","merissa","stilwell","welcome"},rel={"subzone:goldshire","subzone:lion-s-pride-inn","quest:5805","zone:elwynn","npc:jordan-stilwell","npc:daphne-stilwell"},src={"Merissa Stilwell"}}
E["npc:morgan-pestle"] = {t="npc",n="Morgan Pestle",z="elwynn",s="Morgan Pestle is a human alchemist and shopkeeper who runs Pestle's Apothecary in the Trade District of Stormwind City. Working closely with his brother William Pestle in Goldshire, he handles supplies and alchemical research for the capital.",h="Morgan Pestle is a human alchemist and shopkeeper who runs Pestle's Apothecary in the Trade District of...",sec={{t="The City Apothecary",b="Operating out of Pestle's Apothecary along the busy thoroughfares of Stormwind's Trade District, Morgan Pestle provides alchemical goods, reagents, and practical remedies to city residents and passing travelers. While his brother William maintains a workshop at the Lion's Pride Inn in Goldshire, Morgan keeps the family trade rooted in the heart of the kingdom's capital, managing shipments of herbs and compounds back and forth from the rural heartlands.",sp=0}},faq={{q="Where can I find Morgan Pestle?",a="Morgan Pestle is located inside Pestle's Apothecary, a shop in the Trade District of Stormwind City.",al={"morgan pestle location","where is morgan pestle","pestle apothecary stormwind"}},{q="How is Morgan Pestle related to William Pestle?",a="Morgan and William Pestle are brothers. Both work as alchemists in Elwynn, with Morgan running their shop in Stormwind and William working out of Goldshire.",al={"william pestle brother","are william and morgan related","pestle brothers"}},{q="What role does he play in Elwynn quests?",a="Morgan serves as the recipient for shipments and alchemical supplies sent northward from Goldshire by his brother William, connecting local herb harvesting with city commerce.",al={"shipment to stormwind morgan","morgan pestle quest"}}},ang={["profession:Herbalism"]="Morgan relies heavily on fresh ingredients gathered across Elwynn Forest and beyond to supply his apothecary shop in the Trade District.",["faction:Alliance"]="For Alliance adventurers arriving in Stormwind from Elwynn, Morgan's shop is an essential stop for practical alchemical needs and local city deliveries."},kw={"alchemist","morgan pestle","pestle apothecary","shipment to stormwind","stormwind","trade district","william pestle"},rel={"npc:william-pestle","subzone:trade-district","zone:stormwind","quest:61","zone:elwynn"},src={"Morgan Pestle"}}
E["npc:morgan-the-collector"] = {t="npc",n="Morgan the Collector",z="elwynn",s="Morgan the Collector is a high-ranking Defias operative overseeing the Brotherhood's extortion and gathering activities across Elwynn Forest. Based in the overrun Brackwell Pumpkin Patch, he coordinates local thievery right under the nose of the Goldshire guard.",h="Morgan the Collector is a high-ranking Defias operative overseeing the Brotherhood's extortion and gathering...",sec={{t="The Tithe of Elwynn",b="Morgan earned his epithet by squeezing the outlying farms of Elwynn Forest on behalf of the Defias Brotherhood. While common bandits harass wayfarers along the roads, Morgan directs organized shakedowns and collects stolen coin and supplies to funnel deeper into the Brotherhood's network. He has made his headquarters inside the farmhouse at the Brackwell Pumpkin Patch, surrounded by loyal enforcers including Surena Caledon and Erlan Drudgemoor.",sp=0},{t="A Signet of the Past",b="Morgan's operations are not just simple street crimes; he carries a distinct signet ring that marks his authority. To investigators in Goldshire, this band offers hard evidence tying the masked thieves terrorizing the heartland back to the disgraced Stonemasons Guild that rebuilt Stormwind City after the First and Second Wars. Recovering his ring pierces the mystery behind who actually directs the bandits in the woods.",sp=1}},faq={{q="Who is Morgan the Collector?",a="He is an officer in the Defias Brotherhood responsible for extorting wealth and supplies from Elwynn Forest's farms and coordinating bandit activity in the region.",al={"who is morgan","morgan lore","collector in elwynn"}},{q="Where is Morgan found?",a="He hoards his stolen goods inside the abandoned farmhouse at the Brackwell Pumpkin Patch, located in eastern Elwynn Forest.",al={"morgan location","where is morgan the collector","brackwell pumpkin patch house"}},{q="Why is Stormwind hunting him?",a="Marshal Dughan and local authorities want Morgan eliminated to sever Defias leadership in Elwynn and recover proof of who is organizing the rural uprisings.",al={"why kill morgan","manhunt target"}},{q="What is special about the ring he carries?",a="His signet ring provides direct physical evidence linking the Defias bandits in Elwynn Forest to the former Stonemasons Guild of Stormwind.",al={"collectors ring","collector signet ring","morgan ring lore"},sp=1}},ang={["class:Rogue"]="Morgan shows how organized criminal discipline turns disjointed thieves into a functional, underground syndicate capable of funding an insurgency.",["race:Human"]="Taking down Morgan strikes back against the traitors who have turned Stormwind's peaceful farms into fortified bandit dens."},kw={"brackwell","brotherhood","defias","dughan","manhunt","morgan","pumpkin patch","signet","the collector"},rel={"quest:147","subzone:brackwell-pumpkin-patch","topic:defias-brotherhood","topic:stonemasons-guild","npc:marshal-dughan","quest:1688","zone:elwynn","topic:stormwind-kingdom"},src={"Morgan the Collector"}}
E["npc:priestess-anetta"] = {t="npc",n="Priestess Anetta",z="elwynn",s="Priestess Anetta is a human cleric of the Holy Light stationed inside Northshire Abbey. As a member of the Brotherhood of Northshire, she tends to wounded trainees and instructs newly arrived priests in their first sacred rites.",h="Priestess Anetta is a human cleric of the Holy Light stationed inside Northshire Abbey.",sec={{t="Tender of the Faithful",b="Priestess Anetta can be found on the ground floor of Northshire Abbey within its quiet library wing. Amid the threat of Defias bandits and encroaching blackrock orcs pressing into the valley, Anetta works tirelessly to care for injured recruits brought back from the field. She serves as a grounding presence for the Brotherhood of Northshire, ensuring that those fighting to defend the abbey are restored in body and spirit through the grace of the Holy Light.",sp=0},{t="Guiding Novice Priests",b="Beyond her duties as a field healer within the cloister, Anetta acts as the primary mentor for budding human priests. Novices who arrive with a hallowed letter of introduction seek her out to learn the fundamentals of faith: channeling holy words to mend flesh and unleashing smiting radiance to repel evil. Under her tutelage, young acolytes prepare to carry the Light beyond Northshire's secluded walls.",sp=0}},faq={{q="Who is Priestess Anetta?",a="Priestess Anetta is a human priest trainer and healer belonging to the Brotherhood of Northshire. She resides on the ground floor of Northshire Abbey in the library wing, where she aids wounded soldiers and mentors novice priests.",al={"who is anetta","priestess anetta lore","priestess anetta northshire"}},{q="Where can I find Priestess Anetta?",a="She is located inside Northshire Abbey in northern Elwynn Forest. Enter the front gates of the abbey, proceed into the main hall, and look to the ground floor of the library wing.",al={"where is priestess anetta","anetta location","find anetta"}},{q="What role does she play in the Abbey's defense?",a="While Stormwind marshals and recruits fight to reclaim the valley from Defias bandits and kobolds, Anetta provides vital medical care. She treats wounded trainees brought back to the abbey and calls upon the Light to mend their injuries.",al={"what does anetta do","anetta role"}},{q="What training does she offer?",a="Anetta teaches entry-level clerical spells and prayers to young priests, instructing them in the fundamentals of healing and smiting enemies in the name of the Holy Light.",al={"can anetta teach me spells","anetta priest spells"}}},ang={["class:Priest"]="For young human priests starting in Northshire, Priestess Anetta is your very first mentor, validating your holy calling and teaching you how to commune directly with the Light.",["faction:Alliance"]="Anetta represents the enduring spiritual core of the Alliance, ensuring recruits injured defending Northshire Valley survive to continue the fight."},kw={"anetta","brotherhood of northshire","elwynn forest","holy light","library wing","northshire abbey","priest trainer","priestess anetta"},rel={"subzone:northshire-abbey","topic:brotherhood-of-northshire","topic:light","subzone:library-wing-northshire","quest:3103","quest:5623","zone:elwynn","topic:alliance"},src={"Priestess Anetta"}}
E["npc:priestess-josetta"] = {t="npc",n="Priestess Josetta",z="elwynn",s="Priestess Josetta is a human priest trainer stationed on the upper floor of the Lion's Pride Inn in Goldshire. Dedicated to guiding novices of the Holy Light beyond their initial trials in Northshire, she mentors young priests in faith, devotion, and practical ministry.",h="Priestess Josetta is a human priest trainer stationed on the upper floor of the Lion's Pride Inn in Goldshire.",sec={{t="A Beacon in Goldshire",b="While many who take holy vows spend their days within grand cathedrals or cloistered monasteries, Priestess Josetta ministers directly among the common folk of Elwynn Forest. From her modest quarters upstairs in the bustling Lion's Pride Inn, she attends to the spiritual health of travelers, guards, and local laborers alike, demonstrating that service to the Holy Light requires presence wherever hearts need solace.",sp=0},{t="Guiding Young Acolytes",b="Josetta plays a vital role for budding priests who have completed their initial studies at Northshire Abbey. She instructs them in the practical realities of their calling, sending them into the surrounding countryside to aid wounded guards and comfort the afflicted. Through these tasks, she emphasizes that clerical duties are not merely about learning words of prayer, but actively channeling the Light to mend a broken world.",sp=0},{t="A Quiet Regret",b="Despite her steady devotion, Josetta carries a touch of wistfulness regarding her life's choices. In her youth, she lacked the courage to step onto the wider roads and explore Azeroth, choosing instead the safety of familiar ground. Though content in her sacred service in Goldshire, she often urges the young disciples who cross her threshold to be bolder than she was and take their faith to distant frontiers.",sp=0}},faq={{q="Where can I find Priestess Josetta?",a="Priestess Josetta resides on the second floor of the Lion's Pride Inn in Goldshire, located in the central upstairs room alongside Michelle Belle.",al={"josetta location","where is priestess josetta","goldshire priest trainer location"}},{q="What role does Priestess Josetta serve?",a="She is a priest trainer for the Alliance, instructing novice priests in holy spells, discipline, and the responsibilities of their sacred calling as they venture forth from Northshire.",al={"what does josetta do","priestess josetta role"}},{q="Why does Josetta operate out of an inn instead of a church?",a="Goldshire does not have a standalone chapel, so the Lion's Pride Inn functions as the town center. Stationing herself upstairs allows Josetta to tend to weary travelers, injured town guards, and local residents directly.",al={"why in an inn","why lions pride inn"}},{q="What personal regret does Josetta share with disciples?",a="She admits that when she was younger, she never mustered the courage to leave home and travel the world, and she encourages young adventurers to explore beyond the borders of Elwynn.",al={"josetta backstory","josetta travel regret"}},{q="What kind of duties does Josetta assign to new priests?",a="Josetta directs acolytes to tend to wounded defenders in the field, teaching them how to mend injuries with healing prayers and reinforcing that the Light must be carried directly to those in need.",al={"josetta quests","garments of the light quest"}},{q="Does Josetta teach racial priest spells?",a="Yes, as a human priestess in Elwynn, she introduces human priests to specialized prayers favored by their people, such as Desperate Prayer.",al={"desperate prayer trainer","human priest spells"}}},ang={["class:Priest"]="Josetta is an essential early mentor for young priests leaving Northshire, offering core spell training and guidance on putting vows of healing into practical service.",["race:Human"]="Human priests will find familiar Church of the Light teachings in Josetta's counsel, as she helps initiate them into their ancestral prayer traditions.",["faction:Alliance"]="Josetta strengthens the Alliance's backbone in Elwynn, ensuring local defenders have the spiritual and healing support necessary to guard the heartland."},kw={"desperate prayer","elwynn forest","goldshire","holy light","josetta","lion's pride inn","priest trainer","priestess josetta"},rel={"subzone:lion-s-pride-inn","subzone:goldshire","zone:elwynn","topic:light","quest:5624","quest:5634","quest:5623","quest:5628"},src={"Priestess Josetta"}}
E["npc:remy-two-times"] = {t="npc",n="Remy \"Two Times\"",z="elwynn",s="Remy \"Two Times\" is a human merchant currently residing in the village of Goldshire. Originally hailing from the Redridge Mountains, he is easily recognized by his peculiar habit of repeating the ends of his sentences. He maintains business interests across Elwynn Forest, trading goods and paying adventurers for raw materials like gold dust.",h="Remy \"Two Times\" is a human merchant currently residing in the village of Goldshire.",sec={{t="A Merchant with an Odd Quirk",b="Operating out of Goldshire, Remy \"Two Times\" is an enterprising trader who made his way west from the rugged terrain of the Redridge Mountains. True to his moniker, Remy possesses a distinctive verbal tick: repeating the final words of his sentences, usually twice. Despite his comical speech pattern, he remains a savvy merchant looking to turn a profit amid the growing troubles in Elwynn Forest, readily striking deals with traveling adventurers.",sp=0},{t="Business in Troubled Waters",b="With kobolds overrunning the local gold mines and aggressive murlocs infesting the riverbanks, normal commerce in Elwynn has been heavily disrupted. Remy seizes opportunity where others see disaster, commissioning adventurers to bring him pouchfuls of gold dust gathered from the vermin infesting the mines, as well as keeping tabs on suspicious murloc movements near Crystal Lake.",sp=0}},faq={{q="Why is he called 'Two Times'?",a="Remy earned his nickname because of an unusual conversational tick where he habitually repeats the final words of his sentences twice whenever he speaks.",al={"remy two times name","why does remy repeat words","two times meaning"}},{q="Where does Remy come from originally?",a="He traveled to Goldshire from the Redridge Mountains to conduct trade in the heartland of Elwynn Forest.",al={"remy origin","where is remy from"}},{q="What does Remy do with all the gold dust he buys?",a="As an opportunistic merchant, Remy collects gold dust scavenged from kobolds in local mines to smelt, trade, or resell for a tidy profit in the local economy.",al={"why does remy want gold dust","gold dust exchange lore"}},{q="Where can Remy be found in Goldshire?",a="Remy stands outdoors in Goldshire in Elwynn Forest, near the Lion's Pride Inn, ready to barter with passing travelers.",al={"where is remy two times","remy location goldshire"}}},ang={["profession:Mining"]="Miners working the Fargodeep and Jasperlode mines often cross paths with Remy, who happily barters for the gold dust collected from the infesting kobolds.",["faction:Alliance"]="For fresh Alliance recruits arriving in Goldshire, Remy provides straightforward tasks that help clear local threats while offering some quick coin."},kw={"elwynn","gold dust","goldshire","merchant","murloc","redridge","remy","two times"},rel={"subzone:goldshire","zone:elwynn","quest:47","quest:40","zone:redridge"},src={"Remy \"Two Times\""}}
E["npc:sara-timberlain"] = {t="npc",n="Sara Timberlain",z="elwynn",s="Sara Timberlain is a skilled tailor residing at the Eastvale Logging Camp in eastern Elwynn Forest. Known for her resourceful needlework with salvaged fabrics, she assists the war effort by stitching cloth and leather armaments for the Stormwind Army.",h="Sara Timberlain is a skilled tailor residing at the Eastvale Logging Camp in eastern Elwynn Forest.",sec={{t="Needlework on the Frontier",b="Situated outside a small cottage on the western edge of the Eastvale Logging Camp, Sara Timberlain works tirelessly with needle and thread amidst the ambient noise of felling axes. Despite the remote nature of Eastvale and the looming threat of prowling wolves and murlocs, she provides hospitality and vital craftwork to travelers. Her talent for turning scraps of linen and salvaged bandanas into durable gear has earned her official recognition, securing commissions to supply protective cloth and leather armaments directly to Stormwind's military forces.",sp=0}},faq={{q="Who is Sara Timberlain?",a="Sara Timberlain is an accomplished seamstress living at the Eastvale Logging Camp in Elwynn Forest. She is renowned for crafting practical gear from reclaimed fabrics and holds contracts to supply the Stormwind Army.",al={"who is sara timberlain","sara timberlain","eastvale tailor"}},{q="Where can I find Sara Timberlain?",a="She can be found sitting outside a house on the western side of the Eastvale Logging Camp, situated in the far eastern reaches of Elwynn Forest along the road to Redridge.",al={"sara timberlain location","where is sara timberlain","timberlain house"}},{q="Why is Sara gathering cloth for the army?",a="The Stormwind Army relies on local crafters to maintain their equipment stockpiles. Sara uses salvaged cloth, such as linen collected by adventurers, to fashion sturdy garments and armor linings for the kingdom's soldiers.",al={"why does sara need linen","stormwind army armor","cloth and leather armor quest"}}},ang={["profession:Tailoring"]="Sara exemplifies the resourcefulness of frontier tailors, turning scraps of rough linen and bandit cloth into functional garments commissioned by the military.",["faction:Alliance"]="Outlying settlements like Eastvale directly sustain the kingdom's defense, with local craftspeople supplying basic armor to the under-resourced Stormwind Army."},kw={"eastvale","linen","logging camp","sara timberlain","seamstress","stormwind army","tailor"},rel={"subzone:eastvale-logging-camp","zone:elwynn","quest:59","quest:83","topic:stormwind-army","topic:stormwind-kingdom"},src={"Sara Timberlain"}}
E["npc:supervisor-raelen"] = {t="npc",n="Supervisor Raelen",z="elwynn",s="Supervisor Raelen oversees timber operations at the Eastvale Logging Camp on the eastern edge of Elwynn Forest. She is responsible for managing the local laborers, maintaining daily logging quotas, and ensuring that harvested lumber safely makes its way into Stormwind's supply chains.",h="Supervisor Raelen oversees timber operations at the Eastvale Logging Camp on the eastern edge of Elwynn...",sec={{t="Keeping the Camp on Schedule",b="Located in the heart of Eastvale Logging Camp near Marshal Patterson and the camp's wood wagons, Supervisor Raelen directs the labor force tasked with harvesting timber for the kingdom. Operating a lumber camp on the border of the Redridge Mountains carries significant logistical challenges, from coordinating weary woodcutters to dealing with wildlife and bandit interference that threatens production quotas. Despite the hazards of the surrounding woods, Raelen focuses squarely on getting timber gathered, processed, and bundled for transport.",sp=0}},faq={{q="Who is Supervisor Raelen?",a="Supervisor Raelen is a human overseer stationed at the Eastvale Logging Camp in eastern Elwynn Forest. She manages the camp's logging crews and makes sure their wood collection quotas are steadily met.",al={"who is raelen","raelen elwynn","eastvale supervisor"}},{q="Where can I find Supervisor Raelen?",a="She can be found in the center of Eastvale Logging Camp in eastern Elwynn Forest, standing near the loaded wood wagons alongside Marshal Patterson and the gryphon master Goss the Swift.",al={"where is raelen","supervisor raelen location","find raelen"}},{q="Why does Supervisor Raelen need help from adventurers?",a="Gathering timber around the edges of the forest has grown dangerous, and cut lumber bundles frequently get abandoned or scattered among the trees when workers face local wildlife or other disruptions.",al={"raelen quest","bundle of trouble quest","why help raelen"}},{q="What role does the Eastvale Logging Camp play in Elwynn Forest?",a="Eastvale is the primary logging operation in eastern Elwynn Forest, providing essential lumber to support the rebuilding and maintenance efforts across Stormwind and its neighboring settlements.",al={"what is eastvale","eastvale logging role","why is eastvale important"}}},ang={["faction:Alliance"]="Maintaining the kingdom's timber supplies is essential for keeping Stormwind's defenses and construction efforts funded, making Raelen's lumber quotas vital to the war effort."},kw={"a bundle of trouble","eastvale","eastvale logging camp","elwynn forest","lumber","raelen","supervisor raelen","wood quotas"},rel={"subzone:eastvale-logging-camp","quest:5545","zone:elwynn"},src={"Supervisor Raelen"}}
E["npc:theocritus"] = {t="npc",n="Theocritus",z="elwynn",s="Archmage Theocritus is an eccentric human wizard who resides at the peak of the Tower of Azora in eastern Elwynn Forest. Formerly affiliated with the Kirin Tor of Dalaran, he now lives independently, surrounded by servants and magical scrying devices. From his high sanctum, Theocritus directs his arcane talents toward keeping watch over the kingdom and combating his dark rival, the rogue mage Morganth.",h="Archmage Theocritus is an eccentric human wizard who resides at the peak of the Tower of Azora in eastern...",sec={{t="Master of the Tower",b="Once a member of Dalaran's prestigious Kirin Tor, Archmage Theocritus chose to establish an independent stronghold far to the south in the kingdom of Stormwind. He settled in the prominent Tower of Azora, situated near the eastern road to Redridge. Theocritus is known for his eccentric habits and comfortable lifestyle, employing an extensive household staff that includes numerous gnomish attendants and his own dedicated clothier, Morley Eberlein. Though he keeps himself largely detached from the mundane concerns of local villagers, his presence serves as a critical magical bulwark in eastern Elwynn.",sp=0},{t="The War Against Morganth",b="Theocritus's greatest ongoing concern is the fallen mage Morganth, a dangerous warlock operating from the Tower of Ilgalar in the nearby Redridge Mountains. Viewing Morganth both as a personal nemesis and a severe peril to Stormwind, Theocritus has dedicated months of arcane research to undermining him. Through scrying artifacts like the Eye of Azora, Theocritus monitors the villain's actions and delves into his thoughts. He also works to turn Morganth's own creations against him, studying the magical pendants carried by the Shadowhide gnolls in hopes of transmitting an arcane pulse that can immobilize the entire pack.",sp=0}},faq={{q="Who is Theocritus?",a="Archmage Theocritus is a former Kirin Tor wizard who makes his home in the Tower of Azora in eastern Elwynn Forest. He lives an eccentric, somewhat isolated life, focusing his arcane craft on safeguarding the region from dark magical threats.",al={"theocritus lore","who is the mage in the tower","tower of azora mage"}},{q="Why did Theocritus leave Dalaran?",a="While he once operated within the Kirin Tor alongside peers like Archmage Karlain, Theocritus chose to become an independent practitioner. He relocated to Elwynn Forest to pursue his own studies and maintain his personal sanctum at the Tower of Azora.",al={"is theocritus kirin tor","why is theocritus in elwynn","theocritus dalaran"}},{q="Who is Theocritus fighting against?",a="His chief rival is Morganth, a fallen human mage who has taken up dark magic in the Tower of Ilgalar across the border in Redridge. Theocritus sees Morganth as both an offensive personal foe and a dire threat to the safety of Stormwind.",al={"theocritus enemy","who is morganth","theocritus rival"}},{q="What is the Eye of Azora?",a="The Eye of Azora is a powerful scrying apparatus developed and housed by Theocritus atop his tower. He uses it to magically peer into distant lands, track threats, and even attempt to read the thoughts of his rival, Morganth.",al={"eye of azora lore","how does theocritus spy","theocritus crystal ball"}},{q="Why does Theocritus want Shadowhide gnoll pendants?",a="The Shadowhide gnolls serve Morganth and wear enchanted pendants tied to their master. Theocritus studies these trinkets to learn how their magical link operates, hoping to broadcast an arcane attack through the network to paralyze the gnolls in battle.",al={"gnoll pendants theocritus","theocritus retrieval","why collect gnoll pendants"}},{q="Who serves Theocritus in his tower?",a="Theocritus surrounds himself with an unusual household, including an entire retinue of gnomish servants who see to his daily affairs, as well as a personal clothier named Morley Eberlein who tends to his wardrobe.",al={"tower of azora staff","who lives in tower of azora","theocritus servants"}}},ang={["class:Mage"]="Theocritus represents the life of a wizard who operates outside Dalaran's strict hierarchy, demonstrating how solitary masters set up sanctums and conduct long-distance scrying.",["faction:Alliance"]="Though eccentric and aloof, Theocritus uses his arcane vision and resources to actively defend eastern Elwynn and Redridge from rogue spellcasters.",["race:Human"]="The conflict between Theocritus and Morganth mirrors the dual paths of human sorcery: disciplined scholarship dedicated to defense versus corruption and dark ambition."},kw={"archmage","elwynn forest","eye of azora","karlain","morganth","morley eberlein","shadowhide","theocritus","tower of azora"},rel={"subzone:tower-of-azora","quest:178","quest:94","quest:249","zone:elwynn","subzone:dalaran","topic:gnoll","topic:stormwind-kingdom"},src={"Theocritus"}}
E["npc:tommy-joe-stonefield"] = {t="npc",n="Tommy Joe Stonefield",z="elwynn",s="Tommy Joe Stonefield is a young farmer caught in a bitter family rivalry in the heart of Elwynn Forest. Deeply in love with Maybell Maclure, he must rely on quiet riverbanks and secret messages to keep their romance hidden from their feuding kin.",h="Tommy Joe Stonefield is a young farmer caught in a bitter family rivalry in the heart of Elwynn Forest.",sec={{t="A Star-Crossed Feud",b="Standing by the riverbank just west of the Stonefield Farm, Tommy Joe Stonefield spends his days looking across the water toward the Maclure homestead. The Stonefields and Maclures have harbored bad blood for years, clashing over land, pride, and petty farmyard squabbles. Yet despite the hostility preached by his elders, Tommy Joe has fallen head over heels for Maybell Maclure. Unable to meet openly without sparking outrage from both households, he depends on trusted intermediaries and his sympathetic grandmother, Gramma Stonefield, to exchange secret notes and tokens of affection.",sp=0}},faq={{q="Who is Tommy Joe Stonefield?",a="He is a young human living on the Stonefield Farm in Elwynn Forest. He is secretly in love with Maybell Maclure, the daughter of his family's bitter rivals.",al={"tommy joe","who is tommy joe","stonefield son"}},{q="Where can I find Tommy Joe Stonefield?",a="Tommy Joe stands along the riverbank west of the Stonefield Farm, gazing across the water toward the Maclure farmstead where Maybell lives.",al={"tommy joe location","where is tommy joe","find tommy joe"}},{q="Why are the Stonefields and Maclures fighting?",a="The two farming families have maintained a petty, bitter feud over property lines, stolen prize crops, and stubborn country pride, forbidding their families from associating with one another.",al={"family feud","why do they hate each other","stonefield maclure feud"}},{q="Who helps Tommy Joe and Maybell meet?",a="Gramma Stonefield is aware of their affection and helps facilitate their secret courtship, using outside travelers to carry discreet messages between Tommy Joe and Maybell.",al={"gramma stonefield help","secret lovers help","who helps the lovers"}}},ang={["faction:Alliance"]="For Alliance adventurers exploring southern Elwynn, Tommy Joe's secret romance is a humble reminder of the quiet, personal lives continuing in the shadow of regional banditry and political unrest."},kw={"elwynn forest","gramma stonefield","maybell maclure","stonefield farm","tommy joe stonefield","young lovers"},rel={"npc:maybell-maclure","npc:gramma-stonefield","subzone:stonefield-farm","npc:ma-stonefield","quest:111","zone:elwynn"},src={"Tommy Joe Stonefield"}}
E["npc:willem"] = {t="npc",n="Willem",z="elwynn",s="Deputy Willem is a human soldier of the Stormwind Army stationed directly outside Northshire Abbey. Serving under Marshal McBride, he acts as the primary field liaison directing new recruits to handle local threats in Northshire Valley. His immediate focus is suppressing the growing encroachment of the Defias Brotherhood.",h="Deputy Willem is a human soldier of the Stormwind Army stationed directly outside Northshire Abbey.",sec={{t="A Watchman at the Abbey",b="Standing just steps from the gates of Northshire Abbey, Deputy Willem represents the frontline presence of the Stormwind Army in the valley. With the kingdom's military stretched thin across multiple territories, local security falls heavily on small detachments like McBride's garrison. Willem evaluates incoming volunteers, assigning them immediate tasks to assist local residents and safeguard the valley's perimeter.",sp=0},{t="Confronting the Defias",b="Willem's most pressing concern is the brazen activity of the Defias Brotherhood. Bandits sporting red bandanas have pushed directly into Northshire, stealing supplies, menacing local farmers like Milly Osworth, and establishing footholds around the surrounding vineyards and hills. Willem coordinates bounties on known cutthroats such as Garrick Padfoot to break their leadership before they can seize the abbey grounds.",sp=0}},faq={{q="Who is Deputy Willem?",a="Deputy Willem is an officer of the Stormwind Army stationed at Northshire Abbey in Elwynn Forest. Serving under Marshal McBride, he coordinates new recruits to defend the valley against local threats.",al={"who is willem","deputy willem role","willem northshire"}},{q="Who does Deputy Willem report to?",a="He reports directly to Marshal McBride, the senior commander responsible for the defense and military operations within Northshire Valley.",al={"willem commander","who is willems boss","willem leader"}},{q="Why is Willem issuing bounties on the Defias?",a="The Defias Brotherhood has infiltrated Northshire Valley, threatening the abbey and terrorizing local laborers. Willem enlists adventurers to cut down their numbers and eliminate leaders like Garrick Padfoot to restore order.",al={"why defias bounty","willem red bandanas","willem defias"}},{q="Where can Deputy Willem be found?",a="Willem stands outside the main entrance of Northshire Abbey in northern Elwynn Forest, greeting travelers and recruits as they step out into the courtyard.",al={"willem location","where is deputy willem","find willem"}},{q="How does Willem assist the local workers?",a="Willem directs able-bodied fighters to assist residents whose livelihoods are threatened, sending recruits to aid figures such as the orchardist Milly Osworth and the peltskinner Eagan.",al={"willem milly osworth","willem eagan","willem quests"}},{q="Why are troops like Willem struggling to maintain order alone?",a="Stormwind is suffering from internal strain, political tension, and distant military commitments. With King Varian missing, garrisons like Northshire must rely on untested recruits and volunteers to handle domestic unrest.",al={"why is stormwind army weak","why northshire undefended","stormwind manpower northshire"}}},ang={["race:Human"]="For humans stepping out of Northshire Abbey into the world, Deputy Willem is often the very first military officer to welcome them into service for the kingdom of Stormwind.",["faction:Alliance"]="Willem serves as an initial touchpoint for the Alliance's domestic security, demonstrating how deeply the Defias unrest threatens even the peaceful heartland of Elwynn.",["class:Warrior"]="Warrior recruits find in Deputy Willem a practical field liaison who directs their martial strength toward clearing out bandits and restoring order to the realm."},kw={"defias","deputy willem","elwynn forest","garrick padfoot","marshal mcbride","northshire","northshire abbey","willem"},rel={"npc:marshal-mcbride","subzone:northshire-valley","quest:783","quest:18","quest:6","topic:defias-brotherhood","topic:stormwind-army","zone:elwynn"},src={"Willem"}}
E["npc:william-pestle"] = {t="npc",n="William Pestle",z="elwynn",s="William Pestle is a human alchemist staying inside Goldshire's Lion's Pride Inn. Together with his brother Morgan, he helps run the apothecary shop in Stormwind's Trade District. He frequently employs traveling adventurers to gather odd reagents like kobold candles, murloc kelp, and herbal supplies.",h="William Pestle is a human alchemist staying inside Goldshire's Lion's Pride Inn.",sec={{t="Apothecary Abroad",b="While his brother Morgan Pestle manages the counter at Pestle's Apothecary in the Trade District of Stormwind City, William operates out of the Lion's Pride Inn in Goldshire. Being stationed in Elwynn Forest allows him to work closely with local gatherers and secure raw materials that city shops constantly require. He maintains regular shipments back to the capital, ensuring Stormwind's citizens have steady access to restorative salves, draughts, and powders.",sp=0},{t="Curious Reagents",b="William's craft often demands unusual components that go beyond simple garden herbs. He frequently commissions newcomers to gather wax candles carried by Elwynn's infesting kobolds, as well as crystal kelp taken from the murlocs of Crystal Lake, just east of Goldshire. Although such concoctions seem bizarre to the uninitiated, William insists these strange ingredients possess potent alchemical virtues.",sp=0},{t="A Concoction for Young Love",b="Beyond his standard trade, William is an old friend of Mildred Stonefield. When the young lovers Maybell Maclure and Tommy Joe Stonefield find themselves caught between their bitterly feuding farmstead families, William agrees to brew an Invisibility Liquor. Using the kelp gathered from local waters, his draft allows Maybell to slip away unnoticed and rendezvous with Tommy Joe.",sp=1}},faq={{q="Who is William Pestle?",a="William Pestle is an alchemist and apothecary living at the Lion's Pride Inn in Goldshire. Alongside his brother Morgan in Stormwind City, he gathers and prepares alchemical supplies for the kingdom.",al={"william pestle","goldshire alchemist","who is pestle"}},{q="Where can William Pestle be found?",a="He is located inside the Lion's Pride Inn in Goldshire, situated in Elwynn Forest.",al={"pestle location","where is william pestle","william pestle goldshire"}},{q="What does William do with kobold candles?",a="William collects the wax candles carried by kobolds in Elwynn's mines, melting them down and refining the tallow for his alchemical mixtures and general apothecary inventory.",al={"why does pestle want candles","kobold candles use"}},{q="Why does William need Crystal Kelp?",a="William uses Crystal Kelp harvested from local Elwynn lakes to formulate an Invisibility Liquor, which helps Maybell Maclure sneak past her family to see Tommy Joe Stonefield.",al={"collecting kelp why","murloc kelp use"},sp=1},{q="What is William Pestle's connection to Stormwind City?",a="William and his brother Morgan run the apothecary in the Trade District of Stormwind City. William gathers ingredients in Goldshire and coordinates shipments back to the city shop.",al={"pestle stormwind","william pestle apothecary shop"}},{q="How is William involved with the Stonefields and Maclures?",a="William is an old friend of Mildred Stonefield. He aids Tommy Joe Stonefield and Maybell Maclure by concocting a covert brew to help them bypass their families' bitter feud.",al={"stonefield maclure pestle","william pestle love quest"},sp=1}},ang={["profession:Herbalism"]="For herbalists wandering through Goldshire, William Pestle represents the practical trade side of plant gathering, constantly turning wild growth and strange aquatic kelp into useful mixtures.",["faction:Alliance"]="William helps keep the Trade District in Stormwind supplied with vital medicines and sundries, relying on Alliance recruits passing through Goldshire to secure materials from the surrounding forest."},kw={"apothecary","collecting kelp","goldshire","kobold candles","lion's pride inn","maclure","morgan pestle","pestle","stonefield","william pestle"},rel={"npc:morgan-pestle","subzone:lion-s-pride-inn","subzone:goldshire","quest:60","quest:112","quest:114","quest:61","npc:maybell-maclure"},src={"William Pestle"}}
E["quest:11"] = {t="quest",n="Riverpaw Gnoll Bounty",z="elwynn",s="Riverpaw Gnoll Bounty is an official contract issued by Deputy Rainer at Westbrook Garrison to cull the encroaching gnolls threatening Elwynn Forest's western borders. The Stormwind Army offers a reward for painted armbands taken from the Riverpaw packs infesting the woods and waterways.",h="Riverpaw Gnoll Bounty is an official contract issued by Deputy Rainer at Westbrook Garrison to cull the...",sec={{t="A Threat on the Border",b="Westbrook Garrison guards the critical borderlands between Elwynn Forest and Westfall. However, depleted garrison forces have left the outpost struggling to contain an aggressive influx of Riverpaw gnolls. These savage creatures have established encampments directly south of the guard tower and further east around the shores of Stone Cairn Lake, encroaching close enough to threaten peaceful travelers and local homesteads.",sp=0},{t="The Price of Order",b="Unable to spare regular infantry to sweep the woods, Deputy Rainer places a bounty on the raiders. To confirm the kills, Rainer requires proof of martial victory: painted gnoll armbands stripped from the slain beasts. By hiring wandering adventurers and recruits to thin the pack's numbers, the garrison hopes to blunt the Riverpaws' advance before they overrun the western marches.",sp=0}},faq={{q="Where can Riverpaw gnolls be found in Elwynn Forest?",a="Riverpaw gnolls gather primarily in two areas in Elwynn: in the dense woods directly south of Westbrook Garrison near the riverbanks, and farther east around the perimeter of Stone Cairn Lake.",al={"gnoll locations","where are the gnolls","riverpaw locations"}},{q="Why is the garrison asking adventurers for help with gnolls?",a="Westbrook Garrison is understaffed and facing pressure along the borders of Elwynn. With too few guards to patrol the perimeter and simultaneously launch offensive sweeps, Deputy Rainer turns to independent champions to hunt the gnolls.",al={"why deputy rainer needs help","why garrison hiring mercenaries"}},{q="What proof does Deputy Rainer require?",a="Deputy Rainer requires eight Painted Gnoll Armbands as physical proof that the encroaching beasts have been put down.",al={"bounty proof","what to collect for rainer"}},{q="Who are the Riverpaw gnolls?",a="The Riverpaws are a notoriously vicious tribe of hyena-like humanoids known for infesting river valleys and borders across human lands. They frequently raid settlements, travelers, and farmlands for food and plunder.",al={"what are riverpaw gnolls","riverpaw tribe lore"}},{q="Does this quest connect to any other threats in Elwynn?",a="Riverpaw Gnoll Bounty is the conclusion of the short Westbrook Garrison alert chain, though Deputy Rainer and Westbrook Garrison also monitor other lawless elements in the area, such as the notorious outlaw Hogger.",al={"quest continuation","what comes after riverpaw bounty"}},{q="Who pays the bounty for these gnolls?",a="The bounty is officially sanctioned and backed by the Stormwind Army, which authorizes local garrisons to commend and compensate those who assist in pacifying royal territories.",al={"who funds the bounty","bounty reward source"}}},ang={["race:Human"]="For humans of the realm, hunting down the Riverpaws is a direct effort to protect Elwynn's frontiers and support the overextended crown guards.",["faction:Alliance"]="Taking on border bounties builds standing with the Stormwind Army while securing vital trade routes through the heart of the kingdom."},kw={"bounty","deputy rainer","elwynn","gnoll","painted gnoll armband","riverpaw","stone cairn lake","westbrook garrison"},rel={"npc:deputy-rainer","subzone:westbrook-garrison","quest:239","subzone:stone-cairn-lake","zone:elwynn","topic:stormwind-army","topic:gnoll","topic:stormwind-kingdom"},m={start="Deputy Rainer",faction="Alliance",id=11},src={"Riverpaw Gnoll Bounty"}}
E["quest:111"] = {t="quest",n="Speak with Gramma",z="elwynn",s="This errand sends an adventurer to Gramma Stonefield on behalf of her grandson Tommy Joe. Caught in a bitter feud between the Stonefield and Maclure families, Tommy Joe hopes the elderly matriarch knows a way he can see Maybell Maclure.",h="This errand sends an adventurer to Gramma Stonefield on behalf of her grandson Tommy Joe.",sec={{t="A Feud and Forbidden Love",b="The Stonefields and the Maclures have spent years locked in bitter agricultural rivalry, turning neighboring homesteads into hostile territory. Caught in the middle are young Tommy Joe Stonefield and Maybell Maclure, whose romance has to be conducted in total secrecy. Desperate for a way to meet his beloved without sparking violence between their kin, Tommy Joe turns to his grandmother for guidance.",sp=0},{t="Gramma's Cunning",b="Though age has kept Gramma Stonefield indoors, she understands the nature of the feud better than anyone. While she recognizes that a true union between the two families is impossible as long as the bad blood persists, she has no intention of letting neighboring grudges crush young love entirely. Instead of urging caution, she begins scheming small opportunities to bring the two together.",sp=0}},faq={{q="Why does Tommy Joe want me to speak with his Gramma?",a="Tommy Joe is deeply in love with Maybell Maclure, but their feuding families make meeting impossible. He believes his grandmother has the wisdom, sympathy, and cunning to help them arrange secret meetings without causing an uproar.",al={"why gramma","tommy joe gramma","speak with gramma purpose"}},{q="Where can Gramma Stonefield be found?",a="Gramma Stonefield stays inside the main Stonefield farmhouse, located east of the riverbank where Tommy Joe hides, south of Goldshire.",al={"gramma stonefield location","where is gramma","find gramma stonefield"}},{q="What is the feud between the Stonefields and the Maclures?",a="The two neighboring farming families have a long-standing personal and territorial grudge. Accusations of theft, rivalry over crops, and mutual distrust keep both households on the brink of violence, forcing any interaction between their children underground.",al={"stonefield maclure feud","why are they fighting","family feud elwynn"}},{q="Does Gramma Stonefield oppose Tommy Joe's relationship?",a="No. Although she acknowledges the feud makes a long-term future difficult right now, she has a soft spot for the young lovers and is willing to concoct schemes to help them meet.",al={"is gramma against maybell","does gramma support lovers"}},{q="What happens after speaking to Gramma?",a="Gramma begins formulating a plan to sneak Tommy Joe and Maybell together, sending the adventurer on errands to prepare an invisibility liquor to bypass watchful family eyes.",al={"what next speak with gramma","gramma quest follow up"},sp=1},{q="Who is Maybell Maclure?",a="Maybell is the daughter of the rival Maclure family, living just across the road from the Stonefields. She is secretly courting Tommy Joe Stonefield.",al={"who is maybell","maybell maclure"}}},ang={["race:Human"]="For humans adventuring in Elwynn, the Stonefield-Maclure conflict is a reminder of how deeply local grudges run in the heartlands of Stormwind, even in the shadow of broader realm-wide crises.",["faction:Alliance"]="While Stormwind faces Defias unrest and beast attacks, Alliance travelers often find themselves playing mediator in petty domestic squabbles between neighboring farmers."},kw={"elwynn forest","gramma stonefield","maclure vineyards","maybell maclure","speak with gramma","stonefield farm","tommy joe stonefield","young lovers"},rel={"npc:gramma-stonefield","npc:tommy-joe-stonefield","npc:ma-stonefield","zone:elwynn"},m={start="Tommy Joe Stonefield",["end"]="Gramma Stonefield",faction="Alliance",id=111},src={"Speak with Gramma"}}
E["quest:112"] = {t="quest",n="Collecting Kelp",z="elwynn",s="Collecting Kelp is an errand undertaken for the apothecary William Pestle in Goldshire to aid two star-crossed young lovers. In order to brew an invisibility potion for Maybell Maclure, Pestle sends adventurers to wrest rare ocean flora from the murlocs nesting around Crystal Lake.",h="Collecting Kelp is an errand undertaken for the apothecary William Pestle in Goldshire to aid two...",sec={{t="A Remedy for Forbidden Love",b="The bitter feud between the Stonefield and Maclure farming families leaves young Tommy Joe Stonefield and Maybell Maclure unable to meet in the open. Desperate to visit her beloved without sparking an armed brawl between their kin, Maybell seeks an unconventional solution: slipping unseen across the valley. William Pestle, the eccentric herbalist and apothecary operating out of the Lion's Pride Inn in Goldshire, concocts a plan to brew an invisibility liquor. However, crafting such an elusive draught demands rare reagents not readily found in the Lion's Pride cupboards.",sp=0},{t="The Scavengers of Crystal Lake",b="The essential catalyst for Pestle's brew is crystal kelp. While natural fronds typically thrive far out in saltwater oceans, the freshwater shores of Crystal Lake—situated just east of Goldshire—have become overrun by tribal murlocs. For reasons best known to their own peculiar instincts, these shore-dwelling scavengers have hauled stashes of marine crystal kelp inland to their crude camps. Recovering enough fronds requires cutting a path through vicious amphibian warrens, prying the plants from the creatures' clutches before returning to Goldshire to distill the liquor.",sp=0}},faq={{q="Why does William Pestle need crystal kelp?",a="William Pestle requires crystal kelp as the primary reagent to brew an invisibility liquor. This draught is intended to let Maybell Maclure sneak off her family's vineyard undetected to see Tommy Joe Stonefield.",al={"why crystal kelp","what is kelp for","william pestle ingredients"}},{q="Why is ocean kelp found near freshwater Crystal Lake?",a="Crystal kelp naturally grows in the ocean, but the murloc tribes infesting Crystal Lake scavenge and transport the plant inland. They hoard the fronds in their lakeside camps, making them the only local source near Goldshire.",al={"why is kelp at crystal lake","kelp in fresh water","murloc kelp lore"}},{q="Who are Maybell Maclure and Tommy Joe Stonefield?",a="Maybell and Tommy Joe are young lovers hailing from rival farming families in southern Elwynn Forest. Because their families despise each other, the pair must resort to secrecy and alchemical tricks simply to speak together.",al={"who is maybell","who is tommy joe","maclure stonefield feud"}},{q="Where is Crystal Lake located?",a="Crystal Lake lies directly east of the town of Goldshire in central Elwynn Forest. Its waters and perimeter are heavily infested with hostile murlocs.",al={"where is crystal lake","crystal lake location","find crystal lake"}},{q="What happens after collecting the kelp?",a="Once you deliver four crystal kelp fronds, William Pestle distills them into an Invisibility Liquor. He then tasks you with bringing the concoction to Maybell Maclure so she can make her clandestine escape.",al={"next quest after kelp","what does pestle make"}},{q="Who is William Pestle?",a="William Pestle is an apothecary and alchemical dabbler based inside the Lion's Pride Inn in Goldshire. He assists locals with folk remedies, strange potions, and confidential favors.",al={"who is william pestle","pestle goldshire"}}},ang={["profession:Herbalism"]="For gatherers, crystal kelp is a curious anomaly: an ocean-dwelling herb harvested not from soil or seabed, but snatched directly from the scavenging pouches of freshwater murlocs.",["faction:Alliance"]="Clearing the murloc camps around Crystal Lake for Pestle's odd errand also helps quiet an aggressive menace lurking uncomfortably close to Goldshire's eastern road."},kw={"collecting kelp","crystal kelp","crystal lake","goldshire","invisibility liquor","maybell maclure","murloc","tommy joe stonefield","william pestle"},rel={"npc:william-pestle","subzone:crystal-lake","quest:114","subzone:goldshire","subzone:maclure-vineyards","topic:murloc","zone:elwynn"},m={start="William Pestle",faction="Alliance",id=112},src={"Collecting Kelp"}}
E["quest:114"] = {t="quest",n="The Escape",z="elwynn",s="\"The Escape\" is the culmination of the forbidden romance between Maybell Maclure and Tommy Joe Stonefield in Elwynn Forest. After gathering ingredients across the region, you deliver William Pestle's brewed Invisibility Liquor to Maybell so she can slip past her family unnoticed. It marks a fleeting, clandestine victory of young love over an entrenched rural feud.",h="\"The Escape\" is the culmination of the forbidden romance between Maybell Maclure and Tommy Joe Stonefield in...",sec={{t="A Concoction for True Love",b="The generational rivalry between the Maclures and the Stonefields leaves no room for harmony, let alone courtship. With both families fiercely protective and hostile toward one another, Tommy Joe Stonefield turned to William Pestle, the alchemist in Goldshire's Lion's Pride Inn. Using crystal kelp harvested from nearby lakes, Pestle formulated a draught of Invisibility Liquor potent enough to mask Maybell's escape from the Maclure homestead.",sp=0},{t="Vanishing into the Woods",b="Delivering the flask to Maybell Maclure allows her to slip away into the trees toward Tommy Joe. Though racked with guilt over deceiving her kin, her devotion outweighs her fear of discovery. Upon downing the liquor, she vanishes before your eyes, buying the young lovers a precious few moments together beyond the watchful glare of their feuding elders.",sp=1}},faq={{q="Who gives the quest The Escape?",a="William Pestle, the apothecary and alchemical assistant residing inside the Lion's Pride Inn in Goldshire, hands you the Invisibility Liquor once you have supplied him with crystal kelp.",al={"quest giver the escape","who starts the escape","where to pick up the escape"}},{q="What is the Invisibility Liquor used for?",a="The liquor allows Maybell Maclure to turn completely invisible long enough to sneak away from her family's farm and visit Tommy Joe Stonefield without provoking her relatives' wrath.",al={"why invisibility liquor","what does the potion do","invisibility liquor purpose"}},{q="Why do Maybell and Tommy Joe have to hide their relationship?",a="The Maclure and Stonefield families are bitter rivals embroiled in an ongoing grudge. Because of the deep hostility between the two households, any open courtship between their children is strictly forbidden.",al={"why are they hiding","stonefield maclure feud","why can't maybell and tommy joe be together"}},{q="What happens when you deliver the potion to Maybell?",a="Maybell thanks you, expresses mixed feelings of guilt and excitement, and promptly drinks the brew. She turns invisible right before your eyes to slip off toward Tommy Joe.",al={"what happens at the end","does maybell vanish","the escape quest completion"},sp=1},{q="What quest leads directly into The Escape?",a="\"The Escape\" follows immediately after \"Collecting Kelp,\" in which you retrieve crystal kelp from the murlocs at Crystal Lake for William Pestle to brew the invisibility potion.",al={"prerequisite for the escape","quest before the escape","what leads to the escape"}},{q="Does this quest resolve the feud between the families?",a="No. The potion merely offers a temporary, secret meeting for the lovers. The broader feud between Grandma Stonefield and the Maclures remains as bitter and unresolved as ever.",al={"do the families make peace","is the feud over","does the feud end"},sp=1}},ang={["faction:Alliance"]="For young adventurers starting in Elwynn Forest, aiding Tommy Joe and Maybell offers a lighthearted break from combating Defias bandits and gnolls, showing that everyday rural grievances persist even on Stormwind's doorstep.",["race:Human"]="Local human settlers in Elwynn know well that stubborn family grudges run deep, making small acts of covert neighborly aid essential to keeping the peace."},kw={"elwynn forest","invisibility liquor","maclure vineyards","maybell maclure","stonefield farm","the escape","tommy joe stonefield","william pestle"},rel={"npc:maybell-maclure","npc:tommy-joe-stonefield","npc:william-pestle","quest:112","zone:elwynn"},m={start="William Pestle",["end"]="Maybell Maclure",faction="Alliance",id=114},src={"The Escape (Alliance)"}}
E["quest:119"] = {t="quest",n="Return to Verner",z="elwynn",s="Return to Verner is an Alliance errand carrying a bulky delivery of fifty freshly forged horseshoes back to Lakeshire. Entrusted by Goldshire's blacksmith, Smith Argus, you must return across the border into Redridge to hand the crate over to an eager Verner Osgood.",h="Return to Verner is an Alliance errand carrying a bulky delivery of fifty freshly forged horseshoes back to...",sec={{t="A Courier Across the Border",b="Having traveled all the way from Lakeshire to Elwynn Forest to secure essential footwear for local mounts, your task concludes with hauling the finished crate of fifty horseshoes back eastward. Redridge Mountains remains strained by supply shortages and marauding gnolls, making every piece of ironmongery vital for keeping horses and draft animals functional on the rugged mountain roads.",sp=0},{t="The Note on the Crate",b="While Verner Osgood is relieved to see the horseshoes arrive, Smith Argus did not forge them purely out of fraternal goodwill. Attached to the shipment is a bill demanding payment. Verner is visibly annoyed to discover that the Goldshire smith actually expects compensation, though the pressing dangers facing Redridge leave little time to bicker over the tab before turning to more perilous problems.",sp=0}},faq={{q="Where do I take the Crate of Horseshoes?",a="Bring the crate back to Verner Osgood in Lakeshire, located in the Redridge Mountains just east of the bridge and lakeside docks.",al={"where is verner","turn in location","who gets horseshoes"}},{q="Who sent this delivery back to Redridge?",a="Smith Argus, the resident blacksmith stationed outside the Lion's Pride Inn in Goldshire, provides the crate once his forging work is finished.",al={"who gave the quest","smith argus","quest giver"}},{q="Why is Verner upset when he receives the crate?",a="Argus attached an invoice to the shipment demanding full payment for the fifty horseshoes, much to Verner's irritation, as he apparently hoped for a free favor or lighter terms.",al={"why is verner mad","argus note","verner reaction"}},{q="What quests open up after completing this delivery?",a="Completing this delivery leads directly into Verner's combat contracts against local threats: 'A Baying of Gnolls' to hunt the Redridge gnolls, alongside an errand for 'Underbelly Scales'.",al={"next quest","followup quests","what unlocks"}},{q="Why does Lakeshire need supplies imported from Goldshire?",a="Lakeshire is under heavy siege by gnolls and Blackrock orcs, stretching local craftsmen thin. Everyday staples like bulk iron horseshoes often have to be ferried in from quieter settlements like Goldshire.",al={"why elwynn shoes","why import horseshoes","redridge supplies"}},{q="Does Smith Argus accompany you back to Redridge?",a="No. Smith Argus remains at his forge in Goldshire, leaving the cross-zone courier duties entirely to traveling adventurers.",al={"does argus come with","escort smith argus"}}},ang={["profession:Blacksmithing"]="Hauling fifty horseshoes highlights the logistical grind behind keeping frontier mounts shod when local red-hot anvils are overwhelmed by war.",["faction:Alliance"]="Running supply lines between Elwynn Forest and Redridge is crucial for keeping beleaguered outlying settlements like Lakeshire tied to the kingdom's core."},kw={"crate of horseshoes","elwynn forest","goldshire","lakeshire","redridge","smith argus","the price of shoes","verner osgood"},rel={"quest:118","npc:verner-osgood","npc:smith-argus","quest:124","quest:122","quest:126","zone:elwynn","topic:gnoll"},m={start="Smith Argus",["end"]="Verner Osgood",level="18",faction="Alliance",id=119},src={"Return to Verner"}}
E["quest:123"] = {t="quest",n="The Collector",z="elwynn",s="Recovered from gnoll raiders prowling the woods, this intercepted dispatch outlines a precise timetable of gold shipments leaving Elwynn Forest's abandoned mines. Addressed to an elusive figure known only as 'The Collector,' the schedule hints at a coordinated operation thriving right under the nose of Stormwind's garrison.",h="Recovered from gnoll raiders prowling the woods, this intercepted dispatch outlines a precise timetable of...",sec={{t="A Paper Trail in the Paws of Gnolls",b="While clearing gnoll packs lurking in eastern Elwynn Forest, adventurers stumble upon a curious piece of parchment tucked among rough furs and crude weapons: the Gold Pickup Schedule. Far from animal scribblings, the note details organized drop-off dates and times for precious metal extracted directly from local mines. The recipients clearly possess discipline and logistical foresight, directing shipments toward an overseer identified solely as 'The Collector.'",sp=0},{t="Unsettling News for Goldshire",b="When brought before Marshal Dughan at the Lion's Pride Inn, the discovery comes as an alarming shock. Official mining operations across Elwynn have been shuttered for months due to gnoll aggression, kobold infestations, and roaming bandits. The realization that ore is still being systematically extracted and moved—and that gnolls carry shipping manifests—confirms that an organized criminal network is plundering the kingdom's natural wealth from the shadows.",sp=0},{t="Eyes on the Brackwell Patch",b="The schedule pins the Collector's suspected location near the Brackwell Pumpkin Patch in eastern Elwynn Forest. While Dughan has heard whispers of the moniker before, he lacks clear evidence of who commands this ring or where the illicit gold ultimately travels. Handing over the schedule gives the garrison its first solid lead in hunting down the mastermind behind the shipments.",sp=1}},faq={{q="What is the Gold Pickup Schedule?",a="It is an intercepted ledger dropped by gnolls in Elwynn Forest. It lists specific dates and times when mined gold is scheduled to be handed over to a secretive figure called 'The Collector.'",al={"pickup schedule","collector note","elwynn gold schedule"}},{q="Who is 'The Collector'?",a="The Collector is an elusive criminal figure operating in eastern Elwynn Forest, believed to be hiding around the Brackwell Pumpkin Patch while coordinating illicit gold trade.",al={"collector identity","who is the collector","brackwell collector"}},{q="Why is Marshal Dughan shocked by the schedule?",a="Stormwind's official miners have abandoned the local mines for months due to rising monster activity. Finding out that someone is still harvesting and moving shipments of gold reveals a covert operation undermining the crown.",al={"why is dughan surprised","dughan reaction","elwynn mines closed"}},{q="Why do gnolls have this note?",a="The gnolls in eastern Elwynn appear to be acting as couriers, guards, or collaborators in the gold smuggling pipeline, carrying orders meant to organize the pickups.",al={"gnolls gold","why gnolls drop schedule","gnoll involvement"}},{q="Where does this investigation lead next?",a="Delivering the schedule to Marshal Dughan initiates the quest 'Manhunt,' directing you to track down and eliminate the Collector near the Brackwell Pumpkin Patch.",al={"collector follow up","manhunt quest","after the collector"}},{q="Where is the Brackwell Pumpkin Patch located?",a="The Brackwell Pumpkin Patch sits in the eastern reaches of Elwynn Forest, north of the river and east of the Maclure and Stonefield vineyards.",al={"brackwell location","where is brackwell","pumpkin patch elwynn"}}},ang={["faction:Alliance"]="Every ounce of gold smuggled out of Elwynn deprives the Crown of vital tax revenue and raw materials during an era when the kingdom struggles to protect its borders.",["class:Rogue"]="Intercepting schedules and tracing organized contraband is classic tradecraft, revealing how deeply criminal syndicates have rooted themselves into Elwynn's wilderness.",["profession:Mining"]="The shuttered mines of Elwynn still hold rich veins of copper and precious metals—veins that someone is unlawfully tapping while honest miners stay home in fear."},kw={"brackwell pumpkin patch","elwynn forest","gold pickup schedule","goldshire","manhunt","marshal dughan","mines","the collector"},rel={"quest:147","npc:marshal-dughan","subzone:brackwell-pumpkin-patch","subzone:goldshire","zone:elwynn","topic:gnoll"},m={start="Gold Pickup Schedule#Classic",["end"]="Marshal Dughan",level="10",faction="Alliance",id=123},src={"The Collector (Classic)"}}
E["quest:147"] = {t="quest",n="Manhunt",z="elwynn",s="Manhunt is an Alliance quest issued by Marshal Dughan in Goldshire to eliminate a Defias bagman known as 'the Collector'. Operating out of the overrun Brackwell Pumpkin Patch, this operative funnels pilfered gold from Elwynn Forest's mines directly into the Brotherhood's coffers.",h="Manhunt is an Alliance quest issued by Marshal Dughan in Goldshire to eliminate a Defias bagman known as 'the...",sec={{t="Justice in the Pumpkin Patch",b="Following the discovery of a gold pickup schedule carried by Elwynn's gnolls, Marshal Dughan dispatches adventurers to Brackwell Pumpkin Patch. Once a quiet homestead, the farm has been overtaken by Defias bandits and gnolls. Amid the overgrown vines hides the Collector, the middleman responsible for skimming kingdom ore and organizing shipments for the gathering rebellion.",sp=0},{t="An Artisan's Seal",b="Upon slaying the Collector, adventurers recover his ring and deliver it to Marshal Dughan. To the marshal's bewilderment, the band does not bear a common criminal crest, but the mark of the old Stormwind Stonemasons Guild. The discovery hints at an uncomfortable truth: the highwaymen choking Elwynn Forest are not merely opportunists, but former craftsmen turned bitter outlaws after the rebuilding of Stormwind.",sp=1}},faq={{q="Where can I find the Collector?",a="The Collector hides in the Brackwell Pumpkin Patch, located in southeastern Elwynn Forest, just east of the Maclure Vineyards and north of the river boundary.",al={"collector location","where is collector","collector spot"}},{q="Why is the Collector stealing gold from Elwynn's mines?",a="He gathers smuggled ore and extortion payments from the kobold-infested Fargodeep and Jasperlode mines to finance the Defias Brotherhood's covert operations across the kingdom.",al={"why steal gold","defias mines","what is collector doing"}},{q="What is the significance of the Collector's ring?",a="The ring belonged to the Stonemasons Guild, the craftsmen who rebuilt Stormwind City after the First and Second Wars. Finding it in the hands of a Defias operative links the highwaymen directly to the disaffected artisans cheated out of payment by the House of Nobles.",al={"collectors ring lore","stonemason ring","what does the ring mean"},sp=1},{q="Does Marshal Dughan figure out who is behind the Brotherhood?",a="Not immediately. Marshal Dughan recognizes the artisan insignia on the ring, but he is puzzled as to why a common thief would hold an artisan guild signet, leaving the broader conspiracy an open question in Goldshire.",al={"does dughan know","dughan reaction","marshal dughan Stonemasons"},sp=1},{q="Who sends you on this manhunt?",a="Marshal Dughan, the garrison commander stationed at the Lion's Pride Inn in Goldshire, offers the quest after you recover the Defias pickup schedule.",al={"who gives manhunt","quest giver manhunt","marshal dughan quest"}},{q="What happened to the Brackwell family?",a="The Brackwell Pumpkin Patch has fallen into ruin, abandoned by its owners and occupied by Defias rogues, bandits, and encroaching Riverpaw gnolls who prowl the southeastern woodlands.",al={"brackwell lore","who owns pumpkin patch","brackwell farm"}}},ang={["class:Rogue"]="The Collector's stealthy operation in the pumpkin patch highlights the expanding network of highwaymen and cutpurses taking root throughout Elwynn Forest.",["faction:Alliance"]="Protecting Stormwind's local resources is critical; stopping the Collector cuts off an illicit flow of kingdom gold intended to fund rebellion right on the capital's doorstep.",["race:Human"]="Recovering the Stonemason's ring touches a raw nerve in Stormwind's recent history, recalling the bitter labor disputes that fractured the kingdom after the capital was rebuilt."},kw={"brackwell pumpkin patch","collector","defias","goldshire","manhunt","marshal dughan","ring","stonemasons guild"},rel={"quest:123","npc:marshal-dughan","subzone:brackwell-pumpkin-patch","zone:elwynn","topic:stormwind-kingdom"},m={start="Marshal Dughan",level="10",faction="Alliance",id=147},src={"Manhunt (Classic)"}}
E["quest:15"] = {t="quest",n="Investigate Echo Ridge",z="elwynn",s="Investigate Echo Ridge is an early military assignment issued by Marshal McBride in Northshire Valley. Tasked with probing the Echo Ridge Mine to the north, recruits are sent to cull the encroaching kobold workers and determine the true scope of the infestation threatening the abbey's mineral wealth.",h="Investigate Echo Ridge is an early military assignment issued by Marshal McBride in Northshire Valley.",sec={{t="A Deepening Infestation",b="While early skirmishes around Northshire focused on scattered vermin prowling the forested perimeter, reports from scouts soon revealed a far more organized threat. Kobolds were not merely scavenging the woods; they had gathered in force around the Echo Ridge Mine. Marshal McBride orders recruits north to confront the kobold workers gathered around the mine's entrance and assess just how deeply the pests have entrenched themselves.",sp=0},{t="Threat to the Abbey's Wealth",b="Echo Ridge Mine is a critical source of ore and raw materials for the Northshire brotherhood and the Stormwind guard garrisoned here. Having rat-like scavengers seizing the tunnels paralyzes extraction efforts and exposes how thin the local defenses are stretched. Culling ten workers proves only a first step, as McBride's fears are confirmed: the infestation runs deeper into the shafts than a simple surface patrol can fix.",sp=0}},faq={{q="Who sends me on this mission?",a="Marshal McBride, the commander of the Stormwind guards stationed at Northshire Abbey, issues the orders to investigate the mine once scouts discover the kobolds grouping to the north.",al={"quest giver","who gives quest","marshal mcbride"}},{q="Where is the Echo Ridge Mine located?",a="Echo Ridge Mine is located in the far northern reaches of Northshire Valley, tucked directly into the foothills above the abbey and its vineyards.",al={"echo ridge location","where is the mine","find echo ridge"}},{q="Why are kobolds dangerous to Northshire?",a="While individual kobolds are cowardly scavengers, they breed rapidly and swarm underground tunnels in huge packs. By seizing Echo Ridge Mine, they halt crucial mining operations and threaten to overwhelm the undermanned valley.",al={"why kill kobolds","what makes kobolds a threat","kobold danger"}},{q="What happens after I defeat the workers outside?",a="Returning to Marshal McBride confirms his worst suspicions: the mine is thoroughly infested. He immediately enlists your aid again for a deeper push into the subterranean shafts in Skirmish at Echo Ridge.",al={"what next","follow up quest","next quest"},sp=1},{q="Why doesn't the Stormwind army clear the mine themselves?",a="With King Varian Wrynn missing and resources drawn thin across Elwynn and neighboring frontiers, Northshire's local garrison is too small to spare full patrols for pest control, relying instead on capable newly arrived recruits.",al={"where are stormwind guards","why use recruits","stormwind garrison"}},{q="What kind of kobolds are found around the mine entrance?",a="The surface surroundings and upper thresholds are worked by kobold workers, the basic laborers who dig tunnels and gather candle wax for their subterranean colony.",al={"kobold types","what enemies to kill","kobold worker"}}},ang={["profession:Mining"]="Echo Ridge Mine is an essential source of copper for Northshire's smiths, making the clearance of these subterranean tunnels a matter of direct economic survival for miners.",["faction:Alliance"]="The creeping infestation of kobolds so close to Stormwind's spiritual heart in Northshire demonstrates how vulnerable the kingdom has become with its regular forces stretched thin.",["race:Human"]="For young humans beginning their service in Northshire Valley, defending Echo Ridge from subterranean pests is one of the earliest trials in proving their worth to the kingdom."},kw={"echo ridge","elwynn","kobold","kobold worker","marshal mcbride","mine","northshire","northshire valley"},rel={"subzone:echo-ridge-mine","npc:marshal-mcbride","quest:21","topic:kobold","zone:elwynn"},m={level="3",faction="Alliance",id=15},src={"Investigate Echo Ridge"}}
E["quest:1598"] = {t="quest",n="The Stolen Tome",z="elwynn",s="The Stolen Tome is an initiation task for novice human warlocks training in Northshire Valley. Tasked by trainer Drusilla La Salle, the practitioner must infiltrate a nearby Defias encampment to recover a forbidden text titled 'Powers of the Void.' In doing so, the fledgling warlock proves their competence and earns the knowledge required to bind their first demonic servant.",h="The Stolen Tome is an initiation task for novice human warlocks training in Northshire Valley.",sec={{t="A Forbidden Opportunity",b="Warlocks tread carefully in Stormwind's domains, practicing their volatile craft in secret corners and keeping prying eyes off their research. Northshire Abbey holds ancient knowledge within its archives, including forbidden grimoires held under lock and key. Drusilla La Salle, the resident warlock mentor lurking on the abbey grounds, coveted one such volume—the Powers of the Void—but dared not risk the suspicion of the abbey's clerics and paladins by attempting to breach the library's protected wing herself.",sp=0},{t="Defias Opportunism",b="La Salle's opportunity arrived when an abbey novice threw his lot in with the Defias Brotherhood. Fleeing into the Northshire Vineyards to join the bandits, the rogue scholar pilfered several valuable texts on his way out. Taking refuge around the Defias campsite in the vineyards, the thieves stashed their prize in a field tent, blissfully unaware of the true danger posed by the dark arts contained inside the volume.",sp=0},{t="The First Binding",b="For an aspiring warlock, recovering the tome is both a test of nerve and a practical shortcut to darker mysteries. Braving the bandit encampment and returning the text satisfies Drusilla's ambition and establishes the novice's readiness. With the grimoire secured in her hands, she rewards the pupil with the dark rites necessary to summon and bind an imp, the very first demon an apprentice learns to command.",sp=0}},faq={{q="What is the Powers of the Void?",a="It is a forbidden grimoire detailing dark magical concepts and planar control. Originally stored inside a guarded, protected wing of the Northshire Abbey library, it contains esoteric insights that warlock instructors like Drusilla La Salle covet for their personal study and teachings.",al={"powers of the void book","what is the book","what did the novice steal"}},{q="Why didn't Drusilla La Salle steal the book herself?",a="Drusilla must be cautious to preserve her standing around Northshire Abbey. Creeping into the library's secured archives would have raised immediate alarms among the clerics. When a disgruntled novice stole the tome and joined the Defias, it gave her the perfect chance to acquire it cleanly using an apprentice.",al={"why drusilla didn't steal it","why send me"}},{q="Where is the stolen tome hidden?",a="The Defias bandits stashed the tome inside a campsite tent pitched within the Northshire Vineyards, just east of the abbey, where their scouts and renegades have taken up residence.",al={"where is the book","tome location","stolen tome tent"}},{q="Why did a Northshire novice join the Defias Brotherhood?",a="Discontent and social strife have spread throughout the kingdom, driving laborers, farmers, and even church students to side with the Defias Brotherhood. The novice abandoned his vows, grabbed several important books from the library as loot, and fled to the vineyard bandits.",al={"why novice joined defias","abbey defias traitor","who stole the book"}},{q="What reward does a warlock get for retrieving the tome?",a="Returning the book convinces Drusilla that the pupil possesses the nerve and resilience to practice the dark arts. She provides the foundational teachings required to summon an imp, marking the apprentice's first successful demonic pact.",al={"what do you learn","warlock quest reward","why do this quest"}},{q="Do the Defias know how to use the book?",a="The bandits see the stolen books primarily as valuable plunder taken from the abbey. Though the Defias employ renegade spellcasters, the novice and his comrades merely tucked the volume away in a tent crate rather than mastering its dark secrets.",al={"can defias use the tome","what defias do with book"}}},ang={["class:Warlock"]="This rite of passage tests whether a fledgling warlock can navigate dangerous territory without flinching. Securing the tome grants you the secret rites needed to call upon your first imp.",["race:Human"]="The quest exposes how deeply the Defias Brotherhood's reach has penetrated Northshire, enticing even cloistered abbey students to steal sacred texts and join the insurrection.",["faction:Alliance"]="Operating right beneath the noses of Northshire's paladins and clerics, Alliance warlocks must tread softly, using outlaws' missteps to claim restricted occult knowledge."},kw={"defias brotherhood","drusilla la salle","northshire abbey","novice thief","powers of the void","stolen book","vineyards","warlock imp"},rel={"npc:drusilla-la-salle","topic:defias-brotherhood","quest:65","zone:elwynn"},m={start="Drusilla La Salle",level="4",faction="Alliance",id=1598},src={"The Stolen Tome"}}
E["quest:16"] = {t="quest",n="Give Gerard a Drink",z="elwynn",s="Give Gerard a Drink is a straightforward favor for Gerard Tiller, a farmer toiling in the fields of Northshire Valley. Looking to quench his thirst under the sun, he trades basic produce in exchange for bottles of fresh spring water. It offers young adventurers an early lesson in barter and supporting local laborers.",h="Give Gerard a Drink is a straightforward favor for Gerard Tiller, a farmer toiling in the fields of...",sec={{t="Thirsty Work in the Abbey Fields",b="Northshire Valley produces much of the grain, fruit, and vegetables consumed by the Abbey's clergy and the nearby garrisons. Tending the rows of crops under the open sky is grueling, hot work. Gerard Tiller spends long days out in the dirt, keeping the pests away and managing the harvests. With little time to run back and forth to the abbey's cellars or wells, he relies on passing recruits to bring him clean spring water to keep going.",sp=0},{t="The Economy of Barter",b="Rather than dealing in coin, Gerard prefers a fair and simple exchange of provisions. Travelers carrying extra flasks of Refreshing Spring Water can trade them directly for fresh apples picked from the orchard. In a kingdom stretching its resources thin to maintain order and feed its army, direct bartering among smallholders and recruits remains a practical way of getting by in rural Elwynn.",sp=0}},faq={{q="Who is Gerard Tiller?",a="Gerard Tiller is a humble farmer working the agricultural plots in Northshire Valley, just outside Northshire Abbey. He manages the fields and orchards that supply the local residents.",al={"gerard tiller","who is tiller","gerard"}},{q="Why does Gerard need water?",a="Laboring in the fields all day under the sun is exhausting work. Gerard relies on passing travelers to supply him with fresh spring water so he can stay hydrated without abandoning his chores.",al={"why spring water","gerard thirsty","why need drink"}},{q="Where can Refreshing Spring Water be found?",a="Refreshing Spring Water is commonly sold by food and drink vendors or innkeepers throughout Elwynn Forest, including Brother Danil inside Northshire Abbey.",al={"where get water","spring water source","how to get water"}},{q="Is this trade repeatable?",a="Yes. Gerard is continually working the fields and remains eager to trade fresh orchard apples for additional bottles of water as long as you have them to spare.",al={"repeatable quest","can i do this again","turn in more water"}},{q="What does Gerard offer in return for the drink?",a="In exchange for fresh water, Gerard trades bundles of freshly harvested Red-speckled Apples from the Northshire orchards.",al={"gerard reward","what do i get","trade reward"}},{q="Where is Gerard located in Northshire?",a="He can be found working the cultivated fields directly south and east of Northshire Abbey in northern Elwynn Forest.",al={"gerard tiller location","where is gerard","where is the farm"}}},ang={["faction:Alliance"]="Supporting Northshire's farmers ensures that the Abbey's garrison and priests remain well-fed during a turbulent period of kingdom defense.",["race:Human"]="For humans starting their journeys in Northshire, aiding neighbors like Gerard Tiller is an early example of the communal spirit that holds Elwynn together."},kw={"abbey farm","apples","barter","elwynn forest","gerard tiller","northshire valley","refreshing spring water"},rel={"npc:gerard-tiller","zone:elwynn"},m={start="Gerard Tiller",["end"]="Gerard Tiller",faction="Alliance",id=16},src={"Give Gerard a Drink"}}
E["quest:1667"] = {t="quest",n="Dead-tooth Jack",z="elwynn",s="Marshal Haggard, a retired officer living in eastern Elwynn Forest, was tricked into surrendering his official insignia to a Defias rogue named Dead-tooth Jack. Jack disguised himself in a Stormwind tabard in the dark to pose as Marshal Dughan and steal the badge. Haggard needs the badge recovered before the Defias Brotherhood can use it to impersonate Stormwind officials.",h="Marshal Haggard, a retired officer living in eastern Elwynn Forest, was tricked into surrendering his...",sec={{t="A Con in the Dark",b="Even seasoned soldiers can be caught off guard in the twilight of their years. Marshal Haggard, who lives in an isolated cottage on the eastern ridges of Elwynn, thought he was speaking to Marshal Dughan when a figure in a Stormwind tabard approached him one night. Claiming official business, the stranger asked for Haggard's old marshal's badge. Believing he was handing it over to a fellow officer, Haggard complied—only for the impostor, a Defias thief known as Dead-tooth Jack, to laugh in his face and vanish into the woods.",sp=0},{t="The Threat of False Authority",b="While Haggard is retired, his old badge still carries the legal weight and authority of the Kingdom of Stormwind. With Defias bandits creeping across Elwynn, Westfall, and Redridge, an authentic officer's badge in criminal hands poses an immediate danger. It could allow rogue operatives to pass guard checkpoints, redirect patrols, or commandeer supplies. Jack retreats to a camp to the south to stash the stolen prize in a locked strongbox, leaving Haggard desperate to see it retrieved before serious damage is done.",sp=0}},faq={{q="Who is Dead-tooth Jack?",a="Dead-tooth Jack is an operative of the Defias Brotherhood operating in eastern Elwynn Forest. Known for his audacity, he posed as Marshal Dughan under cover of darkness to trick the retired Marshal Haggard into handing over his official Stormwind badge.",al={"dead tooth jack","who is dead tooth","dead tooth jack lore"}},{q="Why does Marshal Haggard need his badge back?",a="The badge is an authentic symbol of Stormwind authority. Haggard fears that if the Defias keep it, they will use it to impersonate officials, bypass military patrols, and cause havoc across the realm.",al={"why recover badge","haggards badge","why does the badge matter"}},{q="How did Jack manage to fool Marshal Haggard?",a="Jack approached Haggard's cottage at night wearing a Stormwind tabard. In the poor light, Haggard mistook him for Marshal Dughan of Goldshire and handed over the insignia without question when asked.",al={"how did he fool haggard","haggard tricked","why did haggard give the badge"}},{q="Where does Jack keep the stolen badge?",a="Jack keeps the badge locked inside a strongbox located at his bandit camp south of Marshal Haggard's house. Jack carries the key to the chest on his person.",al={"badge location","where is the badge","dead tooth camp"}},{q="Who sent you to Marshal Haggard in the first place?",a="Harry Burlguard, the veteran warrior who frequents the Pig and Whistle Tavern in Stormwind, sends adventurers to Haggard knowing the old marshal has spare weaponry he might part with in exchange for help.",al={"who sends you here","burlguard","questgiver start"}},{q="What happens once the badge is returned?",a="Haggard is greatly relieved that the Defias cannot use his identity or rank against the kingdom. In gratitude, he salutes you and offers his pick of well-maintained military weapons from his time in service.",al={"quest turn in","haggard reaction","badge returned"},sp=1}},ang={["race:Human"]="For humans of Stormwind, this theft highlights how vulnerable the kingdom's rural borders are to Defias infiltrators who have no qualms wearing the crown's own colors to deceive retired veterans.",["class:Warrior"]="Marshal Haggard was once a veteran frontline fighter, and he rewards those who recover his honor with spare arms preserved from his years of active service.",["class:Rogue"]="Dead-tooth Jack's caper shows that the Defias Brotherhood relies on disguise, social engineering, and impudence just as much as crude highway robbery."},kw={"badge","dead-tooth jack","defias","elwynn forest","guard burlguard","impersonation","marshal dughan","marshal haggard","strongbox"},rel={"quest:1666","npc:marshal-dughan","zone:elwynn","topic:stormwind-kingdom"},m={start="Marshal Haggard",level="10",faction="Alliance",id=1667},src={"Dead-tooth Jack"}}
E["quest:1688"] = {t="quest",n="Surena Caledon",z="elwynn",s="Surena Caledon is a warlock training task given by Gakin the Darkbinder in the hidden basement beneath the Slaughtered Lamb in Stormwind. Gakin tasks an aspiring warlock with hunting down his former pupil, who betrayed him to run off with the Defias Brotherhood, and reclaiming a prized bloodstone choker.",h="Surena Caledon is a warlock training task given by Gakin the Darkbinder in the hidden basement beneath the...",sec={{t="A Bitter Master",b="Beneath the Slaughtered Lamb tavern in the Mage Quarter, Gakin the Darkbinder trains novices in the forbidden arts of fel summoning. Yet Gakin's history is not without misjudgment. Before taking on new pupils, he taught a young woman named Surena Caledon, admiring both her latent magical talent and her beauty. However, Surena abandoned her studies and Gakin's favor, fleeing the city to join the Defias Brotherhood alongside her lover, Erlan Drudgemoor.",sp=0},{t="The Stolen Bloodstone",b="Gakin cares little for the girl's survival after her departure, but he refuses to part with the valuable bloodstone choker he gifted her during her tutelage. He sends his newest apprentice southeast to the Brackwell Pumpkin Patch in Elwynn Forest, a farmstead overrun by Defias bandits, with explicit instructions to strip the jewel from Surena by any means necessary. The reclaimed bloodstone provides the magical catalyst needed for the apprentice's next trial: summoning and binding a Voidwalker.",sp=1}},faq={{q="Who is Surena Caledon?",a="Surena Caledon was an apprentice warlock under Gakin the Darkbinder in Stormwind. Endowed with natural talent, she gained Gakin's favor and gifts before abandoning her craft to elope with a Defias bandit named Erlan Drudgemoor.",al={"surena lore","who is surena","surena caledon backstory"}},{q="Why does Gakin want her choker back?",a="The choker holds a valuable bloodstone that Gakin gifted to Surena during her apprenticeship. In addition to resenting her theft and betrayal, Gakin requires the stone's dark resonance as a ritual reagent to help his new apprentice bind a Voidwalker.",al={"why get the choker","bloodstone choker importance"}},{q="Where can Surena Caledon be found?",a="Surena can be found sheltering alongside her Defias companions at the Brackwell Pumpkin Patch, an abandoned farmstead in southeastern Elwynn Forest.",al={"surena location","where is surena","where is the pumpkin patch"}},{q="What happens after recovering the choker?",a="Returning the bloodstone choker to Gakin completes this trial, opening the next task: entering the summoning circle in the crypts beneath the Slaughtered Lamb to bind a Voidwalker from the Twisting Nether.",al={"what comes next","next quest after surena"},sp=1},{q="Who is Erlan Drudgemoor?",a="Erlan Drudgemoor is a rogue affiliated with the Defias Brotherhood who seduced Surena Caledon and persuaded her to abandon her warlock training and flee Stormwind to live among the bandits.",al={"erlan lore","who is erlan drudgemoor"}},{q="Does Gakin show any remorse over Surena's fate?",a="Not at all. Gakin openly declares that her life means nothing to him anymore, coldly remarking that while it is a shame to waste magical talent, her betrayal makes her elimination necessary.",al={"does gakin care","gakin reaction to surena"}}},ang={["class:Warlock"]="Hunting Surena Caledon is an Alliance warlock's proving ground, showing that betrayal carries a lethal cost and that sentimental attachment has no place in the dark arts.",["race:Human"]="Surena's desertion highlights the persistent lure of the Defias Brotherhood among disgruntled citizens within the kingdom of Stormwind."},kw={"bloodstone choker","brackwell pumpkin patch","defias","erlan drudgemoor","gakin the darkbinder","slaughtered lamb","surena caledon","voidwalker"},rel={"npc:gakin-the-darkbinder","quest:1471","quest:1685","subzone:brackwell-pumpkin-patch","zone:elwynn","topic:stormwind-kingdom"},m={start="Gakin the Darkbinder",level="10",faction="Alliance",id=1688},src={"Surena Caledon (quest)"}}
E["quest:1689"] = {t="quest",n="The Binding",z="elwynn",s="The Binding is the final trial in an Alliance warlock's early training to bind a voidwalker in Stormwind City. Directed by Gakin the Darkbinder, the aspiring summoner uses a recovered Bloodstone Choker to pull an abyssal minion into a hidden subterranean circle and beat it into submission.",h="The Binding is the final trial in an Alliance warlock's early training to bind a voidwalker in Stormwind City.",sec={{t="Subjugation in the Crypts",b="Beneath the Slaughtered Lamb in Stormwind's Mage Quarter winds a complex of forgotten catacombs, far from the watchful gaze of the Silver Hand and Kirin Tor magistrates. Here, Gakin the Darkbinder instructs novice practitioners that mastering the dark arts is not merely about channeling magical currents, but asserting total dominance over otherworldly entities. After recovering Gakin's stolen Bloodstone Choker from Surena Caledon, the warlock is tasked with drawing forth a voidwalker directly into the summoning circle beneath the tavern.",sp=0},{t="Asserting Will over the Void",b="A voidwalker cannot be negotiated with; it must be broken. Utilizing the latent power inside the Bloodstone Choker, the summoner tears a rift, pulling a creature of shadow into the mortal plane. To complete the pact, the warlock must physically and magically batter the entity until its will shatters, proving their authority. Once overcome, the voidwalker's essence is bound to the caster, granting the warlock a durable, shadowy protector capable of absorbing brutal punishment in the battles ahead.",sp=0}},faq={{q="Where is the summoning circle located?",a="The summoning circle is deep inside the basement catacombs beneath The Slaughtered Lamb in Stormwind's Mage Quarter. From Gakin the Darkbinder, follow the stairs down into the underground passages until you reach the lowest chamber bearing a glowing purple ritual rune on the stone floor.",al={"summoning circle location","where do i summon the voidwalker","where is the circle"}},{q="Who is Gakin the Darkbinder?",a="Gakin the Darkbinder is a warlock trainer operating covertly beneath The Slaughtered Lamb tavern in Stormwind. He secretly tutors promising human and gnome practitioners in summoning, subjugation, and controlling demonic and void-touched entities without alerting the city guard or church authorities.",al={"who is gakin","gakin the darkbinder lore","gakin"}},{q="What is the Bloodstone Choker used for?",a="The Bloodstone Choker is a magical talisman previously stolen by Surena Caledon. Imbued with focused magical power, it acts as a catalyst that allows a novice warlock to breach the veil and draw forth an unruly voidwalker inside the designated summoning circle.",al={"bloodstone choker use","why do i need the choker","choker"}},{q="Why do warlocks have to fight their demons to bind them?",a="Extraplanar entities like demons and void creatures do not willingly serve mortal masters. A warlock must demonstrate superior strength and an iron will by physically or magically breaking the creature in combat before establishing a permanent, subservient bond.",al={"why fight the voidwalker","why subdue demons","demon subjugation"}},{q="What happens after completing the ritual?",a="Once the creature is defeated and the choker returned to Gakin, the warlock gains the knowledge and ritual technique required to summon and command a loyal voidwalker to shield them during their travels.",al={"what reward do i get","voidwalker spell","after the binding"}},{q="Why is this ritual performed in secret beneath a tavern?",a="Demonology and void magic are strictly taboo, viewed with intense hostility by the Church of the Holy Light and the magi of the Alliance. Warlocks in Stormwind operate from concealed basements and catacombs to practice their forbidden arts away from the authorities.",al={"why hidden under tavern","is fel magic illegal","slaughtered lamb basement"}}},ang={["class:Warlock"]="This rite of passage provides the warlock with their primary defensive minion, marking the shift from reckless dabbler to a commander of extradimensional forces.",["faction:Alliance"]="Though the Alliance champions the Holy Light and arcane order, pragmatic leaders turn a blind eye to dark practitioners operating beneath the Mage Quarter, recognizing the necessity of their grim arts in perilous times.",["race:Human"]="Human warlocks must navigate the intense scrutiny of Stormwind's priesthood, mastering dangerous entities in the shadows while keeping their power hidden from the city above.",["race:Gnome"]="Gnome warlocks bring clinical curiosity to dark summoning, treating the subjugation of void entities as a precise metaphysical experiment under Gakin's guidance."},kw={"binding","bloodstone choker","gakin the darkbinder","mage quarter","slaughtered lamb","stormwind","summoning circle","voidwalker"},rel={"npc:gakin-the-darkbinder","quest:1688","quest:1685","zone:stormwind","quest:1471","zone:elwynn","topic:stormwind-kingdom"},m={start="Gakin the Darkbinder",level="10",faction="Alliance",id=1689},src={"The Binding (Voidwalker, Stormwind)"}}
E["quest:1739"] = {t="quest",n="The Binding",z="elwynn",s="The Binding is the final initiation ritual for Alliance warlocks seeking to command a succubus in Stormwind. Using the enchanted core obtained from the Heartswood, the practitioner enters the summoning circle beneath The Slaughtered Lamb to drag forth and physically overpower the demon. Once defeated, the demon's will is chained, binding its servitude to the summoner.",h="The Binding is the final initiation ritual for Alliance warlocks seeking to command a succubus in Stormwind.",sec={{t="Descent into the Crypt",b="Hidden beneath the floorboards of The Slaughtered Lamb in Stormwind's Mage Quarter lies a cavernous crypt dedicated to forbidden arts. Far from the watchful eyes of the city watch and the Cathedral of Light, the city's covert warlock enclave conducts its most dangerous rituals here. Summoning circles etched into stone channel the raw forces of the Nether, allowing ambitious initiates to pierce the veil between worlds.",sp=0},{t="Subjugating the Seductress",b="Summoning a succubus requires far more than merely chanting incantations. A warlock must bring a focus—in this case, the prepared Heartswood Core—and cast a ritual of breach at the circle. Succubi are known to corrupt, seduce, and overwhelm even fortified minds. To establish absolute mastery, the summoner must cut the beast down in single combat, banishing its physical form back to the Twisting Nether while securing its true tether.",sp=0},{t="Gakin's Secrets",b="Upon slaying the summoned creature, the triumphant initiate brings the depleted core back to Gakin the Darkbinder. Having proven both mental fortitude and martial prowess, the apprentice receives the fundamental knowledge needed to call the succubus forth across the void whenever needed. The ritual marks an Alliance warlock's maturation into an adept capable of handling volatile, sapient demons.",sp=1}},faq={{q="Where does the summoning take place?",a="The ritual takes place in the deep catacombs beneath The Slaughtered Lamb, an unremarkable tavern located in Stormwind's Mage Quarter. Warlocks descend down spiral stairs past the pub cellar into an underground sanctum equipped with arcane summoning circles.",al={"where do i summon","succubus summoning location","crypt location"}},{q="What is the purpose of the Heartswood Core?",a="The Heartswood Core serves as an anchor and catalyst. Taken from the Heartswood, the tree that grew where two night elf lovers fell in Ashenvale during the War of the Ancients, it provides the precise spiritual resonance required to tear open a localized rift and lure a succubus across the Twisting Nether.",al={"why heartswood core","what does heartswood do"}},{q="Why must the warlock kill the succubus?",a="Demons of the Nether yield only to superior will and strength. A succubus specializes in psychological manipulation and mental subjugation; allowing it to manifest without immediate defeat invites ruin. Slaying the creature in combat establishes dominance, forcibly imprinting the warlock's authority onto the spirit before it coalesces back in the Nether.",al={"why do i fight the succubus","why kill the demon to bind it"}},{q="Who is Gakin the Darkbinder?",a="Gakin the Darkbinder is a senior warlock residing in The Slaughtered Lamb who oversees the training of Alliance practitioners in Stormwind. He coordinates the secretive procurement of demonology artifacts and evaluates whether acolytes have the willpower to bend demonic entities to their command.",al={"who is gakin","gakin darkbinder lore"}},{q="Who is Surena that Gakin mentions?",a="Surena Caledon was Gakin's former student, who ran off with the Defias and whose choker you recovered earlier. Gakin wryly wonders whether she was a succubus in disguise sent to warp his mind, then decides he gives her too much credit.",al={"surena reference","who was surena"}},{q="Are succubi permitted in the streets of Stormwind?",a="Open demonology is strictly forbidden by the Church of the Holy Light and the kingdom's authorities. While game mechanics allow bound demons to follow warlocks through the city, in lore the practice is confined to the shadows, basements, and secluded sanctums such as The Slaughtered Lamb's crypts.",al={"can guards see my succubus","is demon summoning legal in stormwind"}}},ang={["class:Warlock"]="This rite marks a crucial milestone for human and gnome warlocks, graduating them from handling mindless imps and voidwalkers to commanding sapient, calculating demons.",["faction:Alliance"]="The existence of this ritual deep beneath Stormwind shows how the Alliance quietly tolerates shadow magic in secret alcoves despite the Church's doctrines."},kw={"binding","crypt","darkbinder","gakin","heartswood","slaughtered lamb","stormwind","succubus","summoning circle"},rel={"npc:gakin-the-darkbinder","subzone:slaughtered-lamb","quest:1738","quest:1472","quest:1685","topic:stormwind-kingdom","quest:1471","zone:elwynn"},m={start="Gakin the Darkbinder",level="20",faction="Alliance",id=1739},src={"The Binding (Succubus, Stormwind)"}}
E["quest:176"] = {t="quest",n="Wanted: \"Hogger\"",z="elwynn",s="Wanted: \"Hogger\" is an Alliance bounty posted outside Goldshire for the head of a massive, savage gnoll chieftain. Hogger prowls the southwestern woods of Elwynn Forest and has violently thwarted every attempt by the local authorities to bring him down.",h="Wanted: \"Hogger\" is an Alliance bounty posted outside Goldshire for the head of a massive, savage gnoll...",sec={{t="A Menace in the Woods",b="While Elwynn Forest struggles with banditry and kobold infestations, the gnoll tribes in the south have grown bolder and more organized under the brute leadership of Hogger. Towering over typical Riverpaw gnolls, Hogger has established camp near the Forest's Edge, ambushing travelers and overpowering the local militia patrols sent to subdue him.",sp=0},{t="Goldshire's Desperation",b="With the Stormwind Army stretched thin and unable to spare regular forces to police the outskirts of the capital, Marshal Dughan took the unusual step of posting an open bounty on the beast. Taking down Hogger requires venture into deeply hostile gnoll territory, and his ferocity has earned him a reputation as the deadliest threat facing novice adventurers in Elwynn.",sp=0}},faq={{q="Who is Hogger?",a="Hogger is an unusually large and savage gnoll leader terrorizing southwestern Elwynn Forest. He commands local packs around the Forest's Edge and has violently defeated all previous attempts by Stormwind guards to capture or kill him.",al={"who is hogger","hogger lore","what is hogger"}},{q="Where can Hogger be found?",a="Hogger wanders among the gnoll encampments in southwestern Elwynn Forest, near the southern borders known as Forest's Edge, just north of the river boundary with Westfall and Duskwood.",al={"hogger location","where is hogger","find hogger"}},{q="Why is there a bounty on Hogger?",a="The Stormwind Army placed a bounty on Hogger because he has overpowered local patrols and poses a lethal danger to travelers. With official troops stretched thin across the kingdom, Marshal Dughan turned to independent adventurers and bounty hunters to eliminate the threat.",al={"why kill hogger","wanted poster hogger","who put bounty on hogger"}},{q="Who collects the proof of Hogger's death?",a="Proof of the beast's demise—his Huge Gnoll Claw—must be brought directly to Marshal Dughan, who commands the local garrison stationed in Goldshire.",al={"turn in hogger","where to turn in hogger","who wants hogger claw"}},{q="Why is Hogger so dangerous compared to other gnolls?",a="Unlike the common gnolls prowling Elwynn, Hogger possesses immense physical stature and brutality. He hits significantly harder and can withstand far more punishment, often overwhelming single combatants who underestimate him.",al={"is hogger strong","why is hogger elite"}},{q="Why can't the Stormwind guards handle Hogger themselves?",a="The kingdom's military resources are severely depleted and tied down defending major borders or dealing with the missing King Varian Wrynn. Marshal Dughan's small detachment in Goldshire lacks the manpower to safely hunt down such a resilient monster.",al={"why doesn't dughan kill hogger","where is stormwind army"}}},ang={["faction:Alliance"]="Taking down Hogger is considered a rite of passage for young Alliance heroes testing their mettle in the defense of Stormwind's heartland.",["race:Human"]="For humans of Elwynn, slaying Hogger secures homesteads and road trade that have been terrorized by gnoll ambushes for months."},kw={"bounty","dughan","elwynn","forest's edge","gnoll","goldshire","hogger","wanted"},rel={"npc:marshal-dughan","subzone:goldshire","subzone:forest-s-edge","topic:gnoll","topic:stormwind-army","zone:elwynn","topic:stormwind-kingdom"},m={start="Wanted Poster",["end"]="Marshal Dughan",level="11",faction="Alliance",id=176},src={"Wanted: \"Hogger\""}}
E["quest:18"] = {t="quest",n="Brotherhood of Thieves",z="elwynn",s="Brotherhood of Thieves is an early task assigned by Deputy Willem outside Northshire Abbey. It directs young Alliance recruits across the eastern river to push back an encroaching band of brigands known as the Defias Brotherhood. Collecting the thieves' signature red burlap bandanas provides Stormwind authorities their first tangible evidence of the group's organized presence in the valley.",h="Brotherhood of Thieves is an early task assigned by Deputy Willem outside Northshire Abbey.",sec={{t="Bandits in the Valley",b="Northshire Valley has long been considered a safe haven within Elwynn Forest, protected by Stormwind guards and dedicated to training new recruits and Clerics of the Holy Light. Recently, however, discipline around the perimeter has frayed. Vagrants and thieves have crossed the eastern river, lurking near the woods and setting up small camps right under the abbey's nose. Deputy Willem, tasked with maintaining local order, recognizes that the local guard cannot spare the manpower to police every corner of the valley without volunteer aid.",sp=0},{t="The Crimson Sigil",b="What sets these outlaws apart from common highwaymen is their coordination and uniform attire. They call themselves the Defias Brotherhood, marking their allegiance with distinctive red burlap bandanas tied over their faces. By ordering recruits to hunt these brigands and retrieve their masks, Deputy Willem aims to curb their bold advance while taking inventory of just how deeply the Defias have infiltrated the heartland of the kingdom.",sp=0}},faq={{q="Who are the Defias Brotherhood?",a="The Defias Brotherhood is an organized faction of brigands and outlaws currently operating across Elwynn Forest and Westfall. While Northshire authorities initially see them merely as bold thieves, they wear uniform red burlap masks and follow coordinated leadership.",al={"who are the defias","what is defias brotherhood","defias lore"}},{q="Why is Deputy Willem asking recruits for help instead of using the Stormwind Army?",a="The Stormwind Army and local city guards are spread thin throughout the kingdom. With unrest rising in neighboring regions and leadership strained in Stormwind City, local deputies must rely on eager volunteers and novice recruits to clear out encroaching bandits.",al={"why willem needs help","where are stormwind guards","why no army"}},{q="Where are these thieves coming from?",a="In Northshire, the thieves have gathered across the river to the east of the abbey, skulking around the edges of local farmsteads and campsites near the vineyard.",al={"where are the bandits","defias location northshire"}},{q="Why do the thieves wear red burlap bandanas?",a="The red burlap bandana serves as the unified badge of the Defias Brotherhood, masking their identities while signaling their allegiance to fellow outlaws operating throughout the human territories.",al={"why red bandanas","meaning of red masks","red burlap"}},{q="What happens after completing this quest?",a="Deputy Willem and the locals quickly realize the bandit threat extends further into Northshire, leading recruits to aid Milly Osworth with her ruined harvest and track down a specific ringleader named Garrick Padfoot.",al={"what comes next","after brotherhood of thieves"}},{q="Does Deputy Willem know who leads the Defias?",a="At this point, Willem does not understand the full scope of the organization. He only knows they call themselves the Defias Brotherhood and suspects their presence near the abbey bodes ill for Stormwind.",al={"does willem know vancleef","who leads defias northshire"}}},ang={["race:Human"]="For humans starting their training in Northshire, confronting the Defias is the first harsh reminder that the safety of the Kingdom of Stormwind is slipping from within.",["faction:Alliance"]="Stormwind authorities rely on newly arrived Alliance recruits to keep peace in Northshire while the kingdom's formal military is stretched thin.",["class:Rogue"]="Encountering the Defias provides novice rogues a glimpse of how organized criminal networks operate in the shadows of the human heartland."},kw={"bandanas","brotherhood of thieves","defias","deputy willem","elwynn","northshire","stormwind army"},rel={"npc:willem","topic:defias-brotherhood","subzone:northshire-abbey","quest:783","quest:65","zone:elwynn","topic:stormwind-army","topic:stormwind-kingdom"},m={start="Deputy Willem",level="4",faction="Alliance",id=18},src={"Brotherhood of Thieves"}}
E["quest:1861"] = {t="quest",n="Mirror Lake",z="elwynn",s="Mirror Lake is an introductory investigative quest for novice Alliance mages studying in the Mage Quarter of Stormwind. Tasked by Jennea Cannon, apprentices venture just southwest of the city gates to sample the waterfall waters of Mirror Lake for residual magical contamination.",h="Mirror Lake is an introductory investigative quest for novice Alliance mages studying in the Mage Quarter of...",sec={{t="Ley Lines and Shifting Currents",b="Azeroth has suffered catastrophic mystic conflicts over the recent decades, from the opening of the Dark Portal to the Third War and the sundering of Mount Hyjal. These violent shocks tore ancient arcane currents from their once-stable channels. In the Wizard's Sanctum of Stormwind, magi like Jennea Cannon monitor these shifts closely, fearing that dislodged flows of arcane power might bleed into the surrounding wilderness and corrupt local ecosystems.",sp=0},{t="Testing the Waters",b="Mirror Lake lies nestled beneath the cliffs just southwest of the Stormwind gates, serving as a primary natural reservoir fed by mountain falls. Because the surrounding countryside depends on these waters, Jennea sends novice mages equipped with a glass flask directly to the base of the waterfall. Collecting fresh spray allows the Sanctum to conduct delicate scrying and reagent tests to confirm whether wild magic has begun seeping into the public water supply.",sp=0}},faq={{q="Why does Jennea Cannon want a water sample from Mirror Lake?",a="Massive mystical wars across Azeroth have ruptured natural ley currents. Jennea Cannon fears that unsettled arcane energies are bleeding into the water table around Stormwind, which could adversely affect anyone who drinks from the lake.",al={"why mirror lake water","jennea water sample","what is this quest for"}},{q="Where exactly is Mirror Lake?",a="Mirror Lake is situated in northwestern Elwynn Forest, tucked against the high bluffs just southwest of the main gates of Stormwind. The required sample is taken from the pool at the foot of its cascading waterfall.",al={"where is mirror lake","mirror lake location","find mirror lake"}},{q="What happens if the water is tainted?",a="If raw arcane currents seep into the water, anyone relying on Mirror Lake could suffer unpredictable, harmful mutations or magical sickness from sustained exposure.",al={"is the water poisoned","what if water has magic","magical taint effects"}},{q="Who can undertake this mission?",a="This assignment is reserved specifically for novice mages training in the Alliance, serving as one of their earliest practical fieldwork tasks on behalf of the Wizard's Sanctum.",al={"who gets mirror lake quest","is mirror lake mage only"}},{q="Does this quest lead to further investigations?",a="It concludes the direct initial task begun with Jennea Cannon's summons, rewarding the apprentice with their first formal mage implement and establishing their duty to monitor magical disturbances across the realm.",al={"what comes after mirror lake","mirror lake quest chain"}},{q="What caused the magical currents to destabilize in the first place?",a="Successive global cataclysms—including the opening of the Dark Portal, the destruction of Dalaran, and the battle at the World Tree during the Third War—violently disrupted the world's arcane ley network.",al={"why are ley lines damaged","mystic struggles meaning","what broke the magic"}}},ang={["class:Mage"]="This task marks an apprentice's transition from reading dusty tomes in the Wizard's Sanctum to investigating real-world arcane phenomena, rewarding their first dedicated mage staff or off-hand orb.",["race:Human"]="Mirror Lake feeds the surrounding farmlands and waterways of Elwynn, making its purity vital to the daily health of Stormwind's citizenry.",["faction:Alliance"]="Ensuring the safety of Elwynn's natural resources is one of the quiet ways the magi of the Wizard's Sanctum safeguard the heart of the kingdom."},kw={"arcane taint","elwynn forest","jennea cannon","ley lines","mirror lake","water sample","wizards sanctum"},rel={"npc:jennea-cannon","quest:1860","zone:elwynn","subzone:stormwind-gate","topic:stormwind-kingdom"},m={start="Jennea Cannon",level="10",faction="Alliance",id=1861},src={"Mirror Lake (quest)"}}
E["quest:21"] = {t="quest",n="Skirmish at Echo Ridge",z="elwynn",s="Skirmish at Echo Ridge is a direct military operation ordered by Marshal McBride to cleanse the Echo Ridge Mine of kobold laborers. Following initial reconnaissance, this strike aims to prevent the subterranean infestation from establishing a permanent foothold in Northshire Valley.",h="Skirmish at Echo Ridge is a direct military operation ordered by Marshal McBride to cleanse the Echo Ridge...",sec={{t="Purging the Mine",b="After early scouting confirmed that kobolds had overrun the Echo Ridge Mine, Marshal McBride wasted no time organizing an active counterattack. Left undisturbed, subterranean vermin rapidly fortify their tunnels, stockpile stolen resources, and multiply beyond control. To protect the vital agricultural and spiritual retreat of Northshire Valley, the local garrison relies on recruits to engage the kobold laborers directly and thin their ranks before they entrench themselves further.",sp=0},{t="A Thin Defense",b="The necessity of employing newly enlisted recruits for a direct frontal assault reflects the strained state of the Stormwind Army. With frontline garrisons stretched thin across the southern borders and rumors of rising unrest throughout Elwynn, local officers like McBride must muster whatever willing hands they can find. The successful skirmish at Echo Ridge demonstrates the recruit's reliability, earning them formal respect and readying them for more critical missions elsewhere in the kingdom.",sp=0}},faq={{q="Why are kobolds infesting the Echo Ridge Mine?",a="Kobolds are naturally drawn to mineral-rich underground tunnels and abandoned quarries. With Stormwind's military stretched thin, unguarded sites like Echo Ridge became easy targets for vermin looking to dig burrows, hoard gold, and establish subterranean footholds.",al={"why kobolds in mine","echo ridge kobolds","what are kobolds doing"}},{q="Who orders the skirmish?",a="Marshal McBride, the ranking officer of the Stormwind Army stationed at Northshire Abbey, commands the operation. He oversees the defense of the valley and is tasked with maintaining order despite limited military manpower.",al={"who gives skirmish quest","marshal mcbride orders"}},{q="What is the strategic importance of Echo Ridge Mine?",a="Echo Ridge provides raw stone and ore critical for Northshire's maintenance and Stormwind's broader reconstruction efforts. Allowing an infestation to flourish right on Northshire's northern border poses a direct physical threat to the abbey and nearby vineyards.",al={"why echo ridge matters","echo ridge mine importance"}},{q="Where does this mission lead next?",a="Once the mine is cleared of initial laborer resistance, Marshal McBride recognizes the adventurer's proven combat capability and directs them onward toward Goldshire to assist the wider regional defense.",al={"what quest after skirmish","next step after echo ridge"}},{q="Why doesn't the Stormwind Army clear the mine themselves?",a="The Stormwind Army is critically short on personnel, struggling to defend distant borders and responding to banditry across Elwynn. Officers like McBride must rely on newly sworn recruits to handle local threats while seasoned guards hold defensive perimeters.",al={"why recruits","where are stormwind soldiers"}},{q="Are kobolds intelligent enough to be an organized military threat?",a="While individual kobold laborers are cowardly and simple-minded, they are dangerously territorial and aggressive in large numbers. Left unchecked, they rapidly dig labyrinthine tunnels, trap caverns, and invite larger, better-armed vermin to join them.",al={"are kobolds smart","kobold danger level"}}},ang={["race:Human"]="Clearing Echo Ridge represents a recruit's first true test of arms in defense of their ancestral kingdom, proving their mettle directly to the Stormwind military brass.",["faction:Alliance"]="Every mine wrested back from encroaching monsters secures vital stone and ore necessary to rebuild and fortify human settlements in the wake of war.",["class:Warrior"]="Subterranean brawls against swarming workers offer young warriors their first taste of close-quarters melee against multiple entrenched foes.",["profession:Mining"]="Clearing the infestation restores hope that valuable mineral veins throughout Northshire Valley can once again be safely excavated and smelted."},kw={"echo ridge","echo ridge mine","elwynn","kobold","laborer","marshal mcbride","mcbride","northshire","skirmish","stormwind army"},rel={"quest:15","subzone:echo-ridge-mine","npc:marshal-mcbride","subzone:northshire-abbey","topic:kobold","topic:stormwind-army","zone:elwynn","topic:stormwind-kingdom"},m={level="5",faction="Alliance",id=21},src={"Skirmish at Echo Ridge"}}
E["quest:239"] = {t="quest",n="Westbrook Garrison Needs Help!",z="elwynn",s="Marshal Dughan orders available adventurers west to Westbrook Garrison, the outpost guarding Elwynn Forest's border with Westfall. With the Stormwind army stretched thin across the kingdom, Deputy Rainer and his guards find themselves facing mounting pressure from aggressive Riverpaw gnolls and wandering thieves without regular reinforcements.",h="Marshal Dughan orders available adventurers west to Westbrook Garrison, the outpost guarding Elwynn Forest's...",sec={{t="A Frontier Stretched Thin",b="Westbrook Garrison marks the western edge of Elwynn Forest, situated right where the settled woodlands begin to give way to the troubled plains of Westfall. As gnoll warbands and bandits grow bolder along the waterways and western roads, the outpost's small garrison has pleaded for more men. However, Marshal Dughan and the Goldshire administration have no professional Stormwind soldiers to spare, leaving local commanders with no choice but to hire traveling mercenaries and wandering adventurers.",sp=0},{t="The Threat Across the Brook",b="The primary threat facing Deputy Rainer and his men is the Riverpaw gnoll pack, whose raiding parties harass travelers and nearby homesteads. Operating in the borderlands between Elwynn and Westfall, these gnolls have taken advantage of Stormwind's political and military distraction to press deeper into inhabited territory. Westbrook Garrison stands as the final line of defense keeping them from roaming unchecked into the heart of the forest.",sp=0}},faq={{q="Why can't Stormwind send regular soldiers to Westbrook Garrison?",a="Stormwind's standing military is severely overstretched across multiple frontiers. With King Varian Wrynn missing and the realm contending with internal strife, high command has refused or been unable to deploy regular soldiers to rural outposts, forcing town marshals like Dughan to rely on freelance volunteers.",al={"why no stormwind troops","why send adventurers","where is stormwind army"}},{q="Where is Westbrook Garrison located?",a="The garrison sits on the western edge of Elwynn Forest. Follow the main road west out of Goldshire past the small brook; the fortified tower will be on your right just before the border into Westfall.",al={"westbrook garrison location","how to get to westbrook","where is deputy rainer"}},{q="What threats are troubling the garrison?",a="Deputy Rainer is dealing with persistent raids by the Riverpaw gnolls, as well as an uptick in thief and bandit activity operating in the border country between Westfall and Elwynn Forest.",al={"what attacks westbrook","why does rainer need help","who is attacking westbrook garrison"}},{q="Who is Deputy Rainer?",a="Deputy Rainer is the Stormwind officer stationed in command of Westbrook Garrison. Tasked with holding the western border, he is forced to look to civilian volunteers and mercenaries due to a severe shortage of official military reinforcements.",al={"rainer lore","deputy rainer","who is rainer"}},{q="What happens after reporting to Deputy Rainer?",a="Deputy Rainer immediately enlists your aid against the local Riverpaw gnolls, placing a bounty on their collars to thin their numbers and protect the border road.",al={"what comes next","westbrook quest chain","rainer quest"}},{q="Why are the gnolls pushing into Elwynn Forest?",a="The Riverpaw gnolls have established camps along the rivers separating Elwynn and Westfall. Taking advantage of the reduced military presence along the border, they have grown bold enough to raid trade routes and push toward Elwynn's interior farms.",al={"riverpaw gnolls elwynn","why are gnolls here","gnoll problem"}}},ang={["race:Human"]="For humans of Stormwind, this dispatch is an unsettling sign of the kingdom's neglect, showing firsthand how thin the crown's defenses have worn in the wake of the King's disappearance.",["faction:Alliance"]="Alliance volunteers take up the mantle of regular soldiers here, doing the groundwork necessary to keep core territories from descending into complete chaos."},kw={"deputy rainer","elwynn forest","gnolls","goldshire","marshal dughan","riverpaw","westbrook garrison"},rel={"subzone:westbrook-garrison","npc:deputy-rainer","npc:marshal-dughan","quest:11","quest:76","zone:elwynn","topic:gnoll","topic:stormwind-kingdom"},m={start="Marshal Dughan",["end"]="Deputy Rainer",faction="Alliance",id=239},src={"Westbrook Garrison Needs Help!"}}
E["quest:248"] = {t="quest",n="Looking Further",z="elwynn",s="Looking Further is an Alliance espionage mission directed by the wizard Theocritus via an enchanted conduit. To investigate tensions between the rogue mage Morganth and the Blackrock orcs, you must infiltrate the watch tower beside Stonewatch Keep and plant an enchanted glyph inside an unnoticed container.",h="Looking Further is an Alliance espionage mission directed by the wizard Theocritus via an enchanted conduit.",sec={{t="A Rift in Redridge",b="From his sanctum in Elwynn Forest, the wizard Theocritus maintains a vigilant watch over eastern Redridge through scrying magic. While monitoring the Tower of Ilgalar, he detects sudden contention between the renegade human warlock Morganth and the Blackrock orcs entrenched in Stonewatch Keep. Rather than working together against the Kingdom of Stormwind, these hostile factions are locked in conflict over an unknown prize, prompting Theocritus to intervene before the balance shifts.",sp=0},{t="The Eye on Stonewatch",b="To pierce the defenses of Stonewatch Keep, Theocritus requires a second magical anchor point. He commands adventurers to scale the intact watch tower standing adjacent to the ruined fortress. There, among the garrison's clutter, an empty jar discarded by orcish sentries provides the perfect mundane hiding spot. Once the Glyph of Azora is affixed inside the vessel, Theocritus can telepathically sift through the minds within Stonewatch to uncover what drove Morganth and the Blackrocks apart.",sp=1}},faq={{q="Who sends me on this mission?",a="The quest is imparted by Theocritus, the Mage of Azora, speaking through the Old Lion Statue in the Redridge Mountains after you completed his prior task.",al={"who gives quest","quest giver","old lion statue"}},{q="Why is Theocritus spying on Stonewatch Keep?",a="Theocritus detected active hostility brewing between Morganth, the rogue dark wizard in the Tower of Ilgalar, and the Blackrock orcs occupying Stonewatch Keep. He wishes to discover what sparked their conflict.",al={"why spy on orcs","theocritus purpose","why stonewatch"}},{q="Where is the container located?",a="The container is an empty jar resting atop barrels at the very summit of the intact watch tower standing right beside the main entrance of Stonewatch Keep.",al={"empty jar location","where to plant glyph","where is watch tower"}},{q="What does the Glyph of Azora do?",a="It serves as a magical scrying and divination focus, allowing Theocritus to remotely monitor the surrounding area and delve into the minds of the Blackrock orcs inside the keep.",al={"glyph of azora purpose","what does glyph do"}},{q="What follows after planting the glyph?",a="Once Theocritus divines the source of the conflict—learning Morganth searches for the Scythe of Elune—he assigns you to hunt down Morganth himself in the Tower of Ilgalar and bring back his Pendant of Shadow.",al={"next quest","what happens next","looking further follow up"},sp=1},{q="Why use an empty jar?",a="A magical spy rune needs an inconspicuous vessel so guards do not spot or destroy it. The abandoned, foul-smelling liquor jar left forgotten on barrels makes an ideal hiding spot.",al={"why the jar","empty jar lore"}}},ang={["class:Mage"]="Theocritus relies on sophisticated long-range scrying magic through the Glyph of Azora, demonstrating how the Kirin Tor and Azora mages establish magical surveillance across hostile territories.",["faction:Alliance"]="Stonewatch Keep remains the primary stronghold of the Blackrock clan in Redridge. Gathering intelligence on their infighting with Morganth is vital to defending Lakeshire."},kw={"empty jar","glyph of azora","looking further","morganth","old lion statue","stonewatch","stonewatch keep","theocritus","tower of ilgalar"},rel={"quest:94","quest:249","quest:178","npc:theocritus","subzone:stonewatch-keep","subzone:stonewatch","subzone:tower-of-ilgalar","zone:elwynn"},m={start="Old Lion Statue",["end"]="An Empty Jar",level="22",faction="Alliance",id=248},src={"Looking Further"}}
E["quest:3103"] = {t="quest",n="Hallowed Letter",z="elwynn",s="The Hallowed Letter is a formal summons given to promising young priests by Marshal McBride on behalf of Northshire Abbey's resident trainer, Priestess Anetta. It marks the start of a fledgling priest's formal mentorship in the tenets of the Holy Light amidst a troubled and vulnerable world.",h="The Hallowed Letter is a formal summons given to promising young priests by Marshal McBride on behalf of...",sec={{t="A Summons to the Cloth",b="After proving their mettle against the vermin encroaching on Northshire's vineyards, novitiate priests are handed a missive bearing the sacred seal of Priestess Anetta. Delivered through Marshal McBride, the letter serves as an invitation to begin serious study of the Holy Light within the abbey's quiet halls.",sp=0},{t="A World in Need",b="When presented with the letter, Priestess Anetta impresses upon her new pupil the grim state of the realm. Lingering threats from the Burning Legion cast long shadows across Azeroth, while the continents struggle with fresh wounds and unrest. In her eyes, taking up the mantle of a priest is not merely an academic devotion, but an urgent moral responsibility to bring healing and solace to a suffering world.",sp=0}},faq={{q="What is the Hallowed Letter?",a="It is a sealed letter bearing the crest of Priestess Anetta, delivered to newly arrived human priests by Marshal McBride in Northshire Valley. It directs the novice to formalize their training inside Northshire Abbey.",al={"hallowed letter","priest intro quest northshire","anetta letter"}},{q="Who sends the Hallowed Letter?",a="Priestess Anetta, the priest trainer stationed inside Northshire Abbey, pens and seals the missive, asking Marshal McBride to hand it over once the initiate returns from scouting the kobold infestation.",al={"who wrote hallowed letter","who sent the letter"}},{q="Why does Priestess Anetta summon new priests?",a="Anetta recognizes the novice's calling to the Holy Light and seeks to guide their training. With perils like remnants of the Burning Legion lingering in the world, she stresses that disciplined healers and guides are urgently needed.",al={"why does anetta want me","purpose of the letter"}},{q="Where can Priestess Anetta be found?",a="She resides inside the main hall of Northshire Abbey, ready to train human priests as they master their first prayers and rituals.",al={"where is anetta","priestess anetta location"}},{q="What happens after presenting the letter to Priestess Anetta?",a="Upon reading the letter and greeting Anetta, she accepts the player as her student, imparting basic wisdom and directing them to aid wounded soldiers stationed around Northshire.",al={"next quest after hallowed letter","what follows hallowed letter"}},{q="Why is the Burning Legion mentioned in Northshire?",a="Although the Third War ended, demonic remnants from the Legion still haunt Azeroth. Priestess Anetta mentions this global threat to emphasize the broader dangers awaiting any adventurer leaving the valley.",al={"burning legion northshire","why does anetta talk about demons"}}},ang={["class:Priest"]="This quest marks your official induction as a student of the Holy Light under Priestess Anetta, framing your divine magic as a vital duty to heal a fractured world.",["race:Human"]="Northshire Abbey has long been a sanctuary of faith and recuperation for the Kingdom of Stormwind, carrying on its traditions despite the encroaching troubles around Elwynn."},kw={"elwynn","hallowed letter","holy light","marshal mcbride","northshire abbey","priest","priestess anetta"},rel={"npc:priestess-anetta","subzone:northshire-abbey","npc:marshal-mcbride","topic:light","zone:elwynn","topic:burning-legion","topic:kobold"},m={start="Marshal McBride",["end"]="Priestess Anetta",level="3",faction="Alliance",id=3103},src={"Hallowed Letter (quest)"}}
E["quest:3104"] = {t="quest",n="Glyphic Letter",z="elwynn",s="The Glyphic Letter is a formal summons delivered to novice human mages inside Northshire Valley by Marshal McBride. Written under the arcane seal of Khelden Bremen, the note calls promising spellcasters into Northshire Abbey to begin their formal tutelage in the arcane arts.",h="The Glyphic Letter is a formal summons delivered to novice human mages inside Northshire Valley by Marshal...",sec={{t="A Summons to the Arcane",b="Once an aspiring apprentice proves their capability by aiding Marshal McBride against the local vermin, the garrison commander hands them a message marked with arcane runes. The letter comes directly from Khelden Bremen, Northshire's resident mage trainer, who monitors new recruits arriving at the abbey for signs of magical discipline and talent.",sp=0},{t="The Weight of Wizardry",b="Northshire Abbey has historically served as a sanctuary for the Holy Light, yet the ongoing perils facing Stormwind require practitioners of every discipline. Answering the letter leads the novice upstairs to Khelden Bremen. Rather than offering easy praise, the tutor delivers a stark warning: mastering arcane power demands defiance of natural limits, inviting both profound respect and deep-seated fear from ordinary folk.",sp=0}},faq={{q="Who delivers the Glyphic Letter?",a="Marshal McBride presents the letter to newly arrived mages outside Northshire Abbey once they have helped clear the nearby kobold vermin.",al={"who gives glyphic letter","glyphic letter quest giver"}},{q="Who wrote the Glyphic Letter?",a="The letter was written and sealed by Khelden Bremen, the resident mage trainer stationed inside the upper chambers of Northshire Abbey.",al={"author of glyphic letter","who sent glyphic letter"}},{q="Where do I find Khelden Bremen?",a="Enter Northshire Abbey behind Marshal McBride, take the left hallway, head up the stairs, and look toward the rear chambers to find Khelden waiting to teach.",al={"khelden bremen location","where is khelden"}},{q="Why is the mage trainer located in an abbey?",a="While Northshire Abbey is fundamentally a holy sanctuary, Stormwind utilizes the valley as an initial training depot for defenders of all disciplines, stationing arcane tutors alongside clerics and marshals.",al={"why are mages in northshire abbey","mage trainer in holy abbey"}},{q="What happens after turning in the letter?",a="Khelden Bremen accepts you as his student, welcomes your resolve to wield the arcane despite its dangers, and offers direct access to basic spell training.",al={"what comes after glyphic letter","next quest after glyphic letter"}},{q="Why does Khelden warn that mages will be feared?",a="Arcane magic is a volatile, reality-bending force. Khelden reminds apprentices that pursuing supreme knowledge means crossing boundaries that regular folk find deeply unsettling.",al={"why are mages feared","khelden bremen dialogue"}}},ang={["class:Mage"]="This quest marks your official transition from a raw, untrained talent into a recognized apprentice of Stormwind's arcane arts under Khelden Bremen.",["race:Human"]="Northshire's human mages inherit a legacy stretching back to the original human arcanists of Dalaran and the Kirin Tor, carrying arcane might into the Kingdom of Stormwind."},kw={"arcane","elwynn forest","glyphic letter","khelden bremen","mage","marshal mcbride","northshire abbey"},rel={"npc:khelden-bremen","npc:marshal-mcbride","subzone:northshire-abbey","zone:elwynn","topic:kobold"},m={start="Marshal McBride",["end"]="Khelden Bremen",level="3",faction="Alliance",id=3104},src={"Glyphic Letter (quest)"}}
E["quest:33"] = {t="quest",n="Wolves Across the Border",z="elwynn",s="Wolves Across the Border is an early task given by Eagan Peltskinner just outside Northshire Abbey. He enlists new adventurers to hunt down prowling wolves in the valley and collect their meat for his personal cooking.",h="Wolves Across the Border is an early task given by Eagan Peltskinner just outside Northshire Abbey.",sec={{t="A Pragmatic Request",b="While Marshal McBride and the Stormwind guards focus their limited manpower on defending Northshire Abbey from Defias bandits and Blackrock orcs, ordinary tradesfolk still have daily needs. Eagan Peltskinner stands by the abbey walls harboring a deep grudge against the local timber wolves. Rather than merely complain about the beasts prowling the border woods, he recruits passing recruits to cull their numbers and retrieve tough wolf meat for his skillet.",sp=0},{t="Wilds of Northshire",b="Northshire Valley was once a peaceful sanctuary, sheltered by rolling hills and dense woods. With the Kingdom of Stormwind strained by missing leadership and troop shortages, wild predators like young wolves and timber wolves have grown bolder, roaming closer to the abbey's pathways and orchards. Clearing them out not only fills Eagan's pantry but also keeps the immediate trails safer for novitiates, laborers, and newly arrived defenders.",sp=0}},faq={{q="Who is Eagan Peltskinner?",a="Eagan Peltskinner is a local hunter and tradesman situated near the entrance of Northshire Abbey. He has a distaste for the region's wild timber wolves, but he is more than happy to cook and eat their meat.",al={"who is eagan","peltskinner","eagan peltskinner"}},{q="Why does Eagan want wolf meat?",a="Eagan genuinely enjoys eating wolf steaks. He trades useful starter gear and coin to recruits willing to go out and harvest fresh meat for him.",al={"why wolf meat","eagan hungry","what does eagan do with meat"}},{q="Where are the wolves located?",a="Timber wolves and young wolves roam the fields, hills, and riverbanks throughout the Northshire Valley, particularly to the south and east of the abbey.",al={"where are the wolves","wolf locations","find wolves"}},{q="Why are wolves a problem in Northshire?",a="Due to reduced patrols and threats like Defias bandits and Blackrock orcs pressing on the valley, wildlife has encroached on the roads and farms, making unescorted travel dangerous for clergy and workers.",al={"why wolves attacking","northshire wolf problem"}},{q="Do I need to talk to anyone before taking this quest?",a="No. While Deputy Willem may direct newcomers to Eagan Peltskinner via an introductory errand, Eagan will offer this hunting task directly to anyone who approaches him outside the abbey.",al={"quest prereqs","prerequisites","who gives this quest"}},{q="Is tough wolf meat used for cooking recipes?",a="Eagan intends to cook the meat himself, but novitiate cooks often learn that wolf meat gathered in Elwynn Forest serves as a basic staple in outdoor cooking.",al={"tough wolf meat cooking","can players cook wolf meat"}}},ang={["profession:Cooking"]="Eagan's craving for wolf steak introduces new adventurers to the frontier reality of Azeroth: whatever you hunt can often be cooked and eaten.",["race:Human"]="Human recruits starting their journey in Northshire find this to be one of their first practical tasks in securing the immediate borders of Stormwind."},kw={"abbey","eagan","elwynn","meat","northshire","peltskinner","timber wolf","wolves"},rel={"quest:5261","subzone:northshire-abbey","zone:elwynn"},m={start="Eagan Peltskinner",level="2",faction="Alliance",id=33},src={"Wolves Across the Border"}}
E["quest:330"] = {t="quest",n="Princess Must Die!",z="elwynn",s="Princess Must Die! is a local bounty offered by Ma Stonefield at the Stonefield Farm in southern Elwynn Forest. She seeks an end to Princess, an enormous prize-winning sow from the nearby Brackwell Pumpkin Patch that continually raids her prized vegetable patches. Putting down the rampaging pig ensures the Stonefields can harvest their crops in peace.",h="Princess Must Die!",sec={{t="A Menace to the Harvest",b="The Stonefield Farm relies heavily on its crops, but a voracious threat has jeopardized their harvest. Princess, a celebrated prize-winning sow belonging to the Brackwells, has grown to monstrous proportions by trespassing onto the Stonefield plots and devouring their vegetables. Ma Stonefield has had enough of the brazen pig feasting on her hard work and wants the beast put down before she ruins the entire season's yield.",sp=0},{t="The Porcine Entourage",b="Princess rarely roams without company. Over at the Brackwell Pumpkin Patch, situated to the east beyond the Maclure homestead, she stays surrounded by her loyal entourage of protective boars. Slaying this massive sow requires cutting through her guards and stripping the distinctive brass collar from her neck to prove the gluttonous beast will trouble the Stonefield fields no more.",sp=0}},faq={{q="Who is Princess?",a="Princess is a massive, prize-winning sow belonging to the Brackwell family. She has grown to an enormous size primarily by sneaking over to the Stonefield Farm to gorge herself on Ma Stonefield's prized vegetable crops.",al={"what is princess","princess elwynn","who is the pig princess"}},{q="Why does Ma Stonefield want Princess killed?",a="Ma Stonefield is fed up with Princess wandering into her fields and devouring her vegetables. Fearing the enormous sow will consume the family's entire harvest before it can be collected, she hires travelers to slay the beast and retrieve her brass collar as proof.",al={"why kill princess","ma stonefield pig quest","why does princess must die"}},{q="Where can Princess be found?",a="Princess resides in the Brackwell Pumpkin Patch, located in southeastern Elwynn Forest east past the Maclure Vineyards. She roams among the ruined pumpkins guarded by a retinue of boars.",al={"princess location","where is princess","princess spawn"}},{q="Who owns the Brackwell Pumpkin Patch?",a="The patch belongs to the Brackwell family, local farmers whose lands have fallen on hard times amidst bandit activity and wild beast incursions in southern Elwynn Forest. Despite their neglect of the patch, Princess remained behind to gorge on what was left.",al={"who are the brackwells","brackwell farm lore","brackwell owners"}},{q="How do you prove Princess is dead?",a="You must take the Brass Collar from around the sow's neck after defeating her and bring it back to Ma Stonefield at the Stonefield Farm.",al={"princess proof","what item for princess","brass collar"}},{q="Does Princess fight alone?",a="No, Princess is accompanied by a Porcine Entourage made up of defensive boars that will attack anyone attempting to slay the prize sow.",al={"princess adds","princess entourage","princess guards"}}},ang={["profession:Cooking"]="Dealing with the massive sow Princess is a legendary tale among local cooks, as Elwynn's oversized boars yield plenty of hearty meat for roasting over an open fire.",["faction:Alliance"]="Helping local farmers like Ma Stonefield manage rogue beasts keeps the southern breadbasket of Stormwind functioning despite the absence of the kingdom's formal army."},kw={"boar","brackwell pumpkin patch","brass collar","elwynn","ma stonefield","princess","sow","stonefield farm"},rel={"npc:ma-stonefield","subzone:stonefield-farm","subzone:brackwell-pumpkin-patch","zone:elwynn"},m={start="Ma Stonefield",level="9",faction="Alliance",id=330},src={"Princess Must Die! (Classic)"}}
E["quest:35"] = {t="quest",n="Further Concerns",z="elwynn",s="Further Concerns is an Alliance courier quest dispatched by Marshal Dughan in Goldshire to investigate rumors of an amphibious threat. The marshal sends you eastward across Elwynn Forest to consult Guard Thomas at the river crossing. It shifts your attention from central garrison duties to the worsening security crisis along the eastern frontier.",h="Further Concerns is an Alliance courier quest dispatched by Marshal Dughan in Goldshire to investigate rumors...",sec={{t="Eyes on the Eastern Crossing",b="While central Elwynn Forest struggles under the weight of banditry and vermin, alarming rumors have begun circulating about aquatic creatures creeping along the riverbanks. Marshal Dughan, commanding the garrison at Goldshire, refuses to dismiss the panic outright. Rather than pulling guards away from town, he sends travelers eastward aboard a fresh mount to consult Guard Thomas, the sentry posted at the bridge spanning the eastern river toward Redridge.",sp=0},{t="A Frontier Stretched Thin",b="Guard Thomas has held the bridge outpost for over a week, witnessing firsthand what Goldshire's leadership could only suspect. Semi-intelligent, hostile murlocs have established camps all along the waterways of eastern Elwynn. With Stormwind's army absent and local garrisons pinned down protecting town walls and supply lines, rural bridgeheads like Thomas's post are left critically isolated against this encroaching peril.",sp=0}},faq={{q="Why does Marshal Dughan send me to Guard Thomas?",a="Marshal Dughan received reports and rumors of murlocs creeping into the eastern waterways. Because Guard Thomas has been stationed at the eastern Elwynn bridge for a week, Dughan relies on him to confirm whether the threat is genuine.",al={"why guard thomas","dughan purpose","talk to thomas"}},{q="Where is Guard Thomas stationed?",a="Guard Thomas is posted at the wooden bridge spanning the river in far eastern Elwynn Forest, guarding the road that leads toward the Redridge Mountains.",al={"guard thomas location","where is thomas","eastern bridge guard"}},{q="What threat does Guard Thomas confirm?",a="Guard Thomas confirms that hostile, semi-intelligent murlocs have indeed settled along eastern Elwynn's streams and waterways, presenting an immediate danger to travelers and nearby farmsteads.",al={"murloc threat","what did thomas find","eastern river threat"}},{q="How do you reach Guard Thomas?",a="Marshal Dughan offers the use of a Stormwind charger right outside the Goldshire inn, providing a quick ride down the eastern road straight to Guard Thomas at the bridge.",al={"fast travel to thomas","horse ride dughan","charger to bridge"}},{q="Why doesn't Stormwind send an army to help eastern Elwynn?",a="Stormwind's standing military forces are heavily constrained with King Varian Wrynn missing and resources diverted away from the countryside. Outlying sentries like Guard Thomas are largely left to rely on passing adventurers.",al={"where are stormwind guards","why is elwynn undefended","stormwind military help"}},{q="What happens after reporting to Guard Thomas?",a="Once Guard Thomas confirms the murloc presence, he asks you to help investigate the fate of other sentries who were patrolling the riverbank and have failed to return.",al={"next quest after further concerns","thomas follow up","lost guards quest"}}},ang={["faction:Alliance"]="The quest highlights the growing operational cracks in the Kingdom of Stormwind, showing how thin human defenses are stretched even a short walk from the capital.",["race:Human"]="For humans of Elwynn, the spread of aggressive murlocs threatens the breadbasket farms and trade arteries connecting Goldshire to Lakeshire."},kw={"eastern bridge","elwynn forest","further concerns","goldshire","guard thomas","marshal dughan","murloc","stormwind charger"},rel={"npc:marshal-dughan","npc:guard-thomas","quest:40","quest:37","zone:elwynn","topic:stormwind-kingdom","topic:murloc"},m={start="Marshal Dughan",["end"]="Guard Thomas",faction="Alliance",id=35},src={"Further Concerns"}}
E["quest:37"] = {t="quest",n="Find the Lost Guards",z="elwynn",s="Find the Lost Guards is an investigation tasked by Guard Thomas at the eastern bridge in Elwynn Forest. Dispatched to patrol the riverbanks against encroaching murlocs, guards Rolf and Malakai have gone missing, leaving Thomas in desperate need of confirmation on their fates.",h="Find the Lost Guards is an investigation tasked by Guard Thomas at the eastern bridge in Elwynn Forest.",sec={{t="A Patrol Vanished",b="Guard Thomas stands vigil at the eastern crossing of Elwynn Forest, where the King's road approaches Redridge. The local waters have grown increasingly treacherous with murloc incursions. Days prior, Thomas dispatched two Stormwind guards, Rolf and Malakai, northward along the riverbanks to scout the threat and clear out nests. When neither soldier returned, Thomas had to accept that something violent had interrupted their mission.",sp=0},{t="Grim Discovery",b="Following the river north toward the shores of Stone Cairn Lake leads directly into swarming murloc territory. Along the water's edge, adventurers discover a gruesome scene: a half-eaten corpse left in the mud. Discarded beside the mauled remains lies an engraved medallion bearing the name Footman Malakai Stone, confirming the grim fate of one guard and leaving the whereabouts of Rolf still unresolved.",sp=1}},faq={{q="Who gave this quest and where are they located?",a="Guard Thomas assigns this task. He is stationed along the river on the eastern border of Elwynn Forest, guarding the bridge that leads toward Redridge Mountains.",al={"quest giver","where is guard thomas","who starts find the lost guards"}},{q="Who are the missing guards?",a="The missing men are Rolf and Malakai, two Stormwind city footmen sent by Guard Thomas to scout the riverbanks and monitor aggressive murloc activity.",al={"missing guards elwynn","who are rolf and malakai","lost guards names"}},{q="Where are the remains found?",a="The half-eaten remains of Footman Malakai Stone lie on the eastern bank of the river just north of Guard Thomas's post, near the outskirts of a murloc settlement.",al={"where is malakai corpse","half-eaten body location","lost guards location"},sp=1},{q="What killed Malakai?",a="Malakai was overrun and eaten by the local river murlocs that have infested the shores of eastern Elwynn Forest.",al={"how did malakai die","who killed the guards"},sp=1},{q="What happened to Rolf?",a="Malakai's remains are found alone by the river. Rolf's fate remains an open mystery that requires further tracking deeper into the murloc camps.",al={"where is rolf","did rolf survive"},sp=1},{q="Why were the guards sent out alone?",a="With Stormwind's military stretched thin across multiple territories, small garrisons like Guard Thomas's post must rely on minimal two-man patrols to monitor wilderness borders.",al={"why were they sent","stormwind guard shortage"}}},ang={["faction:Alliance"]="The grim loss of footmen so close to Stormwind underscores how vulnerable Elwynn's outer borders have become to beast and murloc attacks.",["class:Paladin"]="Honoring fallen defenders and recovering their personal insignia brings closure and justice to the soldiers guarding the kingdom's frontier."},kw={"elwynn forest","find the lost guards","guard thomas","half-eaten body","malakai","malakai stone","murlocs","rolf"},rel={"npc:guard-thomas","quest:35","quest:45","zone:elwynn"},m={start="Guard Thomas",["end"]="A half-eaten body",faction="Alliance",id=37},src={"Find the Lost Guards"}}
E["quest:39"] = {t="quest",n="Deliver Thomas' Report",z="elwynn",s="Deliver Thomas' Report carries grim intelligence from eastern Elwynn Forest back to Goldshire's garrison command. Guard Thomas charges an adventurer with alerting Marshal Dughan to the deaths of two guards and the uncontrollable expansion of local murloc tribes. The report highlights how precariously thin Stormwind's military presence is across its own heartland.",h="Deliver Thomas' Report carries grim intelligence from eastern Elwynn Forest back to Goldshire's garrison...",sec={{t="Bad Tidings from the East",b="Stationed out along the bridges crossing into the wilderness of eastern Elwynn, Guard Thomas has reached a breaking point. Tasked with monitoring river traffic and frontier unrest, his detachment has suffered critical losses with the deaths of Guards Malakai and Rolf at the hands of aggressive murloc tribes. With his remaining numbers dwindling and unable to contain the aquatic menace, Thomas is forced to send an urgent courier back down the road to Goldshire.",sp=0},{t="A Garrison Stretched to the Brink",b="When Marshal Dughan receives the report at the Lion's Pride Inn, the news validates his worst strategic fears. Goldshire is already struggling to maintain basic patrols while contending with kobold infestations, Defias bandits, and a total lack of reinforcements from Stormwind City. The loss of two experienced guards and the realization that murlocs may soon threaten Goldshire itself illustrates just how close the regional defenses are to collapsing entirely.",sp=0}},faq={{q="Who are Malakai and Rolf?",a="Malakai and Rolf were Stormwind guards stationed in eastern Elwynn Forest under Guard Thomas. While patrolling near the rivers and lakes, both were overwhelmed and slain by aggressive murloc tribes that have infested the waterways.",al={"malakai and rolf","who died","dead guards"}},{q="Why is Guard Thomas asking an adventurer to deliver the report?",a="Guard Thomas simply has no troops left to spare. His outpost is operating under severe manpower shortages, and abandoning his watch or sending away one of his few surviving sentries would leave the eastern bridges completely undefended.",al={"why guard thomas needs help","why courier","cant thomas send a guard"}},{q="What threat do the murlocs pose to Goldshire?",a="As Marshal Dughan notes upon reading the dispatch, the unchecked murloc presence along the eastern rivers is expanding rapidly westward. Without enough guards to hold the perimeter, Dughan fears that fighting will reach the outskirts of Goldshire itself within the week.",al={"murloc threat","will murlocs attack goldshire","how bad are murlocs"}},{q="Why doesn't Stormwind City send reinforcements to Elwynn?",a="Stormwind's military resources are stretched perilously thin across multiple fronts, complicated by political paralysis in the capital following the disappearance of King Varian Wrynn. Outlying settlements and frontier bridges are largely left to fend for themselves using local town watches and hired adventurers.",al={"why no stormwind army","where are the troops","why are defenses thin"}},{q="What happens after Marshal Dughan reads the report?",a="Recognizing that his garrison lacks the manpower to directly stem the tide, Marshal Dughan must look for other ways to outfit and support those willing to hold the line, directing attention toward securing supplies and armor for the regional defense.",al={"next quest","what does dughan do","chain after report"}},{q="Where is Guard Thomas stationed?",a="Guard Thomas is posted on the eastern side of Elwynn Forest, guarding the bridges that cross the rivers separating the heart of the forest from the wilder borders near the Redridge Mountains.",al={"guard thomas location","where is thomas","thomas location"}}},ang={["faction:Alliance"]="Delivering Thomas' report reveals the vulnerability at the core of the Alliance's primary kingdom, showing that even the roads outside the capital are slipping out of garrison control.",["class:Warrior"]="For warriors serving the realm, the loss of Malakai and Rolf underscores the harsh reality of frontier garrison duty against relentless, non-human foes.",["race:Human"]="Human defenders feel the bite of these losses directly, seeing their homeland's security eroded by manpower shortages and rising hostile incursions."},kw={"elwynn forest","goldshire","guard thomas","malakai","marshal dughan","murlocs","report","rolf"},rel={"npc:guard-thomas","npc:marshal-dughan","quest:71","quest:59","subzone:goldshire","topic:murloc","zone:elwynn"},m={start="Guard Thomas",["end"]="Marshal Dughan",level="10",faction="Alliance",id=39},src={"Deliver Thomas' Report"}}
E["quest:3903"] = {t="quest",n="Milly Osworth",z="elwynn",s="Milly Osworth is a short errand entrusted to promising new recruits by Deputy Willem at Northshire Abbey. It directs adventurers across the abbey grounds to assist Milly, a local woman whose wagon and livelihood are in jeopardy. The assignment marks a shift from clearing abbey grounds to aiding the beleaguered civilians of Elwynn Forest.",h="Milly Osworth is a short errand entrusted to promising new recruits by Deputy Willem at Northshire Abbey.",sec={{t="A Dependable Pair of Hands",b="After proving their mettle against the Defias thieves encroaching on Northshire Valley, recruits catch the eye of Deputy Willem. Recognizing capable and willing help, Willem refers adventurers to his friend Milly Osworth. Rather than official garrison business, this task represents a personal favor to assist a civilian trapped by the valley's growing unrest.",sp=0},{t="Trouble by the Stables",b="Milly Osworth waits near her wagon on the other side of Northshire Abbey, close to the stables. While Deputy Willem remains bound to his station defending the abbey, Milly's troubles require direct action out in the valley that the stretched guard garrison simply cannot spare the manpower to resolve.",sp=0}},faq={{q="Who sends you to speak with Milly Osworth?",a="Deputy Willem, stationed just outside the main gates of Northshire Abbey, gives you this quest after you prove your reliability by dealing with the Defias bandits.",al={"who gives milly osworth","quest giver milly osworth","where to get milly osworth quest"}},{q="Where can Milly Osworth be found?",a="Milly Osworth is stationed by her wagon on the other side of Northshire Abbey, near the stables, not far from the vineyards to the southeast.",al={"milly osworth location","where is milly","where is milly osworth"}},{q="Why can't Deputy Willem help Milly himself?",a="Willem's guard duties keep him tied to Northshire Abbey. With the valley pressed by bandits and vermin, the local garrison lacks the spare hands to deal with private civilian troubles.",al={"why doesnt willem help","willem duties","why help milly"}},{q="What prerequisites are needed for this quest?",a="You must complete the quest Brotherhood of Thieves for Deputy Willem before he considers you dependable enough to assist Milly.",al={"milly osworth requirements","brotherhood of thieves follow up","how to unlock milly osworth quest"}},{q="What does Milly need help with?",a="Milly is struggling to manage her crop and wagon amidst the local turmoil, leading directly into the task of securing her harvest from the surrounding valley.",al={"what does milly want","milly problem","milly harvest troubles"}},{q="Who is Milly Osworth to Deputy Willem?",a="Willem refers to Milly simply as a friend in need, someone from the Northshire community he looks out for despite being confined to his post.",al={"willem and milly","is milly related to willem","how does willem know milly"}}},ang={["faction:Alliance"]="This task illustrates the strain on local Alliance forces in Northshire, where guardsmen must rely on passing adventurers to shield local townspeople from emerging threats.",["race:Human"]="For young humans beginning their journey in Northshire, stepping in for Willem demonstrates the community spirit essential to holding Elwynn together."},kw={"deputy willem","elwynn forest","harvest","milly osworth","northshire abbey","stables","wagon"},rel={"npc:willem","quest:18","subzone:northshire-abbey","zone:elwynn"},m={start="Deputy Willem",["end"]="Milly Osworth",level="4",faction="Alliance",id=3903},src={"Milly Osworth (quest)"}}
E["quest:3904"] = {t="quest",n="Milly's Harvest",z="elwynn",s="Milly's Harvest is a simple errand born from Northshire's growing bandit crisis. After Defias thugs force local farmer Milly Osworth to abandon her harvested grapes in the vineyards, an adventurer must brave the occupied fields to recover her livelihood before it is stolen or trampled.",h="Milly's Harvest is a simple errand born from Northshire's growing bandit crisis.",sec={{t="A Crop Left Behind",b="While collecting grapes in the southeastern fields of Northshire Valley, Milly Osworth was forced to flee for her life as Defias brigands swarmed the vines. In her panic, she abandoned her gathered harvest packed in buckets and crates throughout the occupied rows. With the local garrison stretched thin, she fears that even if the guards eventually drive off the intruders, heavy boots and chaotic fighting will smash whatever fruit the bandits haven't already hauled away.",sp=0},{t="Northshire Under Pressure",b="The presence of bandits brazenly occupying working vineyards highlights just how brittle the safety of Northshire has become. While Stormwind's attention is focused elsewhere and the valley lacks adequate numbers of guards, ordinary citizens like Milly are left relying on visiting recruits and wanderers to defend their property and secure the food and wine that supply the abbey.",sp=0}},faq={{q="Who is Milly Osworth?",a="Milly Osworth is a local farmer working the Northshire Vineyards. She tends and harvests the valley's grapes, which are vital for Northshire's winemaking, but she was driven from her fields by the arriving Defias Brotherhood.",al={"milly osworth","who is milly","grape lady"}},{q="Why can't the Northshire guards retrieve the harvest?",a="The guards in Northshire Valley are understaffed and occupied containing the widespread bandit threat and kobold infestations. Milly also worries that a clumsy military sweep would simply trample her delicate grapes into the mud.",al={"why don't guards help","northshire guards","lazy guards"}},{q="What are the Defias doing in the vineyards?",a="The Defias Brotherhood has crept into Northshire Valley to disrupt regional production, harass the local population, and seize resources right under the nose of Stormwind's guards.",al={"why defias in vineyards","defias grapes","defias northshire"}},{q="Where are the crates located?",a="The harvest buckets and crates are scattered across the ground in the Northshire Vineyards, located just southeast of Northshire Abbey, amid the hostile Defias brigands patrolling the rows.",al={"crate locations","where to find grapes","where is harvest"}},{q="What happens after Milly gets her grapes back?",a="Once the harvest is safe, Milly tasks adventurers with bringing her Grape Manifest to Brother Neals inside Northshire Abbey so the yield can be properly accounted for and processed into wine.",al={"next quest","after milly's harvest","what next"},sp=1},{q="Why are grapes important to Northshire Abbey?",a="Northshire Valley produces famous wine and supplies the clerical community at the abbey. Milly's crop sustains both local trade and the cellars maintained by the Brotherhood of Northshire.",al={"northshire wine","why grapes matter"}}},ang={["faction:Alliance"]="Recovering Milly's crop offers young Alliance recruits a stark first look at the Defias problem festering just miles from Stormwind City.",["race:Human"]="For humans beginning their journey in Northshire, protecting smallholder farmers like Milly represents the core duty of defending Elwynn's working folk."},kw={"crates","defias","elwynn forest","grapes","milly osworth","milly's harvest","northshire abbey","northshire vineyards"},rel={"quest:3903","subzone:northshire-vineyards","subzone:northshire-abbey","zone:elwynn"},m={start="Milly Osworth",level="4",faction="Alliance",id=3904},src={"Milly's Harvest (quest)"}}
E["quest:3905"] = {t="quest",n="Grape Manifest",z="elwynn",s="With Milly Osworth's harvest rescued from the Defias thieves, she writes up a manifest documenting the recovered grape yield. Delivering this ledger to Brother Neals in Northshire Abbey ensures the brotherhood can replenish its celebrated stores of wine. It marks a small but sweet victory for the besieged valley's livelihood.",h="With Milly Osworth's harvest rescued from the Defias thieves, she writes up a manifest documenting the...",sec={{t="The Valley's Vintage",b="Northshire Valley is renowned across Elwynn for its fertile soil and quiet orchards, with vineyards tending crops essential both for local sustenance and sacramental trade. When thieves and bandits seized the eastern fields, they jeopardized more than simple fruit: they cut off the abbey's supply chain for wine and food. With the harvest dragged back from the occupied paddocks, the grape manifest formally accounts for every bushel reclaimed.",sp=0},{t="A Tipple in the Belfry",b="Brother Neals serves as Northshire Abbey's steward of food and drink, though he is best known for his fondness for sampling Northshire's vintages high up in the quiet of the bell tower. While the threat of brigands looms right outside the gates, the receipt of fresh grapes gives the brotherhood a reason to toast the Light and breathe a momentary sigh of relief.",sp=0}},faq={{q="What is the Grape Manifest?",a="The Grape Manifest is an inventory ledger written by farmer Milly Osworth after her grape harvest is recovered from Defias thieves. It records the salvaged yield so the abbey's quartermaster can officially restock their cellars.",al={"grape manifest item","what is manifest","millys manifest"}},{q="Who is Brother Neals?",a="Brother Neals is a monk residing in Northshire Abbey responsible for overseeing food and beverage provisions. He spends much of his time testing vintages up in the abbey's bell tower.",al={"brother neals","who is neals","monk in bell tower"}},{q="Where do I find Brother Neals?",a="Brother Neals is located inside Northshire Abbey, resting up in the bell tower overlooking the grounds.",al={"neals location","where is brother neals","find brother neals"}},{q="Why is Northshire's grape crop so important?",a="Northshire produces celebrated wine and fresh provisions that sustain the local Clerical and military presence. An interruption in the harvest threatens both daily stores and liturgical supplies across Elwynn.",al={"why grapes matter","northshire wine lore","milly harvest significance"}},{q="Who was threatening Milly's harvest?",a="Defias brigands occupied the eastern fields of Northshire Valley, driving out Milly Osworth and caching her boxed harvest throughout the vineyards until adventurers drove them back.",al={"who stole the grapes","grape thieves","bandits in vineyards"}},{q="What happens after giving Brother Neals the manifest?",a="Neals offers his blessings in the name of the Light, overjoyed that the abbey's cellars will remain stocked with fresh wine despite the bandit troubles across the valley.",al={"quest aftermath","does neals make wine","what follows grape manifest"}}},ang={["faction:Alliance"]="Securing local food stores in Northshire helps maintain self-sufficiency for Stormwind's primary recruitment and recovery sanctuary.",["race:Human"]="For young humans beginning their journey, helping Milly and Brother Neals protects one of the kingdom's cherished pastoral traditions.",["class:Priest"]="Wine holds both hospitality and sacramental value in Northshire Abbey, linking practical agriculture to the brotherhood's rites."},kw={"brother neals","defias","elwynn","grape manifest","harvest","milly osworth","northshire abbey","vineyard","wine"},rel={"npc:brother-neals","quest:3903","subzone:northshire-abbey","zone:elwynn","topic:light"},m={start="Milly Osworth",["end"]="Brother Neals",level="4",faction="Alliance",id=3905},src={"Grape Manifest (quest)"}}
E["quest:40"] = {t="quest",n="A Fishy Peril",z="elwynn",s="A Fishy Peril is a short dispatch quest tasked by Remy \"Two Times\" in eastern Elwynn Forest. Disturbed by reports of amphibious predators encroaching on the waterways, Remy sends travelers to alert Marshal Dughan in Goldshire. The errand highlights the strained resources of Stormwind's local garrison in responding to emerging wilderness threats.",h="A Fishy Peril is a short dispatch quest tasked by Remy \"Two Times\" in eastern Elwynn Forest.",sec={{t="A Plea from the East",b="While conducting trade along the eastern roads of Elwynn Forest, Remy \"Two Times\" finds himself unnerved by a strange new menace. Murlocs have begun creeping up the streams and inland shallows, disrupting fishing and menacing innocent travelers. Convinced that the local guard is overlooking a brewing catastrophe, Remy pleads with passersby to take word back to the heart of the township.",sp=0},{t="A Strained Garrison",b="Upon receiving the report in Goldshire, Marshal Dughan remains skeptical. Tasked with protecting the realm while royal forces are stretched thin elsewhere, Dughan is already consumed by the violent resurgence of Riverpaw gnolls and Defias highwaymen. Without confirmed military intelligence, the marshal refuses to divert his scarce men to chase rumors of fish-men in the eastern streams.",sp=0}},faq={{q="Who gives the quest A Fishy Peril?",a="The quest is offered by Remy \"Two Times\", a nervous merchant found traveling along the roads of eastern Elwynn Forest.",al={"quest giver a fishy peril","who starts a fishy peril","remy quest"}},{q="Why is Remy \"Two Times\" worried about murlocs?",a="Remy has observed murlocs swimming up the rivers of eastern Elwynn, driving away the local fish and attacking travelers along the waterways.",al={"why remy scared","murloc problem elwynn","fishy peril lore"}},{q="Why won't Marshal Dughan send troops immediately?",a="Marshal Dughan considers the civilian rumors unverified. With Goldshire's garrison heavily preoccupied by gnoll attacks and organized banditry, he cannot commit soldiers without formal military scout reports.",al={"why dughan ignores murlocs","marshal dughan response","why no troops east"}},{q="Where does this quest lead next?",a="Marshal Dughan follows up this conversation with Further Concerns, requiring reliable confirmation from scouts before committing royal resources to the east.",al={"what comes after a fishy peril","next quest after fishy peril","further concerns quest"}},{q="Where does the player turn in A Fishy Peril?",a="The quest is delivered to Marshal Dughan inside or just outside the Lion's Pride Inn in Goldshire.",al={"where turn in fishy peril","fishy peril turn in","dughan location"}},{q="What larger threat are the murlocs part of in Elwynn?",a="While murlocs appear primitive and erratic, their aggressive colonization of inland lakes such as Stonecairn Lake and Crystal Lake threatens rural trade and agriculture alongside gnoll and bandit attacks.",al={"murlocs in elwynn","are murlocs dangerous elwynn"}}},ang={["faction:Alliance"]="This dispatch showcases the bureaucratic and logistical strain on Stormwind's home guard, forcing the township to rely on independent adventurers to investigate rumors.",["race:Human"]="For humans defending their homeland, the invasion of eastern waterways strikes close to home as familiar streams turn into dangerous hunting grounds for aquatic beasts."},kw={"a fishy peril","elwynn forest","further concerns","goldshire","marshal dughan","murloc","remy two times"},rel={"npc:remy-two-times","npc:marshal-dughan","quest:35","topic:murloc","subzone:goldshire","zone:elwynn","topic:gnoll"},m={start="Remy \"Two Times\"",["end"]="Marshal Dughan",faction="Alliance",id=40},src={"A Fishy Peril"}}
E["quest:45"] = {t="quest",n="Discover Rolf's Fate",z="elwynn",s="Discover Rolf's Fate is an Alliance quest in Elwynn Forest following the trail of two missing Stormwind guards. After finding the mangled remains of Guard Malakai along the shore of Stone Cairn Lake, the trail of webbed prints leads east into a hostile murloc village to uncover what became of his companion, Rolf.",h="Discover Rolf's Fate is an Alliance quest in Elwynn Forest following the trail of two missing Stormwind...",sec={{t="A Trail of Webbed Tracks",b="Guard Thomas dispatched patrols around eastern Elwynn Forest to counter rising threats, but two guards—Malakai and Rolf—vanished near the shores of Stone Cairn Lake. Investigating Malakai's half-eaten remains reveals webbed footprints pressed into the mud, leading eastward along the water's edge straight toward a ramshackle murloc encampment.",sp=0},{t="The End of Patrol",b="Following the tracks brings you into the heart of the coastal murloc settlement. There lies another corpse stripped by the creatures. Around the neck of the fallen soldier hangs an inscribed medallion confirming his identity as Footman Rolf Hartford, proving that neither guard survived the ambush.",sp=1}},faq={{q="Who was Rolf?",a="Rolf Hartford was a Stormwind footman assigned to patrol eastern Elwynn Forest alongside Guard Malakai under Guard Thomas's command. Both guards were overwhelmed and killed by murlocs near Stone Cairn Lake.",al={"who is rolf","footman rolf","rolf hartford"},sp=1},{q="Where is Rolf's body located?",a="Rolf's corpse lies further east along the southern shore of Stone Cairn Lake, tucked inside a murloc village near the border of the lake.",al={"rolf location","where is rolf","find rolf"},sp=1},{q="Why were the guards out near Stone Cairn Lake?",a="Guard Thomas stationed guards along the rivers and lakes of eastern Elwynn to monitor incursions from murlocs and gnolls, but the understaffed patrols proved vulnerable to sudden coordinated attacks.",al={"why were guards lost","what were guards doing","guard patrol elwynn"}},{q="How do you confirm the corpse belongs to Rolf?",a="Around the neck of the torn corpse hangs a metal medallion clearly inscribed with the name 'Footman Rolf Hartford'.",al={"rolf medallion","identifying rolf"},sp=1},{q="What happens after finding Rolf?",a="With the tragic fate of both Malakai and Rolf confirmed, you are tasked with returning west to the Eastvale Logging Camp bridge to report the grim news to Guard Thomas.",al={"next quest after rolf","what to do after rolf"},sp=1},{q="Are the murlocs in Stone Cairn Lake an unusual threat?",a="Murloc activity in Elwynn has become unusually aggressive and coordinated, pushing inland into Stone Cairn Lake and the rivers, threatening local trade and lone patrols alike.",al={"murloc threat elwynn","why murlocs attacking"}}},ang={["faction:Alliance"]="Finding Rolf confirms the vulnerability of Stormwind's rural borders, where garrison shortages leave basic patrols exposed to deadly wild attacks.",["class:Warrior"]="Standing over Rolf Hartford's body serves as a stark reminder of the bloody reality faced by front-line footmen serving the realm."},kw={"elwynn forest","guard thomas","malakai","murlocs","rolf","rolf hartford","stone cairn lake"},rel={"quest:37","quest:71","subzone:stone-cairn-lake","topic:murloc","zone:elwynn"},m={start="A half-eaten body",["end"]="Rolf's corpse",faction="Alliance",id=45},src={"Discover Rolf's Fate"}}
E["quest:46"] = {t="quest",n="Bounty on Murlocs",z="elwynn",s="The Stormwind Army has issued a public bounty on the murloc tribes spreading through eastern Elwynn Forest. With the garrison stretched thin, Guard Thomas relies on traveling adventurers to cull the shoreline encampments around Stone Cairn Lake and the southern waterways before they overrun the region's farms and roads.",h="The Stormwind Army has issued a public bounty on the murloc tribes spreading through eastern Elwynn Forest.",sec={{t="A Threat on the Waterways",b="While Elwynn Forest's western roads are comparatively secure, the waters of the east harbor an escalating amphibious infestation. Murloc lurkers and foragers have established aggressive shoreline settlements around Stone Cairn Lake and along the fork of the southern streams. What initially seemed like a minor nuisance has rapidly turned into a territorial expansion, with armed murlocs attacking travelers and encroaching upon human settlements.",sp=0},{t="Stretched Defenses",b="Stationed at the eastern bridge bordering the Redridge Mountains, Guard Thomas finds himself caught between external perils and local disorder. With King Varian Wrynn missing and Stormwind's military command bogged down in bureaucratic paralysis, town garrisons rarely receive the reinforcements they request. Marshal Dughan and local officers have turned to official bounties, trading coin for severed fins to stem the aquatic tide.",sp=0}},faq={{q="Why is there a bounty on murlocs in Elwynn?",a="The murlocs have established growing encampments at Stone Cairn Lake and the southern streams of eastern Elwynn. Their foraging parties threaten nearby farms, roads, and travelers, compelling the Stormwind Army to pay adventurers to cull their numbers.",al={"why kill murlocs","murloc bounty reason","why bounty on murlocs"}},{q="Who is paying for the bounty?",a="The bounty is financed by the Stormwind Army through Goldshire's command under Marshal Dughan, with Guard Thomas serving as the field contact paying out travelers stationed at the eastern river crossing.",al={"who rewards this quest","who pays the bounty","stormwind army bounty"}},{q="Where are the murloc settlements located?",a="The main colonies reside along the shores and islands of Stone Cairn Lake to the north, as well as along the riverbanks to the south where the eastern stream forks.",al={"murloc locations elwynn","where are elwynn murlocs","stone cairn lake murlocs"}},{q="Why can't the Stormwind guards handle this themselves?",a="Stormwind's military is severely overstretched across the kingdom due to political strife, missing leadership, and banditry. Outposts like Guard Thomas's bridge have only a handful of men, leaving them unable to mount sustained offensive assaults on shoreline tribes.",al={"why guard thomas needs help","why aren't guards fighting murlocs","guard shortage elwynn"}},{q="What proof of the cull does Guard Thomas require?",a="Guard Thomas asks for torn murloc fins harvested directly from the lurkers and foragers inhabiting Elwynn's eastern waterways.",al={"what drops torn murloc fins","quest proof","murloc fins"}},{q="Does Marshal Dughan know about the severity of the murloc problem?",a="Yes. Guard Thomas notes that Marshal Dughan is quite anxious about the murloc situation across eastern Elwynn, making positive reports on culled settlements vital for local morale.",al={"marshal dughan murlocs","is goldshire aware","dughan reaction"}}},ang={["faction:Alliance"]="Clearing the waterways keeps vital supply lines and rural homesteads safe between Goldshire and the border to Redridge.",["race:Human"]="For citizens of Stormwind, this contract is a stark reminder of how thin their kingdom's protection has worn right outside the capital's heartland.",["class:Hunter"]="The marshy shores and reed-filled banks around Stone Cairn Lake offer ideal proving grounds for stalking nimble, swarm-minded aquatic predators."},kw={"bounty","elwynn","fins","foragers","guard thomas","lurkers","marshal dughan","murlocs","stone cairn lake"},rel={"npc:guard-thomas","npc:marshal-dughan","subzone:stone-cairn-lake","zone:elwynn","topic:stormwind-army","topic:murloc","topic:stormwind-kingdom"},m={start="Bounty Board",["end"]="Guard Thomas",faction="Alliance",id=46},src={"Bounty on Murlocs"}}
E["quest:47"] = {t="quest",n="Gold Dust Exchange",z="elwynn",s="Gold Dust Exchange is an early bounty offered by Remy \"Two Times\" out of Goldshire. The nervous broker pays adventurers to pry raw gold dust away from the kobolds infesting the mines across Elwynn Forest. While it provides honest work for fledgling travelers, Remy's curious connections hint that there is more to his hustle than simple metalworking.",h="Gold Dust Exchange is an early bounty offered by Remy \"Two Times\" out of Goldshire.",sec={{t="A Town of Pockets and Picks",b="Goldshire sits at the crossroads of Elwynn Forest, where merchants, town guards, and weary travelers mingle. Among them is Remy \"Two Times,\" a shady fellow whose persistent habit of repeating his words masks a shrewd eye for profit. Rather than hiring costly mining teams to extract raw minerals, Remy capitalizes on the wandering adventurers filtering through the Lion's Pride Inn. His proposal is simple: recover the gold dust hoarded by the region's vermin and trade it directly for coin.",sp=0},{t="The Kobold Plunder",b="Kobolds have thoroughly overrun Elwynn's most valuable subterranean excavations, namely Fargodeep Mine to the south and Jasperlode Mine to the northeast. While chipping through the dark for their beloved candles and shiny baubles, these rat-like tunnelers accumulate residue and flecks of unrefined ore in their pouches. Driving them back serves the kingdom's interest, but collecting their dust turns pest extermination into a lucrative trade.",sp=0},{t="Shadows Behind the Counter",b="While Remy claims to pay top coin for pure mercantile reasons, his rewards carry subtle warnings. Upon receiving his dust, he slips his helpers a small token representing his \"associates.\" In an Elwynn increasingly strangled by organized bandits, unpaid stonemasons, and clandestine networks operating in the shadows of Stormwind, Remy's quiet brokers may have plans for that gold that extend far beyond ordinary village commerce.",sp=1}},faq={{q="Who is Remy \"Two Times\"?",a="Remy \"Two Times\" is an eccentric local broker stationed outside the Lion's Pride Inn in Goldshire. Known for repeating the ends of his sentences, he buys up precious materials from wandering adventurers and maintains ties with shadowy associates.",al={"remy two times","who gives gold dust exchange","remy in goldshire"}},{q="Where do kobolds get gold dust?",a="Kobolds spend their lives tunneling through Elwynn's mineral veins, such as those inside Fargodeep and Jasperlode. As they scratch and dig through rock in search of treasure and candle wax, raw gold flakes and dust accumulate in their pockets and pouches.",al={"why do kobolds have gold dust","where does gold dust come from"}},{q="Where can I find the mines mentioned by Remy?",a="Kobolds carrying gold dust can be found primarily within and around the Fargodeep Mine, located south of Goldshire, and the Jasperlode Mine, situated to the northeast near the border toward the Eastvale Logging Camp.",al={"where are the mines","where to find kobolds elwynn"}},{q="Why does Stormwind allow kobolds to control their mines?",a="With King Varian Wrynn missing and the House of Nobles refusing to spare troops for the outskirts, the Stormwind City Guard is stretched terribly thin. Local garrisons cannot clear the mines, leaving them infested by kobolds while independent travelers do the fighting.",al={"why aren't the mines guarded","why did stormwind lose the mines"}},{q="Is gold dust used for blacksmithing or trade?",a="In its raw form carried by kobolds, gold dust is too fine and impure for ordinary forge work. Instead, it is traded as a raw commodity to brokers like Remy, who consolidate and refine it through their own private channels.",al={"what is gold dust used for","can you smelt gold dust"}}},ang={["profession:Mining"]="Miners scouring Fargodeep and Jasperlode will find kobolds clinging directly to the richest copper veins, making clearing them out a necessity for harvesting ore.",["class:Rogue"]="Remy's hushed demeanor and token from unnamed 'associates' carries the unmistakable scent of underground syndicates operating beneath Goldshire's placid surface.",["faction:Alliance"]="The fact that Elwynn's vital gold and mineral deposits are held by feral kobolds rather than royal excavators illustrates how depleted the kingdom's military forces truly are."},kw={"elwynn forest","fargodeep mine","gold dust","goldshire","jasperlode mine","kobold","remy two times"},rel={"npc:remy-two-times","topic:kobold","subzone:fargodeep-mine","subzone:jasperlode-mine","subzone:goldshire","quest:62","quest:76","zone:elwynn"},m={start="Remy \"Two Times\"",faction="Alliance",id=47},src={"Gold Dust Exchange"}}
E["quest:52"] = {t="quest",n="Protect the Frontier",z="elwynn",s="Protect the Frontier is an Alliance assignment handed out by Guard Thomas at the eastern bridge crossing in Elwynn Forest. As Stormwind's military presence thins toward the border, wild predators have grown increasingly bold, harassing travelers and workers at the Eastvale Logging Camp. Guard Thomas seeks capable adventurers to cull the wolves and bears threatening the eastern frontier.",h="Protect the Frontier is an Alliance assignment handed out by Guard Thomas at the eastern bridge crossing in...",sec={{t="A Thinning Defense",b="While Goldshire and the Northshire Valley maintain a visible Stormwind garrison, the far eastern edge of Elwynn Forest receives far less protection. Guard Thomas stands watch at the bridge crossing over the river, serving as one of the few sentries between civilized heartlands and the dangerous wilderness. With resources stretched thin across the realm, solitary guardsmen rely on passing volunteers to keep vital supply lanes open.",sp=0},{t="The Predatory Threat",b="The Eastvale Logging Camp is crucial for supplying timber to Stormwind City, but felling trees along the tree line brings woodsmen into direct conflict with local wildlife. Prowlers, gray forest wolves, and young forest bears have turned increasingly aggressive, wandering near the roads and lumber yards. Thinning their numbers temporarily relieves the pressure on local laborers, though Guard Thomas suspects an unseen disturbance deeper in the woods may be driving the beasts toward settlements.",sp=0}},faq={{q="Who gives the quest Protect the Frontier?",a="Guard Thomas assigns the task. He is stationed at the eastern bridge along the main road through Elwynn Forest, guarding the boundary between the forest interior and the Eastvale region.",al={"quest giver protect the frontier","who starts protect the frontier","guard thomas quest"}},{q="Why are wolves and bears attacking the frontier?",a="The aggressive predators frequently encroach on roads and work sites near the Eastvale Logging Camp. While wolves and bears are naturally territorial, Guard Thomas notes that something deeper in the surrounding wilderness appears to be agitating them and driving them toward civilization.",al={"why are bears aggressive","why are wolves attacking eastvale","animal attacks elwynn"}},{q="Where is the Eastvale Logging Camp?",a="The Eastvale Logging Camp lies in eastern Elwynn Forest, situated south of the main road past Guard Thomas's bridge. It provides vital lumber for Stormwind and border settlements.",al={"eastvale location","where is logging camp elwynn","eastvale camp"}},{q="Why is Guard Thomas watching the bridge alone?",a="Stormwind's standing army and city guard are stretched extremely thin across the kingdom. Sentry outposts along rivers and outer crossroads often have only one or two guards stationed to watch the highways, leaving them dependent on traveling adventurers to handle large-scale wildlife threats.",al={"why is guard thomas alone","guard thomas post","stormwind guards eastvale"}},{q="What animals need to be culled for this task?",a="You are tasked with slaying eight wolves (either prowlers or gray forest wolves) and five young forest bears roaming the woods of eastern Elwynn Forest.",al={"protect the frontier targets","wolves and bears to kill","what mobs for protect the frontier"}},{q="What happens once the wildlife is culled?",a="Reporting back to Guard Thomas secures his gratitude and ensures safer passage for logging caravans. However, he remains wary that whatever dark influence stirred up the beasts might cause further trouble in the forest.",al={"protect the frontier follow up","turn in protect the frontier"}}},ang={["faction:Alliance"]="Keeping the eastern roads secure helps maintain lumber shipments from Eastvale, supporting reconstruction and defensive efforts across Alliance lands.",["class:Hunter"]="The wolves and bears stalking eastern Elwynn Forest provide an early test of tracking and marksmanship against ferocious local game."},kw={"eastvale logging camp","elwynn forest","gray forest wolf","guard thomas","protect the frontier","prowler","young forest bear"},rel={"npc:guard-thomas","subzone:eastvale-logging-camp","zone:elwynn","subzone:goldshire"},m={start="Guard Thomas",faction="Alliance",id=52},src={"Protect the Frontier"}}
E["quest:5261"] = {t="quest",n="Eagan Peltskinner",z="elwynn",s="This brief introductory task directs newly arrived recruits in Northshire Valley to speak with Eagan Peltskinner, a local furrier stationed outside Northshire Abbey. With predator numbers swelling along the valley's fringes, Eagan requires capable adventurers to hunt timber wolves and gather pelts.",h="This brief introductory task directs newly arrived recruits in Northshire Valley to speak with Eagan...",sec={{t="A Word with the Furrier",b="Northshire Valley may appear pastoral, but its quiet orchards and fields are bordered by wild woods crawling with timber wolves. Deputy Willem often directs recruits outside the abbey's walls to Eagan Peltskinner, who works nearby on the abbey grounds. Eagan is eager to put newcomers to work thinning the aggressive packs while securing valuable pelts for his craft.",sp=0},{t="Trouble on the Perimeter",b="The rising wolf population around Northshire is more than an annoyance; it threatens workers, acolytes, and supply lines moving in and out of the valley. Directing young champions to Eagan serves a dual purpose for Stormwind's marshals: it keeps the nearby paths safe without tying up the garrison's few remaining guards, who already face rising tensions across Elwynn Forest.",sp=0}},faq={{q="Who sends you to speak with Eagan Peltskinner?",a="Deputy Willem, stationed just outside the entrance to Northshire Abbey, directs promising recruits to speak with Eagan after introducing them to the valley's security concerns.",al={"who gives this quest","who starts eagan peltskinner quest"}},{q="Where is Eagan Peltskinner located?",a="Eagan Peltskinner stands near the exterior walls of Northshire Abbey, situated around the left side of the main building among his drying racks and gear.",al={"where is eagan","eagan peltskinner location","find eagan"}},{q="What does Eagan Peltskinner need help with?",a="Eagan is looking for an adventurer willing to hunt the aggressive timber wolves prowling the surrounding woods and bring back their pelts, which helps clear the perimeter of Northshire.",al={"what does eagan want","why hunt wolves","eagan purpose"}},{q="Can you skip this quest and talk to Eagan directly?",a="Yes. Eagan offers his hunting task directly to anyone who approaches him. Taking this referral quest first simply provides a formal introduction from Deputy Willem.",al={"can i skip eagan quest","wolves across the border directly"}},{q="Why are there so many wolves in Northshire Valley?",a="Northshire Valley borders dense, untamed woodlands where timber wolves roam freely. With local guards stretched thin and preoccupied by other threats across the kingdom, the wild predator population has grown unchecked.",al={"why wolves in northshire","wolf problem elwynn"}},{q="What task follows speaking with Eagan Peltskinner?",a="Speaking with Eagan leads immediately into his request to hunt timber wolves across the border of the abbey grounds and collect their tough pelts.",al={"next quest after eagan","what does eagan offer next"}}},ang={["faction:Alliance"]="Every small task in Northshire contributes to securing Stormwind's home territory while the kingdom's core army remains stretched thin elsewhere.",["race:Human"]="For young humans stepping out from Northshire Abbey, aiding local tradesfolk like Eagan is their very first lesson in defending their homeland."},kw={"deputy willem","eagan peltskinner","northshire abbey","northshire valley","timber wolves","wolves across the border"},rel={"quest:783","quest:33","subzone:northshire-valley","zone:elwynn"},m={level="2",faction="Alliance",id=5261},src={"Eagan Peltskinner (quest)"}}
E["quest:5545"] = {t="quest",n="A Bundle of Trouble",z="elwynn",s="Supervisor Raelen at the Eastvale Logging Camp faces a looming lumber delivery deadline with no time to spare. Local bears and wolves have driven her laborers away from freshly cut timber, leaving valuable bundles of wood abandoned in the northern woods. She relies on helpful adventurers to venture into the beast-infested forest and retrieve the logs before the contract is lost.",h="Supervisor Raelen at the Eastvale Logging Camp faces a looming lumber delivery deadline with no time to spare.",sec={{t="A Looming Deadline",b="Eastvale Logging Camp supplies vital timber for the reconstruction and defense efforts of the Kingdom of Stormwind. Running a commercial forestry operation on the edge of the wilderness is fraught with danger, and Supervisor Raelen currently finds herself in a bind. Her crew has fallen behind schedule on a critical shipment of cut timber, and the clock is ticking.",sp=0},{t="Predators in the Timber",b="The issue is not a shortage of fallen trees, but the aggressive local wildlife. Hungry wolves and territorial bears north of the camp have chased off the woodcutters, forcing them to abandon the neatly tied bundles of wood scattered across the forest floor. While town authorities have been alerted to the beast menace, Raelen cannot afford to wait for guards to secure the area and must hire wandering heroes to dash in and collect the timber.",sp=0}},faq={{q="Who is Supervisor Raelen?",a="Supervisor Raelen manages day-to-day operations at the Eastvale Logging Camp in eastern Elwynn Forest. She oversees woodcutting crews and ensures that shipments of timber meet the demands of Stormwind and local settlements.",al={"supervisor raelen","raelen","eastvale supervisor"}},{q="Why is the wood abandoned in the woods?",a="Laborers had already cut, trimmed, and tied the logs into bundles before wild bears and prowling wolves drove them out of the clearing. Fearing for their lives, the workers fled back to camp without hauling the cargo.",al={"why wood left","abandoned lumber","forest wood"}},{q="Why does Raelen mention Deputy Rainer?",a="Raelen states she contacted Deputy Rainer regarding the aggressive predators. Curiously, Deputy Rainer is stationed far across Elwynn Forest at the Westbrook Garrison, suggesting that either messages were carried through official guard channels or local authority is stretched thin across the province.",al={"deputy rainer raelen","why deputy rainer","rainer connection"}},{q="Where is the lumber needed?",a="Eastvale Logging Camp provides timber throughout the kingdom, from rebuilding town infrastructure to reinforcing palisades and bridges. Missing deadlines hurts the local economy and stalls construction projects across Elwynn.",al={"who needs the wood","lumber delivery","timber purpose"}},{q="Why can't the loggers collect the wood themselves?",a="The woodcutters are ordinary laborers equipped for felling trees, not fighting off wild predators. After being attacked and routed by aggressive wolves and bears, none of the workers are willing to risk their lives returning to the thicket unarmed.",al={"why loggers scared","why not loggers","loggers wolves"}},{q="Where can the bundles of wood be found?",a="The bundles of cut wood are lying on the ground in the wooded areas immediately north of the Eastvale Logging Camp, where the laborers were working before being chased off by local beasts.",al={"wood location","where are bundles","find bundles"}}},ang={["faction:Alliance"]="Securing lumber from Eastvale ensures the rebuilding of Stormwind and the upkeep of regional outposts continue without costly supply disruptions.",["class:Hunter"]="Navigating predator-thick groves to recover supplies while managing dangerous local beasts plays directly to a tracker's core survival instincts."},kw={"bears","bundle of wood","deputy rainer","eastvale","elwynn forest","logging camp","supervisor raelen","timber","wolves"},rel={"npc:supervisor-raelen","subzone:eastvale-logging-camp","npc:deputy-rainer","zone:elwynn","subzone:westbrook-garrison"},m={start="Supervisor Raelen",faction="Alliance",id=5545},src={"A Bundle of Trouble"}}
E["quest:5623"] = {t="quest",n="In Favor of the Light",z="elwynn",s="In Favor of the Light marks an early milestone for novice priests training within Northshire Valley. Given by Priestess Anetta, it directs the fledgling minister beyond the cloistered abbey to Goldshire. There, Priestess Josetta awaits to deepen their spiritual discipline and guide them further into the faith of the Holy Light.",h="In Favor of the Light marks an early milestone for novice priests training within Northshire Valley.",sec={{t="Stepping Beyond Northshire",b="Northshire Abbey provides shelter and initial instruction for novices, but clerical training in the Church of the Holy Light demands practical ministry out in the world. Once an initiate demonstrates basic mastery of prayer and divine healing, Priestess Anetta sends them south along the sunlit roads to Goldshire. The journey signifies a transition from secluded student to active parish servant amidst the everyday trials of the Elwynn populace.",sp=0},{t="Tutelage in Goldshire",b="At the Lion's Pride Inn in Goldshire, Priestess Josetta tends to local spiritual needs and oversees rising acolytes. Josetta builds directly upon the fundamentals laid down at the abbey, testing the initiate's ability to offer solace, ward the faithful, and mend the injured. Stepping under her guidance introduces the young priest to the duties required of the Church's servants across the broader kingdom.",sp=0}},faq={{q="Who starts this quest and who do I report to?",a="Priestess Anetta inside Northshire Abbey gives the quest, sending you down the road to meet Priestess Josetta in Goldshire.",al={"who gives in favor of the light","quest turn in","where to turn in in favor of the light"}},{q="Why is a priest sent away from Northshire so early?",a="Northshire provides foundational lessons in the Holy Light, but young ministers are expected to serve real communities quickly. Goldshire offers an immediate parish environment where an acolyte can assist everyday townspeople and town guards under Josetta's direction.",al={"why go to goldshire","why leave northshire abbey"}},{q="Where can Priestess Josetta be found in Goldshire?",a="Priestess Josetta resides inside the Lion's Pride Inn in Goldshire, serving as the local priest trainer.",al={"where is priestess josetta","find josetta","josetta location"}},{q="What happens after meeting Priestess Josetta?",a="Priestess Josetta immediately puts your training to the test with the follow-up task, Garments of the Light, which requires ministering to a wounded guard and receiving ceremonial clerical vestments.",al={"next quest after in favor of the light","what follows in favor of the light"}},{q="Is this quest restricted to priests?",a="Yes. This task represents formal spiritual instruction within the Church of the Holy Light and is only offered to priest initiates.",al={"can any class do in favor of the light","is this priest only"}},{q="What role does the Church of the Holy Light play in Elwynn?",a="The Church offers comfort, spiritual leadership, and physical mending to townsfolk and defenders facing increasing banditry and wildlife incursions throughout the forest.",al={"church of the holy light role","priests in elwynn"}}},ang={["class:Priest"]="This rite of passage bridges your sheltered studies in Northshire with active pastoral work among the citizens and garrisons of Elwynn Forest.",["race:Human"]="For humans of Stormwind, seeking guidance from the priesthood in Goldshire is an essential step in upholding the moral and spiritual backbone of the kingdom.",["faction:Alliance"]="The Church of the Holy Light forms one of the Alliance's key pillars, nurturing devoted healers capable of sustaining frontline defenders."},kw={"anetta","church","elwynn forest","goldshire","holy light","josetta","northshire","priest quest"},rel={"quest:5624","npc:priestess-josetta","npc:priestess-anetta","topic:light","subzone:goldshire","zone:elwynn"},m={start="Priestess Anetta",["end"]="Priestess Josetta",level="4",faction="Alliance",id=5623},src={"In Favor of the Light (Elwynn Forest)"}}
E["quest:5624"] = {t="quest",n="Garments of the Light",z="elwynn",s="Garments of the Light is an early trial for novice priests in Goldshire, assigned by Priestess Josetta. Rather than an abstract test of faith, the church sends the acolyte east to Crystal Lake to mend and bolster the wounded Guard Roberts. Fulfilling this duty proves the student's mastery of healing and earns them their first official vestments recognized by the Church of the Holy Light.",h="Garments of the Light is an early trial for novice priests in Goldshire, assigned by Priestess Josetta.",sec={{t="A Practical Test of Faith",b="Within the traditions of the Church of the Holy Light, novice disciples are rarely elevated purely on doctrine. Priestess Josetta, who instructs acolytes arriving in Goldshire from Northshire Abbey, tests an initiate's practical mastery over divine power before granting formal church recognition. When reports reach town that Guard Roberts lies wounded by the lake east of Goldshire, Josetta turns an everyday misfortune into a proving ground, dispatching the young priest to tend to him.",sp=0},{t="Sustaining the Realm",b="The assignment requires more than simply closing flesh; the acolyte must mend the guard's wounds with restorative prayers and bolster his resilience with a blessing of fortitude. In these troubled times, with Stormwind's military stretched thin and local garrisons beleaguered by kobolds and bandits, Josetta stresses that the priesthood's duty extends directly into martial survival. Returning Guard Roberts to active duty serves the township immediately while demonstrating that the initiate can sustain defenders under fire.",sp=0},{t="Vestments of the Order",b="Upon returning to the Lion's Pride Inn after treating the soldier, the young priest receives their first formal set of robes. These garments signify outward approval and fellowship from the priesthood in Stormwind. Though wearing them is not strictly mandatory for future training, the robes stand as a visible declaration that the church recognizes the wearer as an ordained servant of the Holy Light.",sp=0}},faq={{q="Where can I find Guard Roberts?",a="Guard Roberts is stationed just east of Goldshire, near the shores of Crystal Lake. He can be found resting by the roadside and water's edge, recovering from wounds sustained while on watch.",al={"guard roberts location","where is guard roberts","find guard roberts"}},{q="What spells are required to complete this quest?",a="You must tend to Guard Roberts using Lesser Heal (Rank 2) to restore his health, followed by casting Power Word: Fortitude to bolster his stamina, before returning to Priestess Josetta.",al={"spells needed","what spells do i cast on roberts","how to heal guard roberts"}},{q="Who is Priestess Josetta?",a="Priestess Josetta is a priest trainer for the Church of the Holy Light residing in Goldshire's Lion's Pride Inn. She mentors young acolytes who have left Northshire Abbey, guiding them in practical ministry and divine magic.",al={"josetta lore","priestess josetta goldshire","who gives garments of the light"}},{q="Why does the Church give out robes for this task?",a="The robes are an outward sign that the Church of the Holy Light formally approves of the acolyte and supports their ministry. Completing this practical healing duty proves the initiate has the competence and discipline worthy of bearing the church's vestments.",al={"why garments of the light","priest robe reward lore","church robes meaning"}},{q="Can other classes complete this quest?",a="No. This quest is part of the introductory class questline specifically for Alliance priests who have mastered their fundamental healing and warding prayers.",al={"is garments of the light priest only","can paladins do garments of the light","priest class quest"}},{q="What happens after completing Garments of the Light?",a="Garments of the Light concludes the early level 4 priest initiation line in Goldshire. While there is no immediate breadcrumb follow-up, Priestess Josetta and other trainers throughout the kingdom will offer advanced training and further trials as you grow in experience.",al={"next quest after garments of the light","garments of the light followup"}}},ang={["class:Priest"]="This rite of passage bridges classroom theology in Northshire with active field service, reinforcing that a priest's highest calling is keeping frontline allies alive through direct healing and fortifying wards.",["faction:Alliance"]="With the Stormwind army strained and absent from local hamlets, the town guard relies heavily on the assistance of local church disciples to remain standing against encroaching threats.",["race:Human"]="Human culture places great reverence on the Church of the Holy Light; earning ordained vestments from a township priestess marks an important civic and spiritual milestone in an acolyte's life."},kw={"crystal lake","elwynn forest","garments of the light","goldshire","guard roberts","lesser heal","power word fortitude","priest robe","priestess josetta"},rel={"npc:priestess-josetta","subzone:goldshire","quest:5623","zone:elwynn","topic:light"},m={start="Priestess Josetta",level="4",faction="Alliance",id=5624},src={"Garments of the Light (Elwynn Forest)"}}
E["quest:5805"] = {t="quest",n="Welcome!",z="elwynn",s="This errand introduces newly arrived travelers holding a special gift voucher to Merissa Stilwell in Goldshire. By presenting this token, adventurers are welcomed into the world of Azeroth with a rare miniature companion to join them on their travels. It marks one of the earliest friendly encounters for fresh explorers stepping into Elwynn Forest.",h="This errand introduces newly arrived travelers holding a special gift voucher to Merissa Stilwell in...",sec={{t="A Friendly Face in Goldshire",b="Goldshire is the primary crossroads and gathering hub for human recruits leaving Northshire Valley, making it the natural place for travelers to receive aid and supplies. Among the town's welcoming inhabitants is Merissa Stilwell, who stands ready to greet distinguished newcomers bearing special documentation. For those who enter the realm with a unique voucher in hand, she offers a warm reception and a small exotic pet to accompany them through their journeys across Azeroth.",sp=0},{t="Tokens and Companions",b="The gift voucher carried by honored adventurers serves as an official exchange slip recognized by Stilwell. Rather than coin or arms, the trade offers companionship in a world growing increasingly fraught with danger. With the kingdom of Stormwind stretched thin by Defias outlaws, gnoll incursions, and mysterious political tensions, even a humble companion beast provides comfort to those venturing beyond the safety of town borders.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest directs holders of a special gift voucher to deliver it to Merissa Stilwell in Goldshire. In exchange for the voucher, she grants the bearer a unique non-combat companion pet to follow them on their adventures.",al={"welcome quest purpose","why do welcome quest","what is this voucher for"}},{q="Who is Merissa Stilwell?",a="Merissa Stilwell is a welcoming resident of Goldshire who handles special vouchers for arriving travelers. She greets newcomers to Elwynn Forest and presents them with companion animals as a token of goodwill.",al={"who is merissa","merissa stilwell lore","merissa in goldshire"}},{q="Where does this voucher come from?",a="The voucher appears in the belongings of select travelers upon beginning their journey in Azeroth, specifically awarded as a commemorative gift for holders of the original Collector's Edition of the world.",al={"how do i get voucher","gift voucher source","where goldshire voucher from"}},{q="Where can Merissa Stilwell be found?",a="She is located in the town of Goldshire within Elwynn Forest, standing near the town center along the road just south of the Lion's Pride Inn.",al={"where is merissa stilwell","merissa stilwell location","find merissa"}},{q="Does this quest have any prerequisites or danger involved?",a="There are no prerequisites or combat required. The road from Northshire to Goldshire is completely safe along the beaten path, requiring only a short walk down to the crossroads to turn in the voucher.",al={"welcome quest requirements","is welcome quest dangerous"}},{q="Can Horde players complete this task?",a="No. This specific voucher exchange is tied to Goldshire in Elwynn Forest and is meant solely for Alliance adventurers. The Horde has its own designated handlers in their starting settlements.",al={"can horde do welcome","horde voucher turn in"}}},ang={["race:Human"]="For humans walking out of the Northshire gates into the broader province of Elwynn, turning in this voucher at Goldshire is often one of the first official town interactions they experience.",["faction:Alliance"]="The crossroads of Goldshire serves as the heart of Elwynn Forest, where Alliance recruits get their bearings before reporting to Marshal Dughan and local defenders."},kw={"collector","companion","elwynn forest","gift","goldshire","merissa stilwell","pet","voucher"},rel={"npc:merissa-stilwell","subzone:goldshire","zone:elwynn"},m={start="Goldshire Gift Voucher",["end"]="Merissa Stilwell",level="1",faction="Alliance",id=5805},src={"Welcome! (Goldshire)"}}
E["quest:59"] = {t="quest",n="Cloth and Leather Armor",z="elwynn",s="Cloth and Leather Armor is an errand commissioned by Guard Thomas at the eastern bridge in Elwynn Forest. Impressed by an adventurer's service, Thomas issues an official military armor marker redeemable with local artisan Sara Timberlain. This task directs recruits deeper east into the Eastvale Logging Camp to obtain proper gear for the defense of the realm.",h="Cloth and Leather Armor is an errand commissioned by Guard Thomas at the eastern bridge in Elwynn Forest.",sec={{t="A Guard's Token",b="Guard Thomas stands vigil at the eastern crossing over the river in Elwynn, holding the border against hostile murlocs and roving gnolls. Recognizing the efforts of capable travelers who aid his lonely post, he provides an official Stormwind Armor Marker rather than pulling equipment from his own meager field rations. This marker acts as a military requisition voucher, officially recognizing the bearer's service to the crown.",sp=0},{t="The Weaver of Eastvale",b="Across the bridge to the east lies the Eastvale Logging Camp, Elwynn's primary timber operation. Working out of the settlement, Sara Timberlain holds an official commission from the Stormwind Army to produce cloth and leather gear. Because the kingdom's centralized armories are strained and stretched thin, local artisans like Sara are vital for outfitting troops and auxiliary scouts on the frontier.",sp=0}},faq={{q="What is a Stormwind Armor Marker?",a="It is an official military requisition slip issued by officers like Guard Thomas. Rather than stocking bulky armor sets at isolated watch posts, guards carry markers that allow trusted recruits to claim custom-fitted armor from commissioned civilian artisans.",al={"armor marker","stormwind voucher","what is the marker"}},{q="Who is Sara Timberlain?",a="Sara Timberlain is a tailor and crafter residing in the Eastvale Logging Camp. She holds a contract with the Stormwind Army to manufacture cloth and leather equipment for kingdom personnel and authorized auxiliary fighters.",al={"sara timberlain","eastvale tailor","who makes the armor"}},{q="Where is the Eastvale Logging Camp?",a="Eastvale Logging Camp is located in far eastern Elwynn Forest. From Guard Thomas's post at the river bridge, follow the road east into the wooded valley where woodcutters harvest timber for the kingdom.",al={"eastvale location","where is eastvale","how to get to timberlain"}},{q="Why does Guard Thomas send adventurers to Eastvale?",a="Thomas does not carry a surplus of finished gear at his river checkpoint. Instead, he rewards brave deeds by sending recruits to Sara Timberlain, directing travelers toward Eastvale while ensuring they are properly protected to defend Elwynn.",al={"why guard thomas marker","thomas purpose","why eastvale"}},{q="Why is the army relying on local tailors for supplies?",a="With King Varian Wrynn missing and Stormwind's military spread thin responding to Defias activity and wild beasts, local defense posts depend heavily on contracted regional workers to sustain their supply lines.",al={"stormwind supply problems","why local artisan","army logistics"}},{q="Who is Guard Thomas defending against?",a="Guard Thomas monitors the eastern border of Elwynn Forest, watching over the bridge against incursions from river murlocs, prowling beasts, and the dangerous wilderness bordering the Redridge Mountains.",al={"guard thomas enemies","threats at bridge","eastern elwynn threats"}}},ang={["faction:Alliance"]="Outfitting defenders through local contracts demonstrates how rural Elwynn communities keep the Alliance functioning despite political paralysis in the capital.",["race:Human"]="Serving Guard Thomas and trading with Sara Timberlain reflects the shared civic bonds that hold the small homesteads of Elwynn Forest together.",["profession:Tailoring"]="Sara Timberlain's commission with the army shows that cloth crafting is a critical, officially sponsored military trade in the kingdom."},kw={"armor marker","cloth and leather armor","eastvale","elwynn forest","guard thomas","logging camp","sara timberlain","stormwind army"},rel={"npc:guard-thomas","npc:sara-timberlain","subzone:eastvale-logging-camp","quest:71","topic:stormwind-army","zone:elwynn","topic:stormwind-kingdom"},m={start="Guard Thomas",["end"]="Sara Timberlain",faction="Alliance",id=59},src={"Cloth and Leather Armor"}}
E["quest:6"] = {t="quest",n="Bounty on Garrick Padfoot",z="elwynn",s="Bounty on Garrick Padfoot is an Alliance bounty contract issued by Deputy Willem at Northshire Abbey. It directs young recruits to hunt down a notorious local thief who has been harassing Elwynn's farmers and merchants from a secluded shack near the vineyards.",h="Bounty on Garrick Padfoot is an Alliance bounty contract issued by Deputy Willem at Northshire Abbey.",sec={{t="A Plague on the Valley",b="Northshire Valley was once considered a secure sanctuary for training recruits and tending sacred vineyards, but the recent collapse of law and order across Elwynn has left it exposed. Bands of thieves have crept into the valley, and a cutthroat named Garrick Padfoot quickly rose to lead them. For weeks, Garrick and his gang have plundered shipments, robbed merchants along the roads, and threatened the local farmers.",sp=0},{t="Deputy Willem's Justice",b="With the Stormwind guards stretched thin protecting the capital and outer borders, local marshals and deputies must rely on eager volunteers to keep peace in Northshire. Deputy Willem places a public bounty on Garrick's head to rid the valley of his gang once and for all. Taking down Padfoot at his rundown shack east of the river strikes an early blow against the broader lawlessness seeping into the human heartland.",sp=0}},faq={{q="Who is Garrick Padfoot?",a="Garrick Padfoot is a bandit and cutthroat operating in Northshire Valley. He has spent weeks harassing local farmers and ambushing merchants, gathering a small ring of thugs around him to stake out territory near the vineyards.",al={"garrick padfoot","who is garrick","padfoot"}},{q="Where can Garrick Padfoot be found?",a="He holes up in a small wooden shack located east of Northshire Abbey, across the river bridge and near the vineyards. He is guarded by his fellow thugs.",al={"where is garrick padfoot","garrick location","garrick shack"}},{q="Who issues the bounty on Garrick?",a="Deputy Willem, stationed outside Northshire Abbey, posts the bounty. Lacking enough city guards to police the valley, Willem hires wandering recruits to bring the outlaw to justice.",al={"who gives bounty on garrick padfoot","willem bounty"}},{q="Why is Stormwind not sending regular soldiers to deal with him?",a="Stormwind's military is overextended. With King Varian Wrynn missing and tensions rising across Elwynn Forest and beyond, the capital cannot spare veteran garrisons for every small-time thug, leaving local deputies to deputize recruits.",al={"why don't guards kill garrick","where are stormwind guards"}},{q="Is Garrick Padfoot working alone?",a="No. Garrick has surrounded himself with a small gang of outlaws and bandits who camp around his shack near the Northshire vineyards to protect him.",al={"is garrick solo","padfoot gang"}},{q="What proof does Deputy Willem require?",a="Deputy Willem demands physical proof before paying out the coin, specifically requiring you to bring back Garrick Padfoot's severed head to Northshire Abbey.",al={"proof of garrick death","garricks head"}}},ang={["faction:Alliance"]="Taking down Garrick Padfoot represents one of the first direct services an aspiring Alliance adventurer performs to restore stability to the Kingdom of Stormwind.",["race:Human"]="For humans raised in the kingdom, ridding Northshire of cutthroats like Padfoot is a personal matter of protecting their homeland's sacred ground and local farmers.",["class:Rogue"]="Garrick Padfoot provides rogues with an early glimpse of how outlaws operate in the shadows of Elwynn, showing that poorly hidden hideouts invite swift blades."},kw={"bounty","cutthroat","elwynn","garrick","northshire","padfoot","thieves","vineyard","willem"},rel={"subzone:northshire-abbey","quest:18","zone:elwynn"},m={start="Deputy Willem",level="5",faction="Alliance",id=6},src={"Bounty on Garrick Padfoot"}}
E["quest:60"] = {t="quest",n="Kobold Candles",z="elwynn",s="Kobold Candles is an early errand offered by William Pestle in the Lion's Pride Inn at Goldshire. An alchemist visiting from his shop in Stormwind, Pestle seeks the thick wax of large candles carried by the kobolds that have overstocked Elwynn Forest's local mines. For adventurers, it serves as an early introduction to the subterranean pests encroaching on the kingdom's valuable gold veins.",h="Kobold Candles is an early errand offered by William Pestle in the Lion's Pride Inn at Goldshire.",sec={{t="Apothecary's Errands",b="William Pestle runs Pestle's Apothecary alongside his brother in the Trade District of Stormwind City. While brewing remedies, ointments, and concoctions, raw materials like wax are always in short supply. Rather than procuring polished candles from city merchants, Pestle recognizes that the vermin plaguing Elwynn carry surprisingly hefty lumps of tallow and wax atop their brows—free for the taking if an adventurer is willing to pry them loose.",sp=0},{t="The Mines of Elwynn",b="Kobolds have thoroughly infested both Fargodeep Mine to the south of Goldshire and Jasperlode Mine to the northeast. These snuffling subterranean creatures value their candles above almost all else, using their flickering light to navigate dark shafts while digging for gold and shiny trinkets. Plundering these candles not only satisfies Pestle's alchemy stocks, but chips away at the encroaching vermin choking off the kingdom's precious mining claims.",sp=0}},faq={{q="Why does William Pestle need kobold candles?",a="William Pestle and his brother operate an apothecary shop in Stormwind's Trade District. They use the rendered tallow and wax from the large candles as an ingredient for sealing, salves, and various alchemical preparations.",al={"why pestle wants candles","what are candles used for","candle wax use"}},{q="Where do you find the large candles?",a="The candles are carried by the kobold workers, vermin, and diggers dwelling in the mines of Elwynn Forest, primarily inside the tunnels of Fargodeep Mine south of Goldshire and Jasperlode Mine to the east.",al={"where are kobold candles","candle locations","how to get large candles"}},{q="Why are kobolds so obsessed with candles?",a="Kobolds live in pitch-black tunnels underground and rely on the small flames strapped to their heads to see while digging. They hold a superstitious, almost frantic terror of the dark, fiercely defending their candles from anyone who tries to take them.",al={"why do kobolds have candles","you no take candle meaning","kobold candle lore"}},{q="Who is William Pestle?",a="William Pestle is a human merchant and alchemist from Stormwind. When he is not working his shop in the city's Trade District, he travels to Goldshire to secure cheap materials from traveling adventurers.",al={"who is william pestle","william pestle lore","goldshire pestle"}},{q="Does this quest connect to other troubles in Elwynn?",a="Yes. The infestation of Fargodeep and Jasperlode Mines poses a major economic threat to Goldshire and Stormwind. Human miners have been driven out, and securing the tunnels is one of Marshall Dughan's top priorities.",al={"elwynn mine problems","why are kobolds in mines","goldshire kobold threat"}},{q="Are there any other mines infested by kobolds in Elwynn?",a="Fargodeep Mine and Jasperlode Mine are the two primary sites near Goldshire, but kobold activity also spills into the riverbanks of the forest and eastward toward the borders of Redridge.",al={"other kobold mines","elwynn mines list"}}},ang={["profession:Mining"]="Clearing the kobolds for their candles brings prospectors directly into Elwynn's richest copper and gold veins, which have been abandoned by human miners.",["race:Human"]="Reclaiming the stolen mines of Elwynn and providing goods to Stormwind's home artisans are early duties for young subjects of the kingdom.",["faction:Alliance"]="With the royal army stretched thin by internal political strife and missing crown forces, securing local infrastructure falls to civilian volunteers and traveling adventurers."},kw={"apothecary","candle","elwynn","fargodeep","goldshire","jasperlode","kobold","wax","william pestle"},rel={"npc:william-pestle","subzone:fargodeep-mine","subzone:jasperlode-mine","subzone:goldshire","topic:kobold","quest:62","zone:elwynn","topic:stormwind-kingdom"},m={start="William Pestle",faction="Alliance",id=60},src={"Kobold Candles"}}
E["quest:61"] = {t="quest",n="Shipment to Stormwind",z="elwynn",s="Shipment to Stormwind is an Alliance delivery quest that concludes William Pestle's candle venture in Elwynn Forest. After gathering large wax candles from the local kobold vermin, adventurers carry the packaged shipment up the road into the Trade District of Stormwind to William's brother, Morgan Pestle.",h="Shipment to Stormwind is an Alliance delivery quest that concludes William Pestle's candle venture in Elwynn...",sec={{t="A Family Trade",b="The Pestle brothers maintain an alchemical trade between the pastoral hamlets of Elwynn Forest and the bustling avenues of Stormwind City. William gathers herbs, reagents, and raw goods out in Goldshire, while his brother Morgan runs Pestle's Apothecary in the capital's Trade District. Because William cannot easily leave his post at the Lion's Pride Inn, he relies on travelers heading into the city gates to handle courier duties.",sp=0},{t="From Kobold Wax to Capital Potions",b="The contents of William's parcel consist of large, pungent candles harvested directly from the kobolds infesting the Fargodeep and Jasperlode mines. Kobold tallow is notoriously greasy and foul, but alchemists prize raw tallow and wax for compounding salves, sealing drafty glassware, and brewing base draughts. Delivering the wax to Morgan ensures the apothecary remains well-stocked with cheap, potent ingredients.",sp=0}},faq={{q="What is inside William's shipment?",a="The shipment consists of packaged wax candles taken from the kobolds in Elwynn Forest's mines. William's apothecary uses the wax and tallow as reagents for alchemy and brewing.",al={"shipment contents","what is in the package","what did william send"}},{q="Where do I find Morgan Pestle?",a="Morgan Pestle works inside Pestle's Apothecary, located in the Trade District of Stormwind City, just a short walk past the main gates.",al={"morgan pestle location","where is morgan","find morgan pestle"}},{q="How are William and Morgan Pestle related?",a="William and Morgan Pestle are brothers who run an alchemical enterprise together. William procures materials in Elwynn Forest while Morgan operates their shop in Stormwind.",al={"pestle brothers","who is william pestle brother"}},{q="Why doesn't William deliver the package himself?",a="William is tied up managing his trade and collecting alchemical ingredients out in Goldshire. He prefers hiring passing adventurers who are already traveling north toward the capital gates.",al={"why doesn't william go to stormwind","why hire a courier"}},{q="Do kobold candles have an actual alchemical use?",a="Yes. Kobolds craft heavy tallow candles to navigate subterranean tunnels. Alchemists like the Pestle brothers repurpose this tallow and wax for sealing vials, creating unguents, and refining bases for various mixtures.",al={"why kobold candles","kobold wax alchemy"}},{q="What comes after delivering the shipment?",a="This delivery concludes the short chain that began with gathering kobold candles in Elwynn Forest. Morgan simply pays you for the courier work and welcomes your business in his shop.",al={"what next after shipment to stormwind","follow up quest shipment to stormwind"}}},ang={["profession:Herbalism"]="The Pestle family business is deeply tied to Elwynn's local reagents, and making a stop at their Stormwind shop is a familiar routine for gatherers and potion-makers alike.",["faction:Alliance"]="Carrying supplies along the king's road into Stormwind is a classic rite of passage for young Alliance champions moving from countryside skirmishes into the bustling capital."},kw={"elwynn forest","goldshire","kobold candles","morgan pestle","pestle's apothecary","shipment to stormwind","trade district","william pestle"},rel={"quest:60","npc:william-pestle","npc:morgan-pestle","subzone:trade-district","zone:elwynn","topic:kobold","topic:stormwind-kingdom"},m={start="William Pestle",["end"]="Morgan Pestle",level="7",faction="Alliance",id=61},src={"Shipment to Stormwind"}}
E["quest:62"] = {t="quest",n="The Fargodeep Mine",z="elwynn",s="Marshal Dughan of Goldshire tasks scouts with investigating reports that the Fargodeep Mine has been overrun by kobolds. Located south of town between the Stonefield and Maclure farms, the mine's fall signals a growing pest problem throughout Elwynn Forest.",h="Marshal Dughan of Goldshire tasks scouts with investigating reports that the Fargodeep Mine has been overrun...",sec={{t="Trouble South of Goldshire",b="While Northshire Valley dealt with its own vermin, troubling reports reached Goldshire that kobolds had claimed another vital site. The Fargodeep Mine, nestled between the feuding Stonefield and Maclure homesteads south of town, was once a source of stone and ore for the realm. Now, shrill chattering and the flicker of tallow candles fill the damp tunnels, prompting Marshal Dughan to dispatch adventurers to scout the depths and confirm the worst.",sp=0},{t="A Strained Guard",b="Confirming the infestation only deepens the headaches of the Stormwind Guard. With regular troops stretched thin defending against Defias bandits and gnoll incursions, the guard lacks the manpower to clear the mine outright. Dughan's grim reaction upon receiving confirmation highlights the creeping loss of control in the heartland, leading him to immediately worry about other mineral sites like the Jasperlode Mine to the northeast.",sp=0}},faq={{q="Where is the Fargodeep Mine located?",a="Fargodeep Mine sits almost due south of Goldshire in Elwynn Forest, tucked right between the Stonefield and Maclure homesteads.",al={"fargodeep location","where is fargodeep mine","fargodeep mine map"}},{q="Who sends you to scout the Fargodeep Mine?",a="Marshal Dughan, the commanding officer of the Stormwind Guard stationed in Goldshire, hands out the assignment to scout the tunnels.",al={"who gives fargodeep quest","marshal dughan quest"}},{q="What creatures have taken over the mine?",a="The mine has been completely overrun by kobolds, who have dug in, lit their candles, and displaced the human workers.",al={"who is in fargodeep","what monsters in fargodeep"}},{q="Why does Marshal Dughan need adventurers to check the mine?",a="The Stormwind Guard is already stretched thin dealing with local banditry, orc remnants, and gnoll raids, leaving Dughan without the spare soldiers needed even to confirm routine scout reports.",al={"why send scouts","why doesn't the guard go"}},{q="What happens after scouting the Fargodeep Mine?",a="Once you report the bad news to Marshal Dughan, he fears the problem is widespread and sends you northeast to investigate the Jasperlode Mine as well.",al={"next quest after fargodeep","what comes next"},sp=1},{q="Why is the infestation of Fargodeep Mine significant?",a="The fall of Fargodeep proves that the kobold infestation in Northshire was not an isolated event. It shows how rapidly wild threats are encroaching on settled farmland right outside Stormwind's gates.",al={"why does fargodeep matter","lore of fargodeep mine"}}},ang={["profession:Mining"]="The rich copper veins inside Fargodeep Mine are vital for early smiths, but working them requires cutting through territorial kobolds.",["faction:Alliance"]="The overrun mine is another clear sign of Stormwind's failing authority in Elwynn, as the local guard struggles to protect essential infrastructure."},kw={"dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","maclure","stonefield"},rel={"npc:marshal-dughan","subzone:fargodeep-mine","quest:76","subzone:goldshire","topic:kobold","subzone:jasperlode-mine","zone:elwynn"},m={start="Marshal Dughan",faction="Alliance",id=62},src={"The Fargodeep Mine"}}
E["quest:6285"] = {t="quest",n="Return to Lewis",z="elwynn",s="Return to Lewis marks the final leg of an introductory courier flight, delivering desperately needed armor from Stormwind directly to Sentinel Hill. Entrusted with Osric's Crate by Dungar Longdrink, couriers fly across the skies of Elwynn and Westfall on gryphonback to resupply the embattled People's Militia.",h="Return to Lewis marks the final leg of an introductory courier flight, delivering desperately needed armor...",sec={{t="A Lifeline by Air",b="Westfall is slipping out of the kingdom's grasp, besieged by Defias bandits, ravenous gnolls, and mechanical harvest reapers. With overland supply routes harassed and roads dangerous for solitary wagons, the flight master network provides a crucial lifeline. Osric, an armorer based in the Old Town of Stormwind, prepared a heavy crate of armor intended to reinforce the battered volunteers of the People's Militia at Sentinel Hill.",sp=0},{t="The Ways of Gryphons",b="Gryphons are remarkably loyal and well-trained beasts, but navigating them across the lands requires established familiarity. As Dungar Longdrink explains to novice couriers, while gryphons instinctively know how to return home to their capital roost in Stormwind, they will only carry a rider to a remote outpost once the traveler has physically met the destination's flight master. Having previously checked in with Thor at Sentinel Hill, the skies over the frontier open up for rapid transit.",sp=0},{t="Supplies for the Militia",b="Upon landing at Sentinel Hill, the delivered crate is received by Quartermaster Lewis, the officer tasked with outfitting Gryan Stoutmantle's volunteer force. Lewis immediately sets to work distributing the armor among the frontier defenders. For Sentinel Hill, reliable aerial contact with the capital means the difference between holding the line and being completely overrun by the Defias Brotherhood.",sp=0}},faq={{q="What is inside Osric's Crate?",a="The crate contains freshly manufactured suits of armor arranged by the Stormwind armorer Osric. It is urgently needed by the People's Militia at Sentinel Hill, who lack standard royal provisioning and rely on donations and private shipments to equip their volunteer fighters.",al={"osrics crate contents","what is in the box","what am i delivering"}},{q="Who is Quartermaster Lewis?",a="Quartermaster Lewis is the supply officer for the People's Militia, stationed beside the tower at Sentinel Hill. He manages rations, gear, and arms for the volunteer defenders standing against the Defias Brotherhood across Westfall.",al={"lewis westfall","quartermaster lewis role","who is lewis"}},{q="Who is Dungar Longdrink?",a="Dungar Longdrink is the veteran dwarven gryphon master of Stormwind, located at the roost just inside the capital's grand entrance. He oversees the kingdom's aerial courier and passenger routes.",al={"dungar stormwind","stormwind gryphon master","flight master stormwind"}},{q="Why do gryphons only fly to places you've already visited?",a="According to Dungar, gryphons are naturally trained to navigate straight back to the capital city, but they rely on established waypoints and personal familiarity before ferrying riders out to remote frontier roosts like Thor's station at Sentinel Hill.",al={"gryphon flight rule","how flight paths work","why must i visit thor first"}},{q="Who is Thor?",a="Thor is the flight master stationed at Sentinel Hill in Westfall. He tends the outpost's gryphons and receives aerial couriers arriving from Stormwind.",al={"thor westfall","sentinel hill gryphon master","flight master thor"}},{q="Why can't Stormwind just send royal wagons with supplies?",a="The roads connecting Elwynn Forest and Westfall are heavily harassed by Defias bandits, riverpaw gnolls, and thieves. Overland supply trains risk ambush and confiscation, making the aerial gryphon route far faster and safer.",al={"why use gryphons","why not overland delivery","roads in westfall"}}},ang={["faction:Alliance"]="Establishing gryphon routes between Stormwind and outlying settlements like Sentinel Hill is essential to binding together an increasingly fractured kingdom.",["race:Dwarf"]="The entire aerial transit system of the kingdom relies on dwarven expertise, from Dungar Longdrink at the capital roost to Thor out in Westfall.",["class:Warrior"]="Every crate of breastplates and greaves flown to Sentinel Hill means one more militia fighter who can withstand the blows of Defias brigands."},kw={"dungar longdrink","flight path","gryphon","osric","osric's crate","people's militia","quartermaster lewis","sentinel hill","thor","westfall"},rel={"quest:6261","quest:6281","quest:6181","npc:quartermaster-lewis","npc:thor","subzone:sentinel-hill","zone:westfall","topic:stormwind-kingdom"},m={start="Dungar Longdrink",["end"]="Quartermaster Lewis",level="10",faction="Alliance",id=6285},src={"Return to Lewis"}}
E["quest:71"] = {t="quest",n="Report to Thomas",z="elwynn",s="Report to Thomas is a quest in eastern Elwynn Forest concerning Guard Thomas's investigation into the missing Stormwind guards near the eastern waterways. An adventurer assists Guard Thomas at the eastern bridge by investigating the fate of his missing comrades and reporting back on the situation along the river.",h="Report to Thomas is a quest in eastern Elwynn Forest concerning Guard Thomas's investigation into the missing...",sec={{t="A Grim Confirmation",b="Guard Thomas has held the crossing between Goldshire and the Eastvale Logging Camp with very few men to spare. When two of his comrades, Malakai and Rolf, disappeared into the riverlands, hope remained that they were merely cut off or delayed. Bringing their recovered service medallions back to the bridge extinguishes that hope, verifying that both guards were slain near the waterways.",sp=0},{t="The Threat Along the Water",b="For months, Stormwind's leadership has largely dismissed murlocs as nuisance river-dwellers, prioritizing bandit activity and broader kingdom borders. The slaughter of two armed Stormwind guards along the inland streams demonstrates organized brutality. With proof in hand, Thomas realizes the eastern frontier of Elwynn faces an active assault, compelling him to demand a response before the logging routes and settlements are overwhelmed.",sp=0}},faq={{q="Where does Guard Thomas stand?",a="Guard Thomas is posted at the stone bridge crossing the river in eastern Elwynn Forest, connecting the road between Goldshire and the Eastvale Logging Camp.",al={"thomas location","guard thomas bridge","where is guard thomas"}},{q="Who were Rolf and Malakai?",a="Rolf and Malakai were Stormwind guards dispatched to patrol eastern Elwynn Forest. Both were overwhelmed and killed by murlocs lurking along the riverbanks and Stonecairn Lake.",al={"missing guards elwynn","who was rolf","who was malakai"},sp=1},{q="Why were their medallions necessary?",a="The medallions served as official identification for Stormwind city guards. Returning them provided indisputable proof to Guard Thomas that his missing men had fallen in duty.",al={"why medallions","guard medallions purpose"},sp=1},{q="Why is the murloc attack such a big deal?",a="Murlocs were commonly regarded as primitive, cowardly pests rather than a lethal threat to trained soldiers. The death of two armed guards proves that the river tribes have grown emboldened and capable of coordinated ambush.",al={"why murlocs threat","are murlocs dangerous elwynn"},sp=1},{q="What happens after reporting back to Thomas?",a="Upon receiving the medallions, Guard Thomas prepares an official dispatch warning the garrison in Goldshire of the escalating murloc danger, seeking reinforcements and assistance.",al={"next quest after report to thomas","what does thomas do next"},sp=1},{q="Why is Guard Thomas posted alone at the bridge?",a="Stormwind's military is stretched thin across the realm, with King Varian Wrynn missing and resources strained. Outlying posts like the eastern bridge have only minimal personnel to guard vital transit routes.",al={"why is thomas alone","stormwind bridge guard alone"}}},ang={["faction:Alliance"]="The death of Rolf and Malakai illustrates the vulnerable state of Elwynn Forest's borders, where even everyday river patrols can be overwhelmed due to manpower shortages.",["race:Human"]="Recovering the fallen guards' medallions offers a measure of honor and finality to Stormwind soldiers who died defending the kingdom's interior roads."},kw={"bridge","elwynn forest","goldshire","guard thomas","malakai","medallions","murlocs","rolf"},rel={"quest:45","npc:guard-thomas","quest:39","quest:59","topic:murloc","zone:elwynn","subzone:eastvale-logging-camp","subzone:goldshire"},m={start="Rolf's corpse",["end"]="Guard Thomas",faction="Alliance",id=71},src={"Report to Thomas"}}
E["quest:76"] = {t="quest",n="The Jasperlode Mine",z="elwynn",s="Following the discovery that kobolds have overrun the Fargodeep Mine, Marshal Dughan tasks scouts with investigating the Jasperlode Mine further east. Reaching the site confirms the worst: the infestation has spread across Elwynn's vital mineral veins, stretching Stormwind's remaining defenders past their limits.",h="Following the discovery that kobolds have overrun the Fargodeep Mine, Marshal Dughan tasks scouts with...",sec={{t="A Second Incursion",b="After securing proof that kobolds had swarmed the Fargodeep tunnels south of Goldshire, Marshal Dughan feared the infestation was not an isolated incident. Jasperlode Mine, nestled in the rocky foothills northeast of the Tower of Azora, represents another critical source of raw stone and metal for the kingdom. Unable to spare regular Stormwind guards from town patrol, Dughan relies on independent adventurers to venture east and confirm whether this site has fallen to the candle-bearing subterranean pests as well.",sp=0},{t="Overextended Defenses",b="Scouting deep into Jasperlode's chambers reveals that kobolds have entirely displaced the human miners, digging in and fortifying the dark passages. For Marshal Dughan, this grim report is another blow in an escalating crisis. With King Varian Wrynn missing and royal troops withheld from the outlying territories, the local garrison lacks the manpower to clear the mines, leaving the heart of the kingdom economically starved and geographically hemmed in.",sp=0}},faq={{q="Where is the Jasperlode Mine located?",a="The mine sits in the northern foothills of eastern Elwynn Forest. To reach it, travel east down the main road past Goldshire until reaching the Tower of Azora, then head north into the hills.",al={"where is jasperlode","jasperlode mine location","how to find jasperlode"}},{q="Why does Marshal Dughan need a scout instead of sending guards?",a="The Stormwind Guard in Elwynn is severely shorthanded due to political gridlock in the capital and the disappearance of King Varian Wrynn. With local forces stretched thin protecting farms and towns from bandits and gnolls, Marshal Dughan must rely on civilian scouts.",al={"why send adventurers","why no stormwind guard","where are the guards"}},{q="Why are kobolds taking over Elwynn's mines?",a="Kobolds are natural tunnelers drawn to subterranean mineral veins and damp caves. As Stormwind's military presence thinned, the creatures grew bolder, aggressively pushing into human-operated dig sites like Fargodeep and Jasperlode to claim gold, ore, and territory.",al={"why kobolds in jasperlode","what do kobolds want","kobold infestation reason"}},{q="What happens after scouting the Jasperlode Mine?",a="Once you report Jasperlode's fall to Marshal Dughan, he acknowledges the grim reality that Elwynn is besieged on multiple fronts. With the eastern mines confirmed lost, his attention shifts to western Elwynn, where the Westbrook Garrison faces heavy pressure from Riverpaw gnolls.",al={"what next after jasperlode","jasperlode follow up"}},{q="Why is the loss of Jasperlode Mine significant to Stormwind?",a="The mines of Elwynn supply raw ore and stone needed to maintain Stormwind's economy and forge weapons and armor. Losing both Fargodeep and Jasperlode halts mineral extraction and severely undermines the kingdom's recovery efforts.",al={"why jasperlode matters","jasperlode importance"}},{q="Who owns the Tower of Azora nearby?",a="The Tower of Azora is a small mage tower along the eastern road in Elwynn Forest, presided over by Theocritus, the Archmage of Azora, and run by the gnomish servants of Azora. It serves as a landmark for travelers navigating toward the eastern foothills.",al={"what is tower of azora","who lives in azora tower"}}},ang={["profession:Mining"]="For a miner, seeing rich underground veins overrun by vermin is a bitter sight. Jasperlode's tunnels hold valuable deposits, but harvesting them requires fighting through swarms of territorial kobolds.",["faction:Alliance"]="The simultaneous loss of Fargodeep and Jasperlode exposes how fragile Stormwind's home territories have become in the absence of centralized royal support.",["race:Human"]="Human scouts witness the creeping collapse of Elwynn's rural infrastructure firsthand as frontier resources fall right on the doorstep of the capital."},kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","mine","scout"},rel={"subzone:jasperlode-mine","quest:62","subzone:fargodeep-mine","npc:marshal-dughan","subzone:tower-of-azora","quest:239","subzone:goldshire","topic:kobold"},m={start="Marshal Dughan",faction="Alliance",id=76},src={"The Jasperlode Mine"}}
E["quest:7677"] = {t="quest",n="White Stallion Exchange",z="elwynn",s="The White Stallion Exchange is an arrangement offered by horse breeder Katie Hunter at Eastvale Logging Camp. Riders who acquired a traditional white stallion can trade their bridle for a steed from the camp's newly outfitted swift herd. It offers Alliance equestrians a fresh look while retaining the speed of their seasoned mount.",h="The White Stallion Exchange is an arrangement offered by horse breeder Katie Hunter at Eastvale Logging Camp.",sec={{t="A New Look at Eastvale",b="Eastvale Logging Camp is known primarily for lumber, but the open pastures along the edge of the forest make it a natural home for Stormwind's horse breeders. Katie Hunter oversees the stables here, tending to both sturdy workhorses and swift riding stock. For riders who already own a prized white stallion, she offers an open trade: surrender your old bridle in exchange for one of her newly bred and armored steeds, granting the mount an updated appearance while maintaining its proven speed.",sp=0},{t="Horses of the Alliance",b="Horses are the traditional backbone of Stormwind's cavalry and civilian travel. As stable masters refine bloodlines and equip steeds with modern barding, riders are given opportunities to adopt mounts from the latest herds. Rather than forcing veteran cavaliers to purchase a replacement outright, stable keepers like Katie allow a straight exchange for those looking to field the freshest breeds.",sp=0}},faq={{q="What is the White Stallion Exchange?",a="It is an exchange offered by Katie Hunter in Elwynn Forest that allows owners of a standard white stallion to trade their mount's bridle for a newly bred swift steed with updated tack and appearance.",al={"what is white stallion exchange","stallion exchange quest","trade white horse"}},{q="Where does this exchange take place?",a="The exchange takes place at Eastvale Logging Camp, situated in the eastern reaches of Elwynn Forest near the border of Redridge Mountains.",al={"where to turn in white stallion exchange","katie hunter location","white stallion turn in"}},{q="Who offers the trade?",a="Katie Hunter, an Alliance horse breeder stationed at the stables in Eastvale Logging Camp, handles the trade.",al={"who gives white stallion exchange","who trades horses elwynn","katie hunter"}},{q="Will the new horse be slower than the old one?",a="No. Katie Hunter guarantees that the steed from the new herd matches the speed of the original mount, offering only a cosmetic change to its armor and look.",al={"is new mount slower","white stallion speed difference","new horse speed"}},{q="Can Horde players trade horses with Katie Hunter?",a="No. Katie Hunter is loyal to the Kingdom of Stormwind and will only trade horses with members of the Alliance.",al={"can horde do white stallion exchange","is this alliance only"}},{q="Why was the exchange offered?",a="Stable masters across Azeroth introduced refreshed breeds with modern armor and barding, and this trade ensures existing riders can update their mount to the new look without having to buy another horse.",al={"why swap white stallion","reason for horse exchange"}}},ang={["race:Human"]="Stormwind's equestrian traditions run deep, and the stables at Eastvale allow human riders to ride into battle atop the kingdom's newest stock.",["faction:Alliance"]="The sturdy steeds of Elwynn provide reliable transportation for Alliance champions navigating the contested roads of the eastern kingdoms."},kw={"bridle","eastvale","elwynn","horse breeder","katie hunter","mount exchange","swift steed","white stallion"},rel={"npc:katie-hunter","zone:elwynn"},m={start="Katie Hunter",level="1",faction="Alliance",id=7677},src={"White Stallion Exchange"}}
E["quest:7678"] = {t="quest",n="Palomino Exchange",z="elwynn",s="The Palomino Exchange is a simple transactional arrangement handled by the horse breeders of Elwynn Forest. It allows riders who acquire an old palomino bridle to trade it in for an updated mount suitable for travel across the kingdom.",h="The Palomino Exchange is a simple transactional arrangement handled by the horse breeders of Elwynn Forest.",sec={{t="Equine Trade in Elwynn",b="Elwynn Forest serves as the heart of equestrian life for the kingdom of Stormwind. Between Eastvale Logging Camp and the farmlands of Goldshire, stable hands and horse breeders care for thoroughbreds that carry messengers, town guards, and travelling adventurers along the King's Road. The palomino exchange reflects standard stable upkeep, offering riders the chance to update their bridles and mounts through the local horse handlers.",sp=0},{t="A Matter of Stock",b="The stables across Azeroth have seen fluctuating supplies of horses since the ravages of the Third War. As the royal cavalry reorganizes and standardizes its gear, stable masters honor old claims and trade agreements, swapping out older palomino bridles for horses conditioned for long-distance road riding.",sp=0}},faq={{q="What is the Palomino Exchange?",a="It is a practical exchange offered by stable masters in Elwynn Forest, allowing a rider with an older Palomino Bridle to turn it in for standard equine stock.",al={"palomino trade","what is palomino exchange","bridle swap"}},{q="Where does this trade take place?",a="The exchange is handled by the horse breeders operating out of the pastures and stables in Elwynn Forest, primarily around Eastvale Logging Camp.",al={"where do i turn in palomino","palomino location","elwynn horse stables"}},{q="Why do the stables exchange palominos?",a="Stable masters maintain uniform stock and gear for travelers and military couriers across the Alliance, swapping out retired equipment and older steeds for standardized mounts.",al={"why trade palomino","why bridle exchange"}},{q="Do I need special standing with Stormwind to ride a palomino?",a="Humans are naturally trained in riding these steeds, while other Alliance races must earn the trust and goodwill of Stormwind before purchasing and handling their horses.",al={"palomino rep requirement","who can ride palomino"}},{q="Is the palomino a common military mount?",a="While heavy pinto and armored chargers often accompany knightly detachments, palominos are prized primarily for swift travel, scouting, and dependable road passage throughout the southern kingdoms.",al={"is palomino military","stormwind army horses"}},{q="Does this involve exotic magical beasts?",a="No. The palomino is an ordinary, well-bred mortal steed raised through patient animal husbandry in the fertile meadows of Elwynn.",al={"is palomino magical","magic horse elwynn"}}},ang={["race:Human"]="The horse breeders of Elwynn take pride in their stock, providing their fellow humans with swift and reliable mounts suited for patrols along the kingdom's borders.",["faction:Alliance"]="Stables throughout Elwynn supply the backbone of Alliance courier and ground transit across Azeroth's southern territories."},kw={"bridle","elwynn","exchange","horse","mount","palomino","stables","stormwind"},rel={"zone:elwynn"},m={level="1",faction="Alliance",id=7678},src={"Palomino Exchange"}}
E["quest:783"] = {t="quest",n="A Threat Within",z="elwynn",s="A Threat Within marks the beginning of service for defenders answering Stormwind's call in Northshire Valley. Directed into Northshire Abbey to meet Marshal McBride, fresh volunteers discover that the kingdom's military is spread thin abroad, leaving local garrisons unable to handle domestic troubles without civilian aid.",h="A Threat Within marks the beginning of service for defenders answering Stormwind's call in Northshire Valley.",sec={{t="A Kingdom Stretched Thin",b="Northshire Valley was once a quiet retreat dedicated to prayer, farming, and monastic study. Today, it stands as the first line of defense against domestic unrest in Elwynn Forest. Stormwind's regular military forces have been widely deployed across distant fronts, leaving the capital's heartlands dangerously understaffed. With few official soldiers stationed locally, the Stormwind Guard must recruit any willing volunteer who arrives at the abbey gates.",sp=0},{t="The Marshal's Call",b="Inside Northshire Abbey, Marshal McBride coordinates the valley's defenses amidst growing regional pressures. While foreign perils threaten the Alliance from afar, lawless bandits, infesting vermin, and subterranean pests exploit the power vacuum right on the kingdom's doorstep. Answering this summons draws recruits into immediate martial service, beginning with clearing the abbey's immediate perimeter before confronting the deeper rot taking root across Elwynn.",sp=0}},faq={{q="What is the purpose of this quest?",a="It serves as the introductory summons for newly arrived recruits in Northshire Valley. You are instructed to walk inside Northshire Abbey and report directly to Marshal McBride to join the local defense effort.",al={"threat within quest","what is this quest","northshire intro quest"}},{q="Who is Marshal McBride?",a="Marshal McBride is the senior officer of the Stormwind Guard stationed at Northshire Abbey. He oversees the valley's defense, coordinating recruits and handing out assignments to curb threats emerging in the immediate countryside.",al={"marshal mcbride","who is mcbride","abbey commander"}},{q="Why is Stormwind recruiting volunteers instead of sending regular soldiers?",a="Stormwind's standing armies have been deployed abroad on distant campaigns to protect Alliance interests. This heavy commitment overseas leaves heartland garrisons critically understaffed, forcing local commanders to rely on newly arrived adventurers and volunteers to defend their own homes.",al={"why volunteers","where are the guards","why is stormwind understaffed"}},{q="What threats are currently plaguing Northshire Valley?",a="The valley faces simultaneous pressures: aggressive kobolds infesting the nearby mines and hills, diseased or predatory pests bothering the surrounding vineyards, and organized groups of brigands and outlaws taking advantage of the depleted local garrison.",al={"valley threats","what is attacking northshire","northshire problems"}},{q="Where does this assignment lead next?",a="Reporting to Marshal McBride opens several immediate tasks around Northshire, directing recruits to clear kobold incursions in the hills, aid local farmers and workers, and investigate the growing presence of organized bandits.",al={"next quest","what comes after threat within","mcbride follow up"}},{q="Why is Northshire Abbey being used as a military command post?",a="Though Northshire Abbey is a holy site of study and faith, its fortified stone walls and central location make it the only practical base of operations in the valley. As local authority strained, the Stormwind Guard set up administrative command directly within its halls.",al={"why military in abbey","northshire church military","holy abbey soldiers"}}},ang={["race:Human"]="As Northshire is the starting valley for human defenders, answering Marshal McBride's summons represents your first official pledge to protect your homeland and the Kingdom of Stormwind.",["faction:Alliance"]="The quest underscores the strain facing the Grand Alliance: maintaining military commitments across distant territories leaves even the most secure core lands vulnerable to internal collapse."},kw={"a threat within","abbey","elwynn forest","marshal mcbride","northshire","recruitment","stormwind guard","volunteers"},rel={"npc:marshal-mcbride","zone:elwynn","topic:stormwind-guard","topic:stormwind-kingdom","topic:alliance"},m={level="1",faction="Alliance",id=783},src={"A Threat Within"}}
E["quest:8026"] = {t="quest",n="Redeem iCoke Prize Voucher",z="elwynn",s="Redeem iCoke Prize Voucher is an unusual promotional turn-in tied to regional prize vouchers across Azeroth. It directs travelers to contact select merchants and handlers scattered across both Alliance and Horde lands to redeem promotional prize tokens.",h="Redeem iCoke Prize Voucher is an unusual promotional turn-in tied to regional prize vouchers across Azeroth.",sec={{t="A Curious Promotion",b="Across both continents, select regional merchants and couriers stand ready to inspect curious vouchers from distant lands. Whether visiting Antonia Dart in Elwynn Forest, Bethina in Teldrassil, Tresa MacGregor in the Wetlands, Nyx Bloodrage in Durotar, Hovrak Gutrender in Silverpine Forest, or Rygal Rocknell in Desolace, adventurers find a peculiar network of trade representatives offering to trade stamped vouchers for rare trinkets.",sp=0},{t="Cross-Continental Handlers",b="The widespread presence of handlers across both Kalimdor and the Eastern Kingdoms makes this errand uniquely agnostic of faction lines. Representatives embedded within small frontier settlements or starting territories were tasked with processing vouchers directly, bringing oddities and exotic companions into the hands of wandering heroes regardless of allegiance.",sp=0}},faq={{q="What is the iCoke Prize Voucher quest?",a="It is a promotional turn-in quest that allows players carrying a specific prize voucher to redeem it with selected handlers located in various outposts across Azeroth.",al={"icoke prize voucher","what is this quest","coke quest"}},{q="Where can Alliance players turn in the voucher?",a="Alliance heroes can take the voucher to Antonia Dart in Elwynn Forest, Bethina in Teldrassil, or Tresa MacGregor in the Wetlands.",al={"alliance turn in","who takes the voucher alliance","antonia dart voucher"}},{q="Where can Horde players turn in the voucher?",a="Horde adventurers can complete the redemption by speaking with Nyx Bloodrage in Durotar, Hovrak Gutrender in Silverpine Forest, or Rygal Rocknell in Desolace.",al={"horde turn in","who takes the voucher horde","nyx bloodrage voucher"}},{q="What is required to complete the quest?",a="Completing the task requires bringing an authentic iCoke Prize Voucher item directly to any of the designated redemption handlers.",al={"quest requirement","what item do i need","voucher turn in item"}},{q="Why is this quest available in so many zones?",a="To ensure that players of any race or faction could conveniently redeem their promotional item without having to travel across the entire world, handlers were stationed across several low-to-mid level zones in both Kalimdor and the Eastern Kingdoms.",al={"why so many turn ins","different quest givers","multiple locations"}},{q="Can players share this quest with each other?",a="Historically, adventurers have been able to pass the quest log entry directly to party members and allies across faction activities and battlegrounds, allowing curious travelers outside the promotion's original territories to hold the task.",al={"share quest","can i share icoke","battleground sharing"}}},ang={["faction:Alliance"]="Alliance citizens will find convenient redemption representatives stationed in Goldshire's vicinity in Elwynn Forest, outside Darnassus in Teldrassil, and within the Wetlands harbor.",["faction:Horde"]="Horde travelers can find handlers stationed in Durotar near the capital, within Silverpine Forest, or out in the barren frontier of Desolace."},kw={"antonia dart","bethina","hovrak gutrender","icoke","nyx bloodrage","promotion","rygal rocknell","tresa macgregor","voucher"},rel={"zone:elwynn","zone:durotar","zone:silverpine","zone:wetlands","zone:desolace","quest:940","topic:murloc"},m={["end"]="Bethina Antonia Dart Tresa MacGregor Nyx Bloodrage Hovrak Gutrender Rygal Rocknell",level="1",id=8026},src={"Redeem iCoke Prize Voucher"}}
E["quest:83"] = {t="quest",n="Red Linen Goods",z="elwynn",s="Red Linen Goods is an Elwynn Forest task offered by seamstress Sara Timberlain at the Eastvale Logging Camp. In need of fabric, she asks passing adventurers to hunt down local Defias bandits and strip them of their linen bandanas. In exchange, she uses the reclaimed cloth to tailor useful goods for travelers.",h="Red Linen Goods is an Elwynn Forest task offered by seamstress Sara Timberlain at the Eastvale Logging Camp.",sec={{t="Bandits and Burlap",b="While the low-level Defias brigands skirmishing in Northshire Valley make do with cheap burlap masks, the organized outlaws prowling greater Elwynn Forest sport finer crimson linen bandanas. To local craftsmen short on raw materials, these gang identifiers represent a surprisingly practical supply of usable cloth.",sp=0},{t="Salvage at the Camp",b="Operating out of the bustling Eastvale Logging Camp near the eastern border of Elwynn, Sara Timberlain is always on the lookout for workable textiles. By encouraging adventurers to thin out the Defias encampments hidden across the woods, she keeps her tailoring trade supplied while helping to curb the Brotherhood's brazen encroachment.",sp=0}},faq={{q="Who offers the Red Linen Goods quest?",a="Sara Timberlain, a resident seamstress located at the Eastvale Logging Camp in eastern Elwynn Forest, offers this quest.",al={"who gives red linen goods","red linen goods questgiver","sara timberlain quest"}},{q="What items are needed for Red Linen Goods?",a="You need to collect 6 Red Linen Bandanas, which can be looted from Defias gang members scattered throughout Elwynn Forest.",al={"what do i collect for red linen goods","items for red linen goods","bandanas needed"}},{q="Where can I find Defias bandits in Elwynn Forest?",a="Defias outlaws inhabit small campsites pocketed across Elwynn Forest, including locations around the Brackwell Pumpkin Patch, Stonefield Farm, and the woods surrounding Jerod's Landing.",al={"defias locations elwynn","where are defias camps","where to get red bandanas"}},{q="Why do the Elwynn Defias wear linen instead of burlap?",a="According to Sara Timberlain, low-ranking Defias in Northshire wear crude burlap masks, whereas the better-equipped members operating across broader Elwynn wear red linen, signaling a higher tier of organization and supply within the Brotherhood.",al={"why red linen","burlap vs linen defias","defias mask material"}},{q="Why does Sara Timberlain want bandit bandanas?",a="Sara is running low on fabric for her tailoring trade. She repurposes the cleanable linen from the Defias masks to sew practical goods for woodsmen and travelers at the logging camp.",al={"why collect bandanas","what does sara do with masks"}},{q="Where is the Eastvale Logging Camp located?",a="Eastvale Logging Camp is situated in far eastern Elwynn Forest, just north of the main road heading toward the bridge into Redridge Mountains.",al={"eastvale location","where is eastvale","how to find sara timberlain"}}},ang={["profession:Tailoring"]="Sara Timberlain's trade demonstrates the harsh realities of rural tailoring, where scarce bolts of fabric force local seamstresses to harvest cloth straight off the backs of regional bandits.",["faction:Alliance"]="Clearing out the Defias bandits infesting Elwynn's groves not only yields useful salvage for Eastvale, but actively weakens the Brotherhood's grip on the heartland of the kingdom."},kw={"burlap","defias brotherhood","eastvale logging camp","elwynn forest","red linen bandana","red linen goods","sara timberlain","tailoring"},rel={"npc:sara-timberlain","subzone:eastvale-logging-camp","zone:elwynn","topic:stormwind-kingdom"},m={start="Sara Timberlain",level="9",faction="Alliance",id=83},src={"Red Linen Goods"}}
E["quest:84"] = {t="quest",n="Back to Billy",z="elwynn",s="Back to Billy is a step in the ongoing feud between the Stonefield and Maclure families in central Elwynn Forest. Having gathered the ingredients for a pork belly pie, you carry the freshly baked dish back to young Billy Maclure to extract information about Bernice Stonefield's missing necklace.",h="Back to Billy is a step in the ongoing feud between the Stonefield and Maclure families in central Elwynn...",sec={{t="A Bitter Pie",b="The generational squabble between the Stonefields and the Maclures leaves little room for neighbourly grace. Auntie Bernice Stonefield reluctantly baked the requested pork belly pie only because young Billy Maclure refused to share what he knew about her family heirloom without it. Even as she hands over the warm pastry, her irritation is plain, bidding the courier to tell the Maclure boy she hopes he chokes on every bite.",sp=0},{t="A Boy's Bribe",b="Across the road at the Maclure Vineyards, Billy Maclure waits with an empty belly and a convenient lapse in memory. The exchange highlights the stubborn pettiness that divides the two homesteads, where even children learn to barter gossip and stolen trinkets for farm treats. With the pie delivered, Billy's memory conveniently clears up, setting up the search for the necklace's true location.",sp=1}},faq={{q="What is the purpose of this delivery?",a="Billy Maclure claimed to know where Auntie Bernice Stonefield's lost necklace was, but refused to talk until he was given a home-cooked pork belly pie. Delivering the pie fulfills his demand so he will reveal where the heirloom went.",al={"why deliver pie","what does billy want","back to billy goal"}},{q="Why is Auntie Bernice so upset with Billy?",a="The Stonefield and Maclure families have been locked in a bitter rural feud for years. Bernice resents having to cook a treat for a troublesome Maclure child just to recover an heirloom that went missing on their borders.",al={"why does bernice hate billy","stonefield maclure fight","why tell him to choke"}},{q="Where does Billy say the necklace actually is?",a="Once Billy devours the pie, he reveals that he did not keep the necklace. Instead, it fell into the hands of Goldtooth, a notorious kobold lurking in the Fargodeep Mine.",al={"where is the necklace","who took the necklace","goldtooth connection"},sp=1},{q="Where is Billy Maclure located?",a="Billy Maclure is located at the Maclure Vineyards, just south of the road in central Elwynn Forest, opposite the Stonefield Farm.",al={"billy maclure location","where is billy","find billy"}},{q="Who baked the Pork Belly Pie?",a="\"Auntie\" Bernice Stonefield baked the pie at the Stonefield Farm after you collected fresh chunks of boar meat from the nearby wilderness.",al={"who made the pie","pie cook"}},{q="Does this quest resolve the feud between the families?",a="No. Delivering the pie only satisfies Billy's personal bribe. The deep-seated animosity between the adult Stonefields and Maclures remains as bitter as ever.",al={"does the feud end","stonefield maclure peace"}}},ang={["faction:Alliance"]="Even peaceful Elwynn Forest is plagued by mundane disputes; dealing with squabbling human farmsteads is typical duty for travelers aiding the local folk.",["profession:Cooking"]="Pork belly pie is a quintessential Elwynn farmhouse comfort dish, made from the meat of the forest's roaming wild boars."},kw={"back to billy","bernice stonefield","billy maclure","elwynn forest","maclure vineyards","pork belly pie","stonefield farm","stonefield necklace"},rel={"npc:billy-maclure","npc:auntie-bernice-stonefield","quest:86","subzone:maclure-vineyards","zone:elwynn"},m={start="\"Auntie\" Bernice Stonefield",["end"]="Billy Maclure",faction="Alliance",id=84},src={"Back to Billy"}}
E["quest:85"] = {t="quest",n="Lost Necklace",z="elwynn",s="Lost Necklace is an introductory task in southern Elwynn Forest given by \"Auntie\" Bernice Stonefield. Suspecting theft by the rival clan's mischievous young boy, Bernice sends adventurers across the road to confront Billy Maclure and retrieve her missing heirloom.",h="Lost Necklace is an introductory task in southern Elwynn Forest given by \"Auntie\" Bernice Stonefield.",sec={{t="A Neighborly Accusation",b="The Stonefield and Maclure families share adjoining land in southern Elwynn Forest, but very little goodwill passes between them. When \"Auntie\" Bernice Stonefield discovers her cherished necklace is missing, she wastes no time pointing the finger at the youngest of the rival household. Convinced that young Billy Maclure snuck onto her farm and snatched the jewelry, the bitter widow asks any willing traveler to cross over to the vineyards, track down the boy, and demand its return.",sp=0},{t="A Boy with an Appetite",b="Confronting Billy Maclure at the neighboring vineyard quickly complicates the matter. Billy indignantly denies taking the necklace, claiming he is no thief. However, with a knowing grin, he hints that he might just know what actually became of the trinket—provided someone satisfies his rumbling stomach with a fresh pork pie first.",sp=1}},faq={{q="Who is Auntie Bernice Stonefield?",a="Auntie Bernice Stonefield is an elderly widow living on the Stonefield Farm in southern Elwynn Forest. She is deeply suspicious of the neighboring Maclure family, especially their troublemaking young son, Billy.",al={"who is auntie bernice","bernice stonefield","who gives lost necklace"}},{q="Did Billy Maclure actually steal the necklace?",a="Billy adamantly denies being a thief when confronted. While he did not take it himself, he admits he saw who or what did, though he refuses to share the secret until he is properly fed.",al={"is billy a thief","did billy steal it","did billy take the necklace"},sp=1},{q="Where can I find Billy Maclure?",a="Billy Maclure is typically found idling among the grapevines at the Maclure Vineyards, located just east across the road from the Stonefield Farm.",al={"billy maclure location","where is billy","find billy maclure"}},{q="Why do the Stonefields and Maclures dislike each other?",a="The two neighboring families have been embroiled in a bitter rural feud for years. Tensions run high over property, pride, and longstanding personal grudges, leading both sides to immediately suspect the worst of one another.",al={"family feud","stonefield maclure feud","why do they hate each other"}},{q="What happens after talking to Billy Maclure?",a="Billy insists that he is far too hungry to recall where the necklace went, sending you right back to Auntie Bernice to bake him a pork pie in exchange for the information.",al={"what next","after lost necklace","next quest"},sp=1},{q="Where does this quest take place?",a="The quest takes place entirely in southern Elwynn Forest, running back and forth between the Stonefield Farm and the adjacent Maclure Vineyards.",al={"quest zone","where is lost necklace"}}},ang={["faction:Alliance"]="For Alliance novices starting their careers in Elwynn Forest, settling petty disputes between the squabbling Stonefield and Maclure families is a quintessential taste of local frontier life.",["race:Human"]="The grudge between the Stonefields and the Maclures shows that not all strife in the Kingdom of Stormwind comes from Defias outlaws or gnoll warbands; old rural neighbor squabbles run just as deep."},kw={"bernice","billy","elwynn","farm","maclure","necklace","stonefield","vineyards"},rel={"npc:auntie-bernice-stonefield","npc:billy-maclure","quest:86","subzone:maclure-vineyards","zone:elwynn"},m={start="\"Auntie\" Bernice Stonefield",["end"]="Billy Maclure",faction="Alliance",id=85},src={"Lost Necklace"}}
E["quest:86"] = {t="quest",n="Pie for Billy",z="elwynn",s="Pie for Billy is an errand caught in the crossfire of the longstanding feud between Elwynn Forest's Stonefield and Maclure families. Young Billy Maclure refuses to give up information regarding Auntie Bernice Stonefield's missing necklace without a pork belly pie in exchange. Adventurers must hunt local boars to gather meat for Bernice to bake the demanded bribe.",h="Pie for Billy is an errand caught in the crossfire of the longstanding feud between Elwynn Forest's...",sec={{t="A Boy's Bribe",b="When approached regarding the theft of Auntie Bernice Stonefield's heirloom necklace, Billy Maclure exhibits none of the remorse an elder might hope for. Instead of returning the heirloom or confessing, the boy seizes an opportunity to indulge his appetite. He demands a freshly baked pork belly pie before he will utter a single word about who holds the necklace, knowing full well that Auntie Bernice is the finest cook in the valley.",sp=0},{t="Baking Through Bad Blood",b="The Maclures and Stonefields have traded insults, brawls, and accusations across the pumpkin patches for generations. Despite her deep indignation at feeding the rascal who stole her family jewelry, Auntie Bernice agrees to fire up her oven. In exchange for tender boar meat collected from the wild beasts roaming the adjacent pastures, she swallows her pride to appease the unruly youth and recover her prized possession.",sp=0}},faq={{q="Why does Billy want a pie before talking?",a="Billy Maclure is an opportunistic farm boy using his knowledge of Auntie Bernice's stolen necklace as leverage. Knowing Bernice makes exceptional pork belly pies, he refuses to reveal who has the heirloom until his appetite is satisfied.",al={"why billy wants pie","billy bribe pie","billy pork belly pie"}},{q="Why does Auntie Bernice agree to bake for a thief?",a="Auntie Bernice is furious about rewarding the very boy she believes snatched her heirloom necklace, but she sees no other way to get it back. She reluctantly agrees to bake the pie once supplied with boar meat, prioritizing the return of her property over pride.",al={"why does bernice bake","bernice stonefield pie reason","stonefield baking for maclure"}},{q="Where does the meat for the pie come from?",a="The meat comes from the wild boars foraging in the meadows and edges around the Stonefield and Maclure farms in Elwynn Forest.",al={"where to get meat","tender boar meat source"}},{q="What is the history between the Stonefields and Maclures?",a="The Stonefield and Maclure families are neighboring farmers who have maintained a bitter, petty rivalry for years, constantly suspecting each other of theft, vandalism, and bad-faith squabbling across their property lines.",al={"stonefield maclure feud","farm rivalry","maclure vs stonefield"}},{q="Did Billy actually steal the necklace?",a="Auntie Bernice accuses Billy directly, and while he dances around a straight confession, he clearly knows where the heirloom ended up and uses that secret to barter for food.",al={"did billy steal necklace","who took necklace","billy necklace thief"}},{q="What happens after Bernice gets the meat?",a="Once provided with the tender boar meat, Auntie Bernice bakes a pork belly pie for you to deliver back to Billy so he will finally disclose who has her necklace.",al={"next step after pie","what follows pie for billy"}}},ang={["profession:Cooking"]="Auntie Bernice notes that while wild boar meat can be tough and bland, proper spices and a slow simmer turn it into exceptional savory pie filling.",["race:Human"]="The squabble highlights the stubborn, insular rivalries that thrive among Elwynn's rural homesteaders just south of Stormwind's gates."},kw={"bernice stonefield","billy maclure","elwynn forest","lost necklace","maclure vineyards","pork belly pie","stonefield farm","tender boar meat"},rel={"quest:85","quest:84","npc:billy-maclure","npc:auntie-bernice-stonefield","zone:elwynn"},m={start="Billy Maclure",["end"]="\"Auntie\" Bernice Stonefield",faction="Alliance",id=86},src={"Pie for Billy"}}
E["quest:8646"] = {t="quest",n="Hammershout the Elder",z="elwynn",s="Elder Hammershout is an ancient spirit visited during the Lunar Festival, standing outside the gates of Stormwind in Elwynn Forest. He rewards travelers who pause to honor his people and show reverence for the venerable heritage of Azeroth's elder races. His presence serves as a reminder of ancient bonds even in the heart of human territory.",h="Elder Hammershout is an ancient spirit visited during the Lunar Festival, standing outside the gates of...",sec={{t="Honoring Ancient Blood",b="During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth, offering wisdom and blessings to any traveler who takes time to pay their respects. Elder Hammershout gathers just outside the great gates of Stormwind, watchful over the winding roads of Elwynn Forest. Though he stands near the heart of modern human civilization, his appearance reminds passing adventurers of a time when the world was shaped by the ancient races who walked the land long before the kingdoms of today rose to prominence.",sp=0},{t="Tokens of Ancestral Reverence",b="Greeting Elder Hammershout requires neither martial trials nor perilous oaths, but rather a simple acknowledgment of the past. He expresses quiet relief and gratitude when the current inhabitants of the realm still take time to pay homage to the olden races. In exchange for this act of memory and respect, the Elder bestows a ceremonial token upon travelers, symbolizing the enduring communion between the living generation and the spirits who came before.",sp=0}},faq={{q="Who is Elder Hammershout?",a="Elder Hammershout is an ancestral spirit who appears during the Lunar Festival. He represents the ancient lineages of Azeroth and stands near Stormwind to offer blessings and tokens to those who honor him.",al={"hammershout","who is hammershout","elder hammershout identity"}},{q="Where can Elder Hammershout be found?",a="Elder Hammershout is located in Elwynn Forest, stationed outside the grand gates of Stormwind along the main road leading into the forest.",al={"hammershout location","where is hammershout","hammershout elwynn"}},{q="Why does Elder Hammershout mention the 'olden races'?",a="His words reflect the Lunar Festival's celebration of antiquity and ancestor worship, honoring the ancient peoples and traditions that helped shape Azeroth long before the rise of modern settlements.",al={"olden races meaning","what does hammershout mean"}},{q="What token does Elder Hammershout offer?",a="He offers a Coin of Ancestry, a ceremonial token granted by the spirits of the Lunar Festival to those who seek out elders and pay their respects.",al={"hammershout reward","hammershout token","what does he give"}},{q="Can Horde adventurers speak with Elder Hammershout?",a="Yes. Ancestral spirits during the Lunar Festival transcend factional warfare, though Horde travelers must tread carefully given his location right outside the Alliance stronghold of Stormwind.",al={"can horde talk to hammershout","hammershout horde"}},{q="Is this encounter tied to an active holiday?",a="Elder Hammershout only manifests during the annual Lunar Festival, appearing temporarily to grant his blessings before fading back to the spirit realm.",al={"is hammershout always there","lunar festival elder"}}},ang={["race:Human"]="Standing outside the bastion of Stormwind, Hammershout reminds humans traversing the Elwynn woods to respect the deeper history of Azeroth that predates their modern kingdom.",["faction:Alliance"]="Alliance heroes leaving the safety of Stormwind find in Hammershout a reminder of reverence, peace, and the shared ancestral past of the world.",["faction:Horde"]="Reaching Hammershout offers a daring challenge for Horde pilgrims, requiring them to approach the heavily defended gates of Stormwind to honor the spirits."},kw={"ancestor","elder hammershout","elwynn forest","hammershout","lunar festival","olden races","stormwind"},rel={"zone:elwynn"},m={id=8646},src={"Hammershout the Elder"}}
E["quest:8649"] = {t="quest",n="Stormbrow the Elder",z="elwynn",s="Elder Stormbrow is one of the ancient spirits honored during the Lunar Festival, standing by the water near Goldshire. Travelers who seek out this elder pay homage to the ancient traditions and the olden races of Azeroth. In return for showing respect, the elder bestows a small token of remembrance.",h="Elder Stormbrow is one of the ancient spirits honored during the Lunar Festival, standing by the water near...",sec={{t="A Spirit in Goldshire",b="Elder Stormbrow manifests near the tranquil pond tucked just behind the smithy in Goldshire. While the town usually bustles with armored guards, tradesfolk, and weary adventurers heading into the forest, the arrival of this honored spirit brings a quiet pause. Standing beneath the peaceful canopy of Elwynn Forest, Stormbrow welcomes anyone willing to honor the long history of the realm.",sp=0},{t="Honoring the Olden Races",b="The Lunar Festival marks a time when the spirits of great ancestors return to walk among the living. Elder Stormbrow commends mortal travelers for taking the time to remember those who came before. In exchange for acknowledging the wisdom and legacy of the elder peoples, he grants his blessing and a commemorative coin to celebrate the season.",sp=0}},faq={{q="Where can I find Elder Stormbrow?",a="Elder Stormbrow stands right by the pond situated directly behind the blacksmith's forge in Goldshire, within Elwynn Forest.",al={"stormbrow location","where is elder stormbrow","goldshire elder"}},{q="Who is Elder Stormbrow?",a="Elder Stormbrow is an ancestral spirit who appears during the Lunar Festival, representing the revered elders of the olden races of Azeroth.",al={"who is stormbrow","stormbrow lore","elder stormbrow identity"}},{q="What is the purpose of visiting Elder Stormbrow?",a="Visiting Elder Stormbrow allows travelers to pay respects to the ancient ancestors during the festival. In return for honoring these traditions, he offers his greetings and a token of appreciation.",al={"why visit stormbrow","elder stormbrow quest","stormbrow the elder purpose"}},{q="Can Horde players speak to Elder Stormbrow?",a="While the Lunar Festival elders honor all who seek them out in peace, Goldshire is heavily guarded Alliance territory, making any visit by Horde travelers exceedingly perilous.",al={"horde stormbrow","can horde visit stormbrow"}},{q="What token does the Elder offer?",a="Elder Stormbrow offers a Coin of Ancestry, a traditional token of respect and remembrance shared by elders throughout the festival.",al={"stormbrow reward","what token","lunar coin stormbrow"}},{q="Why does Stormbrow mention the 'olden races'?",a="Stormbrow commends travelers for remembering that the current civilizations walk upon lands shaped by ancient peoples and enduring customs long before the modern kingdoms arose.",al={"olden races meaning","why olden races","stormbrow dialogue"}}},ang={["race:Human"]="For humans living in Elwynn, the presence of Elder Stormbrow serves as a reminder of ancient history beyond the walls and recent wars of Stormwind.",["faction:Alliance"]="Resting right in the heart of Elwynn Forest, Elder Stormbrow is one of the most accessible ancestral spirits for young Alliance adventurers passing through Goldshire."},kw={"ancestor","elder stormbrow","elwynn forest","forge","goldshire","lunar festival","token"},rel={"zone:elwynn","subzone:goldshire"},m={start="Elder Stormbrow",id=8649},src={"Stormbrow the Elder"}}
E["quest:87"] = {t="quest",n="Goldtooth",z="elwynn",s="Goldtooth is an Elwynn Forest quest that concludes the feud-sparking search for Auntie Bernice Stonefield's missing heirloom. After young Billy Maclure confesses where the necklace ended up, you must track down a thieving kobold lurking in the Fargodeep Mine.",h="Goldtooth is an Elwynn Forest quest that concludes the feud-sparking search for Auntie Bernice Stonefield's...",sec={{t="A Boy's Mischief",b="The search for Auntie Bernice Stonefield's lost family necklace begins as a sour border dispute between the feuding Stonefield and Maclure families. Bernice naturally suspected the rival family had taken it, but the culprit turns out to be Billy Maclure. While horsing around near the Fargodeep Mine, the young rascal ended up losing the trinket, hastily covering up his guilt by claiming he merely stumbled upon it before a creature snatched it away.",sp=0},{t="The Den Above the Mine",b="According to Billy, an unusually large, gleaming-fanged kobold scooped up the shiny keepsake and scurried off. Billy claims it ran back to a den above the mine, but the beast, named Goldtooth, actually lurks on the lower level of the Fargodeep Mine itself. Slaying the creature recovers Bernice's necklace, ending the neighborhood dispute and earning an old campaign keepsake left behind by Bernice's late husband.",sp=0}},faq={{q="Who stole Auntie Bernice's necklace?",a="Billy Maclure took it while messing around, though he claims he merely found and dropped it near the Fargodeep Mine. Before he could retrieve it, the kobold Goldtooth grabbed the shiny prize.",al={"who stole necklace","who took the necklace","did maclures steal necklace"},sp=1},{q="Where can Goldtooth be found?",a="Goldtooth lurks within the Fargodeep Mine itself, on its lower level, rather than in the den above the mine that Billy describes.",al={"goldtooth location","where is goldtooth","find goldtooth"}},{q="What kind of creature is Goldtooth?",a="Goldtooth is an oversized kobold notable for the gleaming golden fang that earned him his moniker, drawn like all his kin to bright, shiny trinkets.",al={"what is goldtooth","is goldtooth a kobold"}},{q="How does this quest tie into the Maclure and Stonefield feud?",a="The Stonefields and Maclures are bitter rivals who suspect each other of any petty theft or misfortune. Auntie Bernice assumed the Maclures stole her necklace out of spite, though tracking it down reveals it was simply Billy's carelessness.",al={"stonefield maclure drama","why does bernice blame billy"},sp=1},{q="What is the reward from Auntie Bernice?",a="Auntie Bernice gives you an old, supposedly lucky keepsake that belonged to her late husband, who tragically forgot to take it along on his final military campaign.",al={"bernice reward","what do you get"}},{q="What quest leads directly into Goldtooth?",a="The quest Back to Billy leads directly into Goldtooth, where you bribe Billy Maclure with pork so he will finally confess what happened to the necklace.",al={"goldtooth prereq","quest before goldtooth"}}},ang={["race:Human"]="Resolving this squabble helps smooth over local friction between two of Elwynn's oldest farming families, while dealing with the persistent kobold vermin that plague the realm."},kw={"bernice","billy","fargodeep","goldtooth","kobold","maclure","necklace","stonefield"},rel={"quest:84","npc:billy-maclure","npc:auntie-bernice-stonefield","subzone:fargodeep-mine","subzone:stonefield-farm","topic:kobold","quest:62","zone:elwynn"},m={start="Billy Maclure",["end"]="\"Auntie\" Bernice Stonefield",faction="Alliance",id=87},src={"Goldtooth (quest)"}}
E["quest:92124"] = {t="quest",n="Book Inventory",z="elwynn",s="Book Inventory is an introductory task in Northshire Abbey given by Brother Paxton. Frustrated by misplaced and missing tomes, the abbey's librarian sends young adventurers to find his assistant, Daniel, and take stock of the abbey library's archives. However, Daniel's notorious habit of daydreaming about local tradeskills makes getting a straight answer far more difficult than Paxton would like.",h="Book Inventory is an introductory task in Northshire Abbey given by Brother Paxton.",sec={{t="A Librarian's Frustration",b="Northshire Abbey preserves some of the oldest scholarly works, spiritual writings, and historical records left standing in the Kingdom of Stormwind after the First War. Managing these volumes falls upon Brother Paxton, a meticulous monk who takes great pride in the abbey's collection. Lately, books have gone missing from the shelves, threatening Northshire's archival peace. Paxton needs a clear inventory to understand how widespread the loss really is, but he lacks the patience to chase down his daydreaming helper.",sp=0},{t="Daniel's Straying Interests",b="Stationed inside the abbey library, Daniel serves as Brother Paxton's assistant, yet the youth's mind rarely stays on parchment and catalog numbers. Instead, Daniel is fascinated by the practical trades of Elwynn Forest—smithing, leatherworking, tailoring, and herbal craft. This preoccupation exasperates Paxton to no end, as every inventory task inevitably leads to the assistant rambling about local crafters rather than locating lost scriptures.",sp=0}},faq={{q="Who is Brother Paxton?",a="Brother Paxton is a monk of Northshire Abbey who tends to the abbey's extensive collection of books, scriptures, and historical scrolls. He is quick to lose his temper when books go missing or when his helpers shirk their duties.",al={"brother paxton","who gives book inventory","paxton elwynn"}},{q="Who is Daniel?",a="Daniel is Brother Paxton's young assistant stationed in the library of Northshire Abbey. Though tasked with organizing books and conducting inventories, he is easily distracted by his passion for tradeskills and professions across Elwynn Forest.",al={"who is daniel","paxton assistant","daniel northshire"}},{q="Why are books missing from Northshire Abbey?",a="Northshire Abbey has faced recent unrest and upheaval, leaving its halls busy and disrupted. Between misplaced volumes and possible theft, Brother Paxton needs an accurate count to determine the extent of the loss.",al={"why are books missing","missing books northshire","lost books abbey"}},{q="Where can Daniel be found?",a="Daniel is located inside Northshire Abbey, specifically studying among the shelves and desks of the abbey library.",al={"where is daniel","daniel location","find daniel"}},{q="Why does Paxton call Daniel useless?",a="Paxton considers Daniel useless because the boy constantly neglects his archival duties. Instead of cataloging and shelving books, Daniel spends his hours daydreaming and talking about practical tradeskills.",al={"why does paxton hate daniel","daniel useless"}},{q="What tradeskills is Daniel interested in?",a="Daniel is fascinated by the various crafts practiced throughout Elwynn Forest, such as blacksmithing, leatherworking, and tailoring, preferring hands-on labor over dusty tomes.",al={"daniel tradeskills","what professions does daniel like"}}},ang={["race:Human"]="For young humans beginning their service at Northshire Abbey, balancing monastic scholarly duties with practical village life is a familiar struggle.",["class:Priest"]="Priests studying Northshire's sacred archives rely on order in the library to preserve holy scriptures and Church traditions."},kw={"book inventory","brother paxton","daniel","elwynn forest","library","northshire abbey","professions","tradeskills"},rel={"zone:elwynn","quest:344"},m={start="Brother Paxton",["end"]="Daniel",level="2",id=92124},src={"Book Inventory"},fv=true}
E["quest:94"] = {t="quest",n="A Watchful Eye",z="elwynn",s="A Watchful Eye is an Alliance quest issued by the wizard Theocritus from the Tower of Azora in Elwynn Forest. Having established a basic scrying link against his rival Morganth, Theocritus directs adventurers east into Redridge Mountains to plant an enchanted focus upon an ancient lion statue watching the Tower of Ilgalar.",h="A Watchful Eye is an Alliance quest issued by the wizard Theocritus from the Tower of Azora in Elwynn Forest.",sec={{t="A Rivalry Across the Border",b="From his tower in eastern Elwynn Forest, the mage Theocritus maintains a vigilant watch over dark spellcraft brewing in the nearby hills. His chief nemesis is Morganth, a vicious sorcerer of formidable power who has claimed the Tower of Ilgalar in the crags of Redridge Mountains. Seeking to uncover Morganth's sinister ambitions before they spill across the border, Theocritus developed the Eye of Azora to surveil the rogue wizard from a distance.",sp=0},{t="The Lion's Vigil",b="While visual scrying affords some information, it is not enough to divine Morganth's deeper schemes. Theocritus entrusts travelers with the Glyph of Azora, commanding them to trek to the shadow of the Tower of Ilgalar. There, keeping a lonely watch for decades, stands an Old Lion Statue. Setting the glyph into a worn depression at the statue's base awakens an arcane conduit, linking the stone back to Azora and allowing Theocritus to delve straight into his rival's mind.",sp=0}},faq={{q="Who is Theocritus?",a="Theocritus is a powerful Alliance wizard who resides atop the Tower of Azora in eastern Elwynn Forest. He dedicates his arcane studies to guarding the region against rogue magical threats, chief among them the renegade sorcerer Morganth.",al={"theocritus","tower of azora mage","who gives a watchful eye"}},{q="Who is Morganth?",a="Morganth is a malevolent, rogue human wizard who has made his stronghold in the Tower of Ilgalar in Redridge Mountains. He is the bitter rival of Theocritus, who fears the dark schemes Morganth is weaving against the surrounding territories.",al={"morganth","who is morganth","rival mage"}},{q="Where is the Old Lion Statue located?",a="The Old Lion Statue stands weathered on the ridges overlooking the Tower of Ilgalar, in the northeastern hills of Redridge Mountains. A shallow depression sits at its base, designed to receive magical foci like the Glyph of Azora.",al={"lion statue location","where is the statue","where to put glyph of azora"}},{q="What does the Glyph of Azora do?",a="The Glyph of Azora is an enchanted stone crafted by Theocritus. When socketed into the lion statue near the Tower of Ilgalar, it acts as an arcane listening post and mind-probing relay, letting Theocritus communicate through the stone and study Morganth's thoughts.",al={"glyph of azora","what is the glyph"}},{q="What is the Tower of Ilgalar?",a="The Tower of Ilgalar is a tall, isolated stone spire set high in the crags of northeastern Redridge Mountains. A mage tower, it is currently occupied and defended by Morganth and his servitors.",al={"tower of ilgalar","ilgalar"}},{q="What comes after placing the glyph?",a="Once the Glyph of Azora is fixed to the statue, Theocritus speaks through the stone and immediately offers the follow-up quest, Looking Further, as he begins unraveling Morganth's machinations.",al={"next quest","what after a watchful eye"}}},ang={["class:Mage"]="For practitioners of the arcane, this mission showcases long-distance divination and scrying relays, contrasting Theocritus's structured Elwynn academy methods with Morganth's illicit rogue sorcery.",["faction:Alliance"]="Neutralizing renegade human spellcasters like Morganth is vital to securing the border between Elwynn Forest and the embattled settlements of Redridge Mountains."},kw={"elwynn","glyph of azora","morganth","old lion statue","redridge","theocritus","tower of azora","tower of ilgalar"},rel={"quest:178","quest:248","quest:249","npc:theocritus","subzone:tower-of-ilgalar","zone:elwynn"},m={start="Theocritus",["end"]="Old Lion Statue",level="21",faction="Alliance",id=94},src={"A Watchful Eye"}}
E["quest:96607"] = {t="quest",n="The Great Outdoors",z="elwynn",s="The Great Outdoors is an introductory survival lesson offered by seasoned travelers to newly minted wanderers across Azeroth. By taking a moment to rest by a warm campfire, fledglings learn how staying well-rested and prepared keeps an adventurer alive beyond city walls. It marks the first step into mastering wilderness survival and specialized field camps.",h="The Great Outdoors is an introductory survival lesson offered by seasoned travelers to newly minted wanderers...",sec={{t="Lessons of the Trail",b="No matter how sharp your blade or potent your magic, the wilds of Azeroth quickly whittle down anyone who neglects the basics of survival. Seasoned wanderers stationed near roadside clearings offer this simple lesson to travelers setting out from their home valleys. Taking time to rest by a campfire does more than ease sore boots—it settles the mind and readies the spirit for the harsh road ahead. Only those who master the discipline of regular rest and preparation stand a chance of surviving long enough to claim fortune and glory.",sp=0},{t="A Home Away from Home",b="Once an adventurer grasps the value of a crackling fire and proper rest, the instructors point them directly toward town tradesfolk. A camp in the field is rarely complete with just an ember and a bedroll; survival requires practical crafts. Whether forging replacement rivets, cooking trail rations, or stitching torn gear under the stars, every profession provides unique camp fixtures to turn a barren hillside into a self-sufficient outpost.",sp=0}},faq={{q="Who offers this lesson to new wanderers?",a="A variety of veteran travelers offer this guidance depending on where you are. In Elwynn Forest, the seasoned wanderer Sam Sarsaparilla steps up, while elsewhere figures such as Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof, and Raan Wildwind share their wilderness experience.",al={"who gives the great outdoors","who starts the great outdoors","quest giver great outdoors"}},{q="What is the purpose of sitting by the campfire?",a="Sitting quietly by a blazing campfire lets an adventurer catch their breath and gain a Boosted Rest effect. Taking deliberate downtime in the field is essential for keeping your strength up during long expeditions across the wilds.",al={"why sit by the fire","what does campfire do","boosted rest buff"}},{q="Where does this training lead next?",a="Once you finish resting by the fire, your mentor directs you to nearby settlements to learn practical tradeskills. From there, you begin learning Camping 101: Cooking as well as specific field camping lessons tailored to whatever profession you choose to pursue.",al={"what comes after great outdoors","great outdoors next quest","camping quests"}},{q="Can Horde adventurers undertake this lesson as well?",a="Yes. Surviving in the harsh wilds is a necessity regardless of allegiance. Veteran instructors from both the Alliance and the Horde—such as Brakk, Eleanor Shackleton, and Kaga Wildhoof—teach the exact same fundamental campcraft to their faction's initiates.",al={"is this alliance only","horde great outdoors","can orcs do this quest"}},{q="Why do the instructors tell you to speak with trade trainers?",a="Survival requires more than just sitting by flames; an adventurer needs self-reliance. Tradeskill trainers teach you how to craft specialized camp fixtures that let you ply your trade, whether that is cooking trail rations, mending armor, or brewing remedies under the open sky.",al={"why learn professions","camp fixtures trade trainers","profession camp connection"}},{q="What prior experience is expected before taking this quest?",a="Adventurers typically receive this lesson directly following 'The Adventurer', once they have proved their basic ambition and stepped beyond their starter enclaves into the wider region.",al={"prerequisites for the great outdoors","how do i unlock great outdoors","before great outdoors"}}},ang={["profession:Cooking"]="Every wilderness camp starts with fire, making cooking the natural companion to outdoor survival. Following this lesson, master campers immediately direct you to trailside culinary instruction.",["faction:Alliance"]="In the safety of Elwynn Forest, human travelers learn these survival basics from experienced wayfarers before facing the harsher threats lurking in Westfall and Redridge.",["faction:Horde"]="Whether crossing the arid plains of Durotar or the windswept mesas of Mulgore, Horde survivalists instill firecraft and outdoor discipline into every young warrior."},kw={"adventurer","boosted rest","campfire","camping","eleanor shackleton","elwynn forest","sam sarsaparilla","survival","tradeskill"},rel={"quest:96627","quest:96658","npc:eleanor-shackleton","zone:elwynn"},m={start="Varies",level="6",faction="Both",id=96607},src={"The Great Outdoors (Forever)"},fv=true}
E["quest:96627"] = {t="quest",n="The Adventurer",z="elwynn",s="The Adventurer is a breadcrumb assignment given by Marshal McBride in Northshire Valley. Recognising your early competence, McBride directs you beyond the cloistered abbey grounds toward Goldshire to look into a newcomer named Sam Sarsaparilla.",h="The Adventurer is a breadcrumb assignment given by Marshal McBride in Northshire Valley.",sec={{t="Leaving the Valley",b="Once recruits clear Northshire Valley of immediate threats like the local Defias and vermin, Marshal McBride begins looking down the road. With Stormwind's regular military presence stretched thin across the kingdom, the local garrison must rely on promising fighters to keep tabs on travelers and wanderers roaming the surrounding woods.",sp=0},{t="A Curious Newcomer",b="Rather than a military order or a bounty hunt, McBride tasks you with an unusual errand: checking up on a specific new adventurer spotted near Goldshire named Sam Sarsaparilla. The request serves as a transition out of Northshire's secluded valley into the wider, more perilous expanse of Elwynn Forest.",sp=0}},faq={{q="Who sends me on this task?",a="Marshal McBride, the commander of the Stormwind garrison stationed in Northshire Valley, offers this task once you have proven your mettle defending the abbey.",al={"quest giver","who gives the adventurer","marshal mcbride quest"}},{q="Who is Sam Sarsaparilla?",a="Sam Sarsaparilla is an adventurer lingering along the road near Goldshire. Marshal McBride catches wind of his presence and asks you to investigate what he is up to.",al={"sam sarsaparilla","who is sam","goldshire adventurer"}},{q="Where do I find Sam Sarsaparilla?",a="He is located down the main road leading out of Northshire toward the town of Goldshire in Elwynn Forest.",al={"sam sarsaparilla location","where is sam","find sam sarsaparilla"}},{q="Why does Marshal McBride care about a random adventurer?",a="Northshire remains on high alert against bandits and intruders. McBride prefers to keep a close eye on unfamiliar sellswords and wanderers passing through the region, utilizing dependable local talent to make initial contact.",al={"why send me","mcbride motives","why look for sam"}},{q="Do I need to leave Northshire Valley to finish this?",a="Yes. This task directs you through the southern gates of Northshire Valley and out onto the forest road leading toward Goldshire.",al={"outside northshire","does this leave northshire","go to goldshire"}},{q="Is this part of the normal Stormwind military chain of command?",a="While issued by an officer of Stormwind, McBride explicitly calls it an unusual task rather than standard guard duty, relying on your discretion as an independent protector rather than formal military protocol.",al={"stormwind military","is this standard duty","official business"}}},ang={["faction:Alliance"]="For fresh Alliance recruits finishing their service in Northshire, this marks the first official push out into the broader realm of Elwynn Forest.",["race:Human"]="Human defenders stepping out of Northshire Abbey take their first steps toward Goldshire, the bustling heart of Elwynn."},kw={"elwynn forest","goldshire","marshal mcbride","northshire","sam sarsaparilla","the adventurer"},rel={"npc:marshal-mcbride","subzone:goldshire","zone:elwynn"},m={start="Marshal McBride",["end"]="Sam Sarsaparilla",level="6",faction="Alliance",id=96627},src={"The Adventurer (Elwynn Forest)"},fv=true}
E["quest:96658"] = {t="quest",n="Camping 101: Cooking",z="elwynn",s="Camping 101: Cooking teaches fledgling adventurers the essential art of starting a fire and preparing sustenance in the wild. Found across the starting settlements of both the Alliance and Horde, this lesson introduces the campfire as the core anchor for any makeshift outdoor campsite.",h="Camping 101: Cooking teaches fledgling adventurers the essential art of starting a fire and preparing...",sec={{t="The Hearth of the Wilderness",b="To survive outside fortified walls, every traveler must know how to build a fire. Beyond boiling water and roasting meat, a basic campfire serves as the vital foundation for pitching a camp in uncharted terrain. Without an open flame to keep back the cold and dark, raising any proper shelter is impossible.",sp=0},{t="From Embers to Encampments",b="While apprentice cooks can only sustain a modest fire with minimal surroundings, mastering culinary arts unlocks the ability to kindle larger blazes capable of supporting more elaborate campsites. Furthermore, adventurers who branch out into other practical tradeskills discover ways to craft useful furnishings to complement their camps.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest directs new adventurers to seek out their local cooking trainer in nearby settlements, ensuring they learn basic cooking and how to light a campfire to anchor an outdoor campsite.",al={"why do camping 101","camping 101 cooking purpose","what does this quest do"}},{q="Who offers this quest to travelers?",a="Various experienced wilderness guides and adventurers offer this training across both factions, including Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof, and Raan Wildwind.",al={"who gives camping 101","camping quest giver"}},{q="Where do Alliance players turn this in?",a="Alliance adventurers report to trainers such as Tomas in Goldshire, Gremlock Pilsnor in Kharanos, or Zarrin in Dolanaar, depending on their home territory.",al={"where to turn in alliance","alliance cooking trainer"}},{q="Where do Horde players turn this in?",a="Horde adventurers can complete the training with Cook Torka in Razor Hill, William Pickman in Brill, or Pyall Silentstride in Bloodhoof Village.",al={"horde cooking trainer","where to turn in horde"}},{q="Can campsite size be expanded later?",a="Yes. As you increase your cooking skill, you can learn to light larger, more enduring fires that can support more camp furnishings in the wilderness.",al={"bigger campfire","improve camp"}},{q="Can other professions contribute to camping?",a="Yes. While cooking provides the campfire that anchors the camp, other tradeskill trainers offer ways to craft practical furnishings for your site if you have practiced their crafts.",al={"camping professions","campsite furnishings"}}},ang={["profession:Cooking"]="Cooking is the literal spark of camping life, providing both the vital sustenance to recover strength and the central campfire required to pitch an outdoor bivouac.",["faction:Alliance"]="Novices departing Northshire, Dun Morogh, or Teldrassil are guided to towns like Goldshire, Kharanos, and Dolanaar to learn self-reliance before braving the wilds.",["faction:Horde"]="Survival is second nature to the Horde, and young fighters in Durotar, Mulgore, and Tirisfal are pointed straight toward campfires in Razor Hill, Bloodhoof Village, and Brill."},kw={"campfire","camping 101","cooking","goldshire","shackleton","tomas","wilderness","zarrin"},rel={"subzone:goldshire","subzone:kharanos","subzone:razor-hill","subzone:bloodhoof-village","subzone:brill","subzone:dolanaar","npc:eleanor-shackleton","npc:zarrin"},m={start="Varies",level="6",faction="Both",id=96658},src={"Camping 101: Cooking"},fv=true}
E["subzone:brackwell-pumpkin-patch"] = {t="subzone",n="Brackwell Pumpkin Patch",z="elwynn",s="Brackwell Pumpkin Patch is an overrun farmstead in southeastern Elwynn Forest. Once home to the Brackwell family, the fields and cottage have been thoroughly seized by the Defias Brotherhood as an operational hideout. It serves as a meeting point for rogue conspirators and a staging ground for smuggling stolen gold.",h="Brackwell Pumpkin Patch is an overrun farmstead in southeastern Elwynn Forest.",sec={{t="A Bandit Haven",b="Situated southeast of the Stonefield homestead, the Brackwell farm was once a productive patch of Elwynn farmland. Today, the rightful owners have vanished without a trace, driven out or worse by the rising criminal tide. In their absence, the Defias Brotherhood claimed the farm's sturdy cottage and overgrown fields. The area functions as a safehouse and transfer post, where brigands regroup away from the watchful eyes of Goldshire's patrols. High-profile conspirators like Morgan the Collector use the isolated patch to receive shipments of illicitly gathered gold skimmed from the forest's mines.",sp=0},{t="Pigs and Dark Magic",b="The Defias are not the only troublemakers prowling the pumpkin vines. The Brackwells left behind an enormous prize-winning sow named Princess, who roams the patch and constantly terrorizes neighboring fields. Meanwhile, the farmhouse attic and outbuildings shelter dangerous personal dealings: bandit Erlan Drudgemoor seduced Surena Caledon, a rogue warlock apprentice who fled her master in Stormwind with a stolen bloodstone artifact, bringing the attention of dark practitioners down upon the hideout.",sp=1}},faq={{q="What happened to the Brackwell family?",a="Their exact fate remains unknown. When the Defias Brotherhood expanded their presence throughout southeastern Elwynn Forest, the Brackwells were either forced to flee or killed, leaving their pumpkin fields and farmhouse to the bandits.",al={"where are the brackwells","who lived at brackwell farm","brackwell family fate"}},{q="Why is the Defias Brotherhood using this farm?",a="The farm provides an out-of-the-way base close to the forest's borders. It allows the brotherhood to store plundered goods and coordinate smuggling operations, such as receiving shipments of stolen mine gold via couriers like Morgan the Collector, well away from the Stormwind Guard.",al={"why are defias here","what are bandits doing at the pumpkin patch","defias at brackwell"}},{q="Who is Princess?",a="Princess is an enormous, prize-winning pig originally raised by the Brackwells. Left behind when the farm fell, she has grown even larger by regularly breaking into the nearby Stonefield Farm to devour their prized crops.",al={"giant pig","princess pig","why is there a huge boar here"}},{q="Why do warlocks come to the pumpkin patch?",a="Surena Caledon, an apprentice of the Stormwind warlock trainer Gakin the Darkbinder, stole a powerful bloodstone choker and fled to the farm to hide alongside her lover, the Defias bandit Erlan Drudgemoor. Gakin sends novice warlocks here to execute her and recover the relic.",al={"warlock quest brackwell","surena caledon","gakin voidwalker quest"}}},ang={["class:Warlock"]="The farm's shack shelters the fugitive apprentice Surena Caledon, whose stolen bloodstone choker is needed to bind a voidwalker.",["faction:Alliance"]="The overrun patch marks one of the easternmost operational bases of the Defias inside Elwynn, directly threatening nearby farms and trade routes."},kw={"brackwell","defias","elwynn","erlan drudgemoor","morgan the collector","princess","pumpkin patch","surena caledon"},rel={"topic:defias-brotherhood","zone:elwynn","quest:123","quest:330","quest:1688","subzone:stonefield-farm","npc:marshal-dughan","npc:gakin-the-darkbinder"},src={"Brackwell Pumpkin Patch"}}
E["subzone:crystal-lake"] = {t="subzone",n="Crystal Lake",z="elwynn",s="Crystal Lake is a body of water lying just east of Goldshire in the heart of Elwynn Forest. While once a peaceful spot, its shores have been overrun by aggressive murlocs, turning it into a frequent hazard for local villagers and passing travelers.",h="Crystal Lake is a body of water lying just east of Goldshire in the heart of Elwynn Forest.",sec={{t="A Troubled Shore",b="Situated within walking distance of Lion's Pride Inn, Crystal Lake should be an idyllic rural retreat, but it is plagued by dangerous wildlife. Tribes of freshwater murlocs have claimed the shoreline and shallow shoals, attacking anyone who strays too close. Local alchemist William Pestle frequently hires passing adventurers to venture to the water's edge, directing them to defeat the creatures and harvest the crystal kelp they carry for use in his experimental concoctions.",sp=0},{t="The Silent Island",b="Resting quietly in the center of the lake is a tiny, isolated islet. Solitary and overgrown, it bears a simple grave marked with the tender inscription: 'Deeply missed, never forgotten.' The identity of whoever rests beneath the soil remains unrecorded in town ledgers, providing a somber mystery amidst the surrounding croaks of the shoreline murlocs.",sp=0}},faq={{q="Where is Crystal Lake located?",a="Crystal Lake lies directly east of the crossroads town of Goldshire in central Elwynn Forest, easily reached by walking past the outskirts of the village.",al={"crystal lake location","where is crystal lake","find crystal lake"}},{q="Why are murlocs gathered at Crystal Lake?",a="Like many waterways in Elwynn Forest, Crystal Lake provides a natural freshwater habitat where murlocs can nest and forage. Their numbers have swelled close to Goldshire due to the strained resources of Stormwind's local guard.",al={"why murlocs crystal lake","murloc problem goldshire","crystal lake murlocs"}},{q="Whose grave is on the island in the lake?",a="The grave marker on the central island reads only 'Deeply missed, never forgotten.' There is no name etched upon the stone, leaving the identity of the person buried there an enduring local mystery.",al={"crystal lake grave","tombstone on island elwynn","who is buried at crystal lake"}},{q="What do adventurers need from Crystal Lake?",a="William Pestle, an apothecary working out of Lion's Pride Inn in Goldshire, contracts adventurers to slay the murlocs along the shore to gather crystal kelp, which he requires for an invisibility potion.",al={"william pestle crystal lake","kelp quest crystal lake","invisibility potion elwynn"}}},ang={["profession:Herbalism"]="The freshwater shallows harbor Crystal Kelp, though it is primarily gathered directly from the resident murlocs who harvest it from the lake bed.",["faction:Alliance"]="The murloc infestation so close to Goldshire underscores how thinly stretched the kingdom's military has become in safeguarding its core territories."},kw={"crystal kelp","crystal lake","elwynn","goldshire","grave","jason mathers","murloc","william pestle"},rel={"zone:elwynn","subzone:goldshire","npc:william-pestle","topic:murloc","topic:stormwind-kingdom"},src={"Crystal Lake"}}
E["subzone:eastvale-logging-camp"] = {t="subzone",n="Eastvale Logging Camp",z="elwynn",s="Eastvale Logging Camp is a vital lumber settlement tucked into the eastern woodlands of Elwynn Forest, near the border with the Redridge Mountains. The camp supplies vital timber to Stormwind and surrounding settlements, but its operations are constantly hampered by hungry predators prowling the surrounding forests.",h="Eastvale Logging Camp is a vital lumber settlement tucked into the eastern woodlands of Elwynn Forest, near...",sec={{t="A Vital Operation Under Siege",b="Orders for timber constantly stream into Eastvale Logging Camp from buyers across the Kingdom of Stormwind, but meeting these strict deadlines is a harrowing task. The dense wilderness surrounding the camp swarms with vicious wolves and prowling bears that routinely chase lumberjacks away from their worksites, leaving valuable cut timber abandoned in the woods. Under the direction of Supervisor Raelen, the camp frequently relies on wandering adventurers to cull the encroaching beasts and retrieve fallen wood before deliveries fall fatally behind schedule.",sp=0},{t="Life on the Eastern Frontier",b="Despite its remote location, Eastvale is more than just a logging outpost. It features several residential dwellings and bustling horse stables where travelers can purchase fine mounts. The lumber trade here is closely tied to Stormwind nobility, including Lord Joran Tremaind, whose family maintains significant business interests in the camp's timber harvest. On a nearby hill overlooking the worksite sits the quiet manor of retired Marshal Haggard, the former leader of the Stormwind Guard, who withdrew to this rustic outpost to live out his retirement away from capital politics.",sp=0}},faq={{q="What is the main purpose of Eastvale Logging Camp?",a="Eastvale serves as the primary timber source in eastern Elwynn Forest for the Kingdom of Stormwind. Lumberjacks here work long hours under strict deadlines to fulfill heavy demands for wood from builders and nobles across the realm.",al={"why is eastvale here","what is eastvale","eastvale lumber role"}},{q="Why is the logging camp always hiring adventurers?",a="Dense woods surround the camp, and aggressive wild bears and prowling wolves constantly menace the workers. The attacks often force the woodcutters to flee, leaving chopped timber behind and putting timber orders at serious risk of missing shipment deadlines.",al={"eastvale problems","why do loggers need help","wolves at eastvale"}},{q="Who is Marshal Haggard?",a="Marshal Haggard is the retired former leader of the Stormwind Guard. He stepped down from service a few years ago and now resides in a peaceful estate on the bluffs overlooking the Eastvale Logging Camp.",al={"haggard","old man near eastvale","marshal haggard elwynn"}},{q="Can you buy mounts at Eastvale Logging Camp?",a="Yes. The logging camp features an active horse-breeding stable where Alliance adventurers can purchase riding horses and riding training.",al={"horse vendor eastvale","eastvale horses","buy mount elwynn"}}},ang={["race:Human"]="For humans of Stormwind, Eastvale provides the essential timber that continues to rebuild and maintain the kingdom's settlements.",["faction:Alliance"]="Eastvale Logging Camp is one of the premier locations in Elwynn Forest where Alliance members can purchase dependable Stormwind steeds."},kw={"eastvale","elwynn","haggard","horses","logging camp","lumber","raelen","timber","tremaind"},rel={"npc:supervisor-raelen","quest:1666","quest:52","quest:5545","zone:elwynn","topic:stormwind-kingdom","zone:redridge","subzone:goldshire"},src={"Eastvale Logging Camp"}}
E["subzone:echo-ridge-mine"] = {t="subzone",n="Echo Ridge Mine",z="elwynn",s="Echo Ridge Mine is a small excavation carved into the northwestern cliffs of Northshire Valley. Rich in stone and ore, it has recently fallen into the clutches of a destructive kobold infestation, halting Northshire's local operations.",h="Echo Ridge Mine is a small excavation carved into the northwestern cliffs of Northshire Valley.",sec={{t="A Foothold for Vermin",b="Tucked away in the hills above Northshire Abbey, Echo Ridge Mine was meant to supply the valley with useful stone and metal. Instead, opportunistic kobolds swarmed through the tunnels, driving out the local workers. Marshal McBride views the infestation as an unacceptable security risk to Northshire's safety and recruitment efforts, directing new recruits straight into the tunnels to cull their numbers and reclaim the site.",sp=0},{t="The Threat Beneath Northshire",b="The occupation of Echo Ridge is part of a broader pattern of kobold encroachment spreading across Elwynn Forest. If left unchecked in the northwestern ridge, these subterranean pests threaten to disrupt Northshire's peaceful training grounds and choke off crucial resources from reaching the abbey.",sp=0}},faq={{q="Why are kobolds in Echo Ridge Mine?",a="Kobolds are natural burrowers drawn to dark, mineral-rich tunnels. Sensing weak defenses, they overran Echo Ridge Mine to dig for treasures and claim the territory as their own.",al={"why kobolds here","echo ridge kobolds","who took the mine"}},{q="Who is trying to reclaim Echo Ridge Mine?",a="Marshal McBride at Northshire Abbey oversees efforts to clear the mine. He enlists newly arrived adventurers to scout the tunnels and cull the infesting vermin before they expand further into the valley.",al={"who wants echo ridge back","echo ridge quests","mcbride echo ridge"}},{q="Where is Echo Ridge Mine located?",a="The mine entrance sits in the northwestern corner of Northshire Valley, carved directly into the rocky hillside just north of the abbey vineyards.",al={"echo ridge location","where is echo ridge","find echo ridge mine"}}},ang={["profession:Mining"]="The shafts of Echo Ridge are rich in early mineral deposits, though any prospector seeking ore will have to fight through hordes of candle-bearing kobolds first.",["race:Human"]="For fresh recruits answering Stormwind's call, purging Echo Ridge Mine serves as an essential trial by fire to defend Northshire Abbey."},kw={"echo ridge","echo ridge mine","kobold","marshal mcbride","mine","northshire","northshire valley"},rel={"subzone:northshire-valley","npc:marshal-mcbride","quest:15","quest:21","topic:kobold","zone:elwynn"},src={"Echo Ridge Mine"}}
E["subzone:fargodeep-mine"] = {t="subzone",n="Fargodeep Mine",z="elwynn",s="Fargodeep Mine is an abandoned gold mine nestled in central Elwynn Forest, south of Goldshire. Once a productive source of wealth for the Kingdom of Stormwind, it has recently been overrun by a belligerent clan of kobolds.",h="Fargodeep Mine is an abandoned gold mine nestled in central Elwynn Forest, south of Goldshire.",sec={{t="A Lost Vein",b="Fargodeep Mine once provided steady gold to Stormwind's treasury, but the Kingdom's dwindling military presence in Elwynn has left outlying resources vulnerable. Kobolds quickly swarmed into the dark tunnels, establishing a bustling warren beneath the hills. Marshal Dughan and the local authorities in Goldshire view the infestation with deep concern, not only because of lost ore, but because the emboldened creatures now threaten nearby farmsteads like the Stonefield and Maclure holdings.",sp=0},{t="Depths of the Warren",b="The mine spans multiple levels, with the lower shafts winding deep beneath the forest floor. Kobold laborers and vermin scurry along the wooden scaffolds, fiercely guarding their scavenged wax and gold dust. Deeper within lurks Goldtooth, a particularly cunning kobold leader known for hoarding trinkets pilfered from unwary travelers and surrounding residents.",sp=0}},faq={{q="Why did Stormwind abandon Fargodeep Mine?",a="The mine was neglected as Stormwind's military stretched thin across southern lands. With town guards focused on protecting Goldshire and the main roads, the subterranean dig site was left unguarded, allowing kobolds to move in and fortify the tunnels.",al={"why abandoned","why did humans leave fargodeep","who owned fargodeep mine"}},{q="Why are the kobolds here so dangerous to local farmers?",a="Fargodeep Mine lies right between the Stonefield and Maclure family farms. The kobolds venture out from the tunnels to steal livestock, tools, and personal belongings, harassing anyone who wanders near the mine's entrance.",al={"why are kobolds a problem","kobold threat","stonefield kobolds"}},{q="Who is Goldtooth?",a="Goldtooth is a prominent kobold who nests deep within the lower shafts of Fargodeep Mine. He is notorious for snatching Auntie Bernice Stonefield's prized family necklace.",al={"goldtooth","who is goldtooth","goldtooth location"}},{q="Why do people in Goldshire want items from the mine?",a="Local merchants and townsfolk see opportunity in clearing the pests: Remy 'Two Times' buys up salvaged gold dust, the alchemist William Pestle uses kobold candle wax for reagents, and Marshal Dughan needs the infestation monitored to safeguard Elwynn.",al={"fargodeep quests","why gather candles","gold dust"}}},ang={["profession:Mining"]="Though infested with pests, the rocky tunnels of Fargodeep remain rich in accessible copper veins for fledgling miners.",["faction:Alliance"]="Clearing the vermin out of Fargodeep Mine is vital for securing the supply lines and farmlands immediately surrounding Goldshire."},kw={"candles","elwynn","fargodeep","fargodeep mine","goldshire","goldtooth","kobold","marshal dughan","remy two times"},rel={"zone:elwynn","npc:marshal-dughan","quest:62","quest:87","quest:47","quest:60","topic:kobold"},src={"Fargodeep Mine"}}
E["subzone:forest-s-edge"] = {t="subzone",n="Forest's Edge",z="elwynn",s="Forest's Edge is a wooded wedge of land along the southwestern frontier of Elwynn Forest, flanked by rivers leading toward Westfall. Guarded to the north by Westbrook Garrison, this untamed area has become dangerously overrun by riverpaw gnolls under the command of the notorious Hogger.",h="Forest's Edge is a wooded wedge of land along the southwestern frontier of Elwynn Forest, flanked by rivers...",sec={{t="A Contested Frontier",b="Tucked southwest of Stormwind City between Mirror Lake Orchard and the rivers bordering Westfall, Forest's Edge forms a natural peninsula of woodland. Despite its proximity to Westbrook Garrison, the Stormwind army's thin ranks have left the area vulnerable to wild beasts and raiding parties. Wandering boars roam among the trees and along the riverbanks, but the true menace is the concentration of Riverpaw gnolls who have made these woods their staging ground.",sp=0},{t="Hogger's Stronghold",b="In the southern reaches of Forest's Edge rises a prominent hill that serves as the den of Hogger, a massive and brutal gnoll chieftain. With a sizable bounty placed on his head by the authorities at Westbrook Garrison, Hogger directs his pack in harassing travelers and raiding nearby farms, turning what could be a peaceful timberland into a lethal proving ground for young Alliance adventurers.",sp=0}},faq={{q="Where exactly is Forest's Edge?",a="Forest's Edge is located in the southwestern corner of Elwynn Forest. It sits south of Westbrook Garrison, bordered by Mirror Lake Orchard and the waterways that lead into Westfall.",al={"forests edge location","where is forests edge","forest edge map"}},{q="Why is this area so dangerous?",a="A large and aggressive pack of Riverpaw gnolls has claimed the woods, threatening travel along the southwestern border. The biggest threat is their chieftain, Hogger, an exceptionally vicious gnoll who commands the southern hill.",al={"why dangerous forests edge","what is at forest edge","forests edge threats"}},{q="Who is Hogger?",a="Hogger is a notorious, powerful gnoll leader responsible for violent attacks on Elwynn's borders. The officers at Westbrook Garrison have posted an active bounty for his huge pelt, warning adventurers not to face him alone.",al={"hogger lore","who is hogger","hogger info"}},{q="Why hasn't Westbrook Garrison cleared the area?",a="Stormwind's military is stretched remarkably thin across the kingdom. With unrest in Westfall and threats encroaching on all sides, the garrison lacks the manpower to clear the gnoll camps, leaving the task to volunteer adventurers.",al={"why westbrook garrison not clearing","why stormwind guards not help","westbrook guards"}}},ang={["faction:Alliance"]="For recruits stationed in Elwynn Forest, clearing Forest's Edge and defeating Hogger is one of the first major trials proving their combat readiness to the crown.",["profession:Herbalism"]="The quiet riverbanks and shaded groves of Forest's Edge yield common woodland herbs, though gathering them often requires dodging aggressive gnoll patrols."},kw={"elwynn forest","forest's edge","forests edge","gnolls","hogger","nazferiti river","riverpaw","westbrook garrison"},rel={"subzone:westbrook-garrison","topic:gnoll","zone:elwynn","subzone:mirror-lake-orchard","zone:westfall","topic:stormwind-kingdom","zone:stormwind","quest:1861"},src={"Forest's Edge"}}
E["subzone:goldshire"] = {t="subzone",n="Goldshire",z="elwynn",s="Goldshire is a vital human crossroads town nestled in central Elwynn Forest, connecting Stormwind City with Westfall, Redridge, and the southern frontier. Rebuilt after its destruction in the First War, it serves as a bustling waystation anchored by the famous Lion's Pride Inn and defended by a hard-pressed contingent of the Stormwind Guard.",h="Goldshire is a vital human crossroads town nestled in central Elwynn Forest, connecting Stormwind City with...",sec={{t="A Crossroads Under Strain",b="Positioned where the king's highways meet, Goldshire has long been the civic and commercial heart of rural Elwynn. However, the town's bucolic charm masks escalating peril in Year 25 ADP. With Stormwind's military resources stretched thin and King Varian Wrynn mysteriously absent, Marshal Dughan must rely on passing adventurers rather than regular troops to contain surrounding threats. Aggressive Riverpaw gnolls push inward from the western border, while vicious murlocs claim the shores of Stone Cairn Lake and Crystal Lake, claiming the lives of royal guards and encroaching dangerously close to the town center.",sp=0},{t="Scars of the Great Wars",b="Goldshire's quiet atmosphere belies a brutal military history. Circa 75 BDP, the settlement repelled savage assaults during the Gnoll War. Decades later in the First War, Goldshire and Moonbrook were the final strongholds overwhelmed by the Orcish Horde as Warchief Blackhand cut off King Llane Wrynn I from his realm before sacking Stormwind Keep. The town was reduced to ash and remained barren until after the Second War, when the Alliance of Lordaeron under Supreme Commander Turalyon funded and organized its reconstruction to repatriate human refugees returning south.",sp=0}},faq={{q="Who is in charge of defending Goldshire?",a="Marshal Dughan of the Stormwind Guard commands local defense. Operating out of the center of town, he coordinates the garrison, though a lack of reinforcements forces him to hire freelance adventurers to handle border threats and monster bounties.",al={"who leads goldshire","goldshire marshal","who protects goldshire"}},{q="What threats are currently menacing the town?",a="Goldshire is pressured from multiple fronts: Riverpaw gnolls raiding eastward toward Westbrook Garrison, and bands of hostile murlocs infesting the waterways at Stone Cairn Lake and Crystal Lake. Local scouts warn that without intervention, skirmishes could reach the village streets.",al={"goldshire problems","why is goldshire in danger","enemies near goldshire"}},{q="What happened to Goldshire during the First War?",a="Goldshire was one of the last two human towns to fall before the sack of Stormwind. Warchief Blackhand destroyed it alongside Moonbrook to sever King Llane's supply lines, leaving the settlement in ruins until it was rebuilt following the Second War.",al={"goldshire first war","did goldshire fall to orcs","goldshire destruction"}},{q="Why is the Lion's Pride Inn so notable?",a="The Lion's Pride Inn is renowned as one of the most respectable and frequented alehouses in Azeroth. Situated at the junction of several regional highways, it serves as the primary meeting hall, resting spot, and training ground for travelers passing through the kingdom.",al={"lions pride inn","goldshire inn","tavern in goldshire"}}},ang={["race:Human"]="For humans fresh out of Northshire Abbey, Goldshire represents the first real taste of the kingdom beyond monastery walls, offering a sobering look at Stormwind's strained borders.",["faction:Alliance"]="Goldshire is an essential transit hub connecting the Alliance capital to the surrounding frontier lands of Westfall, Redridge, and Duskwood."},kw={"crystal lake","elwynn","goldshire","lion's pride inn","marshal dughan","murloc","riverpaw","stone cairn lake"},rel={"subzone:lion-s-pride-inn","npc:marshal-dughan","zone:elwynn","topic:stormwind-guard","quest:46","quest:11","subzone:crystal-lake","topic:first-war"},src={"Goldshire"}}
E["subzone:hall-of-arms-northshire"] = {t="subzone",n="Hall of Arms (Northshire)",z="elwynn",s="The Hall of Arms is the martial wing of Northshire Abbey, situated south of the Main Hall. Here, veteran instructors drill the newest recruits of the Stormwind Army in the arts of the sword, shield, and holy combat.",h="The Hall of Arms is the martial wing of Northshire Abbey, situated south of the Main Hall.",sec={{t="Groundwork of the Guard",b="While the clerics and scholars ponder ancient tomes across the courtyard in the Library Wing, the Hall of Arms rings with the clash of blunted steel and the heavy cadence of martial instruction. Positioned on the south side of Northshire Abbey, this chamber serves as the primary training station for raw human fighters and devout aspirants taking up arms for the Stormwind Army. Here, seasoned battle instructors and paladin mentors teach the basic postures, disciplines, and fundamentals required to defend Elwynn Forest against encroaching kobolds, Defias bandits, and orc raiders.",sp=0}},faq={{q="What is the purpose of the Hall of Arms?",a="The Hall of Arms serves as the initial martial training ground inside Northshire Abbey. It provides newly enlisted soldiers, mercenaries, and paladins with basic weapons training and combat techniques before they venture out into the wider kingdom.",al={"what is this room","hall of arms purpose","what happens here"}},{q="Who can be found inside this wing?",a="The wing is staffed by veteran warrior and paladin trainers who instruct fresh recruits in martial disciplines, shield work, and basic combat maneuvers on behalf of the Stormwind Army.",al={"who is in hall of arms","trainers hall of arms","who teaches here"}},{q="Where is the Hall of Arms located within Northshire Abbey?",a="The Hall of Arms lies on the southern side of Northshire Abbey, directly accessible from the central Main Hall and mirrored across the abbey courtyard by the Library Wing.",al={"hall of arms location","where is hall of arms","abbey layout"}}},ang={["class:Warrior"]="For human warriors stepping into service, this wing is where you receive your very first lessons in stance, weapon handling, and the martial discipline of the Stormwind Army.",["class:Paladin"]="The Hall of Arms balances holy devotion with martial grit, offering fledgling paladins their foundational instruction in wielding the Light alongside martial arms."},kw={"elwynn forest","hall of arms","northshire abbey","northshire valley","paladin trainer","stormwind army","warrior trainer"},rel={"subzone:northshire-abbey","subzone:main-hall-northshire","subzone:library-wing-northshire","subzone:northshire-valley","topic:stormwind-army","zone:elwynn","topic:stormwind-kingdom"},src={"Hall of Arms (Northshire)"}}
E["subzone:heroes-vigil"] = {t="subzone",n="Heroes' Vigil",z="elwynn",s="Heroes' Vigil is a quiet, sacred clearing situated on the central island within Stone Cairn Lake in eastern Elwynn Forest. Centered around a monument known as the Stone of Remembrance, it was dedicated to honor those who fell during the First War. Today, however, the shrine sits largely neglected by Stormwind and is overrun by dangerous renegade wizards.",h="Heroes' Vigil is a quiet, sacred clearing situated on the central island within Stone Cairn Lake in eastern...",sec={{t="A Forgotten Memorial",b="Erected after the First War, Heroes' Vigil centers upon the Stone of Remembrance, an inscribed stone circle meant to honor the soldiers and citizens slaughtered during the Old Horde's sacking of Goldshire and the surrounding valleys. Though once revered as a sacred bastion of faith and sacrifice, the vigil has gradually slipped from the attention of Stormwind's current rulers, leaving its hallowed grounds overgrown and unattended by the realm's soldiers.",sp=0},{t="Claimed by Renegades",b="Because the kingdom has left the island garrisoned by none, outcasts have seized the memorial. A cabal of rogue wizards now controls Stone Cairn Lake and the monument grounds, practicing wild and undisciplined magic away from the oversight of the Kirin Tor and the Academy of Arcane Sciences. The desecration is made all the more bitter by tragic casualties left near the stones, including the body of Henze Faulk, leaving travelers to wonder if the shrine will ever be restored to peace.",sp=0}},faq={{q="What is Heroes' Vigil?",a="Heroes' Vigil is a monument located on the island in Stone Cairn Lake in eastern Elwynn Forest. It consists of a stone ring and memorial dedicated to honoring the fallen victims of the First War.",al={"heroes vigil","what is heroes vigil","island shrine elwynn"}},{q="What does the Stone of Remembrance commemorate?",a="The Stone of Remembrance was placed in memory of the fallen citizens and defenders who perished when the orcish Horde sacked Goldshire and ravaged eastern Elwynn Forest during the First War.",al={"stone of remembrance","monument meaning","what is the stone of remembrance"}},{q="Who controls Heroes' Vigil today?",a="The island and the vigil have been occupied by hostile rogue wizards. These rogue spellcasters operate outside the law of the Kingdom of Stormwind and the oversight of established magical institutions.",al={"who is at heroes vigil","heroes vigil enemies","wizards on lake"}},{q="Why has Stormwind neglected the vigil?",a="With King Varian Wrynn missing and the realm stretched thin handling internal dissent, brigands, and monster incursions, remote shrines like Heroes' Vigil have been left undefended and largely forgotten by the ruling regency.",al={"why is it abandoned","why did stormwind forget it","forgotten shrine"}},{q="Who is Henze Faulk?",a="Henze Faulk is a fallen traveler whose lifeless body lies abandoned near the monument, an unfortunate testament to the ruthless hostility of the rogue wizards occupying the island.",al={"henze faulk body","who is the dead guy on the island"}}},ang={["race:Human"]="For humans of Stormwind, this sacred stone ring is a bitter reminder of the First War's blood price and the kingdom's modern failure to protect its own heritage.",["class:Mage"]="The renegade wizards encamping on these sacred grounds practice dangerous, unregulated arts without the discipline or sanction of the Academy of Arcane Sciences."},kw={"elwynn forest","henze faulk","heroes vigil","heroes' vigil","rogue wizards","stone cairn lake","stone of remembrance"},rel={"subzone:stone-cairn-lake","zone:elwynn","subzone:goldshire","topic:first-war","topic:stormwind-kingdom","topic:defias-brotherhood"},src={"Heroes' Vigil"}}
E["subzone:hogger-hill"] = {t="subzone",n="Hogger Hill",z="elwynn",s="Hogger Hill is a grassy knoll located in southwestern Elwynn Forest, just south of Westbrook Garrison. It serves as the bloody campsite and hunting ground for the notorious gnoll chieftain Hogger.",h="Hogger Hill is a grassy knoll located in southwestern Elwynn Forest, just south of Westbrook Garrison.",sec={{t="A Chieftain's Encampment",b="Situated near the border of Westfall south of Westbrook Garrison, this small hill marks the territory of Hogger, the ferocious Riverpaw gnoll chieftain. Littered with animal carcasses and the unfortunate remains of local thieves, the mound serves as a bloody monument to gnoll savagery. Its proximity to Stormwind's western road makes it a constant threat to travelers and local guardsmen alike.",sp=0}},faq={{q="Where is Hogger Hill located?",a="Hogger Hill lies in southwestern Elwynn Forest, directly south across the road from Westbrook Garrison and east of the river bordering Westfall.",al={"hogger hill location","where is hogger","find hogger hill"}},{q="Who controls this hill?",a="The hill is occupied by Hogger, a massive and vicious Riverpaw gnoll who terrorizes Elwynn Forest alongside his scavengers and warband.",al={"who lives here","hogger hill ruler","who is at hogger hill"}},{q="Why is there a dead thief on the hill?",a="The dead thief is a victim of Hogger's brutality. Even outlaws such as the Defias thieves operating in western Elwynn are preyed upon if they wander into gnoll territory.",al={"dead thief hogger hill","who died on hogger hill"}},{q="Why haven't the guards from Westbrook Garrison cleared this hill?",a="The guards at Westbrook Garrison are stretched thin dealing with Defias bandits and widespread gnoll incursions. While they post bounties for Hogger, they lack the manpower to assault his encampment directly.",al={"why don't guards kill hogger","westbrook garrison hogger"}}},ang={["faction:Alliance"]="For Alliance recruits training in Elwynn Forest, clearing this hill and confronting Hogger represents one of their first true trials of martial valor.",["race:Human"]="The encroachment of gnolls so close to human farms and the road to Sentinel Hill makes Hogger Hill a constant source of anxiety for the people of Stormwind."},kw={"dead thief","elwynn forest","gnoll","hogger","hogger hill","riverpaw","westbrook garrison"},rel={"subzone:westbrook-garrison","zone:elwynn","topic:gnoll","topic:alliance"},src={"Hogger Hill"}}
E["subzone:jasperlode-mine"] = {t="subzone",n="Jasperlode Mine",z="elwynn",s="Jasperlode Mine is an iron and mineral excavation in north-central Elwynn Forest that once supplied Stormwind City with vital resources. Today, the shafts are overrun by swarming kobolds and deadly giant spiders, leaving the resource-strapped kingdom unable to reclaim it.",h="Jasperlode Mine is an iron and mineral excavation in north-central Elwynn Forest that once supplied Stormwind...",sec={{t="A Lost Resource in Elwynn",b="Jasperlode Mine was historically one of Stormwind's most productive mining operations, providing steady mineral wealth alongside nearby Fargodeep. With the kingdom's military stretched thin defending against external threats and unrest, local garrisons have been unable to protect the shafts. Kobolds seized the opportunity to burrow inside, driving human miners out and stockpiling stolen gold and tallow candles.",sp=0},{t="Dangers in the Deep",b="The infestation within Jasperlode extends beyond simple vermin. In the deepest, darkest corridors beneath the timber supports, an aggressive colony of mine spiders has taken root. Led by a massive matriarch known to locals as Mother Fang, the spiders treat trespassing kobolds—and any unwary prospectors—as effortless prey, making any attempt to salvage the mine exceptionally hazardous.",sp=0}},faq={{q="Why is Jasperlode Mine overrun?",a="Stormwind's standing army is spread thin across the realm, leaving rural outposts like Goldshire short on manpower. Opportunistic kobolds quickly swarmed the dig sites once the human miners lost their guard protection.",al={"why are there kobolds","who controls jasperlode","why abandoned"}},{q="What is the difference between Jasperlode and Fargodeep?",a="Fargodeep Mine lies to the south near the Maclure and Stonefield farms, while Jasperlode sits to the north nestled in the foothills near the river. Both are major Elwynn mineral sites lost to the kobold infestation.",al={"jasperlode vs fargodeep","other elwynn mine"}},{q="What lurks in the back of the mine?",a="The deepest shafts are infested with predatory mine spiders led by a massive arachnid known as Mother Fang. Even the occupying kobolds avoid their webbed caverns.",al={"spiders in jasperlode","mother fang","what is at the bottom"}},{q="Why hasn't Marshal Dughan cleared the mine?",a="Marshal Dughan lacks the troops to mount a prolonged subterranean clearing. Between Defias river patrols, gnoll incursions, and garrison duties, the local militia must rely on traveling adventurers to scout and cull the threats inside.",al={"why no stormwind guard","dughan sending soldiers"}}},ang={["profession:Mining"]="Rich in mineral veins, Jasperlode remains an enticing target for prospectors willing to fight through kobold pickaxes and spider webs to stake a claim.",["faction:Alliance"]="Securing raw metal from Jasperlode is vital to maintaining Stormwind's equipment supplies during a time when the kingdom's borders face constant peril."},kw={"elwynn forest","fargodeep","gold dust","goldshire","jasperlode","kobold","marshal dughan","mother fang"},rel={"subzone:fargodeep-mine","zone:elwynn","npc:marshal-dughan","topic:kobold","quest:76","quest:47","quest:60","zone:stormwind"},src={"Jasperlode Mine"}}
E["subzone:jerod-s-landing"] = {t="subzone",n="Jerod's Landing",z="elwynn",s="Jerod's Landing is a modest river dock situated on the Elwynn Forest bank of the Nazferiti River. Currently seized by the Defias Brotherhood, the outpost serves as a clandestine transfer point for illicit shipments smuggled across the kingdom's waterways.",h="Jerod's Landing is a modest river dock situated on the Elwynn Forest bank of the Nazferiti River.",sec={{t="A Smuggler's Waypoint",b="Tucked away along the eastern waters of the Nazferiti River, Jerod's Landing provides river access connecting Elwynn Forest to neighboring territories. While originally an ordinary boat dock, the site has fallen firmly into the hands of the Defias Brotherhood. Under the watchful eye of a Defias dockmaster, outlaws utilize the dock as a hub to receive goods plundered from the Redridge Mountains, discreetly moving river cargo downstream toward holdings such as Klaven's Tower in Westfall.",sp=0},{t="Eyes in the Shadows",b="Because of its strategic placement on the river, Jerod's Landing has drawn the attention of SI:7, Stormwind's covert intelligence network. Operatives monitoring Defias operations view the landing as a vital link in the syndicate's supply lines, sending resourceful rogues to infiltrate the docks, pilfer river shipment ledgers, and unravel the wider conspiracy strangling the kingdom.",sp=1}},faq={{q="Where is Jerod's Landing located?",a="Jerod's Landing is located in eastern Elwynn Forest, resting along the western bank of the Nazferiti River, which marks the boundary between Elwynn and the Redridge Mountains.",al={"jerods landing location","where is jerod's landing","jerod dock map"}},{q="Who controls Jerod's Landing?",a="The landing has been occupied by members of the Defias Brotherhood, led by a Defias dockmaster who coordinates shipments with armed bandits guarding the waterside.",al={"who is at jerods landing","defias at jerods landing","jerod landing mobs"}},{q="What is the purpose of this dock for the Defias?",a="The Brotherhood utilizes the dock as a smuggling waystation to transport stolen goods and weaponry intercepted in the Redridge Mountains toward rogue strongholds like Klaven's Tower in Westfall.",al={"why do defias use jerods landing","defias river smuggling"}},{q="Why is SI:7 interested in Jerod's Landing?",a="Master Mathias Shaw and his intelligence agents track the flow of Defias contraband through this dock to expose the network linking Westfall, Elwynn, and Redridge.",al={"si7 jerods landing","rogue quest jerods landing"}}},ang={["class:Rogue"]="Rogues working on behalf of SI:7 are dispatched to Jerod's Landing to test their stealth, pickpocket the Defias dockmaster, and recover sensitive trade ledgers.",["faction:Alliance"]="The occupation of Jerod's Landing highlights how thoroughly the Defias have compromised the interior waterways linking Elwynn to Redridge right beneath Stormwind's nose."},kw={"defias dockmaster","jerod's landing","klaven's tower","mathias shaw","nazferiti river","smuggling","snatch and grab"},rel={"topic:defias-brotherhood","quest:2206","quest:2359","zone:elwynn","zone:redridge","zone:westfall","quest:65"},src={"Jerod's Landing"}}
E["subzone:library-wing-northshire"] = {t="subzone",n="Library Wing (Northshire)",z="elwynn",s="The Library Wing is the quiet, book-lined southern wing of Northshire Abbey in Elwynn Forest. It serves as a sanctuary for scholars, offering early instruction to fledgling priests and mages joining the defense of Stormwind.",h="The Library Wing is the quiet, book-lined southern wing of Northshire Abbey in Elwynn Forest.",sec={{t="Haven of Arcane and Divine Study",b="Branching south from the Main Hall of Northshire Abbey, the Library Wing houses dusty shelves, study lecterns, and quiet alcoves dedicated to intellectual and spiritual training. While martial recruits drill in the northern Hall of Arms, aspiring mages and priests gather here to grasp the fundamentals of the Arcane and the Holy Light. Currently, Priestess Anetta guides novice priests in matters of faith and healing, while Khelden Bremen teaches budding mages how to shape primal elemental energy.",sp=0}},faq={{q="Where is the Library Wing located?",a="The Library Wing occupies the southern section of Northshire Abbey, situated just off the Main Hall. It sits directly opposite the martial Hall of Arms.",al={"where is the library wing","how to find northshire library","library location northshire"}},{q="What is the purpose of this wing?",a="It serves as the academic and spiritual center of Northshire Abbey, dedicated to scholarly research, magical instruction, and prayer for recruits training to serve the Kingdom of Stormwind.",al={"why does northshire abbey have a library","library wing purpose"}}},ang={["class:Priest"]="Priestess Anetta resides here, offering fledgling priests their very first lessons in channeling the Holy Light to mend wounds and smite foes.",["class:Mage"]="Khelden Bremen instructs novice mages within these quiet halls, teaching the foundational disciplines of fire and frost."},kw={"elwynn forest","khelden bremen","library wing","mage trainer","northshire","northshire abbey","priest trainer","priestess anetta"},rel={"subzone:northshire-abbey","subzone:main-hall-northshire","subzone:hall-of-arms-northshire","subzone:northshire-valley","npc:priestess-anetta","npc:khelden-bremen","zone:elwynn","topic:stormwind-army"},src={"Library Wing (Northshire)"}}
E["subzone:lion-s-pride-inn"] = {t="subzone",n="Lion's Pride Inn",z="elwynn",s="The Lion's Pride Inn is the bustling tavern and community center of Goldshire in Elwynn Forest. Kept for generations by the Farley family, it serves as the primary resting place, meeting hall, and hiring house for travelers venturing just south of Stormwind City.",h="The Lion's Pride Inn is the bustling tavern and community center of Goldshire in Elwynn Forest.",sec={{t="Heart of Goldshire",b="Standing at the crossroads of Elwynn Forest, the Lion's Pride Inn is Goldshire's lively centerpiece. Operated by Innkeeper Farley under the tavern's traditional motto—'Rest and relaxation for the tired and cold'—the inn offers warm hearths, strong drinks, and rooms for weary adventurers fresh out of Northshire. Farley's family has managed the establishment with pride for generations, dating back through the reign of King Llane Wrynn I. Because Goldshire lies along the vital trade routes between Stormwind, Westfall, Redridge, and Duskwood, the tavern serves as an indispensable rallying point where town marshals, local crafters, and seasoned trainers gather to share news and contract passing mercenaries.",sp=0}},faq={{q="Who owns and runs the Lion's Pride Inn?",a="The inn is operated by Innkeeper Farley. His family has maintained and run the Lion's Pride Inn as an above-board business for generations, dating back to before the First War in the era of King Llane Wrynn I.",al={"innkeeper","who owns lions pride","who runs goldshire inn"}},{q="What services are available inside the inn?",a="Beyond food, drink, and lodging, the Lion's Pride Inn houses various class trainers, visiting merchants, and local quest givers seeking aid with the gnoll, kobold, and bandit problems troubling Elwynn Forest.",al={"trainers","what is inside","amenities"}},{q="Why is the inn such a central hub in Elwynn?",a="Positioned directly at the Goldshire crossroads just south of Stormwind, the inn is the primary rest stop for travelers moving between the capital, Westfall, and the Redridge Mountains. It is naturally the first major hub young adventurers visit upon departing Northshire Valley.",al={"why so popular","goldshire crossroads","importance of lions pride"}},{q="What is the motto of the Lion's Pride Inn?",a="According to Innkeeper Farley, the inn's founding motto is 'Rest and relaxation for the tired and cold.'",al={"inn motto","motto"}}},ang={["race:Human"]="For humans venturing forth from Northshire Abbey, the Lion's Pride Inn is their first encounter with the broader life and troubles of the kingdom outside monastery walls.",["faction:Alliance"]="As the main inn outside Stormwind's gates, it serves as a bustling waystation where Alliance travelers coordinate patrols and trade across the heartlands."},kw={"elwynn forest","farley","goldshire","goldshire inn","innkeeper farley","lion's pride inn","lions pride"},rel={"subzone:goldshire","npc:innkeeper-farley","zone:elwynn","topic:llane-wrynn-i","topic:stormwind-kingdom","topic:stormwind-army"},src={"Lion's Pride Inn"}}
E["subzone:maclure-vineyards"] = {t="subzone",n="Maclure Vineyards",z="elwynn",s="Maclure Vineyards is a sprawling agricultural estate in southern Elwynn Forest owned by the Maclure family. While known for producing grapes and wine for the kingdom of Stormwind, the farmstead is equally infamous for an ongoing, bitter feud with the neighboring Stonefield family.",h="Maclure Vineyards is a sprawling agricultural estate in southern Elwynn Forest owned by the Maclure family.",sec={{t="A Bitter Harvest",b="Nestled in the lush hills of southern Elwynn Forest, the Maclure Vineyards should be a peaceful haven of winecraft and farming. Instead, everyday labor is overshadowed by a vicious, long-standing rivalry with the Stonefields just down the road. Accusations of theft and bad blood run deep between the households, keeping tempers flaring even as common troubles—like hungry prowling boars and encroaching kobolds—threaten both homesteads.",sp=0},{t="A Forbidden Romance",b="Despite the fierce animosity between the two patriarchs, young love has crossed the boundary lines. Maybell Maclure and Tommy Joe Stonefield have fallen secretly in love, meeting in hidden groves away from their parents' suspicious eyes. Those passing through the vineyards often find themselves drawn into running secret messages, resolving petty grievances, and trying to help the young couple escape the shadow of their families' grudge.",sp=1}},faq={{q="Why are the Maclures and Stonefields fighting?",a="The rivalry is a long-standing rural feud built on years of mistrust, petty accusations, and stubborn pride. Neither family trusts the other an inch, blaming each other for lost goods and livestock, though neither has outright proof of foul play.",al={"maclure stonefield feud","why do they hate each other","family feud"}},{q="Who is Maybell Maclure?",a="Maybell is the daughter of the Maclure household. She has secretly fallen in love with Tommy Joe Stonefield, defying her family's bitter hatred of their neighbors in the hope of finding a way for them to be together.",al={"maybell","maclure daughter"}},{q="What threats do the vineyards face?",a="Aside from family disputes, the vineyards are plagued by ravenous wild boars trampling the crops and vines, as well as wandering kobolds raiding nearby fields from surrounding gold mines.",al={"vineyard dangers","boars at maclure"}},{q="What do the Maclures produce here?",a="The Maclure family cultivates grapevines to supply wine and fresh fruit to tavern-keepers and merchants throughout Elwynn Forest and Stormwind City.",al={"what grows here","maclure crops"}}},ang={["race:Human"]="For humans of Stormwind, the vineyard feud is a classic example of countryside stubbornness, reminding travelers that even within the heartland, neighbors often bicker over fences while larger perils loom.",["faction:Alliance"]="The estate serves as an important breadbasket and vineyard supplying the nearby settlements of Goldshire and Stormwind City with food and spirits."},kw={"boars","elwynn","gerard","maclure","maybell","stonefield","vineyard","wine"},rel={"zone:elwynn","topic:stormwind-kingdom","quest:114","quest:86","quest:85","quest:16","quest:330","topic:kobold"},src={"Maclure Vineyards"}}
E["subzone:main-hall-northshire"] = {t="subzone",n="Main Hall (Northshire)",z="elwynn",s="The Main Hall is the central entrance chamber of Northshire Abbey in Elwynn Forest. It serves as the primary crossroads connecting the abbey's grounds to its upper tower, the Hall of Arms, and the Library Wing. Here, newly recruited human adventurers report to receive their initial assignments in service of the Kingdom of Stormwind.",h="The Main Hall is the central entrance chamber of Northshire Abbey in Elwynn Forest.",sec={{t="Heart of the Abbey",b="Stepping through the grand archways of Northshire Abbey brings visitors directly into the Main Hall. As the building's central hub, it channels arriving trainees and clerical staff between the abbey's distinct wings: the martial Hall of Arms on one side, the scholastic Library Wing on the other, and the stairs rising into the abbey tower. The quiet sanctuary of the hall is tempered by the ongoing strife in the valley, as officers rally able-bodied newcomers to defend the kingdom's borders.",sp=0}},faq={{q="What is the purpose of the Main Hall?",a="The Main Hall serves as the central reception chamber and crossroads of Northshire Abbey. It directs recruits, priests, and visitors into the Hall of Arms, the Library Wing, and the abbey's upper tower.",al={"what is main hall","northshire main hall use"}},{q="Who directs new recruits here?",a="Officers and clerics of the Stormwind defense stationed in the Main Hall evaluate incoming adventurers, providing them with their first marching orders to clear out threats encroaching on the abbey's grounds.",al={"who gives quests here","abbey commander"}}},ang={["race:Human"]="For humans of the kingdom, the Main Hall of Northshire Abbey marks the beginning of their journey in service of Stormwind and the Holy Light."},kw={"abbey","elwynn","hall of arms","library wing","main hall","northshire","stormwind"},rel={"subzone:northshire-abbey","subzone:northshire-valley","subzone:hall-of-arms-northshire","subzone:library-wing-northshire","zone:elwynn"},src={"Main Hall (Northshire)"}}
E["subzone:mirror-lake"] = {t="subzone",n="Mirror Lake",z="elwynn",s="Mirror Lake is a picturesque body of water tucked into northwestern Elwynn Forest near an orchard. Fed by a gentle waterfall beneath the cliffs of Stormwind, its tranquil surface belies the dangers lurking on its shores, from prowling Defias bandits to strange disruptions in the local ley lines.",h="Mirror Lake is a picturesque body of water tucked into northwestern Elwynn Forest near an orchard.",sec={{t="A Troubled Idyl",b="Situated beneath the towering ramparts of Stormwind City, Mirror Lake ought to be a peaceful retreat for fishermen and weary travelers. Instead, brigands of the Defias Brotherhood stalk the surrounding orchards, making any prolonged stay perilous for passing locals. Worse still, mystical disturbances across Azeroth have begun warping the natural channels of arcane energy throughout the forest. The mages of the Wizard's Sanctum keep a cautious eye on the lake, sending practitioners to sample its currents and ensure that downstream communities are not poisoned by chaotic arcane runoff.",sp=0}},faq={{q="Why is Mirror Lake dangerous?",a="Despite its scenic appearance, the area around the lake is heavily prowled by Defias bandits who target travelers and farmers. Additionally, the recent fluctuations in regional magic have prompted concerns about the lake's water safety.",al={"is mirror lake safe","mirror lake enemies","defias mirror lake"}},{q="Why are mages studying Mirror Lake?",a="Massive magical conflicts across Azeroth have destabilized ley currents throughout Elwynn Forest and Stormwind. The Wizard's Sanctum dispatches initiates to sample the lake's water to test for unstable arcane residue before it can affect those who drink from it.",al={"wizard sanctum mirror lake","mirror lake quest","magic in mirror lake"}},{q="Where does the waterfall at Mirror Lake come from?",a="The waterfall cascades down from the high cliffs and waterways flanking the perimeter of Stormwind City, feeding the lake before the water winds through the Elwynn river system.",al={"mirror lake waterfall","water source mirror lake"}}},ang={["class:Mage"]="Initiates studying under the Wizard's Sanctum in Stormwind are dispatched here to gather water samples, learning firsthand how turbulent arcane channels can seep into the natural ecosystem.",["faction:Alliance"]="Though close to the capital's towering walls, the lake stands as a reminder of how thinly stretched the kingdom's guards are against Defias outlaws."},kw={"defias","elwynn forest","mirror lake","stormwind","waterfall","wizards sanctum"},rel={"zone:elwynn","quest:1861","zone:stormwind","topic:stormwind-kingdom"},src={"Mirror Lake"}}
E["subzone:mirror-lake-orchard"] = {t="subzone",n="Mirror Lake Orchard",z="elwynn",s="Mirror Lake Orchard is a quiet grove and cottage nestled on the southern banks of Mirror Lake in western Elwynn Forest. Once a peaceful homestead near Thunder Falls, it has fallen into the hands of Defias bandits who exploit the countryside while Stormwind's guards look elsewhere.",h="Mirror Lake Orchard is a quiet grove and cottage nestled on the southern banks of Mirror Lake in western...",sec={{t="A Grove Under Seizure",b="Tucked away near the cascading waters of Thunder Falls, Mirror Lake Orchard was once a productive farmstead benefiting from the clean waters of Mirror Lake. Today, the peaceful cottage sits overrun, claimed by opportunistic thieves and brigands flying the colors of the Defias Brotherhood. With the kingdom's military stretched thin and King Varian Wrynn missing, rural properties like this orchard have become easy pickings for outlaws looking to secure hideouts across the Elwynn countryside.",sp=0}},faq={{q="Who controls Mirror Lake Orchard right now?",a="Defias bandits currently occupy Mirror Lake Orchard and the cottage alongside it. They have driven away whatever honest folk once tended the trees and now use the secluded grounds as a base in western Elwynn.",al={"who is at mirror lake orchard","who lives here","orchard enemies"}},{q="Where is Mirror Lake Orchard located?",a="The orchard sits along the southern shore of Mirror Lake in western Elwynn Forest, just east of Thunder Falls and north of the main road heading toward Westfall.",al={"mirror lake orchard location","where is the orchard","find orchard elwynn"}},{q="Why hasn't Stormwind reclaimed the orchard?",a="Stormwind's standing army is largely absent from rural Elwynn due to political deadlock and the mysterious disappearance of King Varian Wrynn. With local garrisons shorthanded, distant farmsteads and orchards are frequently left to fend for themselves against the Defias Brotherhood.",al={"why are defias here","where are the guards"}},{q="What is the connection between the orchard and Thunder Falls?",a="Mirror Lake drains directly into Thunder Falls, placing the orchard just above the roaring cascade. Its secluded position near the cliffs makes it an ideal, defensible spot for bandits.",al={"thunder falls connection","orchard and waterfall"}}},ang={["faction:Alliance"]="For Alliance travelers, the occupied orchard is another bitter sign of the Defias Brotherhood's bold expansion across the heartland of the kingdom.",["class:Rogue"]="The orchard demonstrates classic Defias strategy: seizing defensible, overlooked properties near water and cliffs to monitor roads while evading city patrols."},kw={"defias brotherhood","elwynn forest","mirror lake","mirror lake orchard","stormwind bandits","thunder falls"},rel={"zone:elwynn","quest:1861","subzone:thunder-falls","topic:alliance"},src={"Mirror Lake Orchard"}}
E["subzone:northshire-abbey"] = {t="subzone",n="Northshire Abbey",z="elwynn",s="Northshire Abbey is a historic monastery nestled in Northshire Valley within the northern foothills of Elwynn Forest. Rebuilt after its destruction in the First War, it serves as the spiritual heart of the Brotherhood of Northshire and a premier training center for new defenders answering the kingdom of Stormwind's call.",h="Northshire Abbey is a historic monastery nestled in Northshire Valley within the northern foothills of Elwynn...",sec={{t="A Legacy of Faith and Ruin",b="Centuries ago, clerics from Lordaeron traveled south into the kingdom of Stormwind to spread the worship of the Holy Light, establishing the Holy Order of Northshire Clerics and their abbey. The monastery quickly became an anchor of kingdom life, caring for the sick and even tending to the young Guardian Medivh during his years in a coma. During the First War, the abbey suffered repeated assaults by brigands and the Orcish Horde, culminating in its utter destruction and the loss of holy relics like the Tome of Divinity. When the Alliance of Lordaeron liberated the region in the Second War, Archbishop Alonsus Faol helped rebuild the sanctuary, refounding its protectors as the Brotherhood of Northshire.",sp=0},{t="The Training Grounds",b="Today, Northshire Abbey functions as the starting ground for volunteers, militia recruits, and novices seeking to defend a beleaguered Stormwind. Split into the Main Hall, Hall of Arms, and Library Wing, it houses instructors in the martial, arcane, and holy arts, while scouts and rogues train in the outer yards. Despite the watchful presence of the Knights of the Silver Hand, peace here remains precarious. Kobolds overrun nearby mines, aggressive wolves roam the orchards, and agents of the Defias Brotherhood stalk the valley roads, pilfering ancient scrolls and sacred librams from the abbey's storied archives.",sp=0}},faq={{q="What is the Brotherhood of Northshire?",a="The Brotherhood of Northshire is a religious order of clerics, priests, and paladins based out of Northshire Abbey. Originally founded centuries ago by missioning clerics from Lordaeron, it was re-established by Archbishop Alonsus Faol after the First War to train faithful defenders and preserve sacred scripture.",al={"who runs northshire abbey","northshire clerics","brotherhood of northshire lore"}},{q="Why was Northshire Abbey destroyed in the First War?",a="During the First War, the abbey held strategic and spiritual importance for Stormwind. Orcish forces incited human brigands to attack it, and after the half-orc Garona was briefly held captive there, a massive Horde onslaught leveled the holy grounds. It remained ruined throughout the war until the Alliance drove out the orcish clans and rebuilt it.",al={"who destroyed northshire abbey","northshire first war","what happened to northshire"}},{q="Why are there Defias bandits and kobolds outside the abbey?",a="Stormwind's military is stretched thin protecting distant borders, leaving outlying regions poorly guarded. Opportunistic kobolds have infested the local gold mines, while the Defias Brotherhood exploits the gaps to rob travelers, harass the local vineyards, and raid the abbey's library for arcane tomes and holy relics.",al={"why is northshire under attack","kobolds in northshire","defias outside northshire"}},{q="What is the connection between Northshire Abbey and the Deadmines?",a="During the First War, an ogre chieftain named Turok stole the sacred Tome of Divinity from Northshire Abbey and retreated into the Deadmines. Sir Anduin Lothar led an expedition into the depths to recover the holy scripture, getting trapped until a royal rescue party saved him and returned the tome to the abbey's care.",al={"tome of divinity northshire","northshire deadmines lore","anduin lothar deadmines"}}},ang={["race:Human"]="For humans of Stormwind, Northshire Abbey is the cradle of your journey, where the kingdom's history of resilience and devotion welcomes every recruit taking up arms.",["class:Paladin"]="Northshire represents the legacy of Archbishop Alonsus Faol and the early clerics whose sacrifices laid the foundation for the Knights of the Silver Hand."},kw={"abbey","brotherhood","clerics","defias","elwynn","faol","northshire","valley"},rel={"subzone:northshire-valley","topic:brotherhood-of-northshire","topic:church-of-the-holy-light","topic:stormwind-kingdom","topic:knights-of-the-silver-hand","quest:1598","quest:2997","npc:drusilla-la-salle"},src={"Northshire Abbey"}}
E["subzone:northshire-valley"] = {t="subzone",n="Northshire Valley",z="elwynn",s="Tucked away in the northern mountains of Elwynn Forest, Northshire Valley serves as the peaceful cradle and training ground for the kingdom of Stormwind's newest defenders. Surrounded by natural barriers, it hosts the historic Northshire Abbey, fertile vineyards, and the rich Echo Ridge Mine. Despite its tranquil appearance, the valley faces mounting unrest from rogue bandits, infesting kobolds, and displaced predators.",h="Tucked away in the northern mountains of Elwynn Forest, Northshire Valley serves as the peaceful cradle and...",sec={{t="A Secluded Sanctuary",b="Northshire Valley is framed by nearly impassable mountain ridges, with its only road heading south through a fortified gatehouse toward Goldshire and the rest of Elwynn Forest. A clear river winds through its pastures before feeding south into Crystal Lake. At the valley's heart stands Northshire Abbey, an ancient sanctuary where the Holy Light is taught and where recruits are trained by the Knights of the Silver Hand and seasoned veterans. Beyond the abbey walls lie the bountiful Northshire Vineyards and Echo Ridge Mine, forming a self-sustaining pocket of Stormwind territory that feels far removed from the wider world's wars.",sp=0},{t="Encroaching Troubles",b="Even this sheltered haven has felt the strain of Stormwind's overextended defenses. Marshal McBride and his detachment of the Stormwind Guard struggle to maintain order across the vale. Packs of wolves driven north from blighted Duskwood prowl the surrounding woods, while vermin-like kobolds have overrun the tunnels of Echo Ridge Mine. Worse still, masked thugs aligned with the Defias Brotherhood openly harass the vineyards and threaten the abbey's grounds, forcing local commanders to recruit every able-bodied civilian arriving at their gates.",sp=0}},faq={{q="Why is Northshire Valley so heavily guarded?",a="The valley contains Northshire Abbey, a key spiritual hub and training ground for Stormwind's forces, as well as crucial local resources like Echo Ridge Mine and the vineyards. With Stormwind's military stretched thin, Marshal McBride maintains a guarded gate at the southern pass to prevent threats from leaking between the valley and greater Elwynn Forest.",al={"why guards northshire","gate in northshire","who protects northshire"}},{q="Where did all the wolves in the valley come from?",a="Deputy Willem notes that packs of wolves have recently surged across the river, having fled into the valley from the darkened forests of Duskwood to the south. The darkness spreading in Duskwood has driven wild beasts into normally tranquil pastures.",al={"why so many wolves","wolf infestation","wolves from duskwood"}},{q="Why are kobolds attacking Echo Ridge Mine?",a="Kobolds are opportunistic burrowers drawn to underground mineral veins. As kingdom patrols grew thin, a clan of kobolds took advantage of the lack of protection to claim Echo Ridge Mine for its gold and candles, forcing the human miners out of the tunnels.",al={"echo ridge kobolds","why kobolds in northshire","kobold problem"}},{q="Who are the bandits harassing the vineyards?",a="The thieves operating near Milly Osworth's vineyard are agents of the Defias Brotherhood. They prey on the outskirts of the valley to disrupt supplies, harass local farmers, and test the abbey's defenses.",al={"vineyard bandits","defias in northshire","red mask thugs"}},{q="What happened to Northshire during the Second War?",a="During the Second War, Northshire Abbey fell into enemy hands and was briefly utilized as a headquarters by Cho'gall's Twilight's Hammer clan before the Alliance reclaimed and restored the valley.",al={"northshire second war","twilight hammer northshire","chogall northshire"}},{q="How do you leave Northshire Valley?",a="The only passable exit on foot is the southern road leading through the guarded gatehouse. Passing through this gate takes travelers directly into central Elwynn Forest, pointing down the main road toward Goldshire.",al={"exit northshire","path to goldshire","how to leave"}}},ang={["race:Human"]="For humans of Stormwind, Northshire Valley is the place where their journey begins, stepping into the abbey's grounds to answer the call of a kingdom in need.",["faction:Alliance"]="Northshire serves as a crucial recruitment and recovery station for the Grand Alliance, training the next generation of defenders to stabilize the heart of the kingdom."},kw={"abbey","defias","echo ridge","elwynn","kobolds","mcbride","northshire","vineyards","willem"},rel={"subzone:northshire-abbey","npc:marshal-mcbride","subzone:northshire-vineyards","subzone:echo-ridge-mine","zone:elwynn","topic:stormwind-guard","topic:defias-brotherhood","subzone:goldshire"},src={"Northshire Valley"}}
E["subzone:northshire-vineyards"] = {t="subzone",n="Northshire Vineyards",z="elwynn",s="The Northshire Vineyards are cultivated grape fields lying just east of Northshire Abbey in the valley's sheltered basin. Though once a peaceful source of wine for the clerics, the fields have fallen under the control of the Defias Brotherhood and their local brigands.",h="The Northshire Vineyards are cultivated grape fields lying just east of Northshire Abbey in the valley's...",sec={{t="A Plundered Harvest",b="Located east across the stream from Northshire Abbey, the Northshire Vineyards represent the valley's quiet agrarian life. The fields are tended by local workers like Milly Osworth, but rising civil unrest has left them unprotected. Bandits aligned with the Defias Brotherhood, led on the ground by a cutthroat named Garrick Padfoot, have seized the acreage. Rather than mere vandalism, the thieves occupy the fields to plunder the harvest and strip the local farmers of their livelihood, providing new recruits to the Brotherhood an easy foothold right under the abbey's nose.",sp=0}},faq={{q="Who controls the Northshire Vineyards right now?",a="Thieves and cutthroats belonging to the Defias Brotherhood occupy the fields. Their local ringleader is Garrick Padfoot, a wanted rogue who directs the looting of the crops and terrorizes the local workers.",al={"who is at the vineyards","who took over northshire vineyards","who is garrick padfoot"}},{q="Why is the abbey letting bandits run rampant in the fields?",a="Stormwind's military resources are stretched extraordinarily thin with King Varian Wrynn missing. The abbey guards have pulled back to defend the abbey itself and watch the valley roads, forcing local farmers to rely on newly arrived adventurers to reclaim their stolen goods.",al={"why no stormwind guards","why isn't the abbey defending the vineyards"}},{q="Who is Milly Osworth?",a="Milly Osworth is a local farmer working the vineyards. When the Defias bandits moved in and seized the grape harvest, she was driven off and now seeks brave travelers to venture into the fields and recover her plundered crates.",al={"milly osworth","who is milly"}}},ang={["race:Human"]="For many young humans venturing out into the world, the occupied vineyards are their first direct encounter with the bitterness and reach of the Defias Brotherhood.",["faction:Alliance"]="The unrest in these peaceful grape fields demonstrates how deeply lawlessness has penetrated even the most protected corners of the kingdom of Stormwind."},kw={"defias","elwynn","garrick padfoot","grapes","milly osworth","northshire valley","northshire vineyards"},rel={"subzone:northshire-valley","topic:defias-brotherhood","quest:3903","zone:elwynn"},src={"Northshire Vineyards"}}
E["subzone:ridgepoint-tower"] = {t="subzone",n="Ridgepoint Tower",z="elwynn",s="Ridgepoint Tower is a fortified guard post watching the eastern frontier of Elwynn Forest. Manned by the Stormwind Guard, it serves as an early warning bulwark against hostile incursions threatening the heart of the kingdom. Its guards keep vigil over the perilous corridors leading to neighboring wilderness.",h="Ridgepoint Tower is a fortified guard post watching the eastern frontier of Elwynn Forest.",sec={{t="Sentinel of the Eastern Border",b="Standing sentinel on the high ground of eastern Elwynn Forest, Ridgepoint Tower marks the final bastion of direct Stormwind authority before the untamed wilds take over. The garrison stationed here keeps a constant watch over the surrounding valleys and roads. With tensions mounting across the continent, this stone watchtower ensures that encroaching threats are spotted and checked before they can endanger the farms and settlements closer to Northshire and Goldshire.",sp=0},{t="Threats on Every Horizon",b="Ridgepoint Tower faces pressure from multiple frontiers at once. To the east lie the Redridge Mountains, home to aggressive gnoll packs and blackrock orc raiders who test human defenses. Across the southern river looms the shadowy timberline of Duskwood, with its prowling undead horrors. Closer to home, rogue Defias Brotherhood bandits prowl the wilderness camps, eager to exploit any gap in the guard's defensive line.",sp=0}},faq={{q="What is Ridgepoint Tower?",a="Ridgepoint Tower is a fortified scout tower operated by the Stormwind Guard in eastern Elwynn Forest. It serves as a frontline watchpost tasked with alerting and protecting the kingdom from hostile intrusions.",al={"ridgepoint tower elwynn","what is this guard tower","east elwynn tower"}},{q="Who controls and mans the tower?",a="The tower is held and garrisoned by guardsmen and scouts loyal to the Kingdom of Stormwind, operating under the command of the Stormwind Guard.",al={"who is at ridgepoint tower","who owns ridgepoint tower"}},{q="What threats does the garrison watch out for?",a="The guards watch for gnolls and invading orcs spilling out of the Redridge Mountains, undead crossing from the blighted groves of Duskwood, and Defias bandits operating in clandestine woodland camps nearby.",al={"enemies near ridgepoint","what is attacking ridgepoint","why is the tower here"}},{q="Where is Ridgepoint Tower located?",a="It stands on the elevated ground in the far eastern reaches of Elwynn Forest, near the borders connecting Elwynn with both Redridge Mountains and Duskwood.",al={"ridgepoint tower location","where is ridgepoint"}}},ang={["faction:Alliance"]="For Alliance travelers, Ridgepoint Tower is a reassuring beacon of safety and order before crossing into the perilous passes of Redridge or the haunted roads of Duskwood.",["class:Warrior"]="Soldiers and mercenaries alike can respect the stoic resolve of the guardsmen holding such an exposed border outpost against surrounding hostiles."},kw={"defias","duskwood","elwynn forest","gnolls","redridge","ridgepoint tower","stormwind guard","watchtower"},rel={"zone:elwynn","topic:stormwind-guard","zone:redridge","zone:duskwood","topic:stormwind-kingdom","topic:gnoll"},src={"Ridgepoint Tower"}}
E["subzone:stone-cairn-lake"] = {t="subzone",n="Stone Cairn Lake",z="elwynn",s="Stone Cairn Lake is a ring-shaped body of water resting in northeastern Elwynn Forest. At its center lies an island crowned with Heroes' Vigil, a memorial to the fallen of the First War. Once a tranquil site for reflection, the lake is now troubled by hostile murlocs along its shores and renegade wizards occupying the isle.",h="Stone Cairn Lake is a ring-shaped body of water resting in northeastern Elwynn Forest.",sec={{t="A Monument Besieged",b="Stone Cairn Lake earns its name from the prominent stone memorial erected on the large island in its center. Known as Heroes' Vigil, this monument was raised to honor the heavy loss of human life suffered during the First War against the Orcish Horde. Families and pilgrims once traveled safely to the island to pay respects to the fallen, gazing across the calm waters at the solemn stonework. Today, however, dangerous renegade wizards have established a camp directly beside the memorial, turning a place of sacred remembrance into a hostile redoubt.",sp=0},{t="Shores of the Lake",b="Surrounding the ring-shaped lake is a scenic shoreline that has grown increasingly dangerous for locals and travelers. A tribe of aggressive murlocs has claimed the southern banks, erecting crude huts along the waterline and harassing anyone who draws near. Beyond its dangers, the hills and outcrops encircling the lake are rich in mineral veins, making the perimeter a frequent destination for prospectors and miners willing to brave the local threats.",sp=0}},faq={{q="Why is it called Stone Cairn Lake?",a="The lake takes its name from Heroes' Vigil, a stone cairn monument raised on the central island to commemorate the Alliance soldiers and civilians who perished during the First War.",al={"stone cairn name","why stone cairn","origin of the name"}},{q="Who is currently occupying the central island?",a="The island is overrun by rogue wizards and renegades who have chased away ordinary pilgrims and set up a fortified camp around the memorial.",al={"who is on the island","island wizards","rogue mages on lake"}},{q="Why are murlocs gathered around the water?",a="A local tribe of murlocs has settled the southern shallows and riverbanks, building primitive huts and claiming the plentiful fishing waters as their territory.",al={"murlocs at stone cairn","lake murlocs","south shore huts"}},{q="What is the memorial on the island called?",a="The monument is known as Heroes' Vigil, featuring a stone cairn often referred to as the Stone of Remembrance.",al={"island memorial name","monument name","stone cairn shrine"}}},ang={["profession:Mining"]="The bluffs and hills encircling Stone Cairn Lake boast one of the heaviest concentrations of copper deposits in all of Elwynn Forest, making it a lucrative stop for aspiring blacksmiths and engineers.",["race:Human"]="The central island represents a deeply personal memorial for the Kingdom of Stormwind, honoring those lost when the kingdom fell during the First War."},kw={"copper","elwynn forest","first war","heroes' vigil","murloc","rogue wizards","stone cairn lake","stone of remembrance"},rel={"subzone:heroes-vigil","zone:elwynn","topic:first-war","topic:murloc"},src={"Stone Cairn Lake"}}
E["subzone:stonefield-farm"] = {t="subzone",n="Stonefield Farm",z="elwynn",s="Stonefield Farm is a working homestead situated in southern Elwynn Forest. It is home to the Stonefield family, who have long been locked in a bitter feud with their neighbors, the Maclures.",h="Stonefield Farm is a working homestead situated in southern Elwynn Forest.",sec={{t="A Bitter Homestead",b="Nestled in the rolling greenery south of Goldshire, Stonefield Farm produces crops for the realm while maintaining a fierce, decades-long grudge against the nearby Maclure Vineyards. The bad blood between the households leads to petty squabbles, mutual accusations of theft, and constant tension. Yet beneath the hostile bickering, young Tommy Joe Stonefield has fallen secretly in love with Maybell Maclure, creating a quiet romance that could either bridge the divide between the families or ignite further outrage.",sp=0}},faq={{q="What is the feud between the Stonefields and the Maclures?",a="The Stonefield and Maclure families hold a long-standing, stubborn rivalry in southern Elwynn Forest. They constantly accuse one another of trespassing, petty theft, and general wrongdoing, refusing to cooperate on even simple neighborhood matters.",al={"stonefield maclure feud","why are stonefields fighting","stonefield rivals"}},{q="Who lives at Stonefield Farm?",a="The farmstead is managed by the Stonefield clan, including Gramma Stonefield, Ma Stonefield, and young Tommy Joe Stonefield.",al={"stonefield npcs","who is at stonefield farm"}},{q="What is Tommy Joe Stonefield's secret?",a="Despite the bitter hostility between the two households, Tommy Joe Stonefield is secretly in love with Maybell Maclure. The two lovers rely on sympathetic travelers to pass messages and gifts back and forth without their families noticing.",al={"tommy joe secret","tommy joe romance","stonefield love"}}},ang={["race:Human"]="For humans starting out from Northshire, the squabbles between the Stonefields and Maclures offer a lighthearted look at rural kingdom life beyond the threat of bandits and gnolls."},kw={"elwynn forest","gramma stonefield","maclure","stonefield","stonefield farm","tommy joe"},rel={"zone:elwynn"},src={"Stonefield Farm"}}
E["subzone:stormwind-city"] = {t="subzone",n="Stormwind City",z="elwynn",s="Stormwind City is the majestic capital of the Kingdom of Stormwind and the military and political heart of the Alliance. Rebuilt from ashes following its destruction in the First War, it stands as the greatest remaining bastion of human power in Azeroth following the fall of the northern kingdoms.",h="Stormwind City is the majestic capital of the Kingdom of Stormwind and the military and political heart of...",sec={{t="A Beacon Rebuilt",b="Founded over a millennium ago by Arathi descendants migrating south, Stormwind flourished as a vibrant coastal capital ringed by stone ramparts and powered by swift rivermills. That grandeur ended in the First War when the Orcish Horde besieged the city, breached its defenses, and burned it to the ground, forcing Sir Anduin Lothar to lead surviving refugees across the Great Sea to Lordaeron. Following the victory of the Alliance in the Second War, the Stonemasons' Guild undertook the monumental task of rebuilding the capital into the gleaming fortress of white stone, canal networks, and towering spires that stands north of Elwynn Forest today.",sp=0},{t="Heart of the Alliance",b="With Lordaeron shattered by the Scourge and Dalaran heavily ruined during the Third War, Stormwind City serves as the primary refuge and stronghold for mankind. Its broad avenues and defensive walls are patrolled by the disciplined Stormwind City Guard, while the spires of the Cathedral of Light guide faith and devotion across the southern kingdoms. Yet beneath its orderly districts and ceremonial gates lies quiet political turmoil: King Varian Wrynn has mysteriously vanished, leaving his young son Anduin on the throne under the regency of Highlord Bolvar Fordragon and the whispered counsel of royal advisor Lady Katrana Prestor.",sp=0}},faq={{q="Why was Stormwind rebuilt after the First War?",a="Stormwind was sacked and incinerated by the Orcish Horde during the First War. After the Grand Alliance of Lordaeron defeated the orcs in the Second War, human refugees reclaimed their ancestral kingdom. The royal court commissioned the Stonemasons' Guild to construct a new, even grander fortress city upon the original ruins.",al={"who rebuilt stormwind","rebuilding of stormwind","why does stormwind look new"}},{q="Who rules Stormwind City right now?",a="Nominally, the boy-king Anduin Wrynn sits upon the throne following the sudden and unexplained disappearance of his father, King Varian Wrynn. Because of Anduin's youth, true governing authority rests with Highlord Bolvar Fordragon, who acts as Regent and Commander of the Kingdom's defenses.",al={"who is king of stormwind","who runs stormwind","current ruler of stormwind"}},{q="Why is Stormwind the main human capital instead of Lordaeron?",a="During the Third War, the northern Kingdom of Lordaeron was utterly decimated from within by the undead plague and the Scourge. With Lordaeron destroyed and other northern human realms devastated, Stormwind remains the wealthiest, most intact, and most populous human kingdom left standing on Azeroth.",al={"what happened to lordaeron","why not capital of lordaeron","is stormwind the last city"}},{q="What military forces protect the city?",a="The peace within the wards and upon the battlement walls is enforced by the Stormwind City Guard. Broader territorial defense and royal protection are maintained by the Kingdom's knights, the garrisoned soldiers of Stormwind Keep, and paladins affiliated with the Church of the Light.",al={"who guards stormwind","stormwind army","city guards"}}},ang={["race:Human"]="For humans across Azeroth, the white walls of Stormwind represent endurance, survival, and the enduring glory of mankind after the total loss of the northern kingdoms.",["faction:Alliance"]="Stormwind is the premier military, naval, and spiritual rallying point for the Alliance in the southern Eastern Kingdoms, welcoming dwarves, gnomes, and night elven envoys alike."},kw={"alliance","anduin","bolvar","elwynn","first war","stonemasons","stormwind","stormwind city","wrynn"},rel={"zone:stormwind","subzone:stormwind-keep","subzone:cathedral-of-light","subzone:valley-of-heroes","zone:elwynn","topic:stormwind-kingdom","topic:first-war","topic:alliance"},src={"Stormwind City"}}
E["subzone:stormwind-gate"] = {t="subzone",n="Stormwind Gate",z="elwynn",s="The Stormwind Gate is the monumental fortified entryway connecting Elwynn Forest to Stormwind City. Guarded constantly by royal sentries, this threshold stands as the primary boundary between the tranquil woodlands and the grand Valley of Heroes.",h="The Stormwind Gate is the monumental fortified entryway connecting Elwynn Forest to Stormwind City.",sec={{t="The Threshold of the Kingdom",b="Towering over the southern road of Elwynn Forest, the Stormwind Gate serves as both a defensive bulwark and a ceremonial threshold for the capital. Sentinels of the Stormwind City Guard maintain a constant watch across the stone portal, guarding the approaches from the forest while regular patrols march between the outer arch and the Valley of Heroes. Despite lingering unrest throughout Elwynn, the massive iron-and-stone gates remain wide open to welcome travelers, merchants, and returning defenders into the heart of the Alliance.",sp=0}},faq={{q="Where does the Stormwind Gate lead?",a="Passing through the gate from Elwynn Forest brings you directly into the Valley of Heroes, the grand entryway to Stormwind City lined with towering monuments of the Second War.",al={"where does stormwind gate go","what is past the gate","stormwind entrance"}},{q="Why is the gate left open if Elwynn Forest is dangerous?",a="Stormwind thrives on open trade and steady travel from Goldshire and across the Alliance. While banditry and Defias activity trouble the surrounding woods, the city keeps the passage manned with vigilant guards rather than shutting out its own citizenry and commerce.",al={"why are the gates open","is stormwind gate closed","why open"}},{q="Who guards the gates?",a="The entryway is garrisoned by the Stormwind City Guard. Two sentries stand watch immediately outside in Elwynn Forest, two more guard the inner passage, and armed footmen patrol the bridge leading through the Valley of Heroes.",al={"stormwind gate guards","who defends the gate"}},{q="Are there special events held at the gate?",a="Yes. The open ground around the Stormwind Gate frequently hosts major citywide holidays and seasonal gatherings for the Alliance, serving as an open assembly area outside the crowded districts.",al={"holidays at stormwind gate","events at gate"}}},ang={["faction:Alliance"]="The gate represents the safety and endurance of the Grand Alliance, serving as the first glimpse of majesty for traveling soldiers and young adventurers.",["race:Human"]="To the people of Stormwind, returning through these stone arches means returning home to safety after long journeys through Elwynn and beyond."},kw={"elwynn forest","goldshire","stormwind city guard","stormwind gate","valley of heroes"},rel={"zone:stormwind","zone:elwynn","subzone:valley-of-heroes","subzone:goldshire","topic:stormwind-kingdom","topic:alliance"},src={"Stormwind Gate"}}
E["subzone:thunder-falls"] = {t="subzone",n="Thunder Falls",z="elwynn",s="Thunder Falls is a secluded mountain ravine tucked away in the northwestern heights of Elwynn Forest. Cradled between sheer cliffs and fed by roaring cascades, it features a quiet riverside cottage that has fallen into the hands of local bandits.",h="Thunder Falls is a secluded mountain ravine tucked away in the northwestern heights of Elwynn Forest.",sec={{t="A Hidden Mountain Hollow",b="Tucked away in the jagged ridges above Mirror Lake, Thunder Falls is an unusual geographical cleft. The ravine is carved by a swift mountain stream that enters via an inaccessible northern cascade, only to drop away on both sides in dramatic waterfalls. One side plunges down into Mirror Lake, while the downstream course flows west toward the rugged borders of Westfall. Despite the roaring waters, a small cottage, a dock, and an outdoor forge sit along the shore, though outlaws now claim the peaceful clearing for themselves.",sp=0}},faq={{q="How do you reach Thunder Falls?",a="You can reach Thunder Falls by heading to the northern side of Mirror Lake in Elwynn Forest. A steep, narrow trail winds up into the hills along the right side of the Mirror Lake waterfall, leading directly into the secluded ravine.",al={"how to get to thunder falls","thunder falls location","where is thunder falls"}},{q="Who lives in the cottage at Thunder Falls?",a="The secluded cabin appears to have once belonged to a solitary fisherman or frontiersman, complete with a dock, rowing boat, and outdoor anvil. Today, however, it serves as a remote hideout for bandits operating in the wilderness of Elwynn Forest.",al={"who is at the cottage","thunder falls house","cottage bandits"}},{q="Where does the river at Thunder Falls flow?",a="The stream flows through the narrow mountain gap from an upper mountain cascade. Downstream, it winds past the cottage and cascades down another steep fall that empties near the eastern boundary of Westfall.",al={"where does the water go","thunder falls river"}},{q="What wildlife or resources are found here?",a="The high, rushing mountain water is famous among anglers for Violet Perch. Aside from the fish living in the swift current, visitors will find wild beasts prowling the mountain ridges and hostile outlaws guarding the hollow.",al={"what fish are in thunder falls","thunder falls fishing"}}},kw={"bandits","cottage","elwynn forest","mirror lake","thunder falls","violet perch","waterfall"},rel={"quest:1861","zone:elwynn","zone:westfall"},src={"Thunder Falls"}}
E["subzone:tower-of-azora"] = {t="subzone",n="Tower of Azora",z="elwynn",s="The Tower of Azora is a slender wizard's spire rising out of eastern Elwynn Forest, north of the Brackwell Pumpkin Patch. Presided over by the human Archmage Theocritus, the enclave serves as a scholarly outpost locked in a silent magical feud with a hostile tower in neighboring Redridge Mountains.",h="The Tower of Azora is a slender wizard's spire rising out of eastern Elwynn Forest, north of the Brackwell...",sec={{t="A Spire of Arcane Vigilance",b="Standing along the eastern road toward the Redridge Mountains, the Tower of Azora is an arcane sanctuary staffed almost entirely by gnome spellcasters. Under the stewardship of Archmage Theocritus, these scholars study strange curiosities and provide magical instruction to wandering spellweavers. The wild magical aura surrounding the spire occasionally warps the nearby wildlife, leaving the gnome servants to contend with enchanted household items and mutated insects creeping past the doorway.",sp=0},{t="The Feud with Ilgalar",b="Beneath its quiet scholarly exterior, the tower is engaged in an enduring war of scrying and sabotage. To the east, atop the crags of Redridge, sits the sinister Tower of Ilgalar, ruled by the renegade sorcerer Morganth. Theocritus and Morganth constantly spy on one another through arcane means, employing daring adventurers to plant scrying relics like the Eye of Azora to pierce the wards of Ilgalar and monitor Morganth's dark machinations.",sp=1}},faq={{q="Who rules the Tower of Azora?",a="The tower is presided over by Archmage Theocritus, an accomplished human wizard. He directs the servants within the spire and coordinates their magical defenses against rival sorcerers.",al={"who leads the tower of azora","who is in charge here","tower of azora boss"}},{q="Why are there so many gnomes here?",a="The servants of Azora are predominantly gnome researchers and acolytes who assist Archmage Theocritus with his studies, arcane experiments, and housekeeping against magical mishaps.",al={"why gnomes in elwynn tower","servants of azora"}},{q="Who is the tower fighting against?",a="The tower is locked in a magical rivalry with the Tower of Ilgalar in the Redridge Mountains, home to the evil sorcerer Morganth. Both spires spy on each other with scrying artifacts and contest each other's influence.",al={"azora enemy","tower feud","who is azora spying on"}},{q="What is the Eye of Azora on the top floor?",a="The Eye of Azora is an enchanted scrying focus placed on a table in the upper sanctum. Touching it allows an observer to gaze through magical distance to monitor the outskirts of the Tower of Ilgalar.",al={"orb on top floor","eye of azora","crystal ball azora"}}},ang={["class:Mage"]="For mages traveling beyond Stormwind, the tower offers a secluded haven of study, arcane trainers, and a front-row seat to the dangerous arts of remote divination.",["race:Gnome"]="Seeing an arcane spire in human lands staffed by gnomes under Archmage Theocritus is a proud showcase of your people's mastery over the mystic arts."},kw={"azora","elwynn","enchanting","ilgalar","morganth","scrying","spire","theocritus"},rel={"zone:elwynn","subzone:tower-of-ilgalar","quest:94","zone:redridge","subzone:brackwell-pumpkin-patch","subzone:goldshire","topic:gnome"},src={"Tower of Azora"}}
E["subzone:westbrook-garrison"] = {t="subzone",n="Westbrook Garrison",z="elwynn",s="Westbrook Garrison is a Stormwind Guard outpost situated on the western edge of Elwynn Forest near the Westfall border. Manned by an overworked, under-supplied skeleton crew under Deputy Rainer, it serves as the realm's first line of defense against the encroaching Riverpaw gnolls and rogue bandits.",h="Westbrook Garrison is a Stormwind Guard outpost situated on the western edge of Elwynn Forest near the...",sec={{t="A Beleaguered Border Post",b="Positioned where Elwynn Forest begins to thin toward Westfall, Westbrook Garrison stands as a vital but struggling watchpoint. With much of the Stormwind Army committed abroad or tied down by political inertia in the capital, the outpost has been left critically shorthanded. Deputy Rainer and his handful of guards must patrol the western roads while fending off emboldened thieves and the vicious Riverpaw gnolls who have overrun the southern woods. Unable to secure formal reinforcements from Marshal Dughan in Goldshire, the garrison relies almost entirely on traveling adventurers to secure the highway.",sp=0},{t="The Menace of Forest's Edge",b="The primary threat facing Westbrook is the swelling gnoll presence centered around the south of Forest's Edge. The packs have grown bold enough to stage raids directly on supply lines and homesteads, organized under the fearsome gnoll chieftain known as Hogger. Outnumbered and overwhelmed by the brute strength of Hogger's forces, the garrison has posted a high bounty across its grounds, desperately seeking capable fighters willing to venture into the hills and bring down the beast before he pushes farther east.",sp=0}},faq={{q="Why is Westbrook Garrison so understaffed?",a="The bulk of the Stormwind Army is deployed abroad, and political indecision within the capital's House of Nobles has starved regional garrisons of fresh troops and supplies. Westbrook's commanders must rely heavily on wandering adventurers to pick up the slack.",al={"why so few guards","westbrook reinforcements","deputy rainer lacking troops"}},{q="Who is in command at the garrison?",a="Deputy Rainer oversees operations at Westbrook Garrison. He answers directly to Marshal Dughan stationed at Goldshire, though his requests for additional soldiers have largely gone unanswered.",al={"who leads westbrook garrison","deputy rainer role","westbrook commander"}},{q="What threats does the garrison face?",a="The garrison deals with wandering bandits spilling out of Westfall and the ferocious Riverpaw gnolls who camp in the surrounding woods, led by their dangerous chieftain Hogger.",al={"threats to westbrook","gnolls westbrook","who attacks westbrook garrison"}},{q="What is the relation between Westbrook and Westfall?",a="Westbrook Garrison is the final outpost in Elwynn Forest along the western road before crossing the bridge into Westfall, guarding the border against the lawlessness rising from the west.",al={"is westbrook in westfall","border to westfall"}}},ang={["class:Warrior"]="The beleaguered guards at Westbrook represent an overstretched kingdom holding back wilderness predators with sheer grit, offering plenty of straightforward, brutal work clearing gnoll war bands.",["faction:Alliance"]="For Alliance champions setting out from Elwynn toward Westfall, securing Westbrook's perimeter and claiming the bounty on Hogger is essential to keeping the heartland's western borders secure."},kw={"deputy rainer","elwynn forest","forest's edge","hogger","marshal dughan","riverpaw","westbrook garrison","westfall"},rel={"npc:deputy-rainer","quest:176","quest:11","subzone:forest-s-edge","subzone:goldshire","npc:marshal-dughan","zone:elwynn","zone:westfall"},src={"Westbrook Garrison"}}
E["zone:elwynn"] = {t="zone",n="Elwynn Forest",z="elwynn",s="Elwynn Forest is the verdant heartland of the Kingdom of Stormwind, providing the capital with essential timber, gold, fish, and crops. Sheltered beneath stately hardwoods, it serves as the proving ground for new human recruits stepping forth from Northshire Abbey. Yet beneath its idyllic pastoral canopy, the woods are sorely beleaguered by encroaching vermin, displaced wildlife, and widespread brigandage.",h="Elwynn Forest is the verdant heartland of the Kingdom of Stormwind, providing the capital with essential...",sec={{t="The Breadbasket of the Realm",b="Stretching south from the gates of Stormwind down to the Nazferiti River, Elwynn is a fertile region blessed with abundant rainfall and dense hardwood forests. Communities like Goldshire and the Eastvale Logging Camp provide crucial grain, livestock, lumber, and raw copper to sustain the grand capital. The region is also celebrated for breeding sturdy Evendale horses, favored by travelers and knights across the kingdom.",sp=0},{t="A Precarious Peace",b="Despite its outward serenity, the woods are on the brink of disorder. The Stormwind Army is stretched thin by distant obligations, leaving local marshals and deputies reliant on untested recruits. Kobolds have overrun the vital Fargodeep and Jasperlode mines, Riverpaw gnolls prowl the southwestern borders, and savage murlocs have claimed the shores of Stone Cairn Lake and Crystal Lake. In the wake of rising corruption across the river in Duskwood, even giant spiders and unnatural wolves have crept north across the border.",sp=0},{t="The Red Bandana Threat",b="Far more organized than mere scavengers, the Defias Brotherhood has deeply infiltrated the forest. Originating from Edwin VanCleef's disenfranchised Stonemasons Guild following bitter pay disputes with the House of Nobles, these masked outlaws have seized holdings across Elwynn, including the Northshire Vineyards, the Brackwell Pumpkin Patch, Jerod's Landing, and Mirror Lake Orchard. Rumors persist that their coordinated agents are subtly orchestrating the neighboring gnolls and kobolds to further destabilize the realm.",sp=1}},faq={{q="Why is the Stormwind Guard barely policing the forest?",a="Stormwind's armed forces are severely overstretched. The kingdom expanded heavy military deployments southward into Stranglethorn Vale, running up deep debts and draining local manpower. As a result, outposts like Westbrook Garrison and Goldshire rely on small skeleton crews and volunteer recruits to fight off bandits, gnolls, and murlocs.",al={"where are the guards","why no stormwind army","why is elwynn undefended"}},{q="Why are there kobolds inside all the mines?",a="With guards in short supply, opportunistic kobolds swarmed into Fargodeep Mine, Jasperlode Mine, and Echo Ridge Mine in search of precious gold and minerals. They drove out the human prospectors and miners, aggressively defending their subterranean claims with candles, crude picks, and scavenged tools.",al={"why are kobolds in the mines","elwynn kobolds","fargodeep infested"}},{q="Who are the bandits wearing red masks?",a="They are members of the Defias Brotherhood, led by Edwin VanCleef. Many were originally artisans of the Stonemasons Guild who rebuilt Stormwind City after the First War. When the nobility refused to pay them their promised wages, riots broke out, leading to their banishment and descent into organized brigandage.",al={"red masks","red bandana bandits","who are the defias in elwynn"}},{q="Where does the road south lead?",a="Crossing the bridge over the Nazferiti River takes you into Duskwood, historically known as Brightwood. That once-peaceful territory has fallen into unnatural darkness and is now infested with undead, monstrous spiders, and ravenous beasts.",al={"what is across the river","where does duskwood bridge go","bridge across the nazferiti"}},{q="What is the feud between the Maclures and Stonefields?",a="The Stonefields and the Maclures are neighboring farming families in southern Elwynn who have maintained a bitter, longstanding grudge against each other. Despite their endless bickering and accusations, two of their younger kin—Maybell Maclure and Tommy Joe Stonefield—have secretly fallen in love, complicating the rivalry even further.",al={"maclure vs stonefield","elwynn farm rivalry","stonefield maclure feud"}},{q="What is the Tower of Azora?",a="The Tower of Azora is an arcane spire located along the road between Goldshire and the Eastvale Logging Camp. It houses secluded mages, including Theocritus, who observe the region's leylines and conduct magical research outside the direct oversight of Stormwind's Wizard's Sanctum.",al={"tower on the road to eastvale","wizard tower elwynn","who lives in the tower of azora"}}},ang={["race:Human"]="This is the ancestral heart of the kingdom. Human adventurers begin here, training at Northshire Abbey before venturing out to defend their homeland from bandits, beasts, and political ruin.",["class:Rogue"]="The pervasive shadow of the Defias Brotherhood makes Elwynn an intriguing crossroads of thievery, smuggled goods, and underground rebel signals.",["profession:Mining"]="Echo Ridge, Fargodeep, and Jasperlode are laden with copper veins, making the forest an essential early proving ground for miners despite the kobold infestations.",["faction:Alliance"]="Protecting Elwynn is vital to the survival of the Alliance's primary human kingdom; if the lumber, ore, and grain routes collapse, Stormwind City cannot sustain itself."},kw={"defias","eastvale","elwynn","elwynn forest","fargodeep","goldshire","hogger","jasperlode","nazferiti","northshire","northshire abbey","vancleef"},rel={"zone:stormwind","subzone:goldshire","subzone:northshire-abbey","zone:westfall","zone:duskwood","zone:redridge","subzone:fargodeep-mine","quest:65"},m={levels="1-10"},src={"Elwynn Forest (Classic)","Elwynn Forest"}}
